-- > (wait game load)

if not game:IsLoaded() then game.Loaded:Wait() end

if (identifyexecutor() == "AWP" or identifyexecutor() == "Nihon") then
    cleardrawcache()
end
 
-- > ( bypass anti cheat + hit accurate )
-- Everything in this block belongs to one generation of the script. A newer run raises the generation, takes the older
-- run's connections down and leaves its hooks and loops handing their calls straight on, so re-injecting never stacks work on
-- top of work (every run used to add another namecall hook, another LogService loop and another scan of the whole workspace).

do
    local players_service = cloneref(game:GetService("Players"))
    local log_service = cloneref(game:GetService("LogService"))
    local replicated_storage = cloneref(game:GetService("ReplicatedStorage"))
    local local_player = players_service.LocalPlayer
    local main_event = replicated_storage:WaitForChild("MainEvent", 10)

    if not main_event then
        warn("[ab] MainEvent not found")
    end

    local shared_env = getgenv()
    local string_find = string.find
    local is_valid_level = debug.isvalidlevel or function() return true end

    local previous_unload = shared_env.neverlose_bypass_unload

    if type(previous_unload) == "function" then
        pcall(previous_unload)
    end

    local generation = (shared_env.neverlose_bypass_generation or 0) + 1
    shared_env.neverlose_bypass_generation = generation

    local bypass_connections = {}

    shared_env.neverlose_bypass_unload = function()
        for _, connection in bypass_connections do
            pcall(function()
                connection:Disconnect()
            end)
        end

        table.clear(bypass_connections)
    end

    local function alive()
        return shared_env.neverlose_bypass_generation == generation
    end

    -- LogService.MessageOut: the anti cheat listens there for the errors and warnings that hooks throw
    local silenced = setmetatable({}, { __mode = "k" })

    local function silence_log_listeners()
        for _, connection in getconnections(log_service.MessageOut) do
            if not silenced[connection] then
                silenced[connection] = true

                pcall(function()
                    connection:Disable()
                end)
            end
        end
    end

    silence_log_listeners()

    task.spawn(function()
        while task.wait(2) and alive() do
            pcall(silence_log_listeners)
        end
    end)

    -- remotes the anti cheat reports through: these names, and any CHECKER_n the game adds later
    local blocked_packets = {
        CHECKER_1 = true, CHECKER_4 = true,
        CHECKER = true, TeleportDetect = true,
        OneMoreTime = true, GUI_CHECK = true,
        checkingSPEED = true, BANREMOTE = true,
        KICKREMOTE = true, BR_KICKPC = true,
        BR_KICKMOBILE = true, PERMAIDBAN = true,
        INVISHIT = true,
    }

    -- "MousePos" is also the packet an older anti cheat sent its ban reports in: the second argument names the check that tripped. A real
    -- mouse position is a Vector3, so no real call has one of these strings there.
    local reported_checks = {
        ["Anti Ragdoll"] = true, ["Speed"] = true, ["Height"] = true, ["Jump Hack"] = true,
        ["Reach"] = true, ["Float"] = true, ["Aim"] = true, ["Speed Hack"] = true,
        ["Jump"] = true, ["Collision"] = true, ["Pos"] = true, ["Hum"] = true, ["Weld"] = true,
    }

    -- A report is one of the exact names on any remote, or on MainEvent the CHECKER prefix and the MousePos reports. (The prefix is not
    -- matched on every remote: a minigame could have a packet of its own that starts that way.)
    local function is_report(remote, packet, detail)
        if type(packet) ~= "string" then
            return false
        end

        if blocked_packets[packet] == true then
            return true
        end

        if remote == main_event then
            if string_find(packet, "^CHECKER") ~= nil then
                return true
            end

            -- The game's ViewReport script tells the server when the window loses focus (Focus, false) and when the camera has been on
            -- another player or further from the head than the zoom allows for 4 s (CameraAway, true). Nothing in the game's readable
            -- scripts says what the server does with them, so this is a precaution: a window running in the background (every second
            -- account) or a free camera is the kind of habit a server could read off an account. The other half of each pair (focus
            -- regained, camera back) still goes through.
            if packet == "Focus" then
                return detail == false
            end

            if packet == "CameraAway" then
                return detail == true
            end

            return packet == "MousePos" and type(detail) == "string" and reported_checks[detail] == true
        end

        return false
    end

    -- LogService:GetLogHistory() hands back everything printed since the game began, which is where a script's output would show. The game
    -- gets a few empty entries in the shape of real ones instead (a call from this script still gets the real history). It is compared with
    -- a LogService that is not a cloneref, since the game's own reference is not one.
    local log_service_raw = game:GetService("LogService")

    local function decoy_log_history()
        local history = {}

        for index = 1, math.random(1, 10) do
            history[index] = { message = "", messageType = Enum.MessageType.MessageOutput, timestamp = os.time() }
        end

        return history
    end

    -- its crash routine is a global called crash in some script's environment, and one stub stands in for every copy of it
    local crash_stub = newcclosure(function() end)

    local old_namecall = nil

    old_namecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
        -- an older generation's hook only hands the call on
        if not alive() then
            return old_namecall(self, ...)
        end

        local method = getnamecallmethod()

        if method == "FireServer" or method == "InvokeServer" then
            local packet, detail = ...

            if is_report(self, packet, detail) then
                return
            end
        elseif method == "GetLogHistory" then
            if self == log_service_raw and not checkcaller() then
                return decoy_log_history()
            end
        elseif method == "Kick" and self == local_player and not checkcaller() then
            return
        end

        if not checkcaller() and is_valid_level(2) then
            local environment = getfenv(2)
            local current = environment and rawget(environment, "crash")

            if current and current ~= crash_stub then
                rawset(environment, "crash", crash_stub)
            end
        end

        return old_namecall(self, ...)
    end))

    -- Kick, GetLogHistory and FireServer can also be held as bound functions and called without the method syntax, which a __namecall hook
    -- never sees
    local old_kick = nil

    pcall(function()
        old_kick = hookfunction(local_player.Kick, newcclosure(function(player, ...)
            if alive() and player == local_player and not checkcaller() then
                return
            end

            return old_kick(player, ...)
        end))
    end)

    local old_log_history = nil

    pcall(function()
        old_log_history = hookfunction(log_service_raw.GetLogHistory, newcclosure(function(service, ...)
            if alive() and service == log_service_raw and not checkcaller() then
                return decoy_log_history()
            end

            return old_log_history(service, ...)
        end))
    end)

    local old_fire_server = nil

    pcall(function()
        local sample = Instance.new("RemoteEvent")

        old_fire_server = hookfunction(sample.FireServer, newcclosure(function(remote, ...)
            if alive() then
                local packet, detail = ...

                if is_report(remote, packet, detail) then
                    return
                end
            end

            return old_fire_server(remote, ...)
        end))

        sample:Destroy()
    end)
    local function disable_connections(signal)
        for _, connection in getconnections(signal) do
            pcall(function()
                connection:Disable()
            end)
        end
    end

    -- the anti cheat watches the body for added children (CHECKER_1) and every tool for Grip changes
    local function silence_body(character)
        for _, name in { "HumanoidRootPart", "UpperTorso" } do
            local part = character:FindFirstChild(name)

            if part then
                disable_connections(part.ChildAdded)
            end
        end
    end

    local function silence_tool(tool)
        if tool:IsA("Tool") then
            disable_connections(tool:GetPropertyChangedSignal("Grip"))
        end
    end

    -- Its watchers are made a moment after the body spawns, not at one fixed time, so the body is swept more than once.
    local function sweep_character(character)
        local waited = 0

        for _, at in { 0, 0.25, 1, 2.5, 5, 10 } do
            task.wait(at - waited)
            waited = at

            if not alive() or not character.Parent then
                return
            end

            silence_body(character)

            for _, child in character:GetChildren() do
                silence_tool(child)
            end
        end
    end

    local function watch_character(character)
        character.ChildAdded:Connect(function(child)
            if alive() and child:IsA("Tool") then
                task.wait(0.1)
                silence_tool(child)
            end
        end)

        sweep_character(character)
    end

    if local_player.Character then
        task.spawn(watch_character, local_player.Character)
    end

    table.insert(bypass_connections, local_player.CharacterAdded:Connect(function(character)
        task.spawn(watch_character, character)
    end))

    -- accuracy: the gun modules' accuracy is pinned, and so are the zone modules in the workspace
    task.spawn(function()
        local modules = replicated_storage:FindFirstChild("Modules")

        if not modules then
            return
        end

        -- game modules are required at a low identity so they cannot see this environment
        local function require_module(module)
            local identity = getthreadidentity()

            setthreadidentity(2)

            local ok, result = pcall(require, module)

            setthreadidentity(identity)

            return ok, result
        end

        local hooked = setmetatable({}, { __mode = "k" })

        local function hook_accuracy_module(module)
            if hooked[module] then
                return
            end

            hooked[module] = true

            local ok, result = require_module(module)

            if not ok or type(result) ~= "table" then
                return
            end

            if result.setAccuracy then
                pcall(hookfunction, result.setAccuracy, newcclosure(function() end))
            end

            if result.accuracy then
                pcall(function()
                    result.accuracy = 1
                end)
            end

            if result.enums and result.enums.Accuracy then
                local accuracy_enum = result.enums.Accuracy

                if accuracy_enum.getProperty then
                    pcall(hookfunction, accuracy_enum.getProperty, newcclosure(function()
                        return 0
                    end))
                end
            end

            for name, value in pairs(result) do
                if type(name) == "string" and type(value) == "function" then
                    if string_find(name, "find", 1, true) or string_find(name, "get", 1, true) then
                        pcall(hookfunction, value, newcclosure(function(...)
                            return true
                        end))
                    end
                end
            end
        end

        for _, descendant in modules:GetDescendants() do
            if descendant:IsA("ModuleScript") then
                local name = descendant.Name

                if string_find(name, "Zone", 1, true) or string_find(name, "Accuracy", 1, true) then
                    hook_accuracy_module(descendant)
                end
            end
        end

        -- The zone modules are found once and as they appear. Scanning the whole workspace every ten seconds was a hitch.
        local zones = {}

        local function add_zone(instance)
            if instance:IsA("ModuleScript") and string_find(instance.Name, "Zone", 1, true) then
                zones[instance] = true
            end
        end

        for _, descendant in workspace:GetDescendants() do
            add_zone(descendant)
        end

        table.insert(bypass_connections, workspace.DescendantAdded:Connect(add_zone))

        while task.wait(10) and alive() do
            pcall(function()
                for module in zones do
                    if not module:IsDescendantOf(workspace) then
                        zones[module] = nil
                        continue
                    end

                    local ok, result = require_module(module)

                    if ok and type(result) == "table" and result.setAccuracy then
                        pcall(function()
                            result:setAccuracy(1)
                        end)

                        pcall(function()
                            result.accuracy = 1
                        end)
                    end
                end
            end)
        end
    end)
end

-- > ( luraph variables )

if not LPH_OBFUSCATED then
    LPH_JIT_MAX = function(...) return ... end
    LPH_NO_VIRTUALIZE = function(...) return ... end
    LPH_ENCSTR = function(...) return ... end
    LPH_NO_UPVALUES = function(...) return ... end
    LPH_JIT = function(...) return ... end
end

getgenv()["neverlose"] = {}

-- > ( workspace folder migration )
-- copy the old assets/configs folder across once, the paths below use the new name

pcall(function()
    local function copy_folder(from, to)
        if not isfolder(to) then
            makefolder(to)
        end

        for _, path in listfiles(from) do
            local name = path:match("([^/\\]+)$")

            if isfolder(path) then
                copy_folder(path, to.."/"..name)
            elseif not isfile(to.."/"..name) then
                writefile(to.."/"..name, readfile(path))
            end
        end
    end

    if isfolder("juju recode") then
        copy_folder("juju recode", "neverlose recode")
    end
end)

-- > ( bypass )

LPH_JIT_MAX(function()
    if not getgenv().done then
        local reg = getreg()
        local connection = reg["RBXScriptConnection"]
        local signal = reg["RBXScriptSignal"]
        local gc = getgc(true)

        local connection_count = 0

        for i, v in reg do
            if typeof(v) == "function" and islclosure(v) then
                local info = getinfo(v)
                local _, count = string.gsub(info.source, "%.", "")
                if count == 1 and not string.find(info.source, "Replicated") then
                    if getupvalues(v)[2] ~= 26 then
                        connection_count+=1
                        reg[i] = function(a) end
                    end
                end
            end
        end

        --[[if connection_count < 4 then
            cloneref(game:GetService("Players"))["LocalPlayer"]:Kick("[femmyhac.cc]\nda hood has updated, please wait for femmyhac.cc to update.")
            task["wait"](9e9) -- << idk if this will yield in luraph ?
            return
        end]]

        local function safe_hook_function(old, replace)
            local fake_old = clonefunction(old)

            local replacements = {}

            for _, v in gc do
                if typeof(v) == "table" and #v < 2500 then
                    local index = table.find(v, old)

                    if index then
                        replacements[v] = index
                    end
                end
            end

            hookfunction(old, replace)

            for _, v in replacements do
                rawset(_, v, fake_old)
            end

            return fake_old
        end

        old = nil; old = safe_hook_function(signal.__index, LPH_NO_UPVALUES(function(self, index)
            if (index:find("^[Cc]onnect")) and getinfo(3) then
                local source = getinfo(3).source
                local _, count = string.gsub(source, "%.", "")
                if count == 1 and not string.find(source, "Replicated") then
                    return function()
                        return setrawmetatable(newproxy(), connection)
                    end
                end
            end
            return old(self, index)
        end))

        old2 = nil; old2 = safe_hook_function(cloneref(game["GetService"](game, "UserInputService")).GetFocusedTextBox, newcclosure(LPH_NO_UPVALUES(function()
            return nil
        end)))

        getgenv().done = true
    end
end)()

-- > ( bypass: actor anti cheat )
-- CHECKER_2 / CHECKER_3 and a local kick("no") run from a parallel actor state,
-- the namecall hook above does not exist in there, so the same filter goes into it.
-- Read from that state (it holds three game functions, all from ReplicatedFirst.<actor>.Handshake.desc): a CharacterAdded listener
-- that gives each character a DescendantAdded watcher (a body mover or LinearVelocity without the AllowedBM attribute is CHECKER_2) and
-- a watcher on the Head's Anchored property (CHECKER_3, then Kick("no") a second later). Both are switched off below as well as
-- having their packets dropped, so nothing is built that has to be caught.

LPH_JIT_MAX(function()
    local generation = getgenv().neverlose_bypass_generation
    local actor_hooked = getgenv().actor_hooked or {}
    getgenv().actor_hooked = actor_hooked

    local actor_source = [==[
        local main_event = game:GetService("ReplicatedStorage"):WaitForChild("MainEvent", 10)
        local local_player = game:GetService("Players").LocalPlayer
        local log_service = game:GetService("LogService")
        local string_find = string.find

        -- the same report names as the filter in the main state
        local blocked_packets = {
            CHECKER_1 = true, CHECKER_4 = true, CHECKER = true, TeleportDetect = true, OneMoreTime = true,
            GUI_CHECK = true, checkingSPEED = true, BANREMOTE = true, KICKREMOTE = true, BR_KICKPC = true,
            BR_KICKMOBILE = true, PERMAIDBAN = true, INVISHIT = true,
        }

        local reported_checks = {
            ["Anti Ragdoll"] = true, ["Speed"] = true, ["Height"] = true, ["Jump Hack"] = true,
            ["Reach"] = true, ["Float"] = true, ["Aim"] = true, ["Speed Hack"] = true,
            ["Jump"] = true, ["Collision"] = true, ["Pos"] = true, ["Hum"] = true, ["Weld"] = true,
        }

        local old_namecall
        old_namecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            local method = getnamecallmethod()

            if method == "FireServer" or method == "InvokeServer" then
                local packet, detail = ...

                if type(packet) == "string" then
                    if blocked_packets[packet] == true then
                        return print("[ab] blocked "..packet)
                    end

                    if self == main_event and (string_find(packet, "^CHECKER") or (packet == "MousePos" and type(detail) == "string" and reported_checks[detail] == true)) then
                        return print("[ab] blocked "..packet)
                    end
                end
            elseif method == "GetLogHistory" then
                if self == log_service and not checkcaller() then
                    local history = {}

                    for index = 1, math.random(1, 10) do
                        history[index] = { message = "", messageType = Enum.MessageType.MessageOutput, timestamp = os.time() }
                    end

                    return history
                end
            elseif method == "Kick" and self == local_player and not checkcaller() then
                return
            end

            return old_namecall(self, ...)
        end))

        -- the same Kick, called without the method syntax
        local old_kick
        pcall(function()
            old_kick = hookfunction(local_player.Kick, newcclosure(function(player, ...)
                if player == local_player and not checkcaller() then
                    return
                end

                return old_kick(player, ...)
            end))
        end)

        -- The checkers themselves, switched off as well. The only game code that runs in this state is the Handshake script: a
        -- CharacterAdded listener that, for each character, watches its DescendantAdded (CHECKER_2) and the Head's Anchored property
        -- (CHECKER_3, then Kick("no")). The packets are dropped above either way; this stops them being built.
        local function from_checker(connection)
            local callback = connection.Function

            if not callback or isexecutorclosure(callback) then
                return false
            end

            local ok, source = pcall(debug.info, callback, "s")

            return ok and type(source) == "string" and string_find(source, "ReplicatedFirst", 1, true) ~= nil
        end

        local function disable_checkers(signal)
            for _, connection in getconnections(signal) do
                if from_checker(connection) then
                    pcall(function()
                        connection:Disable()
                    end)
                end
            end
        end

        -- the listener that builds the checkers for every new character: off, and no later character gets any
        pcall(disable_checkers, local_player.CharacterAdded)

        -- the current character already has its two watchers. They are swept more than once in case one is made a moment late.
        local function sweep_checkers(character)
            local waited = 0

            for _, at in { 0, 0.25, 1, 2.5, 5, 10 } do
                task.wait(at - waited)
                waited = at

                if not character.Parent then
                    return
                end

                pcall(disable_checkers, character.DescendantAdded)

                local head = character:FindFirstChild("Head")

                if head then
                    pcall(disable_checkers, head:GetPropertyChangedSignal("Anchored"))
                end
            end
        end

        if local_player.Character then
            task.spawn(sweep_checkers, local_player.Character)
        end

        local_player.CharacterAdded:Connect(function(character)
            pcall(disable_checkers, local_player.CharacterAdded)
            task.spawn(sweep_checkers, character)
        end)
    ]==]

    -- bumped whenever actor_source changes, so a run after an update puts the new filter into an actor that already has the old one
    local ACTOR_VERSION = 2

    local function hook_actor(actor)
        if actor_hooked[actor] == ACTOR_VERSION then
            return
        end

        actor_hooked[actor] = ACTOR_VERSION
        pcall(run_on_actor, actor, actor_source)
    end

    local function hook_actors()
        for _, actor in getactors() do
            hook_actor(actor)
        end

        for _, actor in getdeletedactors() do
            hook_actor(actor)
        end
    end

    pcall(hook_actors)
    task.spawn(function()
        while task.wait(2) and getgenv().neverlose_bypass_generation == generation do
            pcall(hook_actors)
        end
    end)
end)()

-- > ( bypass: backpack grip watchers )
-- gun scripts watch Grip from the backpack too, the hook above only reaches the held tool

LPH_JIT_MAX(function()
    local function kill_grip_watchers(tool)
        if not tool:IsA("Tool") then
            return
        end

        for _, connection in getconnections(tool:GetPropertyChangedSignal("Grip")) do
            pcall(function()
                connection:Disable()
            end)
        end
    end

    task.spawn(function()
        local player = cloneref(game:GetService("Players")).LocalPlayer
        local generation = getgenv().neverlose_bypass_generation

        while task.wait(1) and getgenv().neverlose_bypass_generation == generation do
            pcall(function()
                for _, container in {player.Character, player:FindFirstChildOfClass("Backpack")} do
                    for _, tool in container:GetChildren() do
                        kill_grip_watchers(tool)
                    end
                end
            end)
        end
    end)
end)()

-- > ( bypass: void + anti afk )
-- ported from based hub. the engine deletes anything that falls under FallenPartsDestroyHeight and
-- NaN switches that check off, so a fall into nothing is put back on the last ground stood on.
-- the idle kick is answered the way a player touching the mouse would

LPH_JIT_MAX(function()
    local previous = getgenv().void_afk_unload

    if type(previous) == "function" then
        pcall(previous)
    end

    local player_service = cloneref(game:GetService("Players"))
    local run_service = cloneref(game:GetService("RunService"))
    local virtual_user = cloneref(game:GetService("VirtualUser"))
    local input_service = cloneref(game:GetService("UserInputService"))
    local player = player_service.LocalPlayer

    local VOID_RESCUE = true -- false keeps the NaN height but never moves the character
    local AFK_QUIET = 600 -- seconds without input before an answer is given unasked, the engine kicks at 1200
    local FALL_DROP = 150 -- studs fallen with nothing underneath before it counts as the void
    local FALL_SEE = 15000 -- how far down a ray looks for ground
    local HIDE_RANGE = 1e5 -- further out than this is a void hide teleport, not a fall
    local SPOT_SETTLE = 0.4 -- seconds stood on ground before it is kept
    local SPOT_APART = 10 -- studs between two kept spots
    local SPOT_KEEP = 8
    local nan = 0 / 0

    local stopped = false
    local game_height = nil
    local last_input, last_answer = os.clock(), 0
    local stood_since, fall_top, last_rescue = nil, nil, 0
    local spots = {}
    local connections = {}

    local ray_params = RaycastParams.new()
    ray_params.FilterType = Enum.RaycastFilterType.Exclude
    ray_params.RespectCanCollide = true

    -- the game's own height is kept so it can be handed back
    local function apply_void()
        if stopped then
            return
        end

        local height = workspace.FallenPartsDestroyHeight

        if height == height then
            game_height = height
            workspace.FallenPartsDestroyHeight = nan
        end
    end

    local function answer_idle()
        last_answer = os.clock()

        pcall(function()
            virtual_user:CaptureController()
            virtual_user:ClickButton2(Vector2.new())
        end)
    end

    local function ground_below(position, reach, character)
        ray_params.FilterDescendantsInstances = {character}

        return workspace:Raycast(position, Vector3.new(0, -reach, 0), ray_params)
    end

    -- ground the body has stood on for a moment that is part of the map, not something loose or carried
    local function remember(character, humanoid, root, now)
        stood_since = stood_since or now

        if now - stood_since < SPOT_SETTLE then
            return
        end

        local hit = ground_below(root.Position, humanoid.HipHeight + root.Size.Y + 6, character)

        if not hit or not hit.Instance.Anchored then
            return
        end

        local newest = spots[#spots]

        if newest and (newest.Position - root.Position).Magnitude < SPOT_APART then
            spots[#spots] = root.CFrame
        else
            table.insert(spots, root.CFrame)

            if #spots > SPOT_KEEP then
                table.remove(spots, 1)
            end
        end
    end

    local function rescue(character, root, now)
        -- back in the void this soon after the last time, that spot was no good so the one before is used
        if now - last_rescue < 4 and #spots > 1 then
            table.remove(spots)
        end

        while #spots > 0 do
            local spot = spots[#spots]

            if ground_below(spot.Position + Vector3.new(0, 2, 0), 14, character) then
                root.CFrame = spot + Vector3.new(0, 0.5, 0)
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero

                last_rescue, fall_top = now, nil
                getgenv().neverlose_rescued_at = now

                return
            end

            -- the ground there has gone
            table.remove(spots)
        end
    end

    local function look(now)
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")

        if not humanoid or not root or humanoid.Health <= 0 then
            stood_since, fall_top = nil, nil
            return
        end

        local position = root.Position

        -- void hide parks the body millions of studs away for a frame, that is not a fall
        if math.max(math.abs(position.X), math.abs(position.Y), math.abs(position.Z)) > HIDE_RANGE then
            return
        end

        local state = humanoid:GetState()

        if humanoid.SeatPart or state == Enum.HumanoidStateType.Swimming or state == Enum.HumanoidStateType.Climbing then
            stood_since, fall_top = nil, nil
            return
        end

        if humanoid.FloorMaterial ~= Enum.Material.Air and state ~= Enum.HumanoidStateType.Freefall then
            fall_top = nil
            remember(character, humanoid, root, now)
            return
        end

        stood_since = nil
        fall_top = math.max(fall_top or position.Y, position.Y)

        -- under where the game itself would have ended it
        local caught = game_height ~= nil and position.Y < game_height

        if not caught and root.AssemblyLinearVelocity.Y < -4 and fall_top - position.Y > 30 then
            if not ground_below(position, FALL_SEE, character) then
                caught = fall_top - position.Y > FALL_DROP
            end
        end

        if caught then
            rescue(character, root, now)
        end
    end

    apply_void()

    -- the game setting its height again must not bring the void back
    table.insert(connections, workspace:GetPropertyChangedSignal("FallenPartsDestroyHeight"):Connect(apply_void))
    table.insert(connections, player.Idled:Connect(answer_idle))
    table.insert(connections, input_service.InputBegan:Connect(function()
        last_input = os.clock()
    end))

    if VOID_RESCUE then
        local elapsed = 0

        table.insert(connections, run_service.Heartbeat:Connect(function(dt)
            elapsed += dt

            if elapsed < 0.06 then
                return
            end

            elapsed = 0
            pcall(look, os.clock())
        end))
    end

    -- backup for when Idled never fires
    task.spawn(function()
        while task.wait(5) and not stopped do
            if os.clock() - math.max(last_input, last_answer) >= AFK_QUIET then
                answer_idle()
            end
        end
    end)

    getgenv().void_afk_unload = function()
        if stopped then
            return
        end

        stopped = true

        for _, connection in connections do
            pcall(function()
                connection:Disconnect()
            end)
        end

        -- stopped is set first, giving the height back fires the signal above
        if game_height ~= nil and workspace.FallenPartsDestroyHeight ~= workspace.FallenPartsDestroyHeight then
            workspace.FallenPartsDestroyHeight = game_height
        end
    end
end)()

