local create_instance = LPH_NO_VIRTUALIZE(function(class, properties)
    local instance = Instance["new"](class)

    for property, value in properties do
        instance[property] = value
    end

    return instance
end)

local round = LPH_NO_VIRTUALIZE(function(num, decimals)
    local mult = 10^(decimals or 0)

    -- halves go away from zero: a negative number is rounded as its positive twin (0 - x also avoids a negative zero)
    if num < 0 then
        return (0 - floor(-num * mult + 0.5)) / mult
    end

    return floor(num * mult + 0.5) / mult
end)

local remove = LPH_NO_VIRTUALIZE(function(tbl, index)
    local length = #tbl
    for i = index, length - 1 do
        tbl[i] = tbl[i + 1]
    end
    tbl[length] = nil
end)

-- > ( unload: engine teardown )
-- the menu's Unload only took the UI down and the engine kept running behind it. same order as entry's destroy:
-- stop scheduling first (everything create_connection made), then put the local character back

LPH_JIT_MAX(function()
    local original_max_zoom = local_player["CameraMaxZoomDistance"]

    -- a run that replaces an earlier one starts while the earlier one's distance is still applied
    if original_max_zoom >= 1e8 then
        original_max_zoom = 128
    end

    -- things that live outside this script's own connections (a hook in the game's gun module, say) register how to come out here
    local teardowns = {}
    getgenv()["neverlose_teardowns"] = teardowns

    getgenv().neverlose_unload_engine = function()
        for index = #teardowns, 1, -1 do
            pcall(teardowns[index])
            teardowns[index] = nil
        end

        for index, connection in connections do
            pcall(function()
                connection:Disconnect()
            end)

            connections[index] = nil
        end

        local character = local_player["Character"]
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")

        if humanoid then
            pcall(function()
                humanoid:SetStateEnabled(Enum["HumanoidStateType"]["Seated"], true)
                humanoid:SetStateEnabled(Enum["HumanoidStateType"]["FallingDown"], true)
            end)
        end

        -- only a distance this script set is taken back
        if local_player["CameraMaxZoomDistance"] == 9e9 then
            local_player["CameraMaxZoomDistance"] = original_max_zoom
        end
    end
end)()

-- > ( signal library )

local signal = {}

do
    -- > ( connection class)

    local connection = {}

    connection["__index"] = connection

    function connection.new(signal, callback)
        local callbacks = signal["callbacks"]
        callbacks[#callbacks+1] = callback

        return setmetatable({
            callback = callback,
            signal = signal
        }, connection)
    end

    function connection:Disconnect()
        -- A second call would otherwise remove another registration of the same function.
        if self["disconnected"] then
            return
        end

        self["disconnected"] = true

        local callbacks = self["signal"]["callbacks"]
        local callback = self["callback"]

        for i = 1, #callbacks do
            if callbacks[i] == callback then
                remove(callbacks, i)

                break
            end
        end
    end

    -- > ( signal class )

    signal["__index"] = signal

    signal.new = LPH_JIT_MAX(function()
        return setmetatable({
            callbacks = {}
        }, signal)
    end)

    function signal:Fire(...)
        local callbacks = self["callbacks"]
        local count = #callbacks

        if count == 0 then
            return
        end

        -- A handler can disconnect (itself or another one) while the signal is firing, which shifts the list under the loop.
        local snapshot = table.move(callbacks, 1, count, 1, {})

        for i = 1, count do
            spawn(snapshot[i], ...)
        end
    end

    function signal:Connect(callback)
        return connection["new"](self, callback)
    end
end

-- > ( tween library )

local active_tweens = {
    Color = {},
    Color3 = {},
    Size = {},
    tween_position = {},
    Position = {},
    tween_size = {},
    Transparency = {},
    FillTransparency = {},
    OutlineTransparency = {},
    BackgroundTransparency = {},
    ImageTransparency = {},
    FillColor = {},
    OutlineColor = {},
    [11] = {},
    [15] = {}
}

local tween = nil 
do
    local sqrt = math["sqrt"]
 
    tween = LPH_NO_VIRTUALIZE(function(object, properties, easing_style, _, tween_duration)
        -- A duration of 0 divides by zero below and writes NaN into the object for a frame.
        tween_duration = math["max"](tween_duration or 0, 0.001)

        local start_time = clock()

        local tween_functions = {}

        for property, value in properties do
            local tweens = active_tweens[property]
            local old_tween = tweens[object]

            if old_tween then
                for i = 1, #heartbeat do
                    if heartbeat[i] == old_tween then
                        remove(heartbeat, i)
                        break
                    end
                end
            end

            local old_value = object[property]

            if property == "Color" or property == "Color3" or property == "FillColor" or property == "OutlineColor" then
                tween_functions[property] = function()
                    local t = math["min"]((clock() - start_time)/tween_duration, 1)
                    object[property] = color3_lerp(old_value, value, easing_style == exponential and (t == 1 and 1 or 1 - 2 ^ (-10 * t)) or easing_style == quad and t^2 or sqrt(1 - (t - 1) ^ 2)) or easing_style == "sine" and t < 0.5 and 0.5 * math.sin(clamp(t, 0, 1) * 355/113) or 0.5 + 0.5 * (1 - math.cos((clamp(t, 0, 1) - 0.5) * 355/113))
                end
            elseif property == "tween_position" or property == "tween_size" then
                tween_functions[property] = function()
                    local t = math["min"]((clock() - start_time)/tween_duration, 1)
                    local tween_value = easing_style == exponential and (t == 1 and 1 or 1 - 2 ^ (-10 * t)) or easing_style == quad and t^2 or sqrt(1 - (t - 1) ^ 2)

                    local new = (value - old_value)
                    new = udim2_new(new["X"]["Scale"] * tween_value, new["X"]["Offset"] * tween_value, new["Y"]["Scale"] * tween_value, new["Y"]["Offset"] * tween_value)

                    object[property] = old_value + new
                end
            else
                tween_functions[property] = function()
                    local t = math["min"]((clock() - start_time)/tween_duration, 1)

                    object[property] = old_value + (value - old_value) * (easing_style == exponential and (t == 1 and 1 or 1 - 2 ^ (-10 * t)) or easing_style == quad and t^2 or sqrt(1 - (t - 1) ^ 2))
                end
            end
        end

        for property, tween in tween_functions do
            heartbeat[#heartbeat+1] = tween
            active_tweens[property][object] = tween
        end

        delay(tween_duration, function()
            for property, tween in tween_functions do
                for i = 1, #heartbeat do
                    if heartbeat[i] == tween then
                        remove(heartbeat, i)

                        -- The object can be gone by now (a drawing removed mid-tween): one failed write must not stop the other properties from finishing.
                        pcall(function()
                            object[property] = properties[property]
                        end)
                        break
                    end
                end

                -- The registry only grew otherwise: it kept every object ever tweened (destroyed drawings, player records) and this closure alive for the
                -- whole session, and every later tween of the same object scanned the heartbeat list for this finished one. A newer tween of the same
                -- property has already replaced the entry.
                if active_tweens[property][object] == tween then
                    active_tweens[property][object] = nil
                end
            end
        end)
    end)
end

-- > ( connection list )
-- create_connection only ever added to `connections`, and the entries were dropped at unload only: every respawn of every player (nine connections each)
-- left dead connection objects, and the character tree their closures hold, in the list for the rest of the session. Every 256 new connections the list
-- is compacted: connections that are already disconnected go, everything else stays in order.
do
    local create = create_connection
    local added = 0

    create_connection = LPH_NO_VIRTUALIZE(function(signal, callback)
        local connection = create(signal, callback)

        added += 1

        if added >= 256 then
            added = 0

            local kept = 0
            local size = #connections

            for index = 1, size do
                local entry = connections[index]
                local dead = false

                if typeof(entry) == "RBXScriptConnection" then
                    dead = not entry["Connected"]
                elseif type(entry) == "table" then
                    dead = entry["disconnected"] == true
                end

                if not dead then
                    kept += 1
                    connections[kept] = entry
                end
            end

            for index = kept + 1, size do
                connections[index] = nil
            end
        end

        return connection
    end)
end

