-- > ( menu shim: femmyhac.cc UI replaces femmyhac.cc's menu library )
-- Everything above this is femmyhac.cc's bypass, globals, signal/tween libs and the menu table skeleton.
-- Below this file provides:
--   * menu methods (:create_tab, :create_section, :create_notification, etc.)
--   * stub elements returned by section:create_element({name=...}, {toggle={flag=X,default=Y}, ...})
--   * pop_menu noop so femmyhac.cc's config loader doesn't crash
--   * getgenv().neverlose.{get_flags,set_flag} + menu["new_notification"]
-- The femmyhac.cc UI (loaded further down) populates flags[*] via its toggle Callbacks AND
-- fires the matching stub's on_*_change signals so femmyhac.cc's engine listeners run.

local new_signal = signal.new

-- Every section the engine creates is recorded here (with its elements and gear settings), so the
-- femmyhac.cc menu can build matching rows once the engine has finished defining them.
_G.NL_ENGINE_UI = { sections = {}, panels = {} }

-- shared __index for stub elements/sections:
--   "_"-prefixed state fields stay nil (engine does `~= nil` checks),
--   "on_"-prefixed keys become a cached real signal so create_connection can bind,
--   anything else is a no-op method.
local function stub_index(t, k)
    if type(k) == "string" then
        if k:sub(1, 1) == "_" then return nil end
        if k:sub(1, 3) == "on_" then
            local sig = new_signal()
            rawset(t, k, sig)
            return sig
        end
    end
    return function() end
end

local make_section_stub -- forward declared

local function make_element_stub(def)
    local el = {}
    el.on_toggle_change = new_signal()
    el.on_slider_change = new_signal()
    el.on_dropdown_change = new_signal()
    el.on_color_change = new_signal()
    el.on_transparency_change = new_signal()
    el.on_keybind_change = new_signal()
    el.on_clicked = new_signal()
    el.on_tab_switch = new_signal()
    el._flag_name = nil
    el._color_flag = nil
    el._transparency_flag = nil

    if type(def) == "table" then
        if def.toggle then
            local t = def.toggle
            el._flag_name = t.flag
            if t.flag ~= nil then flags[t.flag] = t.default end
        end
        if def.slider then
            local s = def.slider
            el._flag_name = s.flag
            if s.flag ~= nil then flags[s.flag] = s.default end
        end
        if def.dropdown then
            local d = def.dropdown
            el._flag_name = d.flag
            if d.flag ~= nil then flags[d.flag] = d.default end
        end
        if def.colorpicker then
            local c = def.colorpicker
            el._color_flag = c.color_flag
            el._transparency_flag = c.transparency_flag
            if c.color_flag ~= nil then flags[c.color_flag] = c.default_color end
            if c.transparency_flag ~= nil then flags[c.transparency_flag] = c.default_transparency end
        end
        if def.color then
            local c = def.color
            el._color_flag = c.flag
            if c.flag ~= nil then flags[c.flag] = c.default end
        end
        if def.keybind then
            local k = def.keybind
            el._flag_name = k.flag
            if k.flag ~= nil then flags[k.flag] = k.default end
        end
    end

    function el:set_toggle(v)
        if self._flag_name ~= nil then flags[self._flag_name] = v end
        self.on_toggle_change:Fire(v)
        -- keep the femmyhac.cc row in step when the engine flips a toggle itself
        local mirror = rawget(self, "_ui_toggle")
        if mirror then pcall(mirror, v) end
    end
    function el:set_value(v)
        if self._flag_name ~= nil then flags[self._flag_name] = v end
        self.on_slider_change:Fire(v)
        self.on_dropdown_change:Fire(v)
        self.on_keybind_change:Fire(v)
    end
    function el:set_color(c)
        if self._color_flag ~= nil then flags[self._color_flag] = c end
        self.on_color_change:Fire(c)
    end
    function el:set_transparency(t)
        if self._transparency_flag ~= nil then flags[self._transparency_flag] = t end
        self.on_transparency_change:Fire(t)
    end
    function el:set_visible(v)
        rawset(self, "_visible", v)
        local hook = rawget(self, "_ui_visible")
        if hook then pcall(hook, v) end
    end
    function el:set_text(t) end
    function el:set_title(t) end
    function el:set_info(...) end
    function el:tooltip(t) end
    function el:add_icon(name, fn) end
    function el:add_option(...) return make_section_stub() end
    function el:create_settings()
        -- one settings (gear) container per element, so its children stay recorded
        local settings = rawget(self, "_settings")
        if not settings then
            settings = make_section_stub()
            rawset(self, "_settings", settings)
        end
        return settings
    end
    return setmetatable(el, { __index = stub_index })
end

make_section_stub = function()
    local s = { _items = {} }
    -- real signals so femmyhac.cc's create_connection(section["on_*"], fn) has something to bind
    s.on_selection_change = new_signal()
    s.on_clicked = new_signal()
    s.on_tab_switch = new_signal()
    function s:create_element(info, def)
        local el = make_element_stub(def)
        local items = rawget(self, "_items")
        items[#items + 1] = { name = type(info) == "table" and info.name or nil, def = def or {}, stub = el }
        return el
    end
    function s:create_section(tab, title, column)
        local section = make_section_stub()
        if type(tab) == "string" and type(title) == "string" and _G.NL_ENGINE_UI then
            local sections = _G.NL_ENGINE_UI.sections
            sections[#sections + 1] = { tab = tab, title = title, column = column, stub = section }
        end
        return section
    end
    function s:create_panel_section(tab, title, ...)
        local panel = make_section_stub()
        if type(title) == "string" and _G.NL_ENGINE_UI then
            _G.NL_ENGINE_UI.panels[title] = panel
        end
        return panel
    end
    function s:create_tab(...) return make_section_stub() end
    function s:create_settings(...) return make_section_stub() end
    function s:add_option(...) return make_section_stub() end
    function s:set_visible(v) end
    function s:set_title(t) end
    -- shared catch-all: on_* keys become signals, "_" keys nil, else no-op method
    return setmetatable(s, { __index = stub_index })
end

-- Groups: menu["groups"]["main"]:create_section(...)
local group_mt = { __index = function(t, k)
    local g = make_section_stub()
    rawset(t, k, g)
    return g
end }
setmetatable(menu.groups, group_mt)

menu["ordered_groups"] = menu["ordered_groups"] or {}

function menu:create_tab(...) return make_section_stub() end
function menu:create_section(...) return make_section_stub() end
function menu:create_panel_section(...) return make_section_stub() end
function menu:create_notification(text, kind) return nil end
function menu:create_logger(...)
    return setmetatable({}, { __index = function(t, k)
        return function() end
    end })
end
function menu:load_theme(...) return nil end
function menu:get_flags() return flags end
function menu:get_addon_list() return {} end
