-- Catch unknown method calls on the menu table so stray engine references don't blow up.
local menu_mt = getmetatable(menu)
if type(menu_mt) ~= "table" then menu_mt = {} end
local existing_index = menu_mt.__index
menu_mt.__index = function(t, k)
    if existing_index then
        local v = (type(existing_index) == "function") and existing_index(t, k) or existing_index[k]
        if v ~= nil then return v end
    end
    -- Unknown field: hand back a tolerant stub (callable, chainable, iterable)
    return function(...) return nil end
end
setmetatable(menu, menu_mt)

-- Global pop_menu — called in femmyhac.cc's config loader. Noop.
_G.pop_menu = function(initial_hide) end
pop_menu = _G.pop_menu

-- Public API seed. femmyhac.cc engine (further down) will layer more into getgenv().neverlose.
if type(getgenv) == "function" then
    getgenv()["neverlose"] = getgenv()["neverlose"] or {}
    getgenv()["neverlose"]["get_flags"] = function() return flags end
    getgenv()["neverlose"]["set_flag"] = function(name, value)
        flags[name] = value
        local el = menu_references[name]
        if el then
            if el.on_toggle_change then el.on_toggle_change:Fire(value) end
            if el.on_slider_change then el.on_slider_change:Fire(value) end
            if el.on_dropdown_change then el.on_dropdown_change:Fire(value) end
            if el.on_keybind_change then el.on_keybind_change:Fire(value) end
            if el.on_color_change then el.on_color_change:Fire(value) end
        end
    end
    getgenv()["neverlose"]["get_flag"] = function(name) return flags[name] end
end

