local nl_ok, nl_err = pcall(function()

local WINDOW_NAME = "Visions hook"
local WINDOW_CONTENT = "Da Hood"
local CONFIG_FOLDER = "NeverLoseConfigs"
local BINDS_FILE = CONFIG_FOLDER .. "/binds.json" -- right-click keybinds are saved here
local MENU_KEY = "Insert"
local TARGET_KEY = "E" -- key that adds the player under the cursor to the Target List
local DEBUG = false -- true prints every option change to the output
local SESSION_KEY = "__NeverLoseMenuSession"

---------- Environment check ------------
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local TextService = game:GetService("TextService")
local HttpService = game:GetService("HttpService")
local LocalPlayer = Players.LocalPlayer

if not LocalPlayer then
	warn("[Visions hook] This script must run on the client (a LocalScript), not in a server Script.")
	return
end

---------- Single instance ------------
-- Running the script again unloads the previous copy first, so windows,
-- keybinds and loops never stack up.
local sharedEnv = (type(getgenv) == "function" and getgenv()) or _G

local previous = sharedEnv[SESSION_KEY]
if type(previous) == "table" and type(previous.Unload) == "function" then
	pcall(previous.Unload)
end

local Session = { Alive = true, Connections = {}, Cleanups = {}, NativeSections = {}, EngineKeys = {}, Master = { Active = false, Held = {} } }
sharedEnv[SESSION_KEY] = Session

-- The engine's records and flags are kept here: a newer run replaces the globals before it unloads this one.
Session.EngineUi = _G.NL_ENGINE_UI
Session.EngineFlags = _G.neverlose_flags
Session.EngineRefs = _G.neverlose_menu_refs

-- the menu's Unload only took the UI down, the engine behind it is stopped first
if type(sharedEnv.neverlose_unload_engine) == "function" then
	table.insert(Session.Cleanups, 1, sharedEnv.neverlose_unload_engine)
end

-- the void + anti afk block near the top hands the game's void height back on unload
if type(sharedEnv.void_afk_unload) == "function" then
	table.insert(Session.Cleanups, sharedEnv.void_afk_unload)
end

local NeverLose, Notification, Logging
local window, Watermark, ping

-- Flags an unload never switches off: the Anti Report keeps its own watch until the engine's own teardown stops it.
local UNLOAD_KEEPS = "^anti_report"

-- Every toggle the engine defined, gear settings included, newest first.
function Session.engineToggles()
	local found, seen = {}, {}
	local ui = Session.EngineUi

	local function walk(stub)
		if type(stub) ~= "table" or seen[stub] then
			return
		end
		seen[stub] = true

		for _, item in ipairs(rawget(stub, "_items") or {}) do
			local toggle = type(item.def) == "table" and item.def.toggle
			if toggle and toggle.flag ~= nil then
				table.insert(found, { flag = toggle.flag, stub = item.stub })
			end

			walk(rawget(item.stub, "_settings"))
		end
	end

	for _, record in ipairs(ui and ui.sections or {}) do
		walk(record.stub)
	end

	local newestFirst = {}
	for index = #found, 1, -1 do
		table.insert(newestFirst, found[index])
	end

	return newestFirst
end

-- What the engine does to the world (rain, chams, ESP, sounds, lighting, the local character) is taken back out by the listener
-- of the toggle that put it there, so unloading switches each one on off through that same listener.
function Session.switchEngineOff()
	local engineFlags = Session.EngineFlags
	if type(engineFlags) ~= "table" then
		return 0
	end

	local count = 0

	for _, toggle in ipairs(Session.engineToggles()) do
		if engineFlags[toggle.flag] == true and not tostring(toggle.flag):find(UNLOAD_KEEPS) then
			engineFlags[toggle.flag] = false
			count += 1

			local engineSignal = rawget(toggle.stub, "on_toggle_change")
			if engineSignal then
				local okFire, fireError = pcall(engineSignal.Fire, engineSignal, false)
				if not okFire then
					warn("[Visions hook] Switching " .. tostring(toggle.flag) .. " off failed: " .. tostring(fireError))
				end
			end
		end
	end

	return count
end

-- Unloading goes in this order, each step on its own so one that fails never leaves the rest running:
--   1. the Default config is saved, so nothing set in this session is lost
--   2. the engine's toggles are switched off (see switchEngineOff)
--   3. the engine stops: its connections, the hooks that registered a teardown, the local character
--   4. the menu's own steps (visuals, the Semi Rage, previews) in the order they were registered
--   5. the menu's connections, then the library's window, and the globals the menu handed the engine
function Session.Unload()
	if not Session.Alive or Session.Unloading then
		return
	end
	Session.Unloading = true

	if NeverLose and type(NeverLose.SaveDefaultConfig) == "function" then
		pcall(NeverLose.SaveDefaultConfig, NeverLose)
	end

	local okOff, switched = pcall(Session.switchEngineOff)
	if not okOff then
		warn("[Visions hook] Switching the engine's options off failed: " .. tostring(switched))
	end

	Session.Alive = false

	if sharedEnv[SESSION_KEY] == Session then
		sharedEnv[SESSION_KEY] = nil
	end

	for _, connection in ipairs(Session.Connections) do
		pcall(function()
			connection:Disconnect()
		end)
	end
	table.clear(Session.Connections)

	for _, cleanup in ipairs(Session.Cleanups) do
		local cleanupOk, cleanupError = pcall(cleanup)
		if not cleanupOk then
			warn("[Visions hook] An unload step failed: " .. tostring(cleanupError))
		end
	end
	table.clear(Session.Cleanups)

	if Watermark and type(Watermark.SetRender) == "function" then
		pcall(Watermark.SetRender, Watermark, false)
	end

	-- NeverLose:Unload() destroys the library's ScreenGui and disconnects its signals.
	if NeverLose and type(NeverLose.Unload) == "function" then
		if not pcall(NeverLose.Unload, NeverLose) then
			warn("[Visions hook] Unloading the library failed; the menu window stays on screen until you rejoin.")
		end
	end

	-- Only the hand-over globals this run owns are cleared; a newer run may already have its own.
	if _G.NL_PUSH_DEFAULTS == Session.pushDefaults then
		_G.NL_PUSH_DEFAULTS = nil
	end
	_G.NL_LOG = nil

	if sharedEnv.neverlose_is_typing == Session.isTyping then
		sharedEnv.neverlose_is_typing = nil
	end

	-- The engine's hand-over globals go too, and only the ones this run made: a newer run puts its own in place before it unloads this one.
	-- Everything this session still needs of them is kept in Session.EngineUi / EngineFlags / EngineRefs.
	if _G.neverlose_flags == Session.EngineFlags then
		_G.neverlose_flags = nil
	end
	if _G.neverlose_menu_refs == Session.EngineRefs then
		_G.neverlose_menu_refs = nil
	end
	if _G.NL_ENGINE_UI == Session.EngineUi then
		_G.NL_ENGINE_UI = nil
	end
end

local function track(connection)
	table.insert(Session.Connections, connection)
	return connection
end

-- The bypass replaces UserInputService.GetFocusedTextBox with a function that always returns nil, so the script's own "is the player typing"
-- checks never fired. The text box focus events still work: they are followed here, and the engine asks through getgenv().neverlose_is_typing.
do
	local typingBox = nil

	track(UserInputService.TextBoxFocused:Connect(function(box)
		typingBox = box
	end))
	track(UserInputService.TextBoxFocusReleased:Connect(function()
		typingBox = nil
	end))

	function Session.isTyping()
		return typingBox ~= nil
	end

	sharedEnv.neverlose_is_typing = Session.isTyping
end

---------- The menu library ------------
-- The menu is the Juju-style library below (JujuLib), defined right here: nothing is downloaded and no other library is loaded.
local function createJujuLib()
	-- JujuLib: the Gamesense look of the Juju ui (panel with a gradient strip, an icon sidebar, bordered sections, square toggles,
	-- bar sliders) behind the call surface the femmyhac.cc menu was written against (CreateWindow / AddTab / AddSection / AddLabel /
	-- AddToggle / AddSlider / AddDropdown / AddKeybind / AddColorPicker / AddTextInput / AddButton / AddOption / Flags / Unload),
	-- so every control the menu defines shows up here unchanged.

	local Players = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")
	local TweenService = game:GetService("TweenService")
	local TextService = game:GetService("TextService")
	local HttpService = game:GetService("HttpService")
	local CoreGui = game:GetService("CoreGui")

	local Lib = {
		Flags = {},
		UnloadEnabled = true,
		OptionLayoutHooked = true, -- the menu's option-window restacking hack is not needed here: sliders and dropdowns already sit on their own line
		Scales = {
			Default = Vector2.new(800, 650),
			Large = Vector2.new(960, 780),
			Mobile = Vector2.new(700, 560),
			Small = Vector2.new(720, 560),
		},
		GlobalLogo = "",
	}

	local ACCENT = Color3.fromRGB(160, 195, 5)
	local OFF_COLOR = Color3.fromRGB(60, 60, 60)
	local PANEL_COLOR = Color3.fromRGB(45, 45, 45)
	local MENU_COLOR = Color3.fromRGB(20, 20, 20)
	local SIDEBAR_COLOR = Color3.fromRGB(10, 10, 10)
	local LINE_COLOR = Color3.fromRGB(50, 50, 50)
	local BOX_COLOR = Color3.fromRGB(32, 32, 32)
	local POPUP_COLOR = Color3.fromRGB(26, 26, 26)
	local TEXT_COLOR = Color3.fromRGB(255, 255, 255)
	local MUTED_COLOR = Color3.fromRGB(170, 170, 170)
	local FONT = Enum.Font.SourceSans
	local NAME_SIZE = 16
	local ROW_HEIGHT = 22

	local GRADIENT = ColorSequence.new({
		ColorSequenceKeypoint.new(0.00, Color3.fromRGB(14, 163, 180)),
		ColorSequenceKeypoint.new(0.26, Color3.fromRGB(25, 96, 184)),
		ColorSequenceKeypoint.new(0.52, Color3.fromRGB(169, 21, 255)),
		ColorSequenceKeypoint.new(0.77, Color3.fromRGB(190, 202, 20)),
		ColorSequenceKeypoint.new(1.00, Color3.fromRGB(243, 255, 25)),
	})

	-- the icons of the Juju ui, by the tab they belong to
	local TAB_ICONS = {
		aimbot = "rbxassetid://12977951813",
		antiaim = "rbxassetid://12978048207",
		legit = "rbxassetid://12978050702",
		visuals = "rbxassetid://12978061744",
		misc = "rbxassetid://12978113090",
		skins = "rbxassetid://12978115973",
		players = "rbxassetid://12978070034",
	}
	local TAB_ICON_BY_NAME = {
		["rage"] = "aimbot",
		["semi rage"] = "antiaim",
		["legit"] = "legit",
		["world"] = "visuals",
		["character"] = "misc",
		["skins"] = "skins",
		["misc"] = "misc",
		["player list"] = "players",
		["players"] = "players",
		["config"] = "antiaim",
	}

	---------- helpers ------------
	local connections = {}
	local gui = nil
	local overlayOpen = nil -- the one popup (dropdown list, colour picker, option window) that is open
	local overlayAnchor = nil -- the control that opened it: a click on that control is the control's own to answer

	local function randomName()
		return string.sub(HttpService:GenerateGUID(false), 1, 12)
	end

	local function new(class, props, parent)
		local instance = Instance.new(class)

		for key, value in pairs(props or {}) do
			instance[key] = value
		end

		if parent then
			instance.Parent = parent
		end

		return instance
	end

	local function bind(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(connections, connection)
		return connection
	end

	-- Sliders only follow the mouse while one of them is held. One connection serves every slider that is held right now, instead of
	-- one connection per slider running its check on every mouse move.
	local draggers = {}
	local draggerConnection = nil

	local function setDragger(handler, held)
		draggers[handler] = held and true or nil

		if held and not draggerConnection then
			draggerConnection = bind(UserInputService.InputChanged, function(input)
				for dragHandler in pairs(draggers) do
					dragHandler(input)
				end
			end)
		end
	end

	-- The keybind controls that are listening for their key right now (their finish function -> true), and how many there are. While one is
	-- listening, the key it takes is not a press of anything else: the menu key and the options bound to a key skip it.
	local captures = {}
	Lib.KeyCaptures = 0

	local function cancelCaptures()
		for finish in pairs(captures) do
			finish(true)
		end
	end

	local function process(config, defaults)
		config = type(config) == "table" and config or {}

		for key, value in pairs(defaults) do
			if config[key] == nil then
				config[key] = value
			end
		end

		return config
	end

	local function textWidth(text, size)
		local ok, bounds = pcall(TextService.GetTextSize, TextService, tostring(text), size, FONT, Vector2.new(10000, 100))
		return ok and bounds.X or (#tostring(text) * size * 0.5)
	end

	local function roundTo(value, decimals)
		local factor = 10 ^ (decimals or 0)
		return math.floor(value * factor + 0.5) / factor
	end

	local function formatNumber(value, decimals)
		if (decimals or 0) <= 0 then
			return tostring(math.floor(value + 0.5))
		end

		local text = string.format("%." .. decimals .. "f", value)
		text = text:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
		return text
	end

	local function mouseIsOver(frame)
		if not frame or not frame.Parent then
			return false
		end

		local mouse = UserInputService:GetMouseLocation()
		local inset = gui and gui.IgnoreGuiInset and Vector2.zero or Vector2.new(0, 36)
		local position = frame.AbsolutePosition + inset
		local size = frame.AbsoluteSize

		return mouse.X >= position.X and mouse.X <= position.X + size.X and mouse.Y >= position.Y and mouse.Y <= position.Y + size.Y
	end

	local function newSignal(initial)
		local signal = { _value = initial, _listeners = {} }

		function signal:GetValue()
			return self._value
		end

		function signal:Connect(callback)
			table.insert(self._listeners, callback)

			local connection = {}
			function connection:Disconnect()
				for index, listener in ipairs(signal._listeners) do
					if listener == callback then
						table.remove(signal._listeners, index)
						break
					end
				end
			end

			return connection
		end

		function signal:Fire(value)
			self._value = value

			for _, listener in ipairs(table.clone(self._listeners)) do
				pcall(listener, value)
			end
		end

		return signal
	end

	local function keyCodeName(key)
		if key == nil or key == "None" or key == "" then
			return "None"
		end

		if key == "M1B" then
			return "Mouse1"
		elseif key == "M2B" then
			return "Mouse2"
		elseif key == "M3B" then
			return "Mouse3"
		end

		local name = typeof(key) == "EnumItem" and key.Name or tostring(key)
		local short = {
			LeftControl = "LCtrl", RightControl = "RCtrl", LeftShift = "LShift", RightShift = "RShift", LeftAlt = "LAlt", RightAlt = "RAlt",
			Return = "Enter", Backspace = "Bksp", Delete = "Del", Insert = "Ins", PageUp = "PgUp", PageDown = "PgDn", CapsLock = "Caps",
		}

		return short[name] or name
	end

	---------- popups, tooltips ------------
	local function closeOverlay()
		if overlayOpen then
			local close = overlayOpen
			overlayOpen = nil
			overlayAnchor = nil
			pcall(close)
		end
	end

	local function openOverlay(close, anchor)
		if overlayOpen and overlayOpen ~= close then
			closeOverlay()
		end

		overlayOpen = close
		overlayAnchor = anchor
	end

	-- Positions a floating frame under (or above, near the bottom of the screen) an anchor frame, kept on screen.
	local function placeBelow(popup, anchor, width)
		local screen = gui.AbsoluteSize
		local anchorPosition = anchor.AbsolutePosition
		local anchorSize = anchor.AbsoluteSize
		local popupWidth = width or anchorSize.X
		-- A popup with a fixed size is placed by that size: AbsoluteSize still holds the previous frame's, which sent a list upwards.
		local popupHeight = popup.AutomaticSize == Enum.AutomaticSize.None and popup.Size.Y.Offset or popup.AbsoluteSize.Y

		local x = math.clamp(anchorPosition.X, 4, math.max(4, screen.X - popupWidth - 4))
		local y = anchorPosition.Y + anchorSize.Y + 2

		if y + popupHeight > screen.Y - 4 then
			y = math.max(4, anchorPosition.Y - popupHeight - 2)
		end

		popup.Position = UDim2.fromOffset(x, y)
	end

	local tooltip = nil
	local tooltipToken = 0

	local function ensureTooltip()
		if tooltip then
			return tooltip
		end

		local frame = new("Frame", {
			Name = randomName(),
			BackgroundColor3 = POPUP_COLOR,
			BorderColor3 = LINE_COLOR,
			BorderSizePixel = 1,
			AutomaticSize = Enum.AutomaticSize.XY,
			Size = UDim2.fromOffset(10, 10),
			Visible = false,
			ZIndex = 3000,
		}, gui)
		new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), PaddingTop = UDim.new(0, 3), PaddingBottom = UDim.new(0, 3) }, frame)
		local label = new("TextLabel", {
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.XY,
			Size = UDim2.fromOffset(10, 10),
			Font = FONT,
			TextSize = 15,
			TextColor3 = TEXT_COLOR,
			TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 3001,
		}, frame)
		new("UISizeConstraint", { MaxSize = Vector2.new(300, math.huge) }, frame)

		tooltip = { Frame = frame, Label = label }

		bind(UserInputService.InputChanged, function(input)
			if frame.Visible and input.UserInputType == Enum.UserInputType.MouseMovement then
				local position = UserInputService:GetMouseLocation()
				local screen = gui.AbsoluteSize
				local x = math.clamp(position.X + 14, 4, math.max(4, screen.X - frame.AbsoluteSize.X - 4))
				local y = math.clamp(position.Y - 6 + 18, 4, math.max(4, screen.Y - frame.AbsoluteSize.Y - 4))
				frame.Position = UDim2.fromOffset(x, y)
			end
		end)

		return tooltip
	end

	local function attachTooltip(target, text)
		target.MouseEnter:Connect(function()
			tooltipToken += 1
			local token = tooltipToken

			task.delay(0.45, function()
				if token == tooltipToken and mouseIsOver(target) then
					local tip = ensureTooltip()
					tip.Label.Text = text
					tip.Frame.Visible = true
				end
			end)
		end)

		target.MouseLeave:Connect(function()
			tooltipToken += 1

			if tooltip then
				tooltip.Frame.Visible = false
			end
		end)
	end

	---------- controls (a "label" is one row of a section or option window) ------------
	local function newItem(label, flag, kind)
		local item = { Kind = kind, Flag = flag, flag = flag, Row = label }

		if flag then
			Lib.Flags[flag] = item
		end

		return item
	end

	local function makeLabel(owner, name)
		local label = { Name = name, Owner = owner, Controls = 0, HasToggle = false }

		local row = new("Frame", {
			Name = randomName(),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = owner.NextOrder(),
		}, owner.Body)
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, row)

		local head = new("Frame", {
			Name = "Head",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
			LayoutOrder = 0,
		}, row)

		local nameLabel = new("TextLabel", {
			Name = "Name",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(2, 0),
			Size = UDim2.new(1, -4, 1, 0),
			Font = FONT,
			Text = tostring(name),
			TextColor3 = TEXT_COLOR,
			TextSize = NAME_SIZE,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextXAlignment = Enum.TextXAlignment.Left,
		}, head)

		-- Click area for the row (toggle rows flip when the name is clicked); the right-hand controls sit above it.
		local hit = new("TextButton", {
			Name = "Hit",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 1, 0),
			Text = "",
			ZIndex = 1,
		}, head)

		local right = new("Frame", {
			Name = "Right",
			AnchorPoint = Vector2.new(1, 0.5),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Position = UDim2.new(1, -2, 0.5, 0),
			Size = UDim2.new(0, 0, 0, 18),
			ZIndex = 3,
		}, head)
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 4),
		}, right)

		label.Root = row
		label.Head = head
		label.NameLabel = nameLabel
		label.RightHolder = right
		label.Hit = hit
		label.NextRight = 0

		local function fit()
			local nameX = label.HasToggle and 24 or 2
			local rightWidth = right.AbsoluteSize.X
			nameLabel.Position = UDim2.fromOffset(nameX, 0)
			nameLabel.Size = UDim2.new(1, -(nameX + rightWidth + 6), 1, 0)
			hit.Size = UDim2.new(1, -(rightWidth + 4), 1, 0)
		end

		label.Fit = fit
		bind(right:GetPropertyChangedSignal("AbsoluteSize"), fit)
		fit()

		function label:SetVisible(visible)
			row.Visible = visible and true or false
		end

		function label:ToolTip(text)
			attachTooltip(row, tostring(text))
			return self
		end

		function label:SetText(text)
			nameLabel.Text = tostring(text)
		end

		-- a small control on the right of the first line
		local function addRight(instance)
			label.NextRight += 1
			instance.LayoutOrder = label.NextRight
			instance.Parent = right
			return instance
		end

		-- a full-width control on its own line under the name
		local function addBody(instance)
			instance.LayoutOrder = 1 + #row:GetChildren()
			instance.Parent = row
			return instance
		end

		---------- toggle ----------
		function label:AddToggle(config)
			config = process(config, { Default = false, Flag = nil, Callback = function() end })

			local item = newItem(label, config.Flag, "toggle")
			local value = config.Default and true or false

			label.HasToggle = true

			local box = new("Frame", {
				Name = "Box",
				BackgroundColor3 = value and ACCENT or OFF_COLOR,
				BorderSizePixel = 0,
				Position = UDim2.fromOffset(2, 3),
				Size = UDim2.fromOffset(15, 15),
			}, head)
			new("UIStroke", { Color = Color3.fromRGB(0, 0, 0), Transparency = 0.6, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, box)
			fit()

			local function draw()
				box.BackgroundColor3 = value and ACCENT or OFF_COLOR
			end

			function item:GetValue()
				return value
			end

			function item:SetValue(newValue)
				value = newValue and true or false
				draw()
				config.Callback(value)
			end

			hit.MouseButton1Click:Connect(function()
				value = not value
				draw()
				config.Callback(value)
			end)

			item.Box = box

			return item
		end

		---------- slider ----------
		function label:AddSlider(config)
			config = process(config, { Default = 50, Min = 0, Max = 10, Type = "", Rounding = 0, Nums = {}, Flag = nil, Size = 125, Callback = function() end })

			local item = newItem(label, config.Flag, "slider")
			local value = config.Default
			local span = config.Max - config.Min
			if span == 0 then
				span = 1
			end

			-- the number is a box: click it and type the exact value (1.1, 0.1 ...), Enter applies it
			local valueLabel = new("TextBox", {
				Name = "Value",
				BackgroundTransparency = 1,
				ClearTextOnFocus = false,
				Size = UDim2.fromOffset(44, 18),
				AutomaticSize = Enum.AutomaticSize.X,
				Font = FONT,
				TextColor3 = MUTED_COLOR,
				TextSize = 15,
				TextXAlignment = Enum.TextXAlignment.Right,
			}, nil)
			addRight(valueLabel)

			local barHolder = new("Frame", {
				Name = "Slider",
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, -4, 0, 12),
			}, nil)
			addBody(barHolder)

			local bar = new("TextButton", {
				Name = "Bar",
				AutoButtonColor = false,
				BackgroundColor3 = OFF_COLOR,
				BorderSizePixel = 0,
				Position = UDim2.fromOffset(2, 1),
				Size = UDim2.new(1, -4, 0, 10),
				Text = "",
			}, barHolder)
			local fill = new("Frame", {
				Name = "Fill",
				BackgroundColor3 = ACCENT,
				BorderSizePixel = 0,
				Size = UDim2.new(0, 0, 1, 0),
			}, bar)

			local function display()
				local number = tonumber(value) or config.Min
				local word = config.Nums and (config.Nums[number] or config.Nums[tostring(number)])
				valueLabel.Text = word and tostring(word) or (formatNumber(number, config.Rounding) .. tostring(config.Type or ""))
				fill.Size = UDim2.new(math.clamp((number - config.Min) / span, 0, 1), 0, 1, 0)
			end

			display()

			valueLabel.Focused:Connect(function()
				valueLabel.Text = formatNumber(tonumber(value) or config.Min, config.Rounding)
				valueLabel.TextColor3 = TEXT_COLOR
			end)

			valueLabel.FocusLost:Connect(function()
				valueLabel.TextColor3 = MUTED_COLOR
				local typed = tonumber(string.match(valueLabel.Text, "%-?%d*%.?%d+"))

				if typed then
					local typedValue = roundTo(math.clamp(typed, config.Min, config.Max), config.Rounding)
					local changed = typedValue ~= value
					value = typedValue
					display()

					-- typing the number that is already there is not a change
					if changed then
						config.Callback(value)
					end
				else
					display()
				end
			end)

			local function fromInput(input)
				local fraction = math.clamp((input.Position.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
				local newValue = roundTo(config.Min + span * fraction, config.Rounding)

				-- The mouse moves many times between two values: the listeners only hear about a value that is new.
				if newValue == value then
					return
				end

				value = newValue
				display()
				config.Callback(value)
			end

			local holding = false

			local function onDrag(input)
				if holding and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
					fromInput(input)
				end
			end

			bar.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					holding = true
					setDragger(onDrag, true)
					closeOverlay()
					fromInput(input)
				end
			end)

			bind(UserInputService.InputEnded, function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					holding = false
					setDragger(onDrag, false)
				end
			end)

			function item:GetValue()
				return value
			end

			function item:SetValue(newValue)
				-- a value outside the range (a config saved before the range changed, or edited by hand) is held at the nearest end
				if type(newValue) == "number" then
					newValue = math.clamp(newValue, math.min(config.Min, config.Max), math.max(config.Min, config.Max))
				end

				value = newValue
				display()
				config.Callback(value)
			end

			return item
		end

		---------- dropdown ----------
		function label:AddDropdown(config)
			config = process(config, { Default = nil, Multi = false, Values = {}, Flag = nil, AutoUpdate = false, Size = 100, Callback = function() end })

			local item = newItem(label, config.Flag, "dropdown")
			local values = config.Values

			-- A multi dropdown keeps its picks as { [name] = true }; an array default is turned into that form.
			local function normalize(input)
				if config.Multi then
					local map = {}

					if type(input) == "table" then
						for key, picked in pairs(input) do
							if type(key) == "number" then
								map[tostring(picked)] = true
							elseif picked then
								map[key] = true
							end
						end
					elseif input ~= nil then
						map[tostring(input)] = true
					end

					return map
				end

				if type(input) == "table" then
					for key, picked in pairs(input) do
						if type(key) == "number" then
							return picked
						elseif picked then
							return key
						end
					end

					return nil
				end

				return input
			end

			local value = normalize(config.Default)

			local box = new("TextButton", {
				Name = "Dropdown",
				AutoButtonColor = false,
				BackgroundColor3 = BOX_COLOR,
				BorderColor3 = OFF_COLOR,
				BorderSizePixel = 1,
				Size = UDim2.new(1, -4, 0, 20),
				Text = "",
			}, nil)
			addBody(box)

			local boxText = new("TextLabel", {
				BackgroundTransparency = 1,
				Position = UDim2.fromOffset(6, 0),
				Size = UDim2.new(1, -24, 1, 0),
				Font = FONT,
				TextColor3 = TEXT_COLOR,
				TextSize = 15,
				TextTruncate = Enum.TextTruncate.AtEnd,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, box)
			local arrow = new("TextLabel", {
				AnchorPoint = Vector2.new(1, 0.5),
				BackgroundTransparency = 1,
				Position = UDim2.new(1, -5, 0.5, 0),
				Size = UDim2.fromOffset(12, 12),
				Font = FONT,
				Text = "v",
				TextColor3 = MUTED_COLOR,
				TextSize = 14,
			}, box)

			local function picked(name)
				if config.Multi then
					return value[name] == true
				end

				return value == name
			end

			local function describe()
				if config.Multi then
					local names = {}

					for _, name in ipairs(values) do
						if value[tostring(name)] then
							table.insert(names, tostring(name))
						end
					end

					return #names == 0 and "None" or table.concat(names, ", ")
				end

				return value == nil and "None" or tostring(value)
			end

			-- The options open right under the box and push the rows below them down; nothing floats over the menu. A multi dropdown
			-- keeps its box showing the picks and each option under it is a switch; a single one closes after a pick.
			local listHolder = nil
			local holderOrder = nil
			local isOpen = false
			local rowButtons = {}
			local MAX_SHOWN = 10

			-- Search = true puts a box at the top of the list that narrows it as you type. Describe(key) is the text of a row (and what the search is
			-- matched against, so a row can carry a display name next to the key); the picked value stays the key.
			local searchText = ""

			local function applyFilter()
				if not config.Search then
					return
				end

				local needle = string.lower(searchText)

				for _, entry in pairs(rowButtons) do
					entry.Button.Visible = needle == "" or string.find(string.lower(entry.Label), needle, 1, true) ~= nil
				end
			end

			local function paintRows()
				for name, entry in pairs(rowButtons) do
					local on = picked(name)
					entry.Text.TextColor3 = on and ACCENT or TEXT_COLOR

					if config.Multi then
						entry.Mark.BackgroundColor3 = on and ACCENT or OFF_COLOR
					end
				end
			end

			local function close()
				isOpen = false
				arrow.Text = "v"

				if listHolder then
					listHolder.Visible = false
				end
			end

			local function build()
				if listHolder then
					listHolder.Destroy(listHolder)
				end

				rowButtons = {}

				local shown = math.min(math.max(#values, 1), MAX_SHOWN)
				local scrolls = #values > MAX_SHOWN

				local props = {
					Name = "Options",
					BackgroundColor3 = POPUP_COLOR,
					BorderColor3 = OFF_COLOR,
					BorderSizePixel = 1,
					Size = UDim2.new(1, -4, 0, shown * 20 + 2 + (config.Search and 22 or 0)),
					Visible = isOpen,
				}

				if scrolls then
					props.Active = true
					props.AutomaticCanvasSize = Enum.AutomaticSize.Y
					props.CanvasSize = UDim2.new()
					props.ScrollBarImageColor3 = ACCENT
					props.ScrollBarThickness = 3
				end

				listHolder = new(scrolls and "ScrollingFrame" or "Frame", props, nil)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, listHolder)

				-- the first time the list takes the place right after the box; a rebuild keeps that place
				if holderOrder then
					listHolder.LayoutOrder = holderOrder
					listHolder.Parent = row
				else
					addBody(listHolder)
					holderOrder = listHolder.LayoutOrder
				end

				if config.Search then
					local searchBox = new("TextBox", {
						Name = "Search",
						BackgroundColor3 = BOX_COLOR,
						BorderSizePixel = 0,
						ClearTextOnFocus = false,
						Font = FONT,
						LayoutOrder = 0,
						PlaceholderColor3 = MUTED_COLOR,
						PlaceholderText = "search name or display name",
						Size = UDim2.new(1, scrolls and -4 or 0, 0, 22),
						Text = searchText,
						TextColor3 = TEXT_COLOR,
						TextSize = 15,
						TextXAlignment = Enum.TextXAlignment.Left,
					}, listHolder)
					new("UIPadding", { PaddingLeft = UDim.new(0, 8) }, searchBox)

					-- (in some servers GetPropertyChangedSignal("Text") comes back as nil here, which broke the whole list: Changed is used then)
					-- (This list is rebuilt from the Target List's refresh, which can run while method calls are garbled, so ":Connect" and
					-- ":GetPropertyChangedSignal" failed there in big servers; the methods are called through the dot instead, which avoids that.)
					local textSignal = searchBox.GetPropertyChangedSignal(searchBox, "Text")
					local function onSearch()
						searchText = searchBox.Text
						applyFilter()
					end

					if textSignal then
						textSignal.Connect(textSignal, onSearch)
					else
						searchBox.Changed.Connect(searchBox.Changed, function(property)
							if property == "Text" then
								onSearch()
							end
						end)
					end
				end

				for order, name in ipairs(values) do
					local key = tostring(name)
					local rowLabel = config.Describe and tostring(config.Describe(key)) or key
					local button = new("TextButton", {
						AutoButtonColor = false,
						BackgroundColor3 = BOX_COLOR,
						BackgroundTransparency = 1,
						BorderSizePixel = 0,
						LayoutOrder = order,
						Size = UDim2.new(1, scrolls and -4 or 0, 0, 20),
						Text = "",
					}, listHolder)
					local text = new("TextLabel", {
						BackgroundTransparency = 1,
						Position = UDim2.fromOffset(config.Multi and 22 or 8, 0),
						Size = UDim2.new(1, config.Multi and -28 or -14, 1, 0),
						Font = FONT,
						Text = rowLabel,
						TextColor3 = TEXT_COLOR,
						TextSize = 15,
						TextTruncate = Enum.TextTruncate.AtEnd,
						TextXAlignment = Enum.TextXAlignment.Left,
					}, button)
					local mark = new("Frame", {
						AnchorPoint = Vector2.new(0, 0.5),
						BackgroundColor3 = OFF_COLOR,
						BorderSizePixel = 0,
						Position = UDim2.new(0, 6, 0.5, 0),
						Size = UDim2.fromOffset(10, 10),
						Visible = config.Multi and true or false,
					}, button)

					rowButtons[key] = { Text = text, Mark = mark, Button = button, Label = rowLabel }

					button.MouseEnter.Connect(button.MouseEnter, function()
						button.BackgroundTransparency = 0.5
					end)
					button.MouseLeave.Connect(button.MouseLeave, function()
						button.BackgroundTransparency = 1
					end)
					button.MouseButton1Click.Connect(button.MouseButton1Click, function()
						if config.Multi then
							value[key] = not value[key] or nil
							boxText.Text = describe()
							paintRows()
							config.Callback(value)
						else
							value = name
							boxText.Text = describe()
							paintRows()
							close()
							config.Callback(value)
						end
					end)
				end

				paintRows()
				applyFilter()
			end

			build()
			boxText.Text = describe()

			box.MouseButton1Click.Connect(box.MouseButton1Click, function()
				if isOpen then
					close()
					return
				end

				if config.AutoUpdate then
					build()
				end

				isOpen = true
				arrow.Text = "^"
				listHolder.Visible = true
				paintRows()
			end)

			function item:GetValue()
				return value
			end

			function item:SetValue(newValue)
				value = normalize(newValue)
				boxText.Text = describe()
				paintRows()
				config.Callback(value)
			end

			function item:SetValues(newValues)
				values = newValues
				config.Values = newValues
				build()
				boxText.Text = describe()
			end

			return item
		end

		---------- keybind ----------
		function label:AddKeybind(config)
			config = process(config, { Default = "None", Flag = nil, Blacklist = nil, Callback = function() end })

			local item = newItem(label, config.Flag, "keybind")
			local value = config.Default == nil and "None" or (typeof(config.Default) == "EnumItem" and config.Default.Name or tostring(config.Default))

			local button = new("TextButton", {
				Name = "Keybind",
				AutoButtonColor = false,
				BackgroundColor3 = OFF_COLOR,
				BorderSizePixel = 0,
				Size = UDim2.fromOffset(40, 16),
				Font = FONT,
				Text = "",
				TextColor3 = TEXT_COLOR,
				TextSize = 14,
			}, nil)
			addRight(button)

			local function draw(listening)
				local text = listening and "..." or ("[" .. keyCodeName(value) .. "]")
				button.Text = text
				button.Size = UDim2.fromOffset(textWidth(text, 14) + 10, 16)
			end

			draw(false)

			local function blocked(key)
				local list = config.Blacklist
				return list and (list[key] or table.find(list, key)) and true or false
			end

			local listening = false

			button.MouseButton1Click:Connect(function()
				if listening then
					return
				end

				listening = true
				draw(true)
				Lib.KeyCaptures += 1

				local connection

				-- Ends the listening. The capture still counts for a moment after the key was taken: the other listeners of the same key press
				-- have to see it too, or the key picked here would also press whatever is bound to it.
				local function finish(redraw)
					if not listening then
						return
					end

					listening = false
					captures[finish] = nil
					connection:Disconnect()

					local at = table.find(connections, connection)
					if at then
						table.remove(connections, at)
					end

					task.defer(function()
						Lib.KeyCaptures = math.max(Lib.KeyCaptures - 1, 0)
					end)

					if redraw then
						draw(false)
					end
				end

				captures[finish] = true

				connection = bind(UserInputService.InputBegan, function(input)
					local picked = nil

					if input.KeyCode ~= Enum.KeyCode.Unknown then
						if input.KeyCode == Enum.KeyCode.Escape then
							picked = "None"
						elseif not blocked(input.KeyCode.Name) then
							picked = input.KeyCode.Name
						end
					elseif input.UserInputType == Enum.UserInputType.MouseButton2 and not blocked("M2B") then
						picked = "M2B"
					elseif input.UserInputType == Enum.UserInputType.MouseButton3 and not blocked("M3B") then
						picked = "M3B"
					end

					if picked then
						finish(false)
						value = picked
						draw(false)
						config.Callback(value)
					end
				end)
			end)

			function item:GetValue()
				return value
			end

			function item:SetValue(newValue)
				value = newValue == nil and "None" or (typeof(newValue) == "EnumItem" and newValue.Name or tostring(newValue))
				draw(false)
				config.Callback(value)
			end

			return item
		end

		---------- colour picker ----------
		function label:AddColorPicker(config)
			config = process(config, { Default = Color3.new(1, 1, 1), Flag = nil, Callback = function() end, Transparency = nil, TransparencyFlag = nil, TransparencyCallback = function() end })

			local item = newItem(label, config.Flag, "color")

			-- With a transparency the popup gets a bar for it: left is see-through, right is solid; the value is kept as a transparency (0 = solid)
			local hasAlpha = config.Transparency ~= nil
			local transparency = math.clamp(tonumber(config.Transparency) or 0, 0, 1)
			local alphaItem = hasAlpha and newItem(label, config.TransparencyFlag, "slider") or nil
			local popupHeight = hasAlpha and 194 or 170

			local function toColor(input)
				if typeof(input) == "Color3" then
					return input
				elseif type(input) == "string" then
					local ok, color = pcall(Color3.fromHex, input)
					if ok then
						return color
					end
				elseif type(input) == "table" and input.R then
					return Color3.new(input.R, input.G, input.B)
				end

				return Color3.new(1, 1, 1)
			end

			local color = toColor(config.Default)
			local hue, saturation, brightness = color:ToHSV()

			local swatch = new("TextButton", {
				Name = "Color",
				AutoButtonColor = false,
				BackgroundColor3 = color,
				BorderColor3 = Color3.fromRGB(0, 0, 0),
				BorderSizePixel = 1,
				Size = UDim2.fromOffset(24, 12),
				Text = "",
			}, nil)
			addRight(swatch)

			local popup = nil
			local square, squareDot, hueBar, hueDot, hexBox, alphaHolder, alphaBar, alphaDot

			local function apply(fire)
				local previous = color
				color = Color3.fromHSV(hue, saturation, brightness)
				swatch.BackgroundColor3 = color

				if square then
					square.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
					squareDot.Position = UDim2.new(saturation, 0, 1 - brightness, 0)
					hueDot.Position = UDim2.new(0.5, 0, hue, 0)
					hexBox.Text = "#" .. color:ToHex()

					if alphaBar then
						alphaBar.BackgroundColor3 = color
						alphaDot.Position = UDim2.new(1 - transparency, 0, 0.5, 0)
					end
				end

				-- dragging over the colour that is already set is not a change
				if fire and color ~= previous then
					config.Callback(color)
				end
			end

			local function close()
				if popup then
					popup.Visible = false
				end
			end

			local function build()
				popup = new("Frame", {
					Name = randomName(),
					BackgroundColor3 = POPUP_COLOR,
					BorderColor3 = OFF_COLOR,
					BorderSizePixel = 1,
					Size = UDim2.fromOffset(190, popupHeight),
					Visible = false,
					ZIndex = 2000,
				}, gui)

				square = new("Frame", {
					BackgroundColor3 = Color3.fromHSV(hue, 1, 1),
					BorderSizePixel = 0,
					Position = UDim2.fromOffset(8, 8),
					Size = UDim2.fromOffset(150, 130),
					ZIndex = 2001,
				}, popup)
				local white = new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 2002 }, square)
				new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }) }, white)
				local black = new("Frame", { BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 2003 }, square)
				new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }, black)
				squareDot = new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderColor3 = Color3.new(0, 0, 0),
					Size = UDim2.fromOffset(6, 6),
					ZIndex = 2005,
				}, square)

				hueBar = new("Frame", {
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderSizePixel = 0,
					Position = UDim2.fromOffset(166, 8),
					Size = UDim2.fromOffset(16, 130),
					ZIndex = 2001,
				}, popup)
				new("UIGradient", {
					Rotation = 90,
					Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)),
						ColorSequenceKeypoint.new(0.17, Color3.fromHSV(0.17, 1, 1)),
						ColorSequenceKeypoint.new(0.33, Color3.fromHSV(0.33, 1, 1)),
						ColorSequenceKeypoint.new(0.5, Color3.fromHSV(0.5, 1, 1)),
						ColorSequenceKeypoint.new(0.67, Color3.fromHSV(0.67, 1, 1)),
						ColorSequenceKeypoint.new(0.83, Color3.fromHSV(0.83, 1, 1)),
						ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
					}),
				}, hueBar)
				hueDot = new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderColor3 = Color3.new(0, 0, 0),
					Size = UDim2.new(1, 4, 0, 4),
					ZIndex = 2005,
				}, hueBar)

				hexBox = new("TextBox", {
					BackgroundColor3 = BOX_COLOR,
					BorderColor3 = OFF_COLOR,
					BorderSizePixel = 1,
					ClearTextOnFocus = false,
					Font = FONT,
					Position = UDim2.fromOffset(8, 144),
					Size = UDim2.fromOffset(174, 20),
					Text = "#" .. color:ToHex(),
					TextColor3 = TEXT_COLOR,
					TextSize = 15,
					ZIndex = 2001,
				}, popup)

				if hasAlpha then
					alphaHolder = new("Frame", {
						BackgroundColor3 = Color3.fromRGB(60, 60, 60),
						BorderSizePixel = 0,
						Position = UDim2.fromOffset(8, 170),
						Size = UDim2.fromOffset(174, 14),
						ZIndex = 2001,
					}, popup)
					alphaBar = new("Frame", { BackgroundColor3 = color, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 2002 }, alphaHolder)
					new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }, alphaBar)
					alphaDot = new("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						BackgroundColor3 = Color3.new(1, 1, 1),
						BorderColor3 = Color3.new(0, 0, 0),
						Size = UDim2.new(0, 4, 1, 4),
						ZIndex = 2005,
					}, alphaHolder)
				end

				hexBox.FocusLost:Connect(function()
					local ok, parsed = pcall(Color3.fromHex, (hexBox.Text:gsub("#", "")))
					if ok then
						hue, saturation, brightness = parsed:ToHSV()
						apply(true)
					else
						hexBox.Text = "#" .. color:ToHex()
					end
				end)

				local dragging = nil

				square.InputBegan:Connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 then
						dragging = "square"
					end
				end)
				hueBar.InputBegan:Connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 then
						dragging = "hue"
					end
				end)
				if alphaHolder then
					alphaHolder.InputBegan:Connect(function(input)
						if input.UserInputType == Enum.UserInputType.MouseButton1 then
							dragging = "alpha"
						end
					end)
				end

				local function drag(input)
					if dragging == "square" then
						saturation = math.clamp((input.Position.X - square.AbsolutePosition.X) / square.AbsoluteSize.X, 0, 1)
						brightness = 1 - math.clamp((input.Position.Y - square.AbsolutePosition.Y) / square.AbsoluteSize.Y, 0, 1)
						apply(true)
					elseif dragging == "hue" then
						hue = math.clamp((input.Position.Y - hueBar.AbsolutePosition.Y) / hueBar.AbsoluteSize.Y, 0, 1)
						apply(true)
					elseif dragging == "alpha" and alphaHolder then
						local newTransparency = 1 - math.clamp((input.Position.X - alphaHolder.AbsolutePosition.X) / alphaHolder.AbsoluteSize.X, 0, 1)

						if newTransparency ~= transparency then
							transparency = newTransparency
							apply(false)
							config.TransparencyCallback(transparency)
						end
					end
				end

				square.InputBegan:Connect(drag)
				hueBar.InputBegan:Connect(drag)
				if alphaHolder then
					alphaHolder.InputBegan:Connect(drag)
				end
				bind(UserInputService.InputChanged, function(input)
					if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
						drag(input)
					end
				end)
				bind(UserInputService.InputEnded, function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 then
						dragging = nil
					end
				end)

				apply(false)
			end

			swatch.MouseButton1Click:Connect(function()
				if popup and popup.Visible then
					closeOverlay()
					return
				end

				if not popup then
					build()
				end

				placeBelow(popup, swatch, 190)
				popup.Visible = true
				openOverlay(close, swatch)
			end)

			function item:GetValue()
				return color
			end

			function item:SetValue(newValue)
				color = toColor(newValue)
				hue, saturation, brightness = color:ToHSV()
				apply(false)
				config.Callback(color)
			end

			if alphaItem then
				function alphaItem:GetValue()
					return transparency
				end

				function alphaItem:SetValue(newValue)
					transparency = math.clamp(tonumber(newValue) or 0, 0, 1)
					apply(false)
					config.TransparencyCallback(transparency)
				end
			end

			return item
		end

		---------- text input ----------
		function label:AddTextInput(config)
			config = process(config, { Default = "", Placeholder = "", Flag = nil, Size = 100, Numeric = false, Callback = function() end })

			local item = newItem(label, config.Flag, "text")
			local value = config.Default

			local box = new("TextBox", {
				Name = "Input",
				BackgroundColor3 = BOX_COLOR,
				BorderColor3 = OFF_COLOR,
				BorderSizePixel = 1,
				ClearTextOnFocus = false,
				Font = FONT,
				PlaceholderText = tostring(config.Placeholder or ""),
				PlaceholderColor3 = Color3.fromRGB(110, 110, 110),
				Size = UDim2.new(1, -4, 0, 20),
				Text = tostring(value or ""),
				TextColor3 = TEXT_COLOR,
				TextSize = 15,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, nil)
			new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6) }, box)
			addBody(box)

			local function parse(text)
				if config.Numeric then
					text = text:gsub("[^0-9.%-]", "")
					return tonumber(text)
				end

				return text
			end

			box.FocusLost:Connect(function()
				local parsed = parse(box.Text)

				if parsed ~= nil then
					value = parsed
					config.Callback(value)
				end
			end)

			function item:GetValue()
				return value
			end

			function item:SetValue(newValue)
				value = newValue
				box.Text = tostring(newValue)
				config.Callback(value)
			end

			return item
		end

		---------- button ----------
		function label:AddButton(config)
			config = process(config, { Name = name, Callback = function() end })

			local button = new("TextButton", {
				Name = "Button",
				AutoButtonColor = false,
				BackgroundColor3 = OFF_COLOR,
				BorderSizePixel = 0,
				Font = FONT,
				Size = UDim2.new(1, -4, 0, 20),
				Text = tostring(config.Name),
				TextColor3 = TEXT_COLOR,
				TextSize = 15,
			}, nil)
			addBody(button)

			button.MouseEnter:Connect(function()
				button.BackgroundColor3 = Color3.fromRGB(78, 78, 78)
			end)
			button.MouseLeave:Connect(function()
				button.BackgroundColor3 = OFF_COLOR
			end)
			button.MouseButton1Click:Connect(function()
				config.Callback()
			end)

			return { Root = button, SetVisible = function(_, visible) button.Visible = visible and true or false end }
		end

		---------- gear: the settings of a row, opened right under it ----------
		-- A line sits under the row. Opening the gear puts the row's settings between the row and the line, and the line moves down.
		function label:AddOption()
			local option = { Controls = 0 }

			local gear = new("TextButton", {
				Name = "Gear",
				AutoButtonColor = false,
				BackgroundColor3 = OFF_COLOR,
				BorderSizePixel = 0,
				Font = FONT,
				Size = UDim2.fromOffset(20, 16),
				Text = "...",
				TextColor3 = TEXT_COLOR,
				TextSize = 14,
			}, nil)
			addRight(gear)

			-- both keep the last places of the row, whatever is added to it later
			local holder = new("Frame", {
				Name = "Settings",
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundColor3 = POPUP_COLOR,
				BorderSizePixel = 0,
				LayoutOrder = 999998,
				Size = UDim2.new(1, -4, 0, 0),
				Visible = false,
			}, row)
			new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, holder)
			new("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 4), PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4) }, holder)

			local rule = new("Frame", {
				Name = "Line",
				BackgroundColor3 = OFF_COLOR,
				BorderSizePixel = 0,
				LayoutOrder = 999999,
				Size = UDim2.new(1, -4, 0, 1),
			}, row)

			local open = false

			local function setOpen(state)
				open = state and true or false
				holder.Visible = open
				gear.BackgroundColor3 = open and ACCENT or OFF_COLOR
				gear.TextColor3 = open and Color3.fromRGB(20, 20, 20) or TEXT_COLOR
			end

			gear.MouseButton1Click:Connect(function()
				setOpen(not open)
			end)

			local order = 0
			option.Body = holder
			option.NextOrder = function()
				order += 1
				return order
			end
			option.Root = holder
			option.SetOpen = setOpen

			function option:AddLabel(labelName)
				return makeLabel(option, labelName)
			end

			function option:AddButton(buttonConfig)
				local inner = makeLabel(option, "")
				return inner:AddButton(buttonConfig)
			end

			function option:SetVisible(visible)
				option.Hidden = not visible
				gear.Visible = visible and true or false
				rule.Visible = visible and true or false

				if not visible then
					setOpen(false)
				end
			end

			return option
		end

		owner.Rows = owner.Rows or {}
		table.insert(owner.Rows, label)

		-- Written down for the Visions look: the row, and every control put on it (its kind, its settings and its item); a gear's own rows go
		-- under its control. The look reads and writes the same items, so nothing here changes what the classic menu does.
		label.Record = { Name = name, Label = label, Row = row, Controls = {} }
		if owner.Record then
			table.insert(owner.Record.Rows, label.Record)
		end

		for _, method in ipairs({ "AddToggle", "AddSlider", "AddDropdown", "AddKeybind", "AddColorPicker", "AddTextInput", "AddButton", "AddOption" }) do
			local original = label[method]

			label[method] = function(self, config, ...)
				local result = original(self, config, ...)
				local control = { Kind = method, Config = type(config) == "table" and config or {}, Item = result }

				if method == "AddOption" and type(result) == "table" then
					result.Record = { Rows = {} }
					control.Option = result.Record
				end

				table.insert(label.Record.Controls, control)
				return result
			end
		end

		return label
	end

	---------- notifications, logger ------------
	local toastCount = 0

	local function toast(title, content, duration)
		if not gui then
			return
		end

		toastCount += 1
		local index = toastCount

		-- drawn like the menu that is picked: the classic one (square, the gradient line on top) or the Visions one (rounded, dark, a red
		-- line down the left, Gotham)
		local visionsLook = Lib.GetMenuStyle and Lib:GetMenuStyle() == "visions"

		local frame = new("Frame", {
			Name = randomName(),
			AnchorPoint = Vector2.new(1, 1),
			AutomaticSize = Enum.AutomaticSize.XY,
			BackgroundColor3 = visionsLook and Color3.fromRGB(24, 24, 24) or MENU_COLOR,
			BorderColor3 = LINE_COLOR,
			BorderSizePixel = visionsLook and 0 or 1,
			Position = UDim2.new(1, 260, 1, -14),
			Size = UDim2.fromOffset(200, 24),
			ZIndex = 4000,
		}, gui)
		new("UISizeConstraint", { MaxSize = Vector2.new(340, math.huge) }, frame)

		if visionsLook then
			new("UICorner", { CornerRadius = UDim.new(0, 5) }, frame)
			new("UIStroke", { Color = Color3.fromRGB(44, 44, 44), Thickness = 1 }, frame)
			new("UIPadding", { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 12), PaddingTop = UDim.new(0, 7), PaddingBottom = UDim.new(0, 7) }, frame)
			local bar = new("Frame", { BackgroundColor3 = Lib:Accent(), BorderSizePixel = 0, Position = UDim2.new(0, -9, 0, 1), Size = UDim2.new(0, 2, 1, -2), ZIndex = 4001 }, frame)
			new("UICorner", { CornerRadius = UDim.new(0, 1) }, bar)
		else
			new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5) }, frame)
			local bar = new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 2), Position = UDim2.fromOffset(0, -1), ZIndex = 4001 }, frame)
			new("UIGradient", { Color = GRADIENT }, bar)
		end

		new("TextLabel", {
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.XY,
			Font = visionsLook and Enum.Font.Gotham or FONT,
			RichText = false,
			Size = UDim2.fromOffset(10, 14),
			Text = (title and title ~= "" and (title .. "  ") or "") .. tostring(content or ""),
			TextColor3 = visionsLook and Color3.fromRGB(235, 235, 235) or TEXT_COLOR,
			TextSize = visionsLook and 13 or 16,
			TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 4001,
		}, frame)

		-- stack above the ones already showing
		local others = {}
		for _, child in ipairs(gui:GetChildren()) do
			if child:GetAttribute("Toast") then
				table.insert(others, child)
			end
		end
		frame:SetAttribute("Toast", true)

		local offset = 14
		for _, other in ipairs(others) do
			offset += other.AbsoluteSize.Y + 6
		end
		frame.Position = UDim2.new(1, 260, 1, -offset)

		TweenService:Create(frame, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Position = UDim2.new(1, -14, 1, -offset) }):Play()

		task.delay(duration or 4, function()
			if frame.Parent then
				local tween = TweenService:Create(frame, TweenInfo.new(0.25), { Position = UDim2.new(1, 260, 1, frame.Position.Y.Offset) })
				tween:Play()
				tween.Completed:Wait()
				frame:Destroy()
			end
		end)

		return index
	end

	function Lib:CreateNotification()
		local notification = {}

		function notification.new(config)
			config = type(config) == "table" and config or {}
			return toast(config.Title, config.Content, config.Duration)
		end

		return notification
	end

	function Lib:CreateLogger()
		local logger = {}

		function logger.new(_, text, duration)
			return toast("", text, duration)
		end

		return logger
	end

	---------- the window ------------
	function Lib:CreateWindow(config)
		config = process(config, { Name = "menu", Content = "", Size = Lib.Scales.Default, ConfigFolder = "JujuConfigs", Keybind = "Insert" })

		if gui then
			pcall(function()
				gui:Destroy()
			end)
		end

		local parent = (type(gethui) == "function" and gethui()) or CoreGui
		gui = new("ScreenGui", {
			Name = randomName(),
			DisplayOrder = 99999,
			IgnoreGuiInset = true,
			ResetOnSpawn = false,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		})

		pcall(function()
			if syn and syn.protect_gui then
				syn.protect_gui(gui)
			end
		end)

		local okParent = pcall(function()
			gui.Parent = parent
		end)
		if not okParent then
			gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
		end

		Lib.ScreenGui = gui

		local window = {
			Name = config.Name,
			Keybind = config.Keybind,
			ConfigFolder = config.ConfigFolder,
			Signal = newSignal(true),
			Tabs = {},
		}
		Lib.Window = window
		Lib.MenuRecord = {}

		local size = typeof(config.Size) == "Vector2" and config.Size or Lib.Scales.Default

		local panel = new("Frame", {
			Name = "Panel",
			BackgroundColor3 = PANEL_COLOR,
			BorderSizePixel = 0,
			Position = UDim2.new(0.5, -size.X / 2, 0.5, -size.Y / 2),
			Size = UDim2.fromOffset(size.X, size.Y),
			Active = true,
		}, gui)
		window.Panel = panel

		-- top strip: the gradient line, the window name, and the area the window is dragged by
		local strip = new("Frame", { Name = "Gradient", BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Position = UDim2.fromOffset(10, 18), Size = UDim2.new(1, -20, 0, 3) }, panel)
		new("UIGradient", { Color = GRADIENT }, strip)

		local dragArea = new("Frame", { Name = "Drag", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22) }, panel)
		new("TextLabel", {
			BackgroundTransparency = 1,
			Font = FONT,
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -24, 0, 16),
			Text = tostring(config.Name) .. (config.Content ~= "" and ("   |   " .. tostring(config.Content)) or ""),
			TextColor3 = MUTED_COLOR,
			TextSize = 14,
			TextXAlignment = Enum.TextXAlignment.Left,
		}, dragArea)

		local visionsButton = new("TextButton", {
			Name = "VisionsSwitch",
			AnchorPoint = Vector2.new(1, 0),
			AutoButtonColor = false,
			BackgroundColor3 = OFF_COLOR,
			BorderSizePixel = 0,
			Font = FONT,
			Position = UDim2.new(1, -10, 0, 1),
			Size = UDim2.fromOffset(52, 14),
			Text = "Visions",
			TextColor3 = TEXT_COLOR,
			TextSize = 13,
			ZIndex = 2,
		}, panel)
		visionsButton.MouseButton1Click:Connect(function()
			if Lib.SetMenuStyle then
				Lib:SetMenuStyle("visions", true)
			end
		end)

		local dragStart, panelStart = nil, nil
		dragArea.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragStart = input.Position
				panelStart = panel.Position
				closeOverlay()
			end
		end)
		bind(UserInputService.InputChanged, function(input)
			if dragStart and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
				local delta = input.Position - dragStart
				panel.Position = UDim2.new(panelStart.X.Scale, panelStart.X.Offset + delta.X, panelStart.Y.Scale, panelStart.Y.Offset + delta.Y)
			end
		end)
		bind(UserInputService.InputEnded, function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragStart = nil
			end
		end)

		local sidebar = new("Frame", { Name = "Sections", BackgroundColor3 = SIDEBAR_COLOR, BorderSizePixel = 0, Position = UDim2.fromOffset(10, 28), Size = UDim2.new(0, 110, 1, -38) }, panel)
		window.Sidebar = sidebar
		local sidebarLayout = new("UIListLayout", {
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			VerticalAlignment = Enum.VerticalAlignment.Top,
			Padding = UDim.new(0, 3),
		}, sidebar)
		new("UIPadding", { PaddingTop = UDim.new(0, 2) }, sidebar)
		new("Frame", { Name = "Line", BackgroundColor3 = LINE_COLOR, BorderSizePixel = 0, Position = UDim2.fromOffset(119, 28), Size = UDim2.new(0, 1, 1, -38) }, panel)

		local pages = new("Frame", { Name = "Pages", BackgroundTransparency = 1, Position = UDim2.fromOffset(120, 28), Size = UDim2.new(1, -130, 1, -38), ClipsDescendants = true }, panel)
		window.Pages = pages

		local tabs = window.Tabs
		local selected = nil

		local function resizeSidebar()
			local count = math.max(#tabs, 1)
			local height = math.floor((sidebar.AbsoluteSize.Y - 4 - (count - 1) * 3) / count)
			height = math.clamp(height, 44, 84)

			for _, tab in ipairs(tabs) do
				tab.Idx.Size = UDim2.fromOffset(100, height)
			end
		end
		bind(sidebar:GetPropertyChangedSignal("AbsoluteSize"), resizeSidebar)

		local function select(tab)
			selected = tab

			for _, other in ipairs(tabs) do
				local on = other == tab
				other.Page.Visible = on
				other.Idx.ImageColor3 = on and Color3.new(1, 1, 1) or Color3.fromRGB(125, 125, 125)
				other.Marker.Visible = on
				other.Signal:Fire(on)
			end

			closeOverlay()
			cancelCaptures()
		end

		function window:SelectTab(tab)
			select(tab)
		end

		function window:AddTabLabel(_)
			return { SetVisible = function() end }
		end

		function window:AddTab(tabConfig)
			tabConfig = process(tabConfig, { Name = "Tab", Icon = "", Order = nil })

			local tab = { Name = tabConfig.Name, Signal = newSignal(false) }

			-- written down for the Visions look (Lib.MenuRecord)
			tab.Record = { Name = tabConfig.Name, Tab = tab, Sections = {} }
			table.insert(Lib.MenuRecord, tab.Record)

			local iconKey = TAB_ICON_BY_NAME[string.lower(tostring(tabConfig.Name))] or "misc"
			local button = new("ImageButton", {
				Name = tostring(tabConfig.Name),
				AutoButtonColor = false,
				BackgroundColor3 = Color3.new(0, 0, 0),
				BorderSizePixel = 0,
				Image = TAB_ICONS[iconKey],
				ImageColor3 = Color3.fromRGB(125, 125, 125),
				LayoutOrder = tabConfig.Order or (#tabs + 1),
				ScaleType = Enum.ScaleType.Crop,
				Size = UDim2.fromOffset(100, 70),
			}, sidebar)
			new("TextLabel", {
				AnchorPoint = Vector2.new(0.5, 1),
				BackgroundTransparency = 1,
				Font = FONT,
				Position = UDim2.new(0.5, 0, 1, -3),
				Size = UDim2.new(1, -6, 0, 16),
				Text = tostring(tabConfig.Name),
				TextColor3 = TEXT_COLOR,
				TextSize = 15,
				TextStrokeTransparency = 0.4,
				ZIndex = 2,
			}, button)
			local marker = new("Frame", { BackgroundColor3 = ACCENT, BorderSizePixel = 0, Size = UDim2.new(0, 3, 1, 0), Visible = false, ZIndex = 3 }, button)

			local page = new("Frame", {
				Name = tostring(tabConfig.Name) .. "Menu",
				BackgroundColor3 = MENU_COLOR,
				BorderColor3 = LINE_COLOR,
				BorderSizePixel = 1,
				Size = UDim2.fromScale(1, 1),
				Visible = false,
			}, pages)

			local function column(position, offset)
				local scroll = new("ScrollingFrame", {
					Active = true,
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					CanvasSize = UDim2.new(),
					AutomaticCanvasSize = Enum.AutomaticSize.Y,
					Position = UDim2.new(position, offset, 0, 14),
					ScrollBarImageColor3 = ACCENT,
					ScrollBarThickness = 3,
					Size = UDim2.new(0.5, -27, 1, -28),
				}, page)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10) }, scroll)
				new("UIPadding", { PaddingRight = UDim.new(0, 6) }, scroll)
				return scroll
			end

			local left = column(0, 18)
			local right = column(0.5, 9)

			tab.Idx = button
			tab.Page = page
			tab.Content = page
			tab.Marker = marker
			tab.Left = left
			tab.Right = right
			tab.Window = window

			local sectionOrder = { Left = 0, Right = 0 }

			function tab:AddSection(sectionConfig)
				sectionConfig = process(sectionConfig, { Name = "SECTION", Position = "left" })

				local isLeft = string.lower(tostring(sectionConfig.Position)) ~= "right"
				local columnFrame = isLeft and left or right
				local key = isLeft and "Left" or "Right"
				sectionOrder[key] += 1

				local container = new("Frame", {
					Name = randomName(),
					AutomaticSize = Enum.AutomaticSize.Y,
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					LayoutOrder = sectionOrder[key],
					Size = UDim2.new(1, 0, 0, 20),
				}, columnFrame)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, container)

				new("TextLabel", {
					BackgroundTransparency = 1,
					Font = FONT,
					LayoutOrder = 0,
					Size = UDim2.new(1, 0, 0, 16),
					Text = " " .. tostring(sectionConfig.Name),
					TextColor3 = TEXT_COLOR,
					TextSize = 16,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, container)

				local body = new("Frame", {
					Name = "Body",
					AutomaticSize = Enum.AutomaticSize.Y,
					BackgroundColor3 = MENU_COLOR,
					BorderColor3 = LINE_COLOR,
					BorderSizePixel = 1,
					LayoutOrder = 1,
					Size = UDim2.new(1, 0, 0, 20),
				}, container)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3) }, body)
				new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 8) }, body)

				local order = 0
				local section = {
					Root = container,
					Body = body,
					NextOrder = function()
						order += 1
						return order
					end,
				}

				section.Record = { Name = sectionConfig.Name, Side = isLeft and "Left" or "Right", Rows = {}, Section = section, Container = container }
				table.insert(tab.Record.Sections, section.Record)

				function section:AddLabel(labelName)
					return makeLabel(section, labelName)
				end

				function section:AddButton(buttonConfig)
					local inner = makeLabel(section, "")
					inner.NameLabel.Visible = false
					return inner:AddButton(buttonConfig)
				end

				function section:SetVisible(visible)
					container.Visible = visible and true or false
				end

				return section
			end

			table.insert(tabs, tab)
			button.MouseButton1Click:Connect(function()
				select(tab)
			end)

			resizeSidebar()

			if not selected then
				select(tab)
			end

			return tab
		end

		function window:SetSize(scale)
			if typeof(scale) == "Vector2" then
				panel.Size = UDim2.fromOffset(scale.X, scale.Y)
				-- the new size is centred, as the window was when it opened (a window that was dragged away would otherwise grow off the screen)
				panel.Position = UDim2.new(0.5, -scale.X / 2, 0.5, -scale.Y / 2)
			end
		end

		function window:ToggleInterface()
			local open = not window.Signal:GetValue()
			panel.Visible = open
			window.Signal:Fire(open)

			-- the picked look is the one shown (Lib:SetMenuStyle)
			if Lib.ApplyMenuStyle then
				Lib.ApplyMenuStyle()
			end

			if not open then
				closeOverlay()
				cancelCaptures()
			end
		end

		-- toggle key
		bind(UserInputService.InputBegan, function(input, processed)
			if processed or Lib.KeyCaptures > 0 or UserInputService:GetFocusedTextBox() then
				return
			end

			local key = window.Keybind
			local name = typeof(key) == "EnumItem" and key.Name or tostring(key)

			if input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode.Name == name then
				window:ToggleInterface()
			end
		end)

		-- a click anywhere that is not on the open popup closes it
		bind(UserInputService.InputBegan, function(input)
			if overlayOpen and input.UserInputType == Enum.UserInputType.MouseButton1 then
				task.defer(function()
					if not overlayOpen then
						return
					end

					for _, child in ipairs(gui:GetChildren()) do
						if child:IsA("Frame") and child.Visible and child.ZIndex >= 1500 and child.ZIndex < 3000 and mouseIsOver(child) then
							return
						end
					end

					-- a click on the control that opened the popup is answered by that control (the colour swatch closes its popup itself);
					-- closing it here would only have it open again when the button is released
					if overlayAnchor and mouseIsOver(overlayAnchor) then
						return
					end

					closeOverlay()
				end)
			end
		end)

		---------- watermark ----------
		-- A dark bar at the bottom of the screen with a thin accent line on top:
		--   femmyhac.cc | <game> | <player> | <fps> fps | <ping> ms | <time>
		-- (the name in the accent colour). It keeps itself up to date twice a second. Clicking it opens and closes the menu (the blocks the
		-- menu adds keep working: their Input goes to the bar, their text is not shown).
		function window:Watermark()
			local watermark = {}

			local frame = new("TextButton", {
				Name = "Watermark",
				AnchorPoint = Vector2.new(0.5, 1),
				AutoButtonColor = false,
				AutomaticSize = Enum.AutomaticSize.X,
				BackgroundColor3 = Color3.fromRGB(12, 12, 14),
				BackgroundTransparency = 0.12,
				BorderSizePixel = 0,
				Position = UDim2.new(0.5, 0, 1, -64),
				Size = UDim2.fromOffset(10, 26),
				Text = "",
				Visible = false,
				ZIndex = 20,
			}, gui)
			new("UIStroke", { Color = Color3.fromRGB(0, 0, 0), Transparency = 0.4, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, frame)
			local accentLine = new("Frame", { Name = "Line", BackgroundColor3 = ACCENT, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 2), ZIndex = 21 }, frame)
			new("UIPadding", { PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9), PaddingTop = UDim.new(0, 2) }, frame)

			local label = new("TextLabel", {
				Name = "Text",
				AutomaticSize = Enum.AutomaticSize.X,
				BackgroundTransparency = 1,
				Font = FONT,
				RichText = true,
				Size = UDim2.new(0, 10, 1, 0),
				Text = "",
				TextColor3 = Color3.fromRGB(205, 205, 210),
				TextSize = 14,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 21,
			}, frame)

			local player_name = game:GetService("Players").LocalPlayer.Name
			local game_name = "Roblox"

			task.spawn(function()
				local ok, info = pcall(function()
					return game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
				end)

				if ok and type(info) == "table" and type(info.Name) == "string" and info.Name ~= "" then
					game_name = info.Name
				end
			end)

			local frames, fps = 0, 0
			local counted_at = os.clock()
			local alive = true

			local frame_counter = game:GetService("RunService").RenderStepped:Connect(function()
				frames += 1
			end)

			-- green with the Classic look, red with the Visions one (Lib:Accent)
			local function accent_hex()
				local accent = Lib.Accent and Lib:Accent() or ACCENT
				accentLine.BackgroundColor3 = accent
				return string.format("#%02X%02X%02X", math.floor(accent.R * 255 + 0.5), math.floor(accent.G * 255 + 0.5), math.floor(accent.B * 255 + 0.5))
			end

			local function refresh()
				local now = os.clock()

				if now - counted_at > 0 then
					fps = math.floor(frames / (now - counted_at) + 0.5)
				end

				frames, counted_at = 0, now

				local ping = 0
				pcall(function()
					ping = math.floor(game:GetService("Players").LocalPlayer:GetNetworkPing() * 1000 + 0.5)
				end)

				label.Text = string.format('<font color="%s">Visions hook</font> | %s | %s | %d fps | %d ms | %s', accent_hex(), game_name, player_name, fps, ping, os.date("%H:%M:%S"))
			end

			task.spawn(function()
				while alive and frame.Parent do
					refresh()
					task.wait(0.5)
				end

				frame_counter:Disconnect()
			end)

			frame.Destroying:Connect(function()
				alive = false
			end)

			function watermark:AddBlock(_, text)
				local block = {}

				function block:SetText(newText) end

				function block:Input(callback)
					frame.MouseButton1Click:Connect(callback)
				end

				return block
			end

			function watermark:SetRender(visible)
				frame.Visible = visible and true or false

				if visible then
					refresh()
				end
			end

			return watermark
		end

		---------- settings tab: configs on the left, the menu's own settings on the right ------------
		local settingsTab = window:AddTab({ Name = "Config", Order = 9999 })
		local configSection = settingsTab:AddSection({ Name = "CONFIGS", Position = "left" })
		window.UserSettings = settingsTab:AddSection({ Name = "MENU", Position = "right" })

		local folder = tostring(config.ConfigFolder)
		-- Selected is the row picked in the list; Active is the config the menu is in right now (Default until another one is loaded, created or overwritten).
		local configState = { Selected = "Default", Active = "Default", Loaded = false }
		Lib.ConfigState = configState

		local function ensureFolder()
			if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(folder) then
				pcall(makefolder, folder)
			end
		end

		-- the same format the older menu wrote: base64 of a byte-shifted JSON list, so saved configs keep loading
		local function shiftEncode(text)
			local seed = ((#text + 3782) % 111) + 1
			local length = #text
			local bytes = table.create(length)

			-- The same text as before (every byte plus the seed, as a number, joined by ?), read a few thousand bytes per call instead of one.
			for first = 1, length, 4000 do
				local chunk = { text:byte(first, math.min(first + 3999, length)) }

				for offset = 1, #chunk do
					bytes[first + offset - 1] = chunk[offset] + seed
				end
			end

			return "{" .. tostring(seed + 72667) .. "}?" .. table.concat(bytes, "?")
		end

		local function shiftDecode(data)
			local parts = string.split(data, "?")
			local seed = tonumber((parts[1]:gsub("[{}]", "")))
			local real = seed - 72667
			local chars = table.create(#parts)

			for index = 2, #parts do
				chars[index - 1] = string.char(tonumber(parts[index]) - real)
			end

			return table.concat(chars)
		end

		local function base64Encode(text)
			if type(crypt) == "table" and type(crypt.base64encode) == "function" then
				return crypt.base64encode(text)
			elseif type(base64_encode) == "function" then
				return base64_encode(text)
			elseif type(base64) == "table" and base64.encode then
				return base64.encode(text)
			end

			error("no base64 encoder in this executor")
		end

		local function base64Decode(text)
			if type(crypt) == "table" and type(crypt.base64decode) == "function" then
				return crypt.base64decode(text)
			elseif type(base64_decode) == "function" then
				return base64_decode(text)
			elseif type(base64) == "table" and base64.decode then
				return base64.decode(text)
			end

			error("no base64 decoder in this executor")
		end

		-- The settings of the menu as JSON text (what a save is made from; the Default autosave compares it with the last one it wrote).
		function Lib:GetConfigJSON()
			local list = {}

			for flag, item in pairs(Lib.Flags) do
				if item and item.GetValue and not (Lib.NoConfig and Lib.NoConfig[flag]) then
					local data = item:GetValue()

					if Lib.ConfigValueFilter then
						local okFilter, filtered = pcall(Lib.ConfigValueFilter, flag, data)
						if okFilter then
							data = filtered
						end
					end

					if typeof(data) == "Color3" then
						data = data:ToHex()
					end

					table.insert(list, { Idx = flag, Value = data })
				end
			end

			return HttpService:JSONEncode(list)
		end

		function Lib:GetConfigData()
			return base64Encode(shiftEncode(Lib:GetConfigJSON()))
		end

		function Lib:LoadConfigData(data)
			local decoded = HttpService:JSONDecode(shiftDecode(base64Decode((data:gsub("%s", "")))))

			for _, entry in ipairs(decoded) do
				local item = entry.Idx and Lib.Flags[entry.Idx]

				if item and not (Lib.NoConfig and Lib.NoConfig[entry.Idx]) then
					task.spawn(function()
						pcall(item.SetValue, item, entry.Value)
					end)
				end
			end
		end

		local configList = nil
		local nameInput = nil

		local function listConfigs()
			ensureFolder()
			local names = {}

			if type(listfiles) == "function" and type(isfolder) == "function" and isfolder(folder) then
				for _, path in ipairs(listfiles(folder)) do
					local name = string.sub(path, #folder + 2)

					-- the menu keeps its own files here too (binds, skins, sounds): only plain extensionless files are configs
					if name ~= "" and not name:find("%.") and not (type(isfolder) == "function" and isfolder(path)) then
						table.insert(names, name)
					end
				end
			end

			table.sort(names)
			return names
		end

		local logger = Lib:CreateLogger()

		local function refreshConfigs()
			ensureFolder()

			if type(isfile) == "function" and not isfile(folder .. "/Default") and type(writefile) == "function" then
				pcall(function()
					writefile(folder .. "/Default", Lib:GetConfigData())
				end)
			end

			if configList then
				configList:SetValues(listConfigs())
			end
		end

		-- The configs are listed right on the page (a click picks one) instead of in a dropdown that opens over the rest of the menu.
		local selectedLabel = configSection:AddLabel("Selected: " .. tostring(configState.Selected))

		local listFrame = new("ScrollingFrame", {
			Name = "ConfigList",
			Active = true,
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = BOX_COLOR,
			BorderColor3 = OFF_COLOR,
			BorderSizePixel = 1,
			CanvasSize = UDim2.new(),
			LayoutOrder = configSection.NextOrder(),
			ScrollBarImageColor3 = ACCENT,
			ScrollBarThickness = 3,
			Size = UDim2.new(1, -4, 0, 132),
		}, configSection.Body)
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, listFrame)

		local configNames = { "Default" }
		local configRows = {}

		local function paintConfigRows()
			for name, row in pairs(configRows) do
				local on = name == configState.Selected
				row.BackgroundColor3 = on and Color3.fromRGB(58, 58, 58) or BOX_COLOR
				row.TextColor3 = on and ACCENT or TEXT_COLOR
			end

			selectedLabel:SetText("Selected: " .. tostring(configState.Selected))
		end

		configList = {}

		function configList:SetValue(name)
			configState.Selected = name or "Default"
			paintConfigRows()
		end

		function configList:GetValue()
			return configState.Selected
		end

		function configList:SetValues(names)
			configNames = (type(names) == "table" and #names > 0) and names or { "Default" }

			for _, row in pairs(configRows) do
				row:Destroy()
			end
			configRows = {}

			for order, name in ipairs(configNames) do
				local row = new("TextButton", {
					Name = tostring(name),
					AutoButtonColor = false,
					BackgroundColor3 = BOX_COLOR,
					BorderSizePixel = 0,
					Font = FONT,
					LayoutOrder = order,
					Size = UDim2.new(1, -6, 0, 22),
					Text = tostring(name),
					TextColor3 = TEXT_COLOR,
					TextSize = 15,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, listFrame)
				new("UIPadding", { PaddingLeft = UDim.new(0, 8) }, row)

				row.MouseButton1Click:Connect(function()
					configList:SetValue(name)
				end)

				configRows[name] = row
			end

			paintConfigRows()
		end

		configList:SetValues(configNames)

		nameInput = configSection:AddLabel("New Config Name"):AddTextInput({ Default = "", Placeholder = "name", Callback = function() end })

		configSection:AddButton({
			Name = "Load",
			Callback = function()
				local path = folder .. "/" .. tostring(configState.Selected)

				if type(isfile) == "function" and isfile(path) then
					local ok, err = pcall(function()
						Lib:LoadConfigData(readfile(path))
					end)
					if ok then
						configState.Active = configState.Selected
					end
					logger.new("", ok and ("Loaded " .. configState.Selected) or ("Could not load " .. configState.Selected .. ": " .. tostring(err)), 3.5)
				else
					-- the file was deleted or moved outside the menu: say so and bring the list up to date
					logger.new("", "Could not load " .. tostring(configState.Selected) .. ": the file is not there", 3.5)
					refreshConfigs()
				end
			end,
		})

		-- Replaces the selected config with the menu as it is now. The first click only arms the button, the second one (within 3 s) does it.
		local overwriteButton
		local overwriteArmed = 0
		local overwriteArmedName = nil

		overwriteButton = configSection:AddButton({
			Name = "Overwrite Selected",
			Callback = function()
				local name = tostring(configState.Selected)

				-- the second click only counts for the config the first one armed: picking another row in between starts over
				if os.clock() > overwriteArmed or overwriteArmedName ~= name then
					overwriteArmed = os.clock() + 3
					overwriteArmedName = name
					overwriteButton.Root.Text = "Click Again To Overwrite " .. name

					task.delay(3.1, function()
						if overwriteButton.Root.Parent and os.clock() > overwriteArmed then
							overwriteButton.Root.Text = "Overwrite Selected"
						end
					end)

					return
				end

				overwriteArmed = 0
				overwriteArmedName = nil
				overwriteButton.Root.Text = "Overwrite Selected"

				local ok, err = pcall(function()
					writefile(folder .. "/" .. name, Lib:GetConfigData())
				end)
				if ok then
					configState.Active = name
				end
				logger.new("", ok and ("Overwrote " .. name) or ("Could not overwrite " .. name .. ": " .. tostring(err)), 3.5)
				refreshConfigs()
			end,
		})

		configSection:AddButton({
			Name = "Create From Name Above",
			Callback = function()
				-- spaces around the name would be dropped by Windows, leaving a file the list could not find again
				local text = string.match(tostring(nameInput:GetValue() or ""), "^%s*(.-)%s*$")
				local upper = string.upper(text)

				if text == "" then
					logger.new("", "Type a name for the new config first", 3.5)
				elseif text:find('[/\\%.<>:"|%?%*%c]') then
					logger.new("", "That name has a character Windows doesn't allow in file names", 3.5)
				elseif upper == "CON" or upper == "PRN" or upper == "AUX" or upper == "NUL" or upper:find("^COM%d$") or upper:find("^LPT%d$") then
					logger.new("", "Windows keeps that name for itself, pick another one", 3.5)
				else
					text = string.match(string.sub(text, 1, 24), "^%s*(.-)%s*$")
					local ok, err = pcall(function()
						writefile(folder .. "/" .. text, Lib:GetConfigData())
					end)

					if ok then
						configState.Selected = text
						configState.Active = text
						nameInput:SetValue("")
						refreshConfigs()
						configList:SetValue(text)
						logger.new("", "Created " .. text, 3.5)
					else
						logger.new("", "Could not create " .. text .. ": " .. tostring(err), 3.5)
					end
				end
			end,
		})

		configSection:AddButton({
			Name = "Delete",
			Callback = function()
				if configState.Selected == "Default" then
					logger.new("", "You can't delete the default config", 3.5)
					return
				end

				local target = tostring(configState.Selected)
				local targetPath = folder .. "/" .. target

				pcall(delfile, targetPath)

				-- whether the file is really gone is what counts, not whether delfile complained
				if type(isfile) == "function" and isfile(targetPath) then
					logger.new("", "Could not delete " .. target, 3.5)
					return
				end

				logger.new("", "Deleted " .. target, 3.5)
				-- The menu still holds the deleted config's settings: they must not be written over Default, so nothing is in use until one is loaded.
				if configState.Active == configState.Selected then
					configState.Active = nil
				end
				configState.Selected = "Default"
				refreshConfigs()
				configList:SetValue("Default")
			end,
		})

		configSection:AddButton({ Name = "Refresh List", Callback = refreshConfigs })

		-- Writes the Default config now (unload calls this first). Does nothing before the Default config was loaded or while another config is in use.
		function Lib:SaveDefaultConfig()
			local path = folder .. "/Default"

			if configState.Loaded and configState.Active == "Default" and gui and type(isfile) == "function" and isfile(path) then
				return pcall(function()
					writefile(path, Lib:GetConfigData())
				end)
			end

			return false
		end

		-- Called once the menu has been fully built: loads the Default config and keeps it saved while it is the one in use.
		function Lib:LoadDefaultConfig()
			if configState.Loaded then
				return
			end

			configState.Loaded = true
			refreshConfigs()

			local path = folder .. "/Default"

			if type(isfile) == "function" and isfile(path) then
				local ok, err = pcall(function()
					Lib:LoadConfigData(readfile(path))
				end)

				if ok then
					logger.new("", "Loaded Default Config", 3.5)
				else
					warn("[Visions hook] The Default config could not be read: " .. tostring(err))
				end
			end

			local lastWritten = nil

			task.spawn(function()
				while gui and gui.Parent do
					task.wait(5.75)

					-- after an unload Lib.Flags is empty: saving then would wipe the config
					if gui and gui.Parent and configState.Active == "Default" and type(isfile) == "function" and isfile(path) then
						pcall(function()
							-- Nothing changed since the last write: the encoding and the file write (a few hundred KB) are skipped. This ran in full every 5.75 s.
							local json = Lib:GetConfigJSON()

							if json ~= lastWritten then
								writefile(path, base64Encode(shiftEncode(json)))
								lastWritten = json
							end
						end)
					end
				end
			end)
		end

		refreshConfigs()

		-- start with the first real tab in front, not the settings tab that was created first
		task.defer(function()
			for _, tab in ipairs(tabs) do
				if tab.Name ~= "Config" then
					select(tab)
					break
				end
			end
		end)

		return window
	end

	function Lib:Unload()
		closeOverlay()

		for _, connection in ipairs(connections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(connections)
		table.clear(draggers)
		draggerConnection = nil
		table.clear(captures)
		Lib.KeyCaptures = 0

		if gui then
			pcall(function()
				gui:Destroy()
			end)
			gui = nil
		end

		tooltip = nil
		table.clear(Lib.Flags)
		Lib.Window = nil
		Lib.ScreenGui = nil
	end

	---------- the Visions look: a second way to draw the same menu ------------
	-- Every tab, section and row the menu above is given is also written down (Lib.MenuRecord: tab -> section -> row -> its controls, and a
	-- gear's rows under its control). From that list this draws the menu a second time in the Visions look (a search box and the tabs across
	-- the top with the picked one underlined in red, two columns of collapsible sections, square boxes with a red tick, sliders as a box with
	-- the value in it and a fill line, the razor on the top right corner). Its controls do not keep values of their own: each one reads and
	-- writes the very item of the classic menu (item:GetValue / item:SetValue), so both always agree, the config saves the same, and
	-- either can be used. Only one is on screen at a time (Lib:SetMenuStyle, "classic" or "visions"); the style is kept in
	-- visions_menu_style.txt in the workspace. A tab the classic menu draws by itself (no sections, the Skins tab) has a button to open it there.
	local VISIONS_THEME = {
		Window = Color3.fromRGB(24, 24, 24),
		WindowBorder = Color3.fromRGB(44, 44, 44),
		Body = Color3.fromRGB(28, 28, 28),
		Header = Color3.fromRGB(38, 38, 38),
		Element = Color3.fromRGB(40, 40, 40),
		ElementHover = Color3.fromRGB(48, 48, 48),
		Line = Color3.fromRGB(46, 46, 46),
		Text = Color3.fromRGB(235, 235, 235),
		TextDim = Color3.fromRGB(140, 140, 140),
		Accent = Color3.fromRGB(214, 74, 74),
		Font = Enum.Font.Gotham,
		FontBold = Enum.Font.GothamMedium,
		TextSize = 13,
	}
	local STYLE_FILE = "visions_menu_style.txt"

	-- the colour of the picked look: the Classic green or the Visions red (the watermark and the keybind list follow it)
	function Lib:Accent()
		return Lib:GetMenuStyle() == "visions" and VISIONS_THEME.Accent or ACCENT
	end

	-- functions run after every change of look (Lib.StyleListeners, filled by whoever draws in the look's colour)
	Lib.StyleListeners = Lib.StyleListeners or {}

	Lib.MenuRecord = Lib.MenuRecord or {}

	function Lib:GetMenuStyle()
		if Lib.MenuStyle then
			return Lib.MenuStyle
		end

		local ok, saved = pcall(function()
			return isfile and isfile(STYLE_FILE) and readfile(STYLE_FILE) or nil
		end)

		saved = ok and type(saved) == "string" and saved:match("^%s*(%a+)") or nil
		Lib.MenuStyle = (saved == "visions" or saved == "classic") and saved or "classic"
		Lib.MenuStyleChosen = saved == "visions" or saved == "classic"

		return Lib.MenuStyle
	end

	-- the user has never picked a style on this machine (the picker after the intro asks)
	function Lib:MenuStyleIsNew()
		Lib:GetMenuStyle()
		return not Lib.MenuStyleChosen
	end

	local visions = nil

	local function corner(parent, radius)
		return new("UICorner", { CornerRadius = UDim.new(0, radius or 4) }, parent)
	end

	local function vtween(object, props, time)
		local ok, playing = pcall(function()
			local t = TweenService:Create(object, TweenInfo.new(time or 0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
			t:Play()
			return t
		end)

		return ok and playing or nil
	end

	local function buildVisions()
		local T = VISIONS_THEME
		local window = Lib.Window

		if not (window and gui) then
			return nil
		end

		local V = { Syncs = {}, Tabs = {}, Count = 0 }

		-- Panels a tab draws by itself (the Player List's list, the whole Skins browser) are not rows, so they cannot be drawn twice. They are
		-- borrowed instead: while the Visions look is on screen with that tab open, the classic panel itself is moved into it (and that classic
		-- tab is told it is open, which is what those panels listen to), and it goes back the moment the tab, the look or the menu changes.
		V.Borrows = {}

		local function borrowFor(entry, item, home, slot)
			table.insert(V.Borrows, { Entry = entry, Item = item, Home = home, Slot = slot })
		end

		-- the panels were drawn in one accent and are shown in the other: every colour that is exactly the other one is swapped
		local CLASSIC_ACCENT, VISIONS_ACCENT = ACCENT, VISIONS_THEME.Accent
		local COLOR_PROPERTIES = { "BackgroundColor3", "ScrollBarImageColor3", "TextColor3", "ImageColor3", "Color", "BorderColor3", "PlaceholderColor3" }

		local function recolor(root)
			local want = Lib:Accent()
			local other = want == VISIONS_ACCENT and CLASSIC_ACCENT or VISIONS_ACCENT
			local function close(a, b)
				return math.abs(a.R - b.R) + math.abs(a.G - b.G) + math.abs(a.B - b.B) < 0.02
			end
			local function paint(object)
				for _, property in ipairs(COLOR_PROPERTIES) do
					local ok, value = pcall(function()
						return object[property]
					end)
					if ok and typeof(value) == "Color3" and close(value, other) then
						pcall(function()
							object[property] = want
						end)
					end
				end
			end
			paint(root)
			for _, object in ipairs(root:GetDescendants()) do
				paint(object)
			end
		end

		local function placeBorrows(activeEntry)
			local told = {}

			for _, borrow in ipairs(V.Borrows) do
				local item = borrow.Item
				local wanted = borrow.Entry == activeEntry and borrow.Slot or borrow.Home

				if item.Parent ~= wanted and wanted.Parent ~= nil then
					pcall(function()
						item.Parent = wanted
					end)
				end

				pcall(recolor, item)

				local classicTab = borrow.Entry.Record.Tab
				if classicTab and classicTab.Signal and told[classicTab] == nil then
					local open = borrow.Entry == activeEntry or (classicTab.Page and classicTab.Page.Visible and window.Panel.Visible) or false
					told[classicTab] = open
					if classicTab.Signal:GetValue() ~= open then
						classicTab.Signal:Fire(open)
					end
				end
			end
		end
		V.PlaceBorrows = placeBorrows
		local function countRecords()
			local n = 0
			local function rows(list)
				for _, row in ipairs(list) do
					n += 1
					for _, control in ipairs(row.Controls) do
						n += 1
						if control.Option then
							rows(control.Option.Rows)
						end
					end
				end
			end
			for _, tab in ipairs(Lib.MenuRecord) do
				n += 1
				for _, section in ipairs(tab.Sections) do
					n += 1
					rows(section.Rows)
				end
			end
			return n
		end
		V.Count = countRecords()

		local frame = new("Frame", {
			Name = "VisionsLook",
			AnchorPoint = Vector2.new(0.5, 0.5),
			BackgroundColor3 = T.Window,
			BorderSizePixel = 0,
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(760, 640),
			Visible = false,
			Active = true,
		}, gui)
		corner(frame, 6)
		new("UIStroke", { Color = T.WindowBorder, Thickness = 1 }, frame)
		V.Frame = frame

		-- the razor and its red cut off the top right corner (it is also the handle the window is moved by)
		local razor = nil

		if Lib.RazorAsset then
			razor = new("ImageLabel", {
				Name = "Razor",
				Active = true,
				AnchorPoint = Vector2.new(1, 0),
				BackgroundTransparency = 1,
				Image = Lib.RazorAsset,
				Position = UDim2.new(1, 70, 0, -62),
				Size = UDim2.fromOffset(150, 138),
				ZIndex = 10,
			}, frame)
		end

		local top = new("Frame", { Name = "Top", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 58) }, frame)

		local search = new("TextBox", {
			Name = "Search",
			BackgroundColor3 = T.Element,
			BorderSizePixel = 0,
			ClearTextOnFocus = false,
			Font = T.Font,
			PlaceholderColor3 = T.TextDim,
			PlaceholderText = "Search...",
			Position = UDim2.fromOffset(16, 18),
			Size = UDim2.fromOffset(170, 24),
			Text = "",
			TextColor3 = T.Text,
			TextSize = T.TextSize,
			TextXAlignment = Enum.TextXAlignment.Left,
		}, top)
		corner(search, 4)
		new("UIPadding", { PaddingLeft = UDim.new(0, 8) }, search)

		-- the classic look, one click away
		local switch = new("TextButton", {
			Name = "Classic",
			AnchorPoint = Vector2.new(1, 0),
			AutoButtonColor = false,
			BackgroundColor3 = T.Element,
			BorderSizePixel = 0,
			Font = T.Font,
			Position = UDim2.new(1, -16, 0, 18),
			Size = UDim2.fromOffset(64, 24),
			Text = "Classic",
			TextColor3 = T.TextDim,
			TextSize = 12,
		}, top)
		corner(switch, 4)
		bind(switch.MouseButton1Click, function()
			Lib:SetMenuStyle("classic", true)
		end)

		local tabBar = new("ScrollingFrame", {
			Name = "Tabs",
			Active = true,
			AutomaticCanvasSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			CanvasSize = UDim2.new(),
			Position = UDim2.fromOffset(196, 10),
			ScrollBarThickness = 0,
			ScrollingDirection = Enum.ScrollingDirection.X,
			Size = UDim2.new(1, -290, 0, 44),
		}, top)
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, tabBar)

		new("Frame", { Name = "Divider", BackgroundColor3 = T.Line, BorderSizePixel = 0, Position = UDim2.fromOffset(0, 58), Size = UDim2.new(1, 0, 0, 1) }, frame)

		local pages = new("Frame", { Name = "Pages", BackgroundTransparency = 1, Position = UDim2.fromOffset(14, 70), Size = UDim2.new(1, -28, 1, -84) }, frame)

		-- Moving the window: hold the left button on the razor and drag (the top bar only when there is no razor picture)
		do
			local dragStart, startPos = nil, nil

			bind((razor or top).InputBegan, function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					dragStart, startPos = input.Position, frame.Position
				end
			end)
			bind(UserInputService.InputChanged, function(input)
				if dragStart and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
					local delta = input.Position - dragStart
					frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
				end
			end)
			bind(UserInputService.InputEnded, function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					dragStart = nil
				end
			end)
		end

		local function textLabel(parent, text, props)
			local base = {
				BackgroundTransparency = 1,
				Font = T.Font,
				Text = tostring(text),
				TextColor3 = T.Text,
				TextSize = T.TextSize,
				TextTruncate = Enum.TextTruncate.AtEnd,
				TextXAlignment = Enum.TextXAlignment.Left,
			}
			for key, value in pairs(props or {}) do
				base[key] = value
			end
			return new("TextLabel", base, parent)
		end

		local function sync(fn)
			table.insert(V.Syncs, fn)
			pcall(fn)
		end

		local function call(item, value)
			if item and item.SetValue then
				local ok, err = pcall(item.SetValue, item, value)
				if not ok then
					warn("[Visions hook] Setting a value failed: " .. tostring(err))
				end
			end
		end

		local function getValue(item)
			if item and item.GetValue then
				local ok, value = pcall(item.GetValue, item)
				if ok then
					return value
				end
			end
			return nil
		end

		local function box(parent, width, height)
			local b = new("TextButton", {
				AutoButtonColor = false,
				BackgroundColor3 = T.Element,
				BorderSizePixel = 0,
				Font = T.Font,
				Size = UDim2.fromOffset(width, height or 20),
				Text = "",
				TextColor3 = T.Text,
				TextSize = 12,
			}, parent)
			corner(b, 4)
			bind(b.MouseEnter, function() vtween(b, { BackgroundColor3 = T.ElementHover }, 0.1) end)
			bind(b.MouseLeave, function() vtween(b, { BackgroundColor3 = T.Element }, 0.1) end)
			return b
		end

		local renderRows -- (rows, parent, depth)

		-- one control on a row: small ones go on the right of the name, wide ones on a line of their own under it
		local function renderControl(control, rowFrame, right, under, depth)
			local kind, config, item = control.Kind, control.Config or {}, control.Item

			if kind == "AddToggle" then
				local b = box(right, 18, 18)
				b.LayoutOrder = 100
				local tick = textLabel(b, "✓", { Font = T.FontBold, Size = UDim2.fromScale(1, 1), TextColor3 = T.Accent, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1 })
				local shown = nil

				bind(b.MouseButton1Click, function()
					call(item, not getValue(item))
				end)
				bind(b.MouseButton2Click, function()
					if config.Flag and Lib.OpenBind then
						pcall(Lib.OpenBind, config.Flag)
					end
				end)

				sync(function()
					local on = getValue(item) == true
					if on ~= shown then
						shown = on
						vtween(tick, { TextTransparency = on and 0 or 1 }, 0.1)
					end
				end)

				return true
			elseif kind == "AddSlider" then
				local min, max = tonumber(config.Min) or 0, tonumber(config.Max) or 10
				local rounding = tonumber(config.Rounding) or 0
				local suffix = tostring(config.Type or "")
				local bar = box(under, 10, 18)
				bar.Size = UDim2.new(1, 0, 0, 18)
				bar.LayoutOrder = 1
				local fill = new("Frame", { BackgroundColor3 = T.Text, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(0, 0, 0, 2) }, bar)
				local valueText = textLabel(bar, "", { Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center, TextSize = 12 })
				local shown = nil

				local function draw(value)
					value = tonumber(value) or min
					local share = (max ~= min) and math.clamp((value - min) / (max - min), 0, 1) or 0
					fill.Size = UDim2.new(share, 0, 0, 2)
					-- a value that stands for a word ("auto", "off") shows the word, as in the classic menu
					local word = type(config.Nums) == "table" and (config.Nums[value] or config.Nums[tostring(value)])
					valueText.Text = word and tostring(word) or (formatNumber(value, rounding) .. suffix)
				end

				local holding = false
				local function fromMouse(x)
					local share = math.clamp((x - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
					local value = roundTo(min + (max - min) * share, rounding)
					if value ~= getValue(item) then
						call(item, value)
					end
					draw(value)
				end

				bind(bar.InputBegan, function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						holding = true
						fromMouse(input.Position.X)
					end
				end)
				bind(UserInputService.InputChanged, function(input)
					if holding and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
						fromMouse(input.Position.X)
					end
				end)
				bind(UserInputService.InputEnded, function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						holding = false
					end
				end)

				sync(function()
					local value = getValue(item)
					if value ~= shown and not holding then
						shown = value
						draw(value)
					end
				end)

				return true
			elseif kind == "AddDropdown" then
				local multi = config.Multi == true
				local b = box(under, 10, 20)
				b.Size = UDim2.new(1, 0, 0, 20)
				b.LayoutOrder = 1
				local boxText = textLabel(b, "", { Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -26, 1, 0), TextSize = 12 })
				local arrow = textLabel(b, "v", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -6, 0, 0), Size = UDim2.new(0, 12, 1, 0), TextColor3 = T.TextDim, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Right })

				local list = new("Frame", { BackgroundColor3 = T.Body, BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 0), Visible = false }, under)
				corner(list, 4)
				new("UIStroke", { Color = T.Line, Thickness = 1 }, list)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, list)

				local shownKey, builtFor = nil, nil

				local function picks()
					local value = getValue(item)
					local map = {}
					if type(value) == "table" then
						for key, picked in pairs(value) do
							if type(key) == "number" then
								map[tostring(picked)] = true
							elseif picked then
								map[tostring(key)] = true
							end
						end
					elseif value ~= nil then
						map[tostring(value)] = true
					end
					return map
				end

				local function describe(map)
					local names = {}
					for _, option in ipairs(config.Values or {}) do
						if map[tostring(option)] then
							table.insert(names, tostring(option))
						end
					end
					return #names > 0 and table.concat(names, ", ") or "None"
				end

				local optionRows = {}
				local function paint(map)
					for name, rowButton in pairs(optionRows) do
						rowButton.TextColor3 = map[name] and T.Accent or T.Text
					end
				end

				local function build()
					for _, child in ipairs(list:GetChildren()) do
						if child:IsA("TextButton") then
							child:Destroy()
						end
					end
					table.clear(optionRows)

					for index, option in ipairs(config.Values or {}) do
						local name = tostring(option)
						local o = new("TextButton", {
							AutoButtonColor = false,
							BackgroundTransparency = 1,
							Font = T.Font,
							LayoutOrder = index,
							Size = UDim2.new(1, 0, 0, 20),
							Text = "  " .. name,
							TextColor3 = T.Text,
							TextSize = 12,
							TextXAlignment = Enum.TextXAlignment.Left,
						}, list)
						optionRows[name] = o

						bind(o.MouseButton1Click, function()
							if multi then
								local map = picks()
								map[name] = not map[name] or nil
								local out = {}
								for key in pairs(map) do
									out[key] = true
								end
								call(item, out)
							else
								call(item, option)
								list.Visible = false
								arrow.Text = "v"
							end
						end)
					end

					builtFor = config.Values
				end

				bind(b.MouseButton1Click, function()
					if builtFor ~= config.Values then
						build()
					end
					list.Visible = not list.Visible
					arrow.Text = list.Visible and "^" or "v"
					paint(picks())
				end)

				sync(function()
					local map = picks()
					local key = describe(map)
					if builtFor ~= config.Values and list.Visible then
						build()
					end
					if key ~= shownKey or builtFor ~= config.Values then
						shownKey = key
						boxText.Text = key
						paint(map)
					end
				end)

				return true
			elseif kind == "AddKeybind" then
				local b = box(right, 52, 18)
				b.LayoutOrder = 200
				b.TextSize = 11
				local capturing = false
				local shown = nil

				bind(b.MouseButton1Click, function()
					if capturing then
						return
					end

					capturing = true
					Lib.KeyCaptures += 1
					b.Text = "..."

					local connection
					connection = UserInputService.InputBegan:Connect(function(input)
						local value = nil

						if input.UserInputType == Enum.UserInputType.Keyboard then
							value = input.KeyCode == Enum.KeyCode.Escape and "None" or input.KeyCode.Name
						elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
							value = "M2B"
						elseif input.UserInputType == Enum.UserInputType.MouseButton3 then
							value = "M3B"
						end

						if value then
							connection:Disconnect()
							capturing = false
							task.defer(function()
								Lib.KeyCaptures = math.max(Lib.KeyCaptures - 1, 0)
							end)

							local blocked = false
							for _, name in ipairs(type(config.Blacklist) == "table" and config.Blacklist or {}) do
								if name == value then
									blocked = true
								end
							end

							if not blocked then
								call(item, value)
							end
							shown = nil
						end
					end)
				end)

				sync(function()
					if capturing then
						return
					end
					local value = getValue(item)
					if value ~= shown then
						shown = value
						b.Text = keyCodeName(value)
					end
				end)

				return true
			elseif kind == "AddColorPicker" then
				local swatch = box(right, 26, 14)
				swatch.LayoutOrder = 150
				local shown = nil

				-- The picker opens under the row: a square (saturation left to right, brightness top to bottom) in the picked hue, a hue bar on its
				-- right, and the colour's hex code under them (type one in and press enter).
				local picker = new("Frame", { BackgroundColor3 = T.Body, BorderSizePixel = 0, LayoutOrder = 3, Size = UDim2.fromOffset(196, 196), Visible = false }, under)
				corner(picker, 4)
				new("UIStroke", { Color = T.Line, Thickness = 1 }, picker)
				local hsv = { 0, 0, 1 }

				local square = new("Frame", { BackgroundColor3 = Color3.fromHSV(0, 1, 1), BorderSizePixel = 0, Position = UDim2.fromOffset(8, 8), Size = UDim2.fromOffset(150, 150), Active = true }, picker)
				local whiteFade = new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1) }, square)
				new("UIGradient", { Transparency = NumberSequence.new(0, 1) }, whiteFade)
				local blackFade = new("Frame", { BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1) }, square)
				new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(1, 0) }, blackFade)
				local squareCursor = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromOffset(6, 6), ZIndex = 3 }, square)
				new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 1 }, squareCursor)

				local hueBar = new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Position = UDim2.fromOffset(166, 8), Size = UDim2.fromOffset(14, 150), Active = true }, picker)
				local hueKeys = {}
				for step = 0, 6 do
					table.insert(hueKeys, ColorSequenceKeypoint.new(step / 6, Color3.fromHSV(step / 6 % 1, 1, 1)))
				end
				new("UIGradient", { Rotation = 90, Color = ColorSequence.new(hueKeys) }, hueBar)
				local hueCursor = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Position = UDim2.new(0, -2, 0, 0), Size = UDim2.new(1, 4, 0, 3), ZIndex = 3 }, hueBar)
				new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 1 }, hueCursor)

				local hexBox = new("TextBox", {
					BackgroundColor3 = T.Element,
					BorderSizePixel = 0,
					ClearTextOnFocus = false,
					Font = T.Font,
					Position = UDim2.fromOffset(8, 164),
					Size = UDim2.fromOffset(172, 24),
					Text = "",
					TextColor3 = T.Text,
					TextSize = 12,
				}, picker)
				corner(hexBox, 4)

				local function hexOf(color)
					return string.format("#%02x%02x%02x", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
				end

				local function drawPicker()
					square.BackgroundColor3 = Color3.fromHSV(hsv[1], 1, 1)
					squareCursor.Position = UDim2.fromScale(hsv[2], 1 - hsv[3])
					hueCursor.Position = UDim2.new(0, -2, hsv[1], 0)
					if not hexBox:IsFocused() then
						hexBox.Text = hexOf(Color3.fromHSV(hsv[1], hsv[2], hsv[3]))
					end
				end

				local function send()
					local color = Color3.fromHSV(hsv[1], hsv[2], hsv[3])
					shown = color
					swatch.BackgroundColor3 = color
					drawPicker()
					call(item, color)
				end

				local dragging = nil
				local function dragTo(position)
					if dragging == "square" then
						hsv[2] = math.clamp((position.X - square.AbsolutePosition.X) / math.max(square.AbsoluteSize.X, 1), 0, 1)
						hsv[3] = 1 - math.clamp((position.Y - square.AbsolutePosition.Y) / math.max(square.AbsoluteSize.Y, 1), 0, 1)
					elseif dragging == "hue" then
						hsv[1] = math.clamp((position.Y - hueBar.AbsolutePosition.Y) / math.max(hueBar.AbsoluteSize.Y, 1), 0, 0.999)
					end
					send()
				end

				bind(square.InputBegan, function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						dragging = "square"
						dragTo(input.Position)
					end
				end)
				bind(hueBar.InputBegan, function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						dragging = "hue"
						dragTo(input.Position)
					end
				end)
				bind(UserInputService.InputChanged, function(input)
					if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
						dragTo(input.Position)
					end
				end)
				bind(UserInputService.InputEnded, function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						dragging = nil
					end
				end)

				bind(hexBox.FocusLost, function()
					local hex = string.match(hexBox.Text, "^%s*#?(%x%x%x%x%x%x)%s*$")
					if hex then
						local color = Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16))
						hsv[1], hsv[2], hsv[3] = color:ToHSV()
						send()
					else
						drawPicker()
					end
				end)

				bind(swatch.MouseButton1Click, function()
					picker.Visible = not picker.Visible
				end)

				sync(function()
					local color = getValue(item)
					if typeof(color) == "Color3" and color ~= shown and not dragging then
						shown = color
						swatch.BackgroundColor3 = color
						hsv[1], hsv[2], hsv[3] = color:ToHSV()
						drawPicker()
					end
				end)

				-- the hover tween of box() would paint over the colour
				bind(swatch.MouseLeave, function()
					task.defer(function()
						if shown then
							swatch.BackgroundColor3 = shown
						end
					end)
				end)

				return true
			elseif kind == "AddTextInput" then
				local input = new("TextBox", {
					BackgroundColor3 = T.Element,
					BorderSizePixel = 0,
					ClearTextOnFocus = false,
					Font = T.Font,
					LayoutOrder = 1,
					PlaceholderColor3 = T.TextDim,
					PlaceholderText = tostring(config.Placeholder or ""),
					Size = UDim2.new(1, 0, 0, 20),
					Text = "",
					TextColor3 = T.Text,
					TextSize = 12,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, under)
				corner(input, 4)
				new("UIPadding", { PaddingLeft = UDim.new(0, 8) }, input)
				local shown = nil

				bind(input.FocusLost, function()
					local text = input.Text
					if config.Numeric then
						local number = tonumber((text:gsub("[^0-9.%-]", "")))
						if number ~= nil then
							call(item, number)
						end
					else
						call(item, text)
					end
					shown = nil
				end)

				sync(function()
					if input:IsFocused() then
						return
					end
					local value = getValue(item)
					if value ~= shown then
						shown = value
						input.Text = value == nil and "" or tostring(value)
					end
				end)

				return true
			elseif kind == "AddButton" then
				local b = box(under, 10, 22)
				b.Size = UDim2.new(1, 0, 0, 22)
				b.LayoutOrder = 1
				b.Text = tostring(config.Name or "")
				b.TextSize = 12

				bind(b.MouseButton1Click, function()
					if type(config.Callback) == "function" then
						local ok, err = pcall(config.Callback)
						if not ok then
							warn("[Visions hook] A button failed: " .. tostring(err))
						end
					end
				end)

				return true
			elseif kind == "AddOption" and control.Option then
				-- a gear: its rows open indented under this row
				local gear = box(right, 22, 18)
				gear.LayoutOrder = 300
				gear.Text = "..."
				gear.TextColor3 = T.TextDim

				-- (a plain box: a child sized by the box's own height made an AutomaticSize box grow without end)
				local holder = new("Frame", { BackgroundColor3 = T.Body, BorderSizePixel = 0, AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 50, Size = UDim2.new(1, 0, 0, 0), Visible = false }, under)
				corner(holder, 4)
				new("UIStroke", { Color = T.Line, Thickness = 1 }, holder)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, holder)
				new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 6) }, holder)

				local built = false
				bind(gear.MouseButton1Click, function()
					if not built then
						built = true
						renderRows(control.Option.Rows, holder, depth + 1)
					end
					holder.Visible = not holder.Visible
					gear.TextColor3 = holder.Visible and T.Accent or T.TextDim
				end)

				-- a gear hidden in the classic menu (option:SetVisible(false)) is hidden here too
				local shownVisible = nil
				sync(function()
					local visible = control.Item.Hidden ~= true
					if visible ~= shownVisible then
						shownVisible = visible
						gear.Visible = visible
						if not visible then
							holder.Visible = false
						end
					end
				end)

				return true
			end

			return false
		end

		renderRows = function(rows, parent, depth)
			for index, rowRecord in ipairs(rows) do
				local rowFrame = new("Frame", {
					Name = tostring(rowRecord.Name),
					AutomaticSize = Enum.AutomaticSize.Y,
					BackgroundTransparency = 1,
					LayoutOrder = typeof(rowRecord.Row) == "Instance" and rowRecord.Row.LayoutOrder or index,
					Size = UDim2.new(1, 0, 0, 22),
				}, parent)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3) }, rowFrame)

				local head = new("Frame", { Name = "Head", BackgroundTransparency = 1, LayoutOrder = 0, Size = UDim2.new(1, 0, 0, 22) }, rowFrame)
				local name = tostring(rowRecord.Name or "")
				local nameLabel = textLabel(head, name, { Size = UDim2.new(1, -150, 1, 0), TextColor3 = depth > 0 and T.TextDim or T.Text })

				local right = new("Frame", { Name = "Right", AnchorPoint = Vector2.new(1, 0.5), BackgroundTransparency = 1, Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.new(0, 150, 1, 0) }, head)
				new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right, VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 5) }, right)

				local under = new("Frame", { Name = "Under", AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 0) }, rowFrame)
				new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3) }, under)

				-- right click on a row with a toggle: its key bind popup (the classic menu's own), when the toggle can be bound
				for _, control in ipairs(rowRecord.Controls) do
					if control.Kind == "AddToggle" and control.Config and control.Config.Flag then
						local flag = control.Config.Flag
						local function onRightClick(input)
							if input.UserInputType == Enum.UserInputType.MouseButton2 and Lib.OpenBind then
								pcall(Lib.OpenBind, flag)
							end
						end
						bind(head.InputBegan, onRightClick)
						bind(nameLabel.InputBegan, onRightClick)
						break
					end
				end

				local any = false
				for _, control in ipairs(rowRecord.Controls) do
					local ok, drawn = pcall(renderControl, control, rowFrame, right, under, depth)
					if not ok then
						warn("[Visions hook] A row of the Visions look failed (" .. name .. "): " .. tostring(drawn))
					end
					any = any or (ok and drawn)
				end

				-- a row with only a name (a heading or a note) stays a line of text; one with a wide control and no name loses the empty head
				if name == "" then
					head.Visible = false
				end

				-- the classic row decides: hidden there (a mode not picked, a gear option for another style) is hidden here
				local shownVisible = nil
				local search_name = string.lower(name)
				sync(function()
					local original = rowRecord.Row
					local visible = typeof(original) ~= "Instance" or original.Visible
					local query = V.Query
					if visible and query and query ~= "" and depth == 0 then
						visible = string.find(search_name, query, 1, true) ~= nil
					end
					if visible ~= shownVisible then
						shownVisible = visible
						rowFrame.Visible = visible
					end
				end)

				if rowRecord.Label and rowRecord.Label.NameLabel then
					sync(function()
						local text = rowRecord.Label.NameLabel.Text
						if text ~= nameLabel.Text and name ~= "" then
							nameLabel.Text = text
						end
					end)
				end
			end
		end

		local current = nil

		local function selectTab(entry)
			if current == entry then
				return
			end
			if current then
				current.Page.Visible = false
				vtween(current.Button, { TextColor3 = T.TextDim })
				vtween(current.Underline, { Size = UDim2.new(0, 0, 0, 2) })
			end
			current = entry
			Lib.VisionsSelected = entry.Record.Name
			entry.Page.Visible = true
			vtween(entry.Button, { TextColor3 = T.Text })
			vtween(entry.Underline, { Size = UDim2.new(0.8, 0, 0, 2) })

			if not entry.Built then
				entry.Built = true
				entry.Build()
			end

			V.Current = entry
			if frame.Visible then
				placeBorrows(entry)
			end
		end

		local ordered = table.clone(Lib.MenuRecord)
		local function orderOf(record)
			local button = record.Tab and record.Tab.Idx
			return typeof(button) == "Instance" and button.LayoutOrder or 0
		end
		local position = {}
		for index, record in ipairs(ordered) do
			position[record] = index
		end
		table.sort(ordered, function(a, b)
			if orderOf(a) ~= orderOf(b) then
				return orderOf(a) < orderOf(b)
			end
			return position[a] < position[b]
		end)

		for tabIndex, tabRecord in ipairs(ordered) do
			local tabName = tostring(tabRecord.Name)
			local width = math.max(textWidth(tabName, 13) + 22, 50)
			local button = new("TextButton", {
				Name = tabName,
				AutoButtonColor = false,
				BackgroundTransparency = 1,
				Font = T.Font,
				LayoutOrder = tabIndex,
				Size = UDim2.new(0, width, 1, -4),
				Text = tabName,
				TextColor3 = T.TextDim,
				TextSize = 13,
			}, tabBar)
			local underline = new("Frame", { Name = "Underline", AnchorPoint = Vector2.new(0.5, 1), BackgroundColor3 = T.Accent, BorderSizePixel = 0, Position = UDim2.new(0.5, 0, 1, 0), Size = UDim2.new(0, 0, 0, 2) }, button)

			local page = new("Frame", { Name = tabName, BackgroundColor3 = T.Body, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Visible = false }, pages)
			corner(page, 4)

			local entry = { Button = button, Underline = underline, Page = page, Record = tabRecord }

			-- a page is drawn the first time it is opened, so a menu with hundreds of rows opens at once
			entry.Build = function()
				if #tabRecord.Sections == 0 then
					-- the tab draws everything itself (the Skins browser): its classic page content is shown here
					local slot = new("Frame", { Name = "Borrowed", BackgroundTransparency = 1, ClipsDescendants = true, Size = UDim2.fromScale(1, 1) }, page)
					local classicPage = tabRecord.Tab and tabRecord.Tab.Page

					if typeof(classicPage) == "Instance" then
						for _, child in ipairs(classicPage:GetChildren()) do
							if child:IsA("GuiObject") and child ~= tabRecord.Tab.Left and child ~= tabRecord.Tab.Right then
								borrowFor(entry, child, classicPage, slot)
							end
						end
					end

					return
				end

				local columns = {}
				for index, side in ipairs({ "Left", "Right" }) do
					local scroll = new("ScrollingFrame", {
						Name = side,
						Active = true,
						AutomaticCanvasSize = Enum.AutomaticSize.Y,
						BackgroundTransparency = 1,
						BorderSizePixel = 0,
						CanvasSize = UDim2.new(),
						Position = UDim2.new((index - 1) * 0.5, index == 1 and 10 or 5, 0, 10),
						ScrollBarImageColor3 = T.Accent,
						ScrollBarThickness = 2,
						Size = UDim2.new(0.5, -15, 1, -20),
					}, page)
					new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10) }, scroll)
					new("UIPadding", { PaddingRight = UDim.new(0, 6), PaddingBottom = UDim.new(0, 10) }, scroll)
					columns[side] = scroll
				end

				for sectionIndex, sectionRecord in ipairs(tabRecord.Sections) do
					local container = new("Frame", {
						Name = tostring(sectionRecord.Name),
						AutomaticSize = Enum.AutomaticSize.Y,
						BackgroundColor3 = T.Header,
						BorderSizePixel = 0,
						LayoutOrder = sectionIndex,
						Size = UDim2.new(1, 0, 0, 30),
					}, columns[sectionRecord.Side] or columns.Left)
					corner(container, 4)
					new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, container)

					local header = new("TextButton", { AutoButtonColor = false, BackgroundTransparency = 1, LayoutOrder = 0, Size = UDim2.new(1, 0, 0, 30), Text = "" }, container)
					textLabel(header, string.upper(tostring(sectionRecord.Name)), { Font = T.FontBold, Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -40, 1, 0), TextSize = 12 })
					local chevron = textLabel(header, "-", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 0), Size = UDim2.new(0, 20, 1, 0), TextColor3 = T.TextDim, TextXAlignment = Enum.TextXAlignment.Right })

					local body = new("Frame", { AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.Window, BorderSizePixel = 0, LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 0) }, container)
					new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4) }, body)
					new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 10) }, body)

					bind(header.MouseButton1Click, function()
						body.Visible = not body.Visible
						chevron.Text = body.Visible and "-" or "+"
					end)

					renderRows(sectionRecord.Rows, body, 0)

					-- a panel the section draws by itself (the Player List's list) is borrowed into this section
					local classicBody = sectionRecord.Section and sectionRecord.Section.Body
					if typeof(classicBody) == "Instance" then
						local isRow = {}
						for _, rowRecord in ipairs(sectionRecord.Rows) do
							if typeof(rowRecord.Row) == "Instance" then
								isRow[rowRecord.Row] = true
							end
						end
						for _, child in ipairs(classicBody:GetChildren()) do
							if child:IsA("GuiObject") and not isRow[child] then
								borrowFor(entry, child, classicBody, body)
							end
						end
					end

					local shownVisible = nil
					sync(function()
						local original = sectionRecord.Container
						local visible = typeof(original) ~= "Instance" or original.Visible
						if visible ~= shownVisible then
							shownVisible = visible
							container.Visible = visible
						end
					end)
				end
			end

			bind(button.MouseButton1Click, function()
				selectTab(entry)
			end)

			table.insert(V.Tabs, entry)
		end

		-- a redraw keeps the tab that was open
		local reopen = V.Tabs[1]
		for _, entry in ipairs(V.Tabs) do
			if entry.Record.Name == Lib.VisionsSelected then
				reopen = entry
			end
		end
		if reopen then
			selectTab(reopen)
		end

		bind(search:GetPropertyChangedSignal("Text") or search.Changed, function()
			V.Query = string.lower(search.Text)
		end)

		-- keep every drawn control in step with the classic menu while this one is on screen; when the classic menu has been given more tabs,
		-- sections or rows since this was drawn (it is still being built when the intro is skipped), it is drawn again
		task.spawn(function()
			local checked = os.clock()
			while frame.Parent do
				if frame.Visible then
					for _, fn in ipairs(V.Syncs) do
						pcall(fn)
					end

					if os.clock() - checked > 1 then
						checked = os.clock()
						if V.Shallow and Lib.CountShallow() ~= V.Shallow and Lib.ApplyMenuStyle then
							task.defer(Lib.ApplyMenuStyle)
						end
					end
				end
				task.wait(0.15)
			end
		end)

		return V
	end

	-- The menu window on the screen while it is open (whichever look is shown): x0, y0, x1, y1 in screen pixels, or nil when it is closed.
	-- Drawings (ESP, the center panel) are always drawn over every GUI, so they keep out of this rectangle instead.
	function Lib:MenuRect()
		local window = Lib.Window
		if not window or not window.Signal:GetValue() or Lib.MenuHeld then
			return nil
		end

		local frame = nil
		if window.Panel and window.Panel.Visible then
			frame = window.Panel
		elseif visions and visions.Frame.Parent and visions.Frame.Visible then
			frame = visions.Frame
		end

		if not frame then
			return nil
		end

		local position, size = frame.AbsolutePosition, frame.AbsoluteSize
		return position.X, position.Y, position.X + size.X, position.Y + size.Y
	end

	-- tabs + sections + rows written down so far (a change means the Visions look is out of date)
	function Lib.CountShallow()
		local count = 0
		for _, tab in ipairs(Lib.MenuRecord) do
			count += 1 + #tab.Sections
			for _, section in ipairs(tab.Sections) do
				count += #section.Rows
			end
		end
		return count
	end

	-- shows the look that is picked (and hides the other) while the menu is open
	local function applyMenuStyle()
		local window = Lib.Window
		if not window or not window.Panel then
			return
		end

		local open = window.Signal:GetValue() and not Lib.MenuHeld
		local style = Lib:GetMenuStyle()

		if style == "visions" and open then
			-- built again when the classic menu got rows since (the engine adds its rows after the menu opens)
			if visions and visions.Frame.Parent and visions.Count ~= nil then
				local fresh = 0
				for _, tab in ipairs(Lib.MenuRecord) do
					fresh += 1 + #tab.Sections
					for _, section in ipairs(tab.Sections) do
						fresh += #section.Rows
					end
				end
				if fresh ~= visions.Shallow then
					-- borrowed panels go home first, or they would be destroyed with the old drawing
					pcall(visions.PlaceBorrows, nil)
					visions.Frame:Destroy()
					visions = nil
				end
			end

			if not visions or not visions.Frame.Parent then
				local ok, built = pcall(buildVisions)
				if ok and built then
					visions = built
					local shallow = 0
					for _, tab in ipairs(Lib.MenuRecord) do
						shallow += 1 + #tab.Sections
						for _, section in ipairs(tab.Sections) do
							shallow += #section.Rows
						end
					end
					visions.Shallow = shallow
				else
					warn("[Visions hook] The Visions look could not be built, the classic menu is shown: " .. tostring(built))
					Lib.MenuStyle = "classic"
					style = "classic"
				end
			end
		end

		window.Panel.Visible = open and style == "classic"
		if visions and visions.Frame.Parent then
			visions.Frame.Visible = open and style == "visions"

			-- borrowed panels sit in the Visions look while it is on screen, and are back in the classic menu otherwise
			if style == "visions" and open then
				pcall(visions.PlaceBorrows, visions.Current)
			elseif style == "classic" then
				pcall(visions.PlaceBorrows, nil)
			end
		end
	end
	Lib.ApplyMenuStyle = applyMenuStyle

	function Lib:SetMenuStyle(style, save)
		style = style == "visions" and "visions" or "classic"
		Lib.MenuStyle = style
		Lib.MenuStyleChosen = true

		if save then
			pcall(function()
				writefile(STYLE_FILE, style)
			end)
		end

		closeOverlay()
		applyMenuStyle()

		for _, listener in ipairs(Lib.StyleListeners) do
			pcall(listener, style)
		end

		local item = Lib.Flags["menu_style"]
		if item and item.GetValue and item:GetValue() ~= (style == "visions" and "Visions" or "Classic") then
			-- the Settings row shows the new pick (its callback lands back here and does nothing new)
			pcall(item.SetValue, item, style == "visions" and "Visions" or "Classic")
		end
	end

	-- Holds the menu off the screen (the intro and the style picker are on it); Lib:ReleaseMenu shows it again, faded in.
	function Lib:HoldMenu()
		Lib.MenuHeld = true
		applyMenuStyle()
	end

	function Lib:ReleaseMenu(fadeTime)
		Lib.MenuHeld = false
		applyMenuStyle()

		local window = Lib.Window
		if not window or not gui then
			return
		end

		local target = (Lib:GetMenuStyle() == "visions" and visions and visions.Frame) or window.Panel
		if not target or not target.Visible then
			return
		end

		-- the whole window fades in as one picture: it sits in a screen-sized see-through CanvasGroup until the fade is over
		local ok = pcall(function()
			local group = new("CanvasGroup", { Name = randomName(), BackgroundTransparency = 1, GroupTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = target.ZIndex }, gui)
			target.Parent = group
			fadeTime = fadeTime or 0.6
			TweenService:Create(group, TweenInfo.new(fadeTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { GroupTransparency = 0 }):Play()
			task.delay(fadeTime + 0.05, function()
				if target.Parent == group then
					target.Parent = gui
				end
				group:Destroy()
			end)
		end)

		if not ok and target.Parent ~= gui then
			target.Parent = gui
		end
	end

	-- The first run on a machine: two cards, Classic and Visions, each with a small drawing of its look. A click (or 1 / 2) picks one; it can
	-- be changed any time in Settings > Menu Style or with the button at the top of either window. Calls done(style) once picked.
	function Lib:PickMenuStyle(done)
		local T = VISIONS_THEME
		local holder = new("Frame", { Name = randomName(), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, Size = UDim2.fromScale(1, 1), ZIndex = 4000 }, gui)
		local title = new("TextLabel", { AnchorPoint = Vector2.new(0.5, 0), BackgroundTransparency = 1, Font = T.FontBold, Position = UDim2.new(0.5, 0, 0.5, -170), Size = UDim2.fromOffset(500, 30), Text = "Pick your menu", TextColor3 = T.Text, TextSize = 24, ZIndex = 4001 }, holder)
		new("TextLabel", { AnchorPoint = Vector2.new(0.5, 0), BackgroundTransparency = 1, Font = T.Font, Position = UDim2.new(0.5, 0, 0.5, -136), Size = UDim2.fromOffset(500, 20), Text = "You can change it any time in Settings, under Menu Style.", TextColor3 = T.TextDim, TextSize = 13, ZIndex = 4001 }, holder)

		local finished = false
		local keyConnection

		local function pick(style)
			if finished then
				return
			end
			finished = true
			if keyConnection then
				keyConnection:Disconnect()
			end
			Lib:SetMenuStyle(style, true)
			holder:Destroy()
			if done then
				done(style)
			end
		end

		local function card(index, name, description, draw)
			local c = new("TextButton", {
				AnchorPoint = Vector2.new(0.5, 0),
				AutoButtonColor = false,
				BackgroundColor3 = T.Window,
				BorderSizePixel = 0,
				Position = UDim2.new(0.5, index == 1 and -130 or 130, 0.5, -100),
				Size = UDim2.fromOffset(230, 220),
				Text = "",
				ZIndex = 4001,
			}, holder)
			corner(c, 6)
			local stroke = new("UIStroke", { Color = T.WindowBorder, Thickness = 1 }, c)
			local art = new("Frame", { BackgroundColor3 = Color3.fromRGB(14, 14, 14), BorderSizePixel = 0, Position = UDim2.fromOffset(12, 12), Size = UDim2.new(1, -24, 0, 120), ZIndex = 4002 }, c)
			corner(art, 4)
			draw(art)
			new("TextLabel", { BackgroundTransparency = 1, Font = T.FontBold, Position = UDim2.fromOffset(12, 142), Size = UDim2.new(1, -24, 0, 20), Text = index .. "   " .. name, TextColor3 = T.Text, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4002 }, c)
			new("TextLabel", { BackgroundTransparency = 1, Font = T.Font, Position = UDim2.fromOffset(12, 166), Size = UDim2.new(1, -24, 0, 40), Text = description, TextColor3 = T.TextDim, TextSize = 12, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = 4002 }, c)

			bind(c.MouseEnter, function() stroke.Color = T.Accent end)
			bind(c.MouseLeave, function() stroke.Color = T.WindowBorder end)
			bind(c.MouseButton1Click, function()
				pick(index == 1 and "classic" or "visions")
			end)
		end

		card(1, "Classic", "Icons down the side, green ticks, every option in one window.", function(art)
			new("Frame", { BackgroundColor3 = Color3.fromRGB(10, 10, 10), BorderSizePixel = 0, Position = UDim2.fromOffset(8, 10), Size = UDim2.fromOffset(34, 100), ZIndex = 4003 }, art)
			new("Frame", { BackgroundColor3 = ACCENT, BorderSizePixel = 0, Position = UDim2.fromOffset(8, 4), Size = UDim2.new(1, -16, 0, 2), ZIndex = 4003 }, art)
			for i = 0, 4 do
				new("Frame", { BackgroundColor3 = i % 2 == 0 and ACCENT or OFF_COLOR, BorderSizePixel = 0, Position = UDim2.fromOffset(52, 16 + i * 18), Size = UDim2.fromOffset(9, 9), ZIndex = 4003 }, art)
				new("Frame", { BackgroundColor3 = Color3.fromRGB(70, 70, 70), BorderSizePixel = 0, Position = UDim2.fromOffset(66, 19 + i * 18), Size = UDim2.fromOffset(60, 3), ZIndex = 4003 }, art)
			end
		end)

		card(2, "Visions", "Tabs across the top, red ticks, the razor on the corner.", function(art)
			for i = 0, 3 do
				new("Frame", { BackgroundColor3 = i == 0 and T.Accent or Color3.fromRGB(70, 70, 70), BorderSizePixel = 0, Position = UDim2.fromOffset(60 + i * 30, 12), Size = UDim2.fromOffset(22, i == 0 and 3 or 2), ZIndex = 4003 }, art)
			end
			new("Frame", { BackgroundColor3 = T.Element, BorderSizePixel = 0, Position = UDim2.fromOffset(8, 8), Size = UDim2.fromOffset(44, 10), ZIndex = 4003 }, art)
			for i = 0, 3 do
				local b = new("Frame", { BackgroundColor3 = T.Element, BorderSizePixel = 0, Position = UDim2.fromOffset(150, 30 + i * 20), Size = UDim2.fromOffset(12, 12), ZIndex = 4003 }, art)
				corner(b, 2)
				if i % 2 == 0 then
					new("TextLabel", { BackgroundTransparency = 1, Font = T.FontBold, Size = UDim2.fromScale(1, 1), Text = "✓", TextColor3 = T.Accent, TextSize = 10, ZIndex = 4004 }, b)
				end
				new("Frame", { BackgroundColor3 = Color3.fromRGB(70, 70, 70), BorderSizePixel = 0, Position = UDim2.fromOffset(14, 34 + i * 20), Size = UDim2.fromOffset(70, 3), ZIndex = 4003 }, art)
			end
		end)

		keyConnection = UserInputService.InputBegan:Connect(function(input, processed)
			if processed then
				return
			end
			if input.KeyCode == Enum.KeyCode.One or input.KeyCode == Enum.KeyCode.KeypadOne then
				pick("classic")
			elseif input.KeyCode == Enum.KeyCode.Two or input.KeyCode == Enum.KeyCode.KeypadTwo then
				pick("visions")
			end
		end)

		title.TextTransparency = 1
		vtween(title, { TextTransparency = 0 }, 0.4)
	end

	return Lib
end

NeverLose = createJujuLib()

-- Set before any UI is built, so Unload() takes everything down.
NeverLose.UnloadEnabled = true

-- Who is picked in the Target List belongs to the server you are in: configs neither save nor load it.
NeverLose.NoConfig = { target_players = true, menu_style = true }

---------- Option window layout ------------
-- Option windows are a fixed 220px wide and put a control (slider 125px, dropdown 100px) on the
-- same line as its name, so a long name ran under the control. A row that would collide is
-- restacked instead: the name on top, the control on its own line below.
do
	local WINDOW_WIDTH = 220
	local ROW_PADDING = 11
	local NAME_GAP = 8
	local NAME_SIZE = 13
	local STACKED_ROW_HEIGHT = 48
	local STACKED_CONTROL_TOP = 22
	local STACKED_CONTROL_WIDTH = WINDOW_WIDTH - ROW_PADDING * 2 - 2
	local DEFAULT_CONTROL_WIDTH = { AddSlider = 125, AddDropdown = 100 }

	-- True when the name and a control of controlWidth fit on one line without touching.
	local function fitsOnOneLine(name, controlWidth)
		local nameSize = TextService:GetTextSize(tostring(name), NAME_SIZE, Enum.Font.GothamMedium, Vector2.new(math.huge, math.huge))
		return ROW_PADDING + nameSize.X + NAME_GAP <= WINDOW_WIDTH - ROW_PADDING - controlWidth
	end

	-- Moves the control holder under the name and makes the row tall enough for both.
	local function stackRow(label)
		label.Root.Size = UDim2.new(1, 0, 0, STACKED_ROW_HEIGHT)

		for _, child in ipairs(label.Root:GetChildren()) do
			if child:IsA("Frame") and child:FindFirstChildOfClass("UIListLayout") then
				child.Position = UDim2.new(1, -ROW_PADDING, 0, STACKED_CONTROL_TOP)
			end
		end
	end

	-- Clearing the search box shows every row again, which would bring back rows the menu hides on
	-- purpose. A pinned row hides itself again whenever it was last asked to be hidden.
	function Session.pinRow(label)
		if label.Pinned then
			return
		end
		label.Pinned = true

		local wanted = true
		local setVisible = label.SetVisible

		label.SetVisible = function(self, visible)
			wanted = visible
			setVisible(self, visible)
		end

		track(label.Root:GetPropertyChangedSignal("Visible"):Connect(function()
			if not wanted and label.Root.Visible then
				label.Root.Visible = false
			end
		end))
	end

	-- Slider and dropdown rows restack themselves when their name would run under the control.
	local function guardRow(label, name)
		for method, defaultWidth in pairs(DEFAULT_CONTROL_WIDTH) do
			local addControl = label[method]

			if type(addControl) == "function" then
				label[method] = function(self, config, ...)
					local stacked = false

					if type(config) == "table" then
						local ok, fits = pcall(fitsOnOneLine, name, config.Size or defaultWidth)
						if ok and not fits then
							config = table.clone(config)
							config.Size = STACKED_CONTROL_WIDTH
							stacked = true
						end
					end

					local control = addControl(self, config, ...)
					if stacked then
						pcall(stackRow, label)
					end

					return control
				end
			end
		end
	end

	if not NeverLose.OptionLayoutHooked and type(NeverLose.CreateOptionWindow) == "function" then
		NeverLose.OptionLayoutHooked = true

		local createOptionWindow = NeverLose.CreateOptionWindow
		NeverLose.CreateOptionWindow = function(self, ...)
			local window = createOptionWindow(self, ...)

			local addLabel = type(window) == "table" and window.AddLabel
			if type(addLabel) == "function" then
				window.AddLabel = function(windowSelf, name, ...)
					local label = addLabel(windowSelf, name, ...)
					pcall(guardRow, label, name)
					return label
				end
			end

			return window
		end
	end
end

---------- Helpers ------------
local function log(icon, text, duration)
	if Logging then
		pcall(Logging.new, icon, text, duration or 5)
	end
end

local function describe(value)
	if type(value) ~= "table" then
		return tostring(value)
	end

	local parts = {}
	for key, item in pairs(value) do
		if type(key) == "number" then
			table.insert(parts, tostring(item))
		elseif item == true then
			table.insert(parts, tostring(key))
		end
	end
	table.sort(parts)
	return "{" .. table.concat(parts, ", ") .. "}"
end

