local function onChanged(name)
	return function(value)
		if DEBUG then
			print(("[Visions hook] %s = %s"):format(name, describe(value)))
		end
		local map = NL_TO_NEVERLOSE_FLAG[name]
		if not map then return end
		local neverlose_flag = map[1]
		local menu_ref = map[2]
		local kind = map[3]
		-- Dropdowns arrive as { [name] = true } or a string; the engine wants an array of names.
		if kind == "list" then
			local names = {}
			if type(value) == "table" then
				for key, picked in pairs(value) do
					if type(key) == "number" then
						table.insert(names, tostring(picked))
					elseif picked == true then
						table.insert(names, tostring(key))
					end
				end
				table.sort(names)
			elseif value ~= nil then
				table.insert(names, tostring(value))
			end
			value = names
		elseif kind == "hitbox" then
			-- The engine only knows head or root.
			local head = false
			if type(value) == "table" then
				head = value.Head == true or table.find(value, "Head") ~= nil
			end
			value = { head and "head" or "root" }
		end
		if neverlose_flag and type(_G.neverlose_flags) == "table" then
			_G.neverlose_flags[neverlose_flag] = value
		end
		if menu_ref and type(_G.neverlose_menu_refs) == "table" then
			local el = _G.neverlose_menu_refs[menu_ref]
			if el then
				if kind == "color" and type(el.set_color) == "function" then
					pcall(el.set_color, el, value)
				elseif type(el.set_toggle) == "function" and type(value) == "boolean" then
					pcall(el.set_toggle, el, value)
				elseif type(el.set_value) == "function" then
					pcall(el.set_value, el, value)
				else
					if el.on_toggle_change and el.on_toggle_change.Fire then
						pcall(el.on_toggle_change.Fire, el.on_toggle_change, value)
					end
				end
			end
		end
	end
end

local function keyName(value)
	if typeof(value) == "EnumItem" then
		return value.Name
	end
	return tostring(value)
end

-- Keys are stored as a KeyCode name, or "M1B"/"M2B"/"M3B" for mouse buttons.
local function inputMatchesKey(input, key)
	if key == nil or key == "None" then
		return false
	end
	if key == "M1B" then
		return input.UserInputType == Enum.UserInputType.MouseButton1
	end
	if key == "M2B" then
		return input.UserInputType == Enum.UserInputType.MouseButton2
	end
	if key == "M3B" then
		return input.UserInputType == Enum.UserInputType.MouseButton3
	end
	return input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode.Name == key
end

local function displayKey(key)
	if key == "M1B" then
		return "Mouse 1"
	elseif key == "M2B" then
		return "Mouse 2"
	elseif key == "M3B" then
		return "Mouse 3"
	end
	return key
end

local function mouseIsOver(guiObject)
	local mouse = UserInputService:GetMouseLocation()
	local position, size = guiObject.AbsolutePosition, guiObject.AbsoluteSize
	return mouse.X >= position.X and mouse.X <= position.X + size.X and mouse.Y >= position.Y and mouse.Y <= position.Y + size.Y
end

---------- Menu settings state ------------
local currentMenuKey = MENU_KEY
local currentScale = "Default"

local function setMenuKey(value)
	if value == nil then
		return
	end

	local name = keyName(value)
	if name == currentMenuKey then
		return
	end

	-- The menu toggle only understands keyboard keys. "None" (Escape) and the mouse buttons can never match a key press, which would leave the
	-- menu with no way to open and a config would keep that. The control goes back to the key in use.
	local okName, keyCodeOfName = pcall(function()
		return Enum.KeyCode[name]
	end)
	if name == "None" or not okName or keyCodeOfName == nil or keyCodeOfName == Enum.KeyCode.Unknown then
		if name ~= "None" then
			log("ps4-touchpad", name .. " can't open the menu, pick a keyboard key", 5)
		end

		task.defer(function()
			local control = Session.Alive and NeverLose.Flags and NeverLose.Flags["ui_keybind"]
			if control then
				pcall(control.SetValue, control, currentMenuKey)
			end
		end)
		return
	end

	-- Store the key in the same form the window already uses.
	local newKey = name
	if typeof(window.Keybind) == "EnumItem" then
		local okKey, keyCode = pcall(function()
			return Enum.KeyCode[name]
		end)
		if not okKey then
			log("ps4-touchpad", "Unknown key: " .. name, 5)
			return
		end
		newKey = keyCode
	end

	window.Keybind = newKey
	currentMenuKey = name

	log("ps4-touchpad", "Changed ui keybind to " .. name, 5)
end

local function setMenuScale(value)
	if value == currentScale then
		return
	end

	local scale = NeverLose.Scales and NeverLose.Scales[value]
	if scale == nil then
		log("crop", "Menu scale '" .. tostring(value) .. "' is not available", 5)
		return
	end

	window:SetSize(scale)
	currentScale = value

	log("crop", "Changed ui size to " .. tostring(value), 5)
end

local function menuIsOpen()
	local signal = window and window.Signal
	if signal and type(signal.GetValue) == "function" then
		return signal:GetValue() and true or false
	end
	return true
end

-- the engine part (Hold To Fire) asks the same thing
sharedEnv.neverlose_menu_open = function()
	return Session.Alive and menuIsOpen()
end

-- where the open menu is on the screen (nil when closed): the ESP keeps out of it
sharedEnv.neverlose_menu_rect = function()
	if Session.Alive and NeverLose and NeverLose.MenuRect then
		return NeverLose:MenuRect()
	end
	return nil
end

-- The library places the subtitle under the title, left-aligned. Centre it under
-- the title text instead.
local function centerSubtitle()
	for _, item in ipairs(NeverLose.ScreenGui:GetDescendants()) do
		if item:IsA("TextLabel") and item.Text == WINDOW_CONTENT then
			for _, sibling in ipairs(item.Parent:GetChildren()) do
				if sibling:IsA("TextLabel") and sibling.Text == WINDOW_NAME then
					local titleWidth = TextService:GetTextSize(sibling.Text, sibling.TextSize, sibling.Font, Vector2.new(1000, 100)).X
					item.AnchorPoint = Vector2.new(0.5, 0)
					item.Position = UDim2.new(sibling.Position.X.Scale, sibling.Position.X.Offset + titleWidth / 2, item.Position.Y.Scale, item.Position.Y.Offset)
					item.TextXAlignment = Enum.TextXAlignment.Center
					return
				end
			end
		end
	end
end

---------- Shared look for the panels this script draws ------------
local PANEL_COLOR = Color3.fromRGB(20, 20, 20)
local CARD_COLOR = Color3.fromRGB(32, 32, 32)
local STROKE_COLOR = Color3.fromRGB(60, 60, 60)
local ACCENT_COLOR = Color3.fromRGB(160, 195, 5)

local function newCorner(parent, radius)
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, radius)
	corner.Parent = parent
	return corner
end

local function newStroke(parent)
	local stroke = Instance.new("UIStroke")
	stroke.Color = STROKE_COLOR
	stroke.Transparency = 0.35
	stroke.Parent = parent
	return stroke
end

local function newText(parent, text, size, zIndex)
	local label = Instance.new("TextLabel")
	label.BackgroundTransparency = 1
	label.Font = Enum.Font.GothamMedium
	label.Text = text
	label.TextColor3 = Color3.fromRGB(255, 255, 255)
	label.TextSize = size
	label.TextXAlignment = Enum.TextXAlignment.Left
	label.ZIndex = zIndex
	label.Parent = parent
	return label
end

local function newButton(parent, text, zIndex)
	local button = Instance.new("TextButton")
	button.AutoButtonColor = false
	button.BackgroundColor3 = CARD_COLOR
	button.BorderSizePixel = 0
	button.Font = Enum.Font.GothamMedium
	button.Text = text
	button.TextColor3 = Color3.fromRGB(255, 255, 255)
	button.TextSize = 11
	button.ZIndex = zIndex
	button.Parent = parent
	newCorner(button, 4)
	newStroke(button)
	return button
end

---------- Right-click keybinds ------------
-- Right-click any toggle's row in the Rage tab to bind it to a key, as Toggle
-- (press flips it) or Hold (on only while held). Binds are saved to BINDS_FILE.
local Binds = { Entries = {} }
local BindPopup = {}
local capturingEntry

-- The on-screen keybind list; filled in by its own section further down.
local KeybindList = { Mode = "Show All", Rows = {}, Queued = false }
local refreshKeybindList = function() end

local function saveBinds()
	if type(writefile) ~= "function" then
		return
	end

	local data = {}
	for flag, entry in pairs(Binds.Entries) do
		if entry.Key ~= "None" then
			data[flag] = { Key = entry.Key, Mode = entry.Mode }
		end
	end

	pcall(function()
		if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(CONFIG_FOLDER) then
			makefolder(CONFIG_FOLDER)
		end
		writefile(BINDS_FILE, HttpService:JSONEncode(data))
	end)
end

-- Loading a config sets many binds at once: one write of the file a moment later is enough.
local bindSaveQueued = false

local function queueSaveBinds()
	if bindSaveQueued then
		return
	end
	bindSaveQueued = true

	task.delay(0.5, function()
		bindSaveQueued = false

		if Session.Alive then
			saveBinds()
		end
	end)
end

local function loadBinds()
	if type(readfile) ~= "function" or type(isfile) ~= "function" then
		return
	end

	pcall(function()
		if not isfile(BINDS_FILE) then
			return
		end

		local data = HttpService:JSONDecode(readfile(BINDS_FILE))
		for flag, saved in pairs(data) do
			local entry = Binds.Entries[flag]
			if entry and type(saved) == "table" and type(saved.Key) == "string" then
				entry.Key = saved.Key
				entry.Mode = (saved.Mode == "Hold" and "Hold") or "Toggle"
			end
		end
	end)
end

local function refreshBindPopup()
	local entry = BindPopup.Entry
	if not (entry and BindPopup.Frame) then
		return
	end

	BindPopup.Title.Text = entry.Name
	BindPopup.KeyButton.Text = (capturingEntry == entry and "Press a key...") or displayKey(entry.Key)

	-- The active mode is highlighted in the accent blue.
	for mode, button in pairs(BindPopup.ModeButtons) do
		button.BackgroundColor3 = (entry.Mode == mode and ACCENT_COLOR) or CARD_COLOR
	end
end

-- Turns a Hold bind's option off if its key is currently held down.
local function releaseHeld(entry)
	if entry.Held then
		entry.Held = false
		entry.Toggle:SetValue(false)
	end
end

local function setBindMode(mode)
	local entry = BindPopup.Entry
	if not entry or entry.Mode == mode then
		return
	end

	releaseHeld(entry)
	entry.Mode = mode
	refreshBindPopup()
	refreshKeybindList()
	saveBinds()
end

local function clearBind()
	local entry = BindPopup.Entry
	if not entry then
		return
	end

	capturingEntry = nil
	releaseHeld(entry)
	entry.Key = "None"
	entry.Mode = "Toggle"
	refreshBindPopup()
	refreshKeybindList()
	saveBinds()
	log("ps4-touchpad", entry.Name .. " bind cleared", 3)
end

local function closeBindPopup()
	capturingEntry = nil
	BindPopup.Entry = nil
	if BindPopup.Frame then
		BindPopup.Frame.Visible = false
	end
end

local function openBindPopup(entry)
	if not BindPopup.Frame then
		return
	end

	capturingEntry = nil
	BindPopup.Entry = entry
	refreshBindPopup()

	local mouse = UserInputService:GetMouseLocation()
	BindPopup.Frame.Position = UDim2.fromOffset(mouse.X + 6, mouse.Y + 6)
	BindPopup.Frame.Visible = true
end

-- Called with the next key or mouse button after "Key" is clicked.
-- Escape cancels, Backspace clears the bind, a left click outside the popup closes it.
local function finishCapture(input)
	local entry = capturingEntry
	local newKey

	if input.UserInputType == Enum.UserInputType.MouseButton1 then
		if not mouseIsOver(BindPopup.Frame) then
			closeBindPopup()
		end
		return
	elseif input.KeyCode == Enum.KeyCode.Escape then
		capturingEntry = nil
		refreshBindPopup()
		return
	elseif input.KeyCode == Enum.KeyCode.Backspace then
		newKey = "None"
	elseif input.KeyCode ~= Enum.KeyCode.Unknown then
		newKey = input.KeyCode.Name
	elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
		newKey = "M2B"
	elseif input.UserInputType == Enum.UserInputType.MouseButton3 then
		newKey = "M3B"
	else
		return
	end

	capturingEntry = nil

	-- Releasing a Hold bind's old key would no longer turn it off.
	releaseHeld(entry)

	entry.Key = newKey
	refreshBindPopup()
	refreshKeybindList()
	saveBinds()

	if newKey == "None" then
		log("ps4-touchpad", entry.Name .. " bind cleared", 3)
	else
		log("ps4-touchpad", ("%s bound to %s (%s)"):format(entry.Name, displayKey(newKey), entry.Mode), 3)
	end
end

local function buildBindPopup()
	local frame = Instance.new("Frame")
	frame.Name = "KeybindPopup"
	frame.Size = UDim2.fromOffset(190, 120)
	frame.BackgroundColor3 = PANEL_COLOR
	frame.BackgroundTransparency = 0.03
	frame.BorderSizePixel = 0
	frame.Visible = false
	frame.ZIndex = 2600
	newCorner(frame, 6)
	newStroke(frame)

	local title = newText(frame, "", 11, 201)
	title.Font = Enum.Font.GothamBold
	title.Position = UDim2.fromOffset(10, 0)
	title.Size = UDim2.new(1, -20, 0, 28)
	title.TextTruncate = Enum.TextTruncate.AtEnd

	local keyLabel = newText(frame, "Key", 11, 201)
	keyLabel.TextTransparency = 0.35
	keyLabel.Position = UDim2.fromOffset(10, 32)
	keyLabel.Size = UDim2.fromOffset(60, 22)

	local keyButton = newButton(frame, "None", 201)
	keyButton.Position = UDim2.fromOffset(80, 32)
	keyButton.Size = UDim2.fromOffset(100, 22)

	local modeLabel = newText(frame, "Mode", 11, 201)
	modeLabel.TextTransparency = 0.35
	modeLabel.Position = UDim2.fromOffset(10, 60)
	modeLabel.Size = UDim2.fromOffset(60, 22)

	local toggleButton = newButton(frame, "Toggle", 201)
	toggleButton.Position = UDim2.fromOffset(80, 60)
	toggleButton.Size = UDim2.fromOffset(48, 22)

	local holdButton = newButton(frame, "Hold", 201)
	holdButton.Position = UDim2.fromOffset(132, 60)
	holdButton.Size = UDim2.fromOffset(48, 22)

	local clearButton = newButton(frame, "Clear bind", 201)
	clearButton.Position = UDim2.fromOffset(10, 90)
	clearButton.Size = UDim2.new(1, -20, 0, 22)

	-- Act on press, not release, so a click always lands even if the mouse moves
	-- off the button or the global input handler sees it first.
	local function onPress(button, action)
		track(button.InputBegan:Connect(function(input)
			if Session.Alive and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
				action()
			end
		end))
	end

	onPress(keyButton, function()
		if BindPopup.Entry then
			capturingEntry = BindPopup.Entry
			refreshBindPopup()
		end
	end)

	onPress(toggleButton, function()
		setBindMode("Toggle")
	end)

	onPress(holdButton, function()
		setBindMode("Hold")
	end)

	onPress(clearButton, clearBind)

	frame.Parent = NeverLose.ScreenGui
	BindPopup.Frame = frame
	BindPopup.Title = title
	BindPopup.KeyButton = keyButton
	BindPopup.ModeButtons = { Toggle = toggleButton, Hold = holdButton }
end

-- AddToggle on a label, plus right-click-to-bind on that label's row.
-- The callback is wrapped so the keybind list follows the toggle's state.
local function addBindableToggle(label, name, config)
	local callback = config.Callback
	config.Callback = function(value)
		callback(value)
		refreshKeybindList()
	end

	local toggle = label:AddToggle(config)
	local entry = { Name = name, Flag = config.Flag, Toggle = toggle, Key = "None", Mode = "Toggle", Held = false }
	Binds.Entries[config.Flag] = entry

	-- the Visions look opens the bind popup of a row by its flag (a right click on the row there)
	if NeverLose and not NeverLose.OpenBind then
		NeverLose.OpenBind = function(flag)
			local bindEntry = flag and Binds.Entries[flag]

			if Session.Alive and bindEntry and not capturingEntry then
				openBindPopup(bindEntry)
				return true
			end

			return false
		end
	end

	-- The key and the mode of the bind are part of every config: saving or overwriting one keeps them, loading one brings them back.
	if config.Flag and NeverLose and type(NeverLose.Flags) == "table" then
		NeverLose.Flags["bind:" .. tostring(config.Flag)] = {
			Kind = "bind",
			GetValue = function()
				return { Key = entry.Key, Mode = entry.Mode }
			end,
			SetValue = function(_, saved)
				if type(saved) ~= "table" or type(saved.Key) ~= "string" then
					return
				end

				releaseHeld(entry)
				entry.Key = saved.Key
				entry.Mode = saved.Mode == "Hold" and "Hold" or "Toggle"

				if BindPopup.Entry == entry then
					refreshBindPopup()
				end

				refreshKeybindList()
				queueSaveBinds()
			end,
		}
	end

	local function openFromRightClick(input)
		if Session.Alive and input.UserInputType == Enum.UserInputType.MouseButton2 and not capturingEntry then
			openBindPopup(entry)
		end
	end

	-- The name of a row is a button that takes the click before the row itself sees it, so the button is listened to as well.
	for _, part in ipairs({ label.Root, label.Head, label.Hit }) do
		if typeof(part) == "Instance" and part:IsA("GuiObject") then
			track(part.InputBegan:Connect(openFromRightClick))
		end
	end

	if typeof(label.Hit) == "Instance" and label.Hit:IsA("GuiButton") then
		track(label.Hit.MouseButton2Click:Connect(function()
			if Session.Alive and not capturingEntry then
				openBindPopup(entry)
			end
		end))
	end

	return toggle
end

local function onBindInputBegan(input)
	for _, entry in pairs(Binds.Entries) do
		-- While the master switch is on, only the master switches answer to their keys.
		if inputMatchesKey(input, entry.Key) and Session.bindAllowed(entry.Flag) then
			if entry.Mode == "Hold" then
				entry.Held = true
				entry.Toggle:SetValue(true)
			else
				entry.Toggle:SetValue(not entry.Toggle:GetValue())
			end
		end
	end
end

local function onBindInputEnded(input)
	for _, entry in pairs(Binds.Entries) do
		if entry.Mode == "Hold" and entry.Held and inputMatchesKey(input, entry.Key) then
			entry.Held = false
			entry.Toggle:SetValue(false)
		end
	end
end

---------- Character preview ------------
-- A small panel showing each player picked in the Target List. By default it
-- stays on screen with the menu closed; the "Show Selected Outside Menu" setting
-- limits it to while the menu is open. It lives inside the library's ScreenGui,
-- so Unload removes it too.
local Preview = { Cards = {}, CharacterConnections = {}, Names = {}, AlwaysShow = true }

local function cloneCharacter(character)
	local wasArchivable = character.Archivable
	character.Archivable = true
	local ok, copy = pcall(character.Clone, character)
	character.Archivable = wasArchivable

	if not ok or not copy then
		return nil
	end

	-- Only the looks are needed: drop anything that could run or make noise.
	for _, item in ipairs(copy:GetDescendants()) do
		if item:IsA("BaseScript") or item:IsA("Sound") or item:IsA("BillboardGui") or item:IsA("ForceField") then
			item:Destroy()
		end
	end
	return copy
end

local function framingCamera(model)
	local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
	local boxCFrame, boxSize = model:GetBoundingBox()
	local center = (root and root.Position) or boxCFrame.Position
	local forward = (root and root.CFrame.LookVector) or boxCFrame.LookVector
	local height = math.clamp(boxSize.Y, 4, 8)
	local eye = center + forward * (height * 1.15 + 1) + Vector3.new(0, height * 0.1, 0)
	return CFrame.lookAt(eye, center)
end

local function buildPreviewPanel()
	local panel = Instance.new("Frame")
	panel.Name = "TargetPreview"
	panel.AnchorPoint = Vector2.new(1, 0.5)
	panel.Position = UDim2.new(1, -20, 0.5, 0)
	panel.Size = UDim2.fromOffset(228, 300)
	panel.BackgroundColor3 = PANEL_COLOR
	panel.BackgroundTransparency = 0.03
	panel.BorderSizePixel = 0
	panel.Visible = false
	panel.ZIndex = 50
	newCorner(panel, 6)
	newStroke(panel)

	local header = newText(panel, "SELECTED", 11, 51)
	header.Name = "Header"
	header.Font = Enum.Font.GothamBold
	header.TextTransparency = 0.35
	header.Position = UDim2.fromOffset(12, 0)
	header.Size = UDim2.new(1, -24, 0, 30)

	local line = Instance.new("Frame")
	line.BackgroundColor3 = STROKE_COLOR
	line.BackgroundTransparency = 0.35
	line.BorderSizePixel = 0
	line.Position = UDim2.fromOffset(0, 30)
	line.Size = UDim2.new(1, 0, 0, 1)
	line.ZIndex = 51
	line.Parent = panel

	local list = Instance.new("ScrollingFrame")
	list.Name = "Cards"
	list.BackgroundTransparency = 1
	list.BorderSizePixel = 0
	list.Position = UDim2.fromOffset(10, 40)
	list.Size = UDim2.new(1, -20, 1, -50)
	list.CanvasSize = UDim2.new()
	list.AutomaticCanvasSize = Enum.AutomaticSize.Y
	list.ScrollBarThickness = 2
	list.ScrollBarImageColor3 = ACCENT_COLOR
	list.ZIndex = 51
	list.Parent = panel

	local grid = Instance.new("UIGridLayout")
	grid.CellSize = UDim2.fromOffset(100, 124)
	grid.CellPadding = UDim2.fromOffset(8, 8)
	grid.SortOrder = Enum.SortOrder.Name
	grid.Parent = list

	-- Drag the panel by its header.
	local dragStart, panelStart
	track(header.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragStart = input.Position
			panelStart = panel.Position
		end
	end))

	track(UserInputService.InputChanged:Connect(function(input)
		if dragStart and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local delta = input.Position - dragStart
			panel.Position = UDim2.new(panelStart.X.Scale, panelStart.X.Offset + delta.X, panelStart.Y.Scale, panelStart.Y.Offset + delta.Y)
		end
	end))

	track(UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragStart = nil
		end
	end))

	panel.Parent = NeverLose.ScreenGui
	Preview.Panel = panel
	Preview.List = list
end

local function createCard(player)
	local card = Instance.new("Frame")
	card.Name = player.Name:lower()
	card.BackgroundColor3 = CARD_COLOR
	card.BorderSizePixel = 0
	card.ZIndex = 52
	newCorner(card, 4)
	newStroke(card)

	local viewport = Instance.new("ViewportFrame")
	viewport.BackgroundTransparency = 1
	viewport.Size = UDim2.new(1, 0, 1, -22)
	viewport.Ambient = Color3.fromRGB(170, 170, 180)
	viewport.LightColor = Color3.fromRGB(255, 255, 255)
	viewport.LightDirection = Vector3.new(-1, -1, -1)
	viewport.ZIndex = 53
	viewport.Parent = card

	local camera = Instance.new("Camera")
	camera.FieldOfView = 40
	camera.Parent = viewport
	viewport.CurrentCamera = camera

	-- Shown instead of the 3D view while the player has no character.
	local image = Instance.new("ImageLabel")
	image.BackgroundTransparency = 1
	image.Size = UDim2.new(1, 0, 1, -22)
	image.ScaleType = Enum.ScaleType.Fit
	image.Visible = false
	image.ZIndex = 53
	image.Parent = card

	local nameLabel = newText(card, player.DisplayName, 11, 53)
	nameLabel.TextTransparency = 0.2
	nameLabel.TextXAlignment = Enum.TextXAlignment.Center
	nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
	nameLabel.Position = UDim2.new(0, 4, 1, -22)
	nameLabel.Size = UDim2.new(1, -8, 0, 20)

	card.Parent = Preview.List

	return { Card = card, Viewport = viewport, Camera = camera, Image = image }
end

local function fillCard(entry, player)
	if entry.Model then
		entry.Model:Destroy()
		entry.Model = nil
	end
	entry.Image.Visible = false

	local character = player.Character
	local model = character and cloneCharacter(character)

	if model then
		model.Parent = entry.Viewport
		entry.Camera.CFrame = framingCamera(model)
		entry.Model = model
		return
	end

	task.spawn(function()
		local ok, url = pcall(Players.GetUserThumbnailAsync, Players, player.UserId, Enum.ThumbnailType.AvatarThumbnail, Enum.ThumbnailSize.Size180x180)
		if ok and entry.Card.Parent then
			entry.Image.Image = url
			entry.Image.Visible = true
		end
	end)
end

local function updatePreviewVisibility()
	if Session.Alive and Preview.Panel then
		Preview.Panel.Visible = #Preview.Names > 0 and (Preview.AlwaysShow or menuIsOpen())
	end
end

local function disconnectCharacterWatchers()
	for _, connection in pairs(Preview.CharacterConnections) do
		connection:Disconnect()
	end
	table.clear(Preview.CharacterConnections)
end

local function setPreviewPlayers(names)
	if not (Session.Alive and Preview.List) then
		return
	end

	Preview.Names = names

	local wanted = {}
	for _, name in ipairs(names) do
		local player = Players:FindFirstChild(name)
		if player and player:IsA("Player") then
			wanted[name] = player
		end
	end

	-- A player who stays in the list keeps the card and the character copy it already has (every pick used to clone every picked character
	-- again). Cards of players who left the list, or who rejoined as a new Player object, go.
	for name, entry in pairs(Preview.Cards) do
		if wanted[name] ~= entry.Player then
			entry.Card:Destroy()
			Preview.Cards[name] = nil

			local connection = Preview.CharacterConnections[name]
			if connection then
				connection:Disconnect()
				Preview.CharacterConnections[name] = nil
			end
		end
	end

	for _, name in ipairs(names) do
		local player = wanted[name]
		if player and not Preview.Cards[name] then
			local entry = createCard(player)
			entry.Player = player
			Preview.Cards[name] = entry
			fillCard(entry, player)

			-- Refresh after a respawn, once the new character has loaded its look.
			Preview.CharacterConnections[name] = player.CharacterAdded:Connect(function()
				task.delay(1, function()
					if Session.Alive and Preview.Cards[name] == entry then
						fillCard(entry, player)
					end
				end)
			end)
		end
	end

	updatePreviewVisibility()
end

table.insert(Session.Cleanups, disconnectCharacterWatchers)

---------- Target state ------------
local targetKey = TARGET_KEY
local selectedPlayers = {} -- sorted list of names
local targetList

local function playerNames()
	local names = {}
	-- GetPlayers hands back nothing while the server connection is being torn down
	for _, player in ipairs(Players:GetPlayers() or {}) do
		if player ~= LocalPlayer then
			table.insert(names, player.Name)
		end
	end
	table.sort(names, function(a, b)
		return a:lower() < b:lower()
	end)
	return names
end

-- Picking someone should be enough to start killing them: the ragebot, automatic fire and follow
-- target are switched on for as long as anyone is picked. Only the ones switched on here are
-- switched off again, so options the user turned on themselves stay on.
-- (the Ragebot switch itself is not in the list: picking a target with the target key or the Target List never turns the ragebot on. Nor are
-- Auto Equip and Follow Target: they stay as they are set. Only Automatic Fire comes on, and only while the ragebot is already on.)
Session.TargetAutoFlags = { "AutoFire" }
Session.TargetAutoOwned = {}

-- What a config stores for a toggle that is only on for a while: an option a Hold bind has on while its key is down, and the options picking a
-- target switched on by itself. Saved as on they would start the next session already running.
NeverLose.ConfigValueFilter = function(flag, value)
	if value == true then
		local entry = Binds.Entries[flag]
		if entry and entry.Held then
			return false
		end

		if Session.TargetAutoOwned[flag] then
			return false
		end
	end

	return value
end

function Session.updateTargetAutomation(active)
	-- After an Anti Report shutdown nothing switches itself back on, picking a target included.
	if sharedEnv.neverlose_safety_shutdown then
		return
	end

	local flagLib = NeverLose and NeverLose.Flags
	if type(flagLib) ~= "table" then
		return
	end

	-- Only the step from nobody picked to somebody picked switches the options on. A second pick, or a picked player leaving, must not bring back
	-- an option that was turned off in the meantime (Follow Target moves the character).
	local holding = Session.Master and Session.Master.Active
	local ragebotSwitch = flagLib["Ragebot"]
	local ragebotOn = ragebotSwitch and type(ragebotSwitch.GetValue) == "function" and ragebotSwitch:GetValue() == true
	local starting = active and not holding and not Session.TargetAutoOn and ragebotOn

	if not active then
		Session.TargetAutoOn = false
	elseif not holding then
		Session.TargetAutoOn = true
	end

	for _, flag in ipairs(Session.TargetAutoFlags) do
		local toggle = flagLib[flag]

		if toggle and type(toggle.GetValue) == "function" then
			if starting then
				if toggle:GetValue() ~= true then
					Session.TargetAutoOwned[flag] = true
					pcall(toggle.SetValue, toggle, true)
				end
			elseif not active and Session.TargetAutoOwned[flag] then
				Session.TargetAutoOwned[flag] = nil

				-- With the master switch on this one is already off; just don't bring it back later.
				local held = Session.Master.Held
				for index = #held, 1, -1 do
					if held[index] == flag then
						table.remove(held, index)
					end
				end

				if toggle:GetValue() == true then
					pcall(toggle.SetValue, toggle, false)
				end
			end
		end
	end
end

-- Hands the picked players to the engine. While anyone is picked its ragebot only goes for them
-- and chooses one by itself, so there is nothing to press.
function Session.syncEngineTargets(names)
	local api = sharedEnv.neverlose
	if type(api) ~= "table" or type(api.set_target_list) ~= "function" then
		return
	end

	local picked = {}
	for _, name in ipairs(names) do
		local player = Players:FindFirstChild(name)
		if player and player ~= LocalPlayer then
			table.insert(picked, player)
		end
	end

	pcall(api.set_target_list, picked)
	Session.updateTargetAutomation(#picked > 0)
end

-- Multi dropdowns hand back { [name] = true/false } or a plain list; keep only players still here.
local function setSelection(value)
	local names = {}
	if type(value) == "table" then
		for key, picked in pairs(value) do
			local name = (picked == true and key) or (type(key) == "number" and picked) or nil
			if type(name) == "string" and Players:FindFirstChild(name) then
				table.insert(names, name)
			end
		end
	end
	table.sort(names, function(a, b)
		return a:lower() < b:lower()
	end)

	selectedPlayers = names
	setPreviewPlayers(names)
	Session.syncEngineTargets(names)
	refreshKeybindList()
end

local function refreshTargetList()
	if not (Session.Alive and targetList) then
		return
	end

	-- A rebuild that throws halfway leaves the dropdown showing a stale or partial list, so it is
	-- retried once on the next frame instead of being left that way.
	local okValues, valuesError = pcall(targetList.SetValues, targetList, playerNames())
	if not okValues then
		warn("[Visions hook] Target List refresh failed: " .. tostring(valuesError))
		task.defer(function()
			if Session.Alive and targetList then
				pcall(targetList.SetValues, targetList, playerNames())
			end
		end)
		return
	end

	local kept, removed = {}, false
	for _, name in ipairs(selectedPlayers) do
		if Players:FindFirstChild(name) then
			kept[name] = true
		else
			removed = true
		end
	end

	-- The engine must stop chasing anyone who left even when the dropdown itself can't be updated.
	if removed and not pcall(targetList.SetValue, targetList, kept) then
		setSelection(kept)
	end
end

---Target key: adds the player under the cursor to the Target List. A cursor that is on a wall or
---missed by a little falls back to the player closest to it on screen.
function Session.addTarget()
	local camera = workspace.CurrentCamera
	if not (Session.Alive and camera and targetList) then
		return
	end

	local mouse = UserInputService:GetMouseLocation()
	local found

	-- The player the cursor points at.
	local ignore = { camera }
	if LocalPlayer.Character then
		table.insert(ignore, LocalPlayer.Character)
	end

	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = ignore
	params.IgnoreWater = true

	local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
	local result = workspace:Raycast(ray.Origin, ray.Direction * 2000, params)
	local model = result and result.Instance:FindFirstAncestorOfClass("Model")
	local owner = model and Players:GetPlayerFromCharacter(model)
	if owner and owner ~= LocalPlayer then
		found = owner
	end

	-- Otherwise the closest player to the cursor, as long as they are near it.
	if not found then
		local closest = 250

		for _, player in ipairs(Players:GetPlayers()) do
			local root = player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart")
			if root then
				local screen, onScreen = camera:WorldToViewportPoint(root.Position)
				local distance = (Vector2.new(screen.X, screen.Y) - mouse).Magnitude
				if onScreen and distance < closest then
					closest = distance
					found = player
				end
			end
		end
	end

	if not found then
		log("crosshairs-slash", "No player near the cursor", 3)
		return
	end

	if table.find(selectedPlayers, found.Name) then
		log("crosshairs", found.Name .. " is already in the Target List", 3)
		return
	end

	local picked = { [found.Name] = true }
	for _, name in ipairs(selectedPlayers) do
		picked[name] = true
	end

	-- The dropdown's callback applies the pick; if it did not run, apply it directly.
	pcall(targetList.SetValue, targetList, picked)
	if not table.find(selectedPlayers, found.Name) then
		setSelection(picked)
	end

	log("crosshairs", "Target added: " .. found.Name, 3)
end

---------- Keybind list ------------
-- An on-screen list of bound keys. "Show All" lists everything that is bound to a key (the ones that are on are lit),
-- "Show Toggled" only the ones switched on, "Off" hides the list.
-- Drag it by its header.
local function buildKeybindList()
	local panel = Instance.new("Frame")
	panel.Name = "KeybindList"
	panel.AnchorPoint = Vector2.new(0, 0.5)
	panel.Position = UDim2.new(0, 20, 0.4, 0)
	panel.Size = UDim2.fromOffset(200, 0)
	panel.AutomaticSize = Enum.AutomaticSize.Y
	panel.BackgroundColor3 = PANEL_COLOR
	panel.BackgroundTransparency = 0.03
	panel.BorderSizePixel = 0
	panel.Visible = false
	panel.ZIndex = 40
	newCorner(panel, 6)
	newStroke(panel)

	local layout = Instance.new("UIListLayout")
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	layout.Parent = panel

	local padding = Instance.new("UIPadding")
	padding.PaddingBottom = UDim.new(0, 6)
	padding.Parent = panel

	local header = newText(panel, "KEYBINDS", 11, 41)
	header.Font = Enum.Font.GothamBold
	header.TextTransparency = 0.35
	header.TextXAlignment = Enum.TextXAlignment.Center
	header.Size = UDim2.new(1, 0, 0, 26)
	header.LayoutOrder = 0

	local line = Instance.new("Frame")
	line.BackgroundColor3 = STROKE_COLOR
	line.BackgroundTransparency = 0.35
	line.BorderSizePixel = 0
	line.Size = UDim2.new(1, 0, 0, 1)
	line.LayoutOrder = 1
	line.ZIndex = 41
	line.Parent = panel

	local dragStart, panelStart
	track(header.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragStart = input.Position
			panelStart = panel.Position
		end
	end))

	track(UserInputService.InputChanged:Connect(function(input)
		if dragStart and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local delta = input.Position - dragStart
			panel.Position = UDim2.new(panelStart.X.Scale, panelStart.X.Offset + delta.X, panelStart.Y.Scale, panelStart.Y.Offset + delta.Y)
		end
	end))

	track(UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragStart = nil
		end
	end))

	panel.Parent = NeverLose.ScreenGui
	KeybindList.Panel = panel
end

local function addKeybindRow(item, order)
	local row = Instance.new("Frame")
	row.BackgroundTransparency = 1
	row.Size = UDim2.new(1, 0, 0, 20)
	row.LayoutOrder = order
	row.ZIndex = 41

	-- Blue marker for options that are currently on.
	local marker = Instance.new("Frame")
	marker.BackgroundColor3 = NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR
	marker.BorderSizePixel = 0
	marker.Position = UDim2.new(0, 8, 0.5, -5)
	marker.Size = UDim2.fromOffset(2, 10)
	marker.Visible = item.On
	marker.ZIndex = 42
	marker.Parent = row

	local name = newText(row, item.Name, 11, 42)
	name.Position = UDim2.fromOffset(16, 0)
	name.Size = UDim2.new(1, -100, 1, 0)
	name.TextTruncate = Enum.TextTruncate.AtEnd
	name.TextTransparency = (item.On and 0) or 0.5

	local key = newText(row, ("[%s] %s"):format(displayKey(item.Key), item.Mode), 10, 42)
	key.AnchorPoint = Vector2.new(1, 0)
	key.Position = UDim2.new(1, -10, 0, 0)
	key.Size = UDim2.fromOffset(84, 20)
	key.TextXAlignment = Enum.TextXAlignment.Right
	key.TextColor3 = (item.On and (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)) or Color3.fromRGB(255, 255, 255)
	key.TextTransparency = (item.On and 0) or 0.5

	row.Parent = KeybindList.Panel
	table.insert(KeybindList.Rows, row)
end

KeybindList.Rebuild = function()
	if not (Session.Alive and KeybindList.Panel) then
		return
	end

	for _, row in ipairs(KeybindList.Rows) do
		row:Destroy()
	end
	table.clear(KeybindList.Rows)

	local items = {}
	for _, entry in pairs(Binds.Entries) do
		if entry.Key ~= "None" then
			table.insert(items, { Name = entry.Name, Key = entry.Key, Mode = entry.Mode, On = entry.Toggle:GetValue() == true })
		end
	end

	if targetKey ~= "None" then
		table.insert(items, { Name = "Add Target", Key = targetKey, Mode = "Press", On = #selectedPlayers > 0 })
	end

	-- the keys the engine's own options listen to (the legit target bind ...)
	for _, engineKey in ipairs(Session.EngineKeys) do
		if engineKey.name and engineKey.key and engineKey.key ~= "None" then
			table.insert(items, { Name = engineKey.name, Key = engineKey.key, Mode = "Press", On = false })
		end
	end

	-- Show All lists everything that is bound to a key, the ones that are switched on lit up; Show Toggled only the ones switched on.
	local showAll = KeybindList.Mode == "Show All"
	local showToggled = KeybindList.Mode == "Show Toggled"

	local shown = {}
	for _, item in ipairs(items) do
		if showAll or (showToggled and item.On) then
			table.insert(shown, item)
		end
	end

	-- The Semi Rage keys, with the mode each is in.
	local semi = Session.Semi
	if (showAll or showToggled) and semi and semi.Alive and type(semi.keyStates) == "function" then
		local okStates, states = pcall(semi.keyStates)
		if okStates then
			for _, item in ipairs(states) do
				if showAll or (Session.Master.Active and item.On) then
					table.insert(shown, item)
				end
			end
		end
	end

	table.sort(shown, function(a, b)
		return a.Name:lower() < b.Name:lower()
	end)

	for index, item in ipairs(shown) do
		addKeybindRow(item, index + 1)
	end

	KeybindList.Panel.Visible = #shown > 0
end

-- Every change of a bindable option asks for a new list (loading a config changes over a hundred in one frame): the requests of a frame are
-- answered by one rebuild at the end of it.
refreshKeybindList = function()
	if KeybindList.Queued then
		return
	end
	KeybindList.Queued = true

	task.defer(function()
		KeybindList.Queued = false
		KeybindList.Rebuild()
	end)
end

