-- Voxel and Legacy are the old renderers: with either one on, every avatar loses its clothes (confirmed with a config that had Voxel on). They are
-- not offered, and a config that still names one of them gets ShadowMap instead.
local LIGHTING_MODES = { "Compatibility", "ShadowMap", "Unified", "Future" }
local CLOTHES_BREAKING_MODES = { Voxel = true, Legacy = true }

local function safeLightingMode(mode)
	if CLOTHES_BREAKING_MODES[mode] then
		return "ShadowMap", true
	end

	return mode, false
end

function assetId(id)
	return "rbxassetid://" .. tostring(id)
end

function namesOf(list)
	local names = {}
	for _, item in ipairs(list) do
		table.insert(names, item[1])
	end
	return names
end

function findIn(list, name)
	for _, item in ipairs(list) do
		if item[1] == name then
			return item[2]
		end
	end
	return nil
end

local function currentLightingMode()
	local okName, name = pcall(function()
		return Lighting.Technology.Name
	end)
	if okName and table.find(LIGHTING_MODES, name) then
		return name
	end
	return "Future"
end

local WorldSettings = {
	LightingMode = currentLightingMode(),
	Time = 4.5,
	AmbientColor = Lighting.Ambient,
	OutdoorColor = Lighting.OutdoorAmbient,
	Saturation = 0.3,
	Contrast = 0.1,
	Tint = Color3.fromRGB(255, 255, 255),
	AtmosphereColor = Color3.fromRGB(255, 255, 255),
	AtmosphereDecay = Color3.fromRGB(120, 120, 120),
	Haze = 1,
	Glare = 10,
	Offset = 0,
	Density = 0.35,
	Sky = SKYBOXES[1][1],
	Noise = NOISES[1][1],
	Volume = 25,
}

local WorldOn = {}

-- Lighting properties held at a chosen value. The game's own scripts (a day
-- cycle, for example) may set them back, so each is re-applied when it changes.
local World = { Forced = {}, Originals = {}, Watchers = {} }

local function forceLighting(property, value)
	if World.Originals[property] == nil then
		World.Originals[property] = Lighting[property]
	end

	local ok = pcall(function()
		Lighting[property] = value
	end)
	if not ok then
		return false
	end

	World.Forced[property] = value

	if not World.Watchers[property] then
		World.Watchers[property] = track(Lighting:GetPropertyChangedSignal(property):Connect(function()
			local forced = World.Forced[property]
			if Session.Alive and forced ~= nil and Lighting[property] ~= forced then
				pcall(function()
					Lighting[property] = forced
				end)
			end
		end))
	end
	return true
end

local function releaseLighting(property)
	World.Forced[property] = nil

	local original = World.Originals[property]
	World.Originals[property] = nil
	if original ~= nil then
		pcall(function()
			Lighting[property] = original
		end)
	end
end

local function setLightingMode(enabled)
	WorldOn.LightingMode = enabled
	if not enabled then
		releaseLighting("Technology")
		return
	end

	local okMode, mode = pcall(function()
		return Enum.Technology[(safeLightingMode(WorldSettings.LightingMode))]
	end)
	if not (okMode and mode and forceLighting("Technology", mode)) then
		log("sun", "Lighting mode can't be changed here", 4)
	end
end

local function setWorldTime(enabled)
	WorldOn.Time = enabled
	if enabled then
		forceLighting("ClockTime", WorldSettings.Time)
	else
		releaseLighting("ClockTime")
	end
end

local function setAmbient(enabled)
	WorldOn.Ambient = enabled
	if enabled then
		forceLighting("Ambient", WorldSettings.AmbientColor)
		forceLighting("OutdoorAmbient", WorldSettings.OutdoorColor)
	else
		releaseLighting("Ambient")
		releaseLighting("OutdoorAmbient")
	end
end

-- Saturation, contrast and tint share one ColorCorrectionEffect of our own,
-- layered on top of the game's, so turning them off just removes it.
local gradeEffect

local function updateGrade()
	local active = WorldOn.Saturation or WorldOn.Contrast or WorldOn.Tint
	if not active then
		if gradeEffect then
			gradeEffect:Destroy()
			gradeEffect = nil
		end
		return
	end

	if not (gradeEffect and gradeEffect.Parent) then
		gradeEffect = Instance.new("ColorCorrectionEffect")
		gradeEffect.Name = "NeverLoseGrade"
		gradeEffect.Parent = Lighting
	end

	gradeEffect.Saturation = (WorldOn.Saturation and WorldSettings.Saturation) or 0
	gradeEffect.Contrast = (WorldOn.Contrast and WorldSettings.Contrast) or 0
	gradeEffect.TintColor = (WorldOn.Tint and WorldSettings.Tint) or Color3.new(1, 1, 1)
end

-- Atmosphere: edit the game's own if it has one (and restore it later), or add one.
local ATMOSPHERE_PROPERTIES = { "Color", "Decay", "Haze", "Glare", "Offset", "Density" }
local atmosphere = { Target = nil, Original = nil, Created = false }

local function removeAtmosphere()
	local target = atmosphere.Target
	if target then
		if atmosphere.Created then
			target:Destroy()
		elseif atmosphere.Original and target.Parent then
			for property, value in pairs(atmosphere.Original) do
				target[property] = value
			end
		end
	end
	atmosphere.Target, atmosphere.Original, atmosphere.Created = nil, nil, false
end

local function applyAtmosphere()
	if not WorldOn.Atmosphere then
		removeAtmosphere()
		return
	end

	if not (atmosphere.Target and atmosphere.Target.Parent) then
		local existing = Lighting:FindFirstChildOfClass("Atmosphere")
		if existing then
			atmosphere.Original = {}
			for _, property in ipairs(ATMOSPHERE_PROPERTIES) do
				atmosphere.Original[property] = existing[property]
			end
			atmosphere.Target, atmosphere.Created = existing, false
		else
			atmosphere.Target = Instance.new("Atmosphere")
			atmosphere.Target.Parent = Lighting
			atmosphere.Created = true
		end
	end

	local target = atmosphere.Target
	target.Color = WorldSettings.AtmosphereColor
	target.Decay = WorldSettings.AtmosphereDecay
	target.Haze = WorldSettings.Haze
	target.Glare = WorldSettings.Glare
	target.Offset = WorldSettings.Offset
	target.Density = WorldSettings.Density
end

-- Skybox: same approach as the atmosphere, on the six face textures.
local skybox = { Target = nil, Original = nil, Created = false }

local function removeSkybox()
	local target = skybox.Target
	if target then
		if skybox.Created then
			target:Destroy()
		elseif skybox.Original and target.Parent then
			for property, value in pairs(skybox.Original) do
				target[property] = value
			end
		end
	end
	skybox.Target, skybox.Original, skybox.Created = nil, nil, false
end

local function applySkybox()
	if not WorldOn.Sky then
		removeSkybox()
		return
	end

	local faces = findIn(SKYBOXES, WorldSettings.Sky)
	if not faces then
		return
	end

	if not (skybox.Target and skybox.Target.Parent) then
		local existing = Lighting:FindFirstChildOfClass("Sky")
		if existing then
			skybox.Original = {}
			for _, face in ipairs(SKY_FACES) do
				skybox.Original[face] = existing[face]
			end
			skybox.Target, skybox.Created = existing, false
		else
			skybox.Target = Instance.new("Sky")
			skybox.Target.Parent = Lighting
			skybox.Created = true
		end
	end

	for index, face in ipairs(SKY_FACES) do
		skybox.Target[face] = assetId(faces[index])
	end
end

-- Textures: material overrides through MaterialService, applied to the map only.
-- Recolored is weak-keyed: a part the game destroys is not kept alive (and not restored) by this table.
local Textures = { Variants = {}, Overrides = {}, Recolored = setmetatable({}, { __mode = "k" }), Connection = nil, Run = 0 }
local TEXTURE_WHITE = Color3.fromRGB(254, 253, 255)

local function recolorPart(part)
	if (part:IsA("Part") or part:IsA("MeshPart")) and part.Transparency < 0.8 and TEXTURE_PACK[part.Material.Name] and not Textures.Recolored[part] then
		Textures.Recolored[part] = part.Color
		part.Color = TEXTURE_WHITE
	end
end

local function removeTextures()
	-- ends a pass over the map that is still running
	Textures.Run += 1

	if Textures.Connection then
		Textures.Connection:Disconnect()
		Textures.Connection = nil
	end

	for material, previous in pairs(Textures.Overrides) do
		pcall(MaterialService.SetBaseMaterialOverride, MaterialService, material, previous)
	end
	table.clear(Textures.Overrides)

	for _, variant in ipairs(Textures.Variants) do
		variant:Destroy()
	end
	table.clear(Textures.Variants)

	for part, color in pairs(Textures.Recolored) do
		pcall(function()
			part.Color = color
		end)
	end
	table.clear(Textures.Recolored)
end

local function setTextures(enabled)
	WorldOn.Textures = enabled
	removeTextures()
	if not enabled then
		return
	end

	local map = workspace:FindFirstChild("MAP")
	if not map then
		log("cube-vertexes", "Textures: this game has no MAP folder to retexture", 4)
		return
	end

	for name, id in pairs(TEXTURE_PACK) do
		local okMaterial, material = pcall(function()
			return Enum.Material[name]
		end)
		if okMaterial and material then
			local variant = Instance.new("MaterialVariant")
			variant.Name = "NeverLose" .. name
			variant.BaseMaterial = material
			variant.ColorMap = assetId(id)
			variant.StudsPerTile = 5
			variant.Parent = MaterialService
			table.insert(Textures.Variants, variant)

			local okPrevious, previous = pcall(MaterialService.GetBaseMaterialOverride, MaterialService, material)
			Textures.Overrides[material] = (okPrevious and previous) or ""
			pcall(MaterialService.SetBaseMaterialOverride, MaterialService, material, variant.Name)
		end
	end

	-- The map has tens of thousands of parts: they are recoloured a slice per frame instead of all in one frame. The parts that appear
	-- meanwhile are caught by the connection, and recolorPart skips a part it already did, so the two never overlap.
	Textures.Connection = map.DescendantAdded:Connect(recolorPart)

	local run = Textures.Run
	task.spawn(function()
		for index, descendant in ipairs(map:GetDescendants()) do
			recolorPart(descendant)

			if index % 400 == 0 then
				task.wait()

				-- switched off, switched on again (a newer pass has started) or unloaded while waiting
				if Textures.Run ~= run or not Session.Alive then
					return
				end
			end
		end
	end)
end

-- Background noise: one looping sound in the sound service.
local noiseSound

local function applyNoise()
	if not WorldOn.Noise then
		if noiseSound then
			noiseSound:Destroy()
			noiseSound = nil
		end
		return
	end

	if not (noiseSound and noiseSound.Parent) then
		noiseSound = Instance.new("Sound")
		noiseSound.Name = "NeverLoseNoise"
		noiseSound.Looped = true
		noiseSound.Parent = game:GetService("SoundService")
	end

	local id = assetId(findIn(NOISES, WorldSettings.Noise) or NOISES[1][2])
	if noiseSound.SoundId ~= id then
		noiseSound.SoundId = id
		noiseSound:Stop()
	end

	noiseSound.Volume = WorldSettings.Volume / 65
	if not noiseSound.IsPlaying then
		noiseSound:Play()
	end
end

local function resetWorld()
	for property in pairs(World.Originals) do
		releaseLighting(property)
	end
	table.clear(WorldOn)
	updateGrade()
	removeAtmosphere()
	removeSkybox()
	removeTextures()
	applyNoise()
end

table.insert(Session.Cleanups, resetWorld)

-- Slider and colour-picker callbacks store the value and re-apply if the feature is on.
local function onWorldSetting(key, apply)
	return function(value)
		if Session.Alive and value ~= nil then
			WorldSettings[key] = value
			apply()
		end
	end
end

