	Session.NativeSections.WorldLighting = LightingSection

	local SkySection = WorldTab:AddSection({
		Name = "SKY",
		Position = "right",
	})

	local ExtraSection = WorldTab:AddSection({
		Name = "EXTRA",
		Position = "right",
	})

	-- Lighting mode --
	local lightingMode = LightingSection:AddLabel("Lighting Mode")
	addBindableToggle(lightingMode, "Lighting Mode", {
		Default = false,
		Flag = "world_lighting_mode",
		Callback = function(enabled)
			if Session.Alive then
				setLightingMode(enabled)
			end
		end,
	})

