			local mode, replaced = safeLightingMode(value)

			if replaced and Session.Alive then
				log("sun", tostring(value) .. " lighting takes the clothes off every avatar: using " .. mode .. " instead", 6)

				-- the dropdown shows what is really used (this runs the callback again with the safe mode)
				task.defer(function()
					local item = NeverLose.Flags and NeverLose.Flags["world_lighting_mode_value"]
					if Session.Alive and item then
						pcall(item.SetValue, item, mode)
					end
				end)
