-- Feedback for your own hits and shots, bullet tracer styles, and screen
-- effects. All of it is drawn only on your screen.
do
local TweenService = game:GetService("TweenService")
local TextChatService = game:GetService("TextChatService")

local VisualSettings = {
	ChamsColor = Color3.fromRGB(142, 242, 255),
	ChamsMaterial = "Neon",
	ChamsLifetime = 0.8,
	ChamsOnlyLast = false,
	HitSound = "ping",
	HitVolume = 1,
	MarkerColor = Color3.fromRGB(133, 220, 255),
	MarkerLethalColor = Color3.fromRGB(255, 0, 0),
	MarkerLifetime = 0.7,
	Marker3DColor = Color3.fromRGB(133, 220, 255),
	Marker3DLethalColor = Color3.fromRGB(255, 0, 0),
	Marker3DLifetime = 0.7,
	DamageColor = Color3.fromRGB(255, 255, 255),
	DamageLethalColor = Color3.fromRGB(255, 55, 55),
	DamageLifetime = 0.7,
	OverlayColor = Color3.fromRGB(133, 220, 255),
	OverlayLethalColor = Color3.fromRGB(255, 55, 55),
	OverlayLifetime = 0.7,
	LocalTracerStyle = "laser",
	LocalTracerColor = Color3.fromRGB(133, 220, 255),
	LocalTracerGradient = Color3.fromRGB(241, 133, 255),
	LocalTracerLifetime = 0.8,
	LocalTracerServerOrigin = true,
	LocalTracerOneLine = false,
	PlayerTracerStyle = "laser",
	PlayerTracerColor = Color3.fromRGB(133, 220, 255),
	PlayerTracerGradient = Color3.fromRGB(241, 133, 255),
	PlayerTracerLifetime = 0.8,
	ImpactShape = "Sphere",
	ImpactColor = Color3.fromRGB(133, 220, 255),
	ImpactLifetime = 0.8,
	AspectRatio = 0.8,
	BlurIntensity = 25,
}

-- Built-in Roblox sounds, plus any .ogg/.mp3/.wav files found in
-- NeverLoseConfigs/sounds (or femmyhac.cc's own "neverlose recode/assets" folder).
local HIT_SOUNDS = {
	{ "ping", "rbxasset://sounds/electronicpingshort.wav" },
	{ "click", "rbxasset://sounds/clickfast.wav" },
	{ "button", "rbxasset://sounds/button.wav" },
}

local TRACER_STYLES = {
	laser = { Texture = 12781800668, Speed = 1.5, Length = 2, Width = 0.25, Brightness = 2.5, LightInfluence = 0, Wrap = false },
	light = { Texture = 2382169232, Speed = 2, Length = 15, Width = 0.25, Brightness = 1, LightInfluence = 1, Wrap = true },
	flow = { Texture = 12788927812, Speed = 2.5, Length = 1, Width = 0.2, Brightness = 5, LightInfluence = 0, Wrap = false },
}

local SOUND_EXTENSIONS = { ogg = true, mp3 = true, wav = true }

local function loadCustomSounds()
	if not (type(listfiles) == "function" and type(getcustomasset) == "function" and type(isfolder) == "function") then
		return
	end

	pcall(function()
		if type(makefolder) == "function" and not isfolder(CONFIG_FOLDER .. "/sounds") then
			if not isfolder(CONFIG_FOLDER) then
				makefolder(CONFIG_FOLDER)
			end
			makefolder(CONFIG_FOLDER .. "/sounds")
		end
	end)

	for _, folder in ipairs({ CONFIG_FOLDER .. "/sounds", "neverlose recode/assets" }) do
		local okList, files = pcall(function()
			return isfolder(folder) and listfiles(folder) or {}
		end)
		if okList then
			for _, path in ipairs(files) do
				local name, extension = tostring(path):match("([^/\\]+)%.(%w+)$")
				-- the original menu calls its own sound by the script's name
				if name and name:lower() == "neverlose" then
					name = "Visions hook"
				end
				if name and SOUND_EXTENSIONS[extension:lower()] and not findIn(HIT_SOUNDS, name:lower()) then
					local okAsset, asset = pcall(getcustomasset, path)
					if okAsset and asset then
						table.insert(HIT_SOUNDS, { name:lower(), asset })
					end
				end
			end
		end
	end
end

loadCustomSounds()

-- Short-lived effects (chams, markers, tracers...) so Unload can clear them.
local ActiveEffects = {}

local function trackEffect(instance)
	ActiveEffects[instance] = true
	return instance
end

local function dropEffect(instance)
	ActiveEffects[instance] = nil
	instance:Destroy()
end

-- Fade the given { object, goal } pairs over `fade` seconds after `lifetime`, then destroy `root`.
local function expireEffect(root, lifetime, fade, targets)
	task.delay(lifetime, function()
		if not ActiveEffects[root] then
			return
		end
		for _, target in ipairs(targets) do
			if target[1].Parent then
				TweenService:Create(target[1], TweenInfo.new(fade), target[2]):Play()
			end
		end
		task.wait(fade)
		if ActiveEffects[root] then
			dropEffect(root)
		end
	end)
end

local function worldAttachment(position)
	local attachment = Instance.new("Attachment")
	attachment.WorldPosition = position
	attachment.Parent = workspace.Terrain
	return trackEffect(attachment)
end

-- Not the camera: the game removes anything parented to it.
local function effectsParent()
	return workspace.Terrain or workspace
end

-- Four short bars around a point: the hit-marker cross. Returns the bars.
local function buildCross(parent, color, length, gap, thickness, zIndex)
	local bars = {}
	for _, angle in ipairs({ 45, 135, 225, 315 }) do
		local radians = math.rad(angle)
		local offset = gap + length / 2
		local bar = Instance.new("Frame")
		bar.AnchorPoint = Vector2.new(0.5, 0.5)
		bar.BorderSizePixel = 0
		bar.BackgroundColor3 = color
		bar.Size = UDim2.fromOffset(length, thickness)
		bar.Position = UDim2.new(0.5, math.cos(radians) * offset, 0.5, math.sin(radians) * offset)
		bar.Rotation = angle
		bar.ZIndex = zIndex
		bar.Parent = parent
		table.insert(bars, bar)
	end
	return bars
end

---------- Hit effects ------------
local lastCham

local function showHitChams(hit)
	local model = cloneCharacter(hit.Character)
	if not model then
		return
	end

	if VisualSettings.ChamsOnlyLast and lastCham and ActiveEffects[lastCham] then
		dropEffect(lastCham)
	end
	lastCham = model

	local okMaterial, material = pcall(function()
		return Enum.Material[VisualSettings.ChamsMaterial]
	end)

	local fades = {}
	for _, item in ipairs(model:GetDescendants()) do
		if item:IsA("BasePart") then
			item.Anchored = true
			item.CanCollide = false
			item.CanQuery = false
			item.CanTouch = false
			item.CastShadow = false
			item.Color = VisualSettings.ChamsColor
			if okMaterial and material then
				item.Material = material
			end
			if item:IsA("MeshPart") then
				item.TextureID = ""
			end
			if item.Name == "HumanoidRootPart" or item.Transparency >= 1 then
				item.Transparency = 1
			else
				item.Transparency = 0.3
				table.insert(fades, { item, { Transparency = 1 } })
			end
		elseif item:IsA("SpecialMesh") then
			item.TextureId = ""
		elseif item:IsA("Decal") or item:IsA("Texture") or item:IsA("Clothing") or item:IsA("ShirtGraphic") or item:IsA("SurfaceAppearance") or item:IsA("Humanoid") then
			item:Destroy()
		end
	end

	model.Parent = effectsParent()
	trackEffect(model)
	expireEffect(model, VisualSettings.ChamsLifetime, 0.25, fades)
end

local function playHitSound()
	local id = findIn(HIT_SOUNDS, VisualSettings.HitSound) or HIT_SOUNDS[1][2]
	local sound = Instance.new("Sound")
	sound.SoundId = id
	sound.Volume = VisualSettings.HitVolume
	sound.Parent = game:GetService("SoundService")
	sound:Play()
	trackEffect(sound)
	task.delay(5, function()
		if ActiveEffects[sound] then
			dropEffect(sound)
		end
	end)
end

local function showHitMarker(hit)
	local mouse = UserInputService:GetMouseLocation()
	local holder = Instance.new("Frame")
	holder.AnchorPoint = Vector2.new(0.5, 0.5)
	holder.BackgroundTransparency = 1
	holder.Position = UDim2.fromOffset(mouse.X, mouse.Y)
	holder.Size = UDim2.fromOffset(40, 40)
	holder.ZIndex = 35
	holder.Parent = NeverLose.ScreenGui

	local color = hit.Lethal and VisualSettings.MarkerLethalColor or VisualSettings.MarkerColor
	local fades = {}
	for _, bar in ipairs(buildCross(holder, color, 7, 4, 2, 36)) do
		table.insert(fades, { bar, { BackgroundTransparency = 1 } })
	end

	trackEffect(holder)
	expireEffect(holder, VisualSettings.MarkerLifetime, 0.2, fades)
end

local function showHitMarker3D(hit)
	local attachment = worldAttachment(hit.Position)
	local billboard = Instance.new("BillboardGui")
	billboard.Size = UDim2.fromOffset(40, 40)
	billboard.AlwaysOnTop = false
	billboard.LightInfluence = 0
	billboard.Parent = attachment

	local color = hit.Lethal and VisualSettings.Marker3DLethalColor or VisualSettings.Marker3DColor
	local fades = {}
	for _, bar in ipairs(buildCross(billboard, color, 7, 4, 2, 1)) do
		table.insert(fades, { bar, { BackgroundTransparency = 1 } })
	end

	expireEffect(attachment, VisualSettings.Marker3DLifetime, 0.2, fades)
end

local function showDamageNumber(hit)
	local attachment = worldAttachment(hit.Position + Vector3.new(0, 1.5, 0))
	local billboard = Instance.new("BillboardGui")
	billboard.Size = UDim2.fromOffset(80, 30)
	billboard.AlwaysOnTop = false
	billboard.LightInfluence = 0
	billboard.Parent = attachment

	local label = Instance.new("TextLabel")
	label.BackgroundTransparency = 1
	label.Size = UDim2.fromScale(1, 1)
	label.Font = Enum.Font.GothamBold
	label.Text = "-" .. tostring(math.floor(hit.Damage + 0.5))
	label.TextColor3 = hit.Lethal and VisualSettings.DamageLethalColor or VisualSettings.DamageColor
	label.TextSize = 18
	label.TextStrokeColor3 = Color3.fromRGB(15, 15, 15)
	label.TextStrokeTransparency = 0.3
	label.Parent = billboard

	local lifetime = VisualSettings.DamageLifetime
	TweenService:Create(billboard, TweenInfo.new(lifetime + 0.25), { StudsOffset = Vector3.new(0, 2, 0) }):Play()
	expireEffect(attachment, lifetime, 0.25, {
		{ label, { TextTransparency = 1, TextStrokeTransparency = 1 } },
	})
end

local function showHitOverlay(hit)
	local overlay = Instance.new("Frame")
	overlay.BorderSizePixel = 0
	overlay.Size = UDim2.fromScale(1, 1)
	overlay.BackgroundColor3 = hit.Lethal and VisualSettings.OverlayLethalColor or VisualSettings.OverlayColor
	overlay.BackgroundTransparency = 0.8
	overlay.ZIndex = 1
	overlay.Parent = NeverLose.ScreenGui

	trackEffect(overlay)
	TweenService:Create(overlay, TweenInfo.new(VisualSettings.OverlayLifetime), { BackgroundTransparency = 1 }):Play()
	expireEffect(overlay, VisualSettings.OverlayLifetime, 0, {})
end

local function onHit(hit)
	if Visual.HitChams then
		showHitChams(hit)
	end
	if Visual.HitSound then
		playHitSound()
	end
	if Visual.HitMarker then
		showHitMarker(hit)
	end
	if Visual.HitMarker3D then
		showHitMarker3D(hit)
	end
	if Visual.DamageNumbers then
		showDamageNumber(hit)
	end
	if Visual.HitOverlay then
		showHitOverlay(hit)
	end
	if Visual.HitLogs then
		log("crosshairs", ("Hit %s in the %s for %d%s"):format(hit.Player.DisplayName, hit.PartName, math.floor(hit.Damage + 0.5), hit.Lethal and " (knocked)" or ""), 4)
	end
end

local function anyHitVisual()
	return Visual.HitChams or Visual.HitSound or Visual.HitMarker or Visual.HitMarker3D or Visual.DamageNumbers or Visual.HitOverlay or Visual.HitLogs
end

-- The engine reports the hits it confirmed and the health watch below the ones it noticed: a hit both of them see is shown once.
local lastHitShown = setmetatable({}, { __mode = "k" })

local function showHit(hit)
	local now = os.clock()

	if now - (lastHitShown[hit.Player] or -1) < 0.35 then
		return
	end

	lastHitShown[hit.Player] = now
	onHit(hit)
end

-- A hit the engine confirmed: its signal gives the player, the part that was hit and the damage as text (a negative number).
function Session.onEngineHit(player, part, damage)
	if not (Session.Alive and anyHitVisual()) or typeof(player) ~= "Instance" then
		return
	end

	local character = player.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local effects = character:FindFirstChild("BodyEffects")
	local knocked = effects and effects:FindFirstChild("K.O")
	local hitPart = typeof(part) == "Instance" and part:IsA("BasePart") and part or character:FindFirstChild("HumanoidRootPart")
	if not hitPart then
		return
	end

	showHit({
		Player = player,
		Character = character,
		PartName = hitPart.Name,
		Position = hitPart.Position,
		Damage = math.abs(tonumber(damage) or 0),
		Lethal = (humanoid ~= nil and humanoid.Health <= 0) or (knocked ~= nil and knocked.Value == true),
	})
end

---------- Hit detection ------------
-- A hit is a health drop on another player shortly after one of your bullets
-- landed close to them. Uses only what the game already shows: the bullet beams
-- it draws and each character's health.
local RecentShots = {}
local SHOT_WINDOW = 0.35
local HIT_RADIUS = 6

local function recordShot(position)
	local now = os.clock()
	for index = #RecentShots, 1, -1 do
		if now - RecentShots[index].Time > 1 then
			table.remove(RecentShots, index)
		end
	end
	table.insert(RecentShots, { Time = now, Position = position })
end

local function checkHit(player, character, damage, health)
	local window = SHOT_WINDOW + LocalPlayer:GetNetworkPing()
	local now = os.clock()

	for index = #RecentShots, 1, -1 do
		local shot = RecentShots[index]
		if now - shot.Time <= window then
			local nearest, nearestDistance = nil, HIT_RADIUS
			for _, part in ipairs(character:GetChildren()) do
				if part:IsA("BasePart") then
					local distance = (part.Position - shot.Position).Magnitude
					if distance <= nearestDistance then
						nearest, nearestDistance = part, distance
					end
				end
			end

			if nearest then
				table.remove(RecentShots, index)

				local effects = character:FindFirstChild("BodyEffects")
				local knocked = effects and effects:FindFirstChild("K.O")
				showHit({
					Player = player,
					Character = character,
					PartName = nearest.Name,
					Position = shot.Position,
					Damage = damage,
					Lethal = health <= 0 or (knocked ~= nil and knocked.Value == true),
				})
				return
			end
		end
	end
end

local function watchCharacter(player, character)
	local humanoid = character:WaitForChild("Humanoid", 10)
	if not (humanoid and Session.Alive) then
		return
	end

	local lastHealth = humanoid.Health
	track(humanoid.HealthChanged:Connect(function(health)
		local damage = lastHealth - health
		lastHealth = health
		if Session.Alive and damage > 0 and anyHitVisual() then
			checkHit(player, character, damage, health)
		end
	end))
end

function watchPlayer(player)
	if player == LocalPlayer then
		return
	end
	if player.Character then
		task.spawn(watchCharacter, player, player.Character)
	end
	track(player.CharacterAdded:Connect(function(character)
		watchCharacter(player, character)
	end))
end

---------- Bullet tracers and impacts ------------
local function drawTracer(startPosition, endPosition, isLocal)
	local style = TRACER_STYLES[isLocal and VisualSettings.LocalTracerStyle or VisualSettings.PlayerTracerStyle] or TRACER_STYLES.laser
	local color = isLocal and VisualSettings.LocalTracerColor or VisualSettings.PlayerTracerColor
	local gradient = isLocal and VisualSettings.LocalTracerGradient or VisualSettings.PlayerTracerGradient
	local lifetime = isLocal and VisualSettings.LocalTracerLifetime or VisualSettings.PlayerTracerLifetime

	local startAttachment = worldAttachment(startPosition)
	local endAttachment = worldAttachment(endPosition)

	local beam = Instance.new("Beam")
	beam.FaceCamera = true
	beam.Texture = assetId(style.Texture)
	beam.TextureSpeed = style.Speed
	beam.TextureLength = style.Length
	beam.TextureMode = style.Wrap and Enum.TextureMode.Wrap or Enum.TextureMode.Stretch
	beam.Width0 = style.Width
	beam.Width1 = style.Width
	beam.Brightness = style.Brightness
	beam.LightEmission = 3
	beam.LightInfluence = style.LightInfluence
	beam.Color = ColorSequence.new(color, gradient)
	beam.Attachment0 = startAttachment
	beam.Attachment1 = endAttachment
	beam.Parent = startAttachment

	-- Beam transparency is a sequence, so it fades by hand instead of a tween.
	task.delay(lifetime, function()
		local started = os.clock()
		while ActiveEffects[startAttachment] and os.clock() - started < 0.2 do
			beam.Transparency = NumberSequence.new((os.clock() - started) / 0.2)
			RunService.Heartbeat:Wait()
		end
		if ActiveEffects[startAttachment] then
			dropEffect(startAttachment)
		end
		if ActiveEffects[endAttachment] then
			dropEffect(endAttachment)
		end
	end)
end

local function showImpact(position)
	local part = Instance.new("Part")
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Material = Enum.Material.Neon
	part.Color = VisualSettings.ImpactColor
	part.Shape = VisualSettings.ImpactShape == "Cube" and Enum.PartType.Block or Enum.PartType.Ball
	part.Size = Vector3.new(0.4, 0.4, 0.4)
	part.Transparency = 0.2
	part.Position = position
	part.Parent = effectsParent()

	trackEffect(part)
	expireEffect(part, VisualSettings.ImpactLifetime, 0.25, { { part, { Transparency = 1 } } })
end

-- Da Hood draws every shot as a "BULLET_RAYS" object with a beam to where it landed.
local function onBulletRay(object)
	if object.Name ~= "BULLET_RAYS" then
		return
	end
	task.wait()

	-- A skin with a tracer of its own (SkinAssets.GunBeam) puts its beam in the shot as well, and it may not be the first one or have its end set
	-- yet: the first beam (anywhere in the shot) with both ends is used, waiting up to twenty frames for one.
	local beam = nil

	for _ = 1, 20 do
		for _, item in ipairs(object:GetDescendants()) do
			if item:IsA("Beam") and item.Attachment0 and item.Attachment1 then
				beam = item
				break
			end
		end

		if beam or not object.Parent then
			break
		end

		task.wait()
	end

	if not (Session.Alive and beam and beam.Attachment1) then
		return
	end

	local endPosition = beam.Attachment1.WorldPosition
	local startPosition = (object:IsA("BasePart") and object.Position) or (beam.Attachment0 and beam.Attachment0.WorldPosition) or endPosition
	local isLocal = object:GetAttribute("OwnerCharacter") == LocalPlayer.Name

	if isLocal then
		local now = os.clock()

		-- One Line For Shotguns: a shotgun's pellets come in the same moment from the same muzzle; only the first is drawn
		local last = sharedEnv.neverlose_last_ray
		sharedEnv.neverlose_last_ray = { now, startPosition }

		if VisualSettings.LocalTracerOneLine and Visual.LocalTracers and last and now - last[1] < 0.05 and (last[2] - startPosition).Magnitude < 3 then
			beam.Enabled = false
			return
		end

		-- The game draws the shot where the gun was pointed; a shot the ragebot or the silent aim sent somewhere else ends where it was sent
		-- (its claim, kept by the shot hook) so the tracer goes to the target.
		local claim = sharedEnv.neverlose_last_claim

		-- (a shotgun's pellets, the Double-Barrel's or the Tactical's, keep the ends the game gave them: the tracers show the spread)
		if claim and not claim[3] and now - claim[2] < 0.5 and typeof(claim[1]) == "Vector3" then
			endPosition = claim[1]
		end
	end

	-- From Server Position: a shot the gun made starts at the drawn body; while desynced the tracer starts where the server has the character
	-- instead (a shot the ragebot forged already starts there, far from the drawn body, and is left alone).
	if isLocal and VisualSettings.LocalTracerServerOrigin then
		local api = getgenv().neverlose
		local okServer, server = pcall(function()
			return api and api.get_server_cframe and api.get_server_cframe()
		end)
		local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

		if okServer and server and root and server.Position.Magnitude < 9e5 and (server.Position - root.Position).Magnitude > 1 and (startPosition - root.Position).Magnitude < 12 then
			startPosition = server.Position + (startPosition - root.Position)
		end
	end

	-- the shots are only looked at by the hit visuals' health watch: nothing to record while none of them is on
	if isLocal and anyHitVisual() then
		recordShot(endPosition)
	end

	if (isLocal and Visual.LocalTracers) or (not isLocal and Visual.PlayerTracers) then
		for _, item in ipairs(object:GetDescendants()) do
			if item:IsA("Beam") then
				item.Enabled = false
			end
		end
		drawTracer(startPosition, endPosition, isLocal)
	end

	if isLocal and Visual.Impacts then
		showImpact(endPosition)
	end
end

function watchBulletRays()
	local ignored = workspace:WaitForChild("Ignored", 10)
	local siren = ignored and ignored:WaitForChild("Siren", 10)
	local radius = siren and siren:WaitForChild("Radius", 10)
	if radius and Session.Alive then
		track(radius.ChildAdded:Connect(function(object)
			task.spawn(onBulletRay, object)
		end))
	end
end

---------- HUD ------------
-- Hide the game's own crosshair ("Aim" in MainScreenGui) while this is on.
local aimWatcher

function applyHideCrosshair()
	local wasHiding = aimWatcher ~= nil
	if aimWatcher then
		aimWatcher:Disconnect()
		aimWatcher = nil
	end

	local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
	local mainGui = playerGui and playerGui:FindFirstChild("MainScreenGui")
	local aim = mainGui and mainGui:FindFirstChild("Aim")
	if not (aim and aim:IsA("GuiObject")) then
		return
	end

	if Visual.HideCrosshair then
		aim.Visible = false
		aimWatcher = aim:GetPropertyChangedSignal("Visible"):Connect(function()
			if Session.Alive and Visual.HideCrosshair and aim.Visible then
				aim.Visible = false
			end
		end)
	elseif wasHiding then
		-- The game shows its crosshair while a tool is held.
		local character = LocalPlayer.Character
		aim.Visible = character ~= nil and character:FindFirstChildOfClass("Tool") ~= nil
	end
end

local ASPECT_BIND = "NeverLoseAspectRatio"

local function applyAspectRatio()
	pcall(RunService.UnbindFromRenderStep, RunService, ASPECT_BIND)
	if not Visual.AspectRatio then
		return
	end

	RunService:BindToRenderStep(ASPECT_BIND, Enum.RenderPriority.Camera.Value + 1, function()
		local camera = workspace.CurrentCamera
		if camera then
			camera.CFrame = camera.CFrame * CFrame.new(0, 0, 0, 1, 0, 0, 0, VisualSettings.AspectRatio, 0, 0, 0, 1)
		end
	end)
end

local chatWasEnabled

local function applyShowChat()
	local config = TextChatService:FindFirstChildOfClass("ChatWindowConfiguration")
	if not config then
		return
	end

	if Visual.ShowChat then
		if chatWasEnabled == nil then
			chatWasEnabled = config.Enabled
		end
		config.Enabled = true
	elseif chatWasEnabled ~= nil then
		config.Enabled = chatWasEnabled
		chatWasEnabled = nil
	end
end

local function applyRendering()
	pcall(RunService.Set3dRenderingEnabled, RunService, not Visual.NoRender)
end

local motionBlur = { Effect = nil, LastLook = nil, Size = 0 }

local function updateMotionBlur(dt)
	if not Visual.MotionBlur then
		if motionBlur.Effect then
			motionBlur.Effect:Destroy()
			motionBlur.Effect = nil
		end
		motionBlur.LastLook = nil
		motionBlur.Size = 0
		return
	end

	local camera = workspace.CurrentCamera
	if not camera then
		return
	end

	if not (motionBlur.Effect and motionBlur.Effect.Parent) then
		motionBlur.Effect = Instance.new("BlurEffect")
		motionBlur.Effect.Name = "NeverLoseMotionBlur"
		motionBlur.Effect.Size = 0
		motionBlur.Effect.Parent = Lighting
	end

	local look = camera.CFrame.LookVector
	if motionBlur.LastLook and dt > 0 then
		local turnSpeed = (look - motionBlur.LastLook).Magnitude / dt
		local target = math.clamp(turnSpeed * VisualSettings.BlurIntensity * 0.06, 0, 24)
		motionBlur.Size += (target - motionBlur.Size) * math.min(1, dt * 12)
		motionBlur.Effect.Size = motionBlur.Size
	end
	motionBlur.LastLook = look
end

function onRenderStep(dt)
	if not Session.Alive then
		return
	end

	updateMotionBlur(dt)
end

local function resetVisuals()
	table.clear(Visual)
	for instance in pairs(ActiveEffects) do
		pcall(instance.Destroy, instance)
	end
	table.clear(ActiveEffects)
	applyHideCrosshair()
	applyAspectRatio()
	applyShowChat()
	applyRendering()
	updateMotionBlur(0)
end

table.insert(Session.Cleanups, resetVisuals)

---------- Building the Game and HUD sections ------------
local function visualToggle(section, name, flag, key, apply)
	local row = section:AddLabel(name)
	addBindableToggle(row, name, {
		Default = false,
		Flag = flag,
		Callback = function(enabled)
			if Session.Alive then
				Visual[key] = enabled
				if apply then
					apply()
				end
			end
		end,
	})
	return row
end

local function onVisualSetting(key, apply)
	return function(value)
		if Session.Alive and value ~= nil then
			VisualSettings[key] = value
			if apply then
				apply()
			end
		end
	end
end

local function settingSlider(options, name, flag, key, min, max, rounding, suffix, apply)
	options:AddLabel(name):AddSlider({
		Min = min,
		Max = max,
		Rounding = rounding or 0,
		Type = suffix or "",
		Default = VisualSettings[key],
		Flag = flag,
		Callback = onVisualSetting(key, apply),
	})
end

local function settingColor(options, name, flag, key, apply)
	options:AddLabel(name):AddColorPicker({
		Default = VisualSettings[key],
		Flag = flag,
		Callback = onVisualSetting(key, apply),
	})
end

local function settingDropdown(options, name, flag, key, values, apply)
	options:AddLabel(name):AddDropdown({
		Default = VisualSettings[key],
		Values = values,
		Flag = flag,
		Callback = onVisualSetting(key, apply),
	})
end

-- Hit and bullet visuals, as extra sections in the World tab.
function buildGameSections(WorldTab)
	local Hits = WorldTab:AddSection({
		Name = "HITS",
		Position = "left",
	})

	local Bullets = WorldTab:AddSection({
		Name = "BULLETS",
		Position = "right",
	})

	-- Hit chams --
	local chams = visualToggle(Hits, "Hit Chams", "visual_hit_chams", "HitChams")
	local chamsOptions = chams:AddOption()
	settingColor(chamsOptions, "Color", "visual_hit_chams_color", "ChamsColor")
	settingDropdown(chamsOptions, "Material", "visual_hit_chams_material", "ChamsMaterial", { "Neon", "ForceField", "Glass", "SmoothPlastic" })
	settingSlider(chamsOptions, "Lifetime", "visual_hit_chams_lifetime", "ChamsLifetime", 0.1, 1.5, 1, "s")
	chamsOptions:AddLabel("Only Last Hit"):AddToggle({
		Default = VisualSettings.ChamsOnlyLast,
		Flag = "visual_hit_chams_only_last",
		Callback = onVisualSetting("ChamsOnlyLast"),
	})

	-- Hit sound --
	local sound = visualToggle(Hits, "Hit Sound", "visual_hit_sound", "HitSound")
	local soundOptions = sound:AddOption()
	settingDropdown(soundOptions, "Sound", "visual_hit_sound_value", "HitSound", namesOf(HIT_SOUNDS))
	settingSlider(soundOptions, "Volume", "visual_hit_sound_volume", "HitVolume", 0.1, 5, 1)

	-- 2D hit marker --
	local marker = visualToggle(Hits, "Hit Marker", "visual_hit_marker", "HitMarker")
	local markerOptions = marker:AddOption()
	settingColor(markerOptions, "Color", "visual_hit_marker_color", "MarkerColor")
	settingColor(markerOptions, "Lethal Color", "visual_hit_marker_lethal", "MarkerLethalColor")
	settingSlider(markerOptions, "Lifetime", "visual_hit_marker_lifetime", "MarkerLifetime", 0.1, 2, 1, "s")

	-- 3D hit marker --
	local marker3D = visualToggle(Hits, "3D Hit Marker", "visual_hit_marker_3d", "HitMarker3D")
	local marker3DOptions = marker3D:AddOption()
	settingColor(marker3DOptions, "Color", "visual_hit_marker_3d_color", "Marker3DColor")
	settingColor(marker3DOptions, "Lethal Color", "visual_hit_marker_3d_lethal", "Marker3DLethalColor")
	settingSlider(marker3DOptions, "Lifetime", "visual_hit_marker_3d_lifetime", "Marker3DLifetime", 0.1, 2, 1, "s")

	-- Damage numbers --
	local damage = visualToggle(Hits, "Damage Numbers", "visual_damage_numbers", "DamageNumbers")
	local damageOptions = damage:AddOption()
	settingColor(damageOptions, "Color", "visual_damage_color", "DamageColor")
	settingColor(damageOptions, "Lethal Color", "visual_damage_lethal", "DamageLethalColor")
	settingSlider(damageOptions, "Lifetime", "visual_damage_lifetime", "DamageLifetime", 0.7, 2, 1, "s")

	-- Hit overlay --
	local overlay = visualToggle(Hits, "Hit Overlay", "visual_hit_overlay", "HitOverlay")
	local overlayOptions = overlay:AddOption()
	settingColor(overlayOptions, "Color", "visual_hit_overlay_color", "OverlayColor")
	settingColor(overlayOptions, "Lethal Color", "visual_hit_overlay_lethal", "OverlayLethalColor")
	settingSlider(overlayOptions, "Lifetime", "visual_hit_overlay_lifetime", "OverlayLifetime", 0.1, 0.8, 1, "s")

	-- Hit logs --
	visualToggle(Hits, "Hit Logs", "visual_hit_logs", "HitLogs")

	-- Local bullet tracers --
	local tracerStyles = { "laser", "light", "flow" }
	local localTracers = visualToggle(Bullets, "Bullet Tracers", "visual_local_tracers", "LocalTracers")
	local localTracerOptions = localTracers:AddOption()
	settingDropdown(localTracerOptions, "Style", "visual_local_tracer_style", "LocalTracerStyle", tracerStyles)
	settingColor(localTracerOptions, "Color", "visual_local_tracer_color", "LocalTracerColor")
	settingColor(localTracerOptions, "Gradient Color", "visual_local_tracer_gradient", "LocalTracerGradient")
	settingSlider(localTracerOptions, "Lifetime", "visual_local_tracer_lifetime", "LocalTracerLifetime", 0.1, 1.5, 1, "s")
	localTracerOptions:AddLabel("From Server Position"):AddToggle({
		Default = VisualSettings.LocalTracerServerOrigin,
		Flag = "visual_local_tracer_server",
		Callback = onVisualSetting("LocalTracerServerOrigin"),
	})
	-- the Double-Barrel's (or any shotgun's) five pellets drawn as one line
	localTracerOptions:AddLabel("One Line For Shotguns"):AddToggle({
		Default = VisualSettings.LocalTracerOneLine,
		Flag = "visual_local_tracer_one_line",
		Callback = onVisualSetting("LocalTracerOneLine"),
	})

	-- Other players' bullet tracers --
	local playerTracers = visualToggle(Bullets, "Player Tracers", "visual_player_tracers", "PlayerTracers")
	local playerTracerOptions = playerTracers:AddOption()
	settingDropdown(playerTracerOptions, "Style", "visual_player_tracer_style", "PlayerTracerStyle", tracerStyles)
	settingColor(playerTracerOptions, "Color", "visual_player_tracer_color", "PlayerTracerColor")
	settingColor(playerTracerOptions, "Gradient Color", "visual_player_tracer_gradient", "PlayerTracerGradient")
	settingSlider(playerTracerOptions, "Lifetime", "visual_player_tracer_lifetime", "PlayerTracerLifetime", 0.1, 1.5, 1, "s")

	-- Bullet impacts --
	local impacts = visualToggle(Bullets, "Bullet Impacts", "visual_impacts", "Impacts")
	local impactOptions = impacts:AddOption()
	settingDropdown(impactOptions, "Shape", "visual_impact_shape", "ImpactShape", { "Sphere", "Cube" })
	settingColor(impactOptions, "Color", "visual_impact_color", "ImpactColor")
	settingSlider(impactOptions, "Lifetime", "visual_impact_lifetime", "ImpactLifetime", 0.1, 1.5, 1, "s")
end

-- HUD and screen visuals, as extra sections in the World tab.
function buildHudSections(WorldTab)
	local HudSection = WorldTab:AddSection({
		Name = "HUD",
		Position = "left",
	})
	Session.NativeSections.WorldHud = HudSection

	local ScreenSection = WorldTab:AddSection({
		Name = "SCREEN",
		Position = "right",
	})

	-- Hide the game's crosshair --
	visualToggle(HudSection, "Hide Game Crosshair", "visual_hide_crosshair", "HideCrosshair", applyHideCrosshair)

	-- Aspect ratio --
	local aspect = visualToggle(ScreenSection, "Aspect Ratio", "visual_aspect_ratio", "AspectRatio", applyAspectRatio)
	settingSlider(aspect:AddOption(), "Height", "visual_aspect_ratio_value", "AspectRatio", 0.1, 1.2, 2, "x")

	-- Show chat --
	visualToggle(ScreenSection, "Show Chat", "visual_show_chat", "ShowChat", applyShowChat)

	-- Motion blur --
	local blur = visualToggle(ScreenSection, "Motion Blur", "visual_motion_blur", "MotionBlur")
	settingSlider(blur:AddOption(), "Intensity", "visual_motion_blur_intensity", "BlurIntensity", 0, 100, 0, "%")

	-- Disable 3D rendering --
	local noRender = visualToggle(ScreenSection, "Disable Rendering", "visual_no_render", "NoRender", applyRendering)
	noRender:ToolTip("Stops drawing the 3D world to save performance. The menu still works.")
end
end

---------- Players visuals ------------
-- Looks for your own character and tools, plus hiding other players' nametags.
do
local PlayerVisual = {}

local PlayerSettings = {
	HighlightFill = Color3.fromRGB(133, 220, 255),
	HighlightOutline = Color3.fromRGB(255, 255, 255),
	Material = "ForceField",
	MaterialColor = Color3.fromRGB(133, 220, 255),
	HatColor = Color3.fromRGB(133, 220, 255),
	HatLightColor = Color3.fromRGB(133, 220, 225),
	HatScale = 1.7,
	HatBrightness = 5,
	AuraColor = Color3.fromRGB(133, 220, 255),
	ToolMaterial = "Neon",
	ToolColor = Color3.fromRGB(133, 220, 255),
	RainbowSpeed = 30,
	RainbowSaturation = 0.8,
	RainbowBrightness = 1,
	SwayHorizontal = 10,
	SwayHorizontalSpeed = 30,
	SwayVertical = 6,
	SwayVerticalSpeed = 20,
}

local MATERIALS = { "ForceField", "Neon", "Glass", "SmoothPlastic", "Metal", "Foil" }
local ARM_PARTS = { "LeftHand", "LeftLowerArm", "LeftUpperArm", "RightHand", "RightLowerArm", "RightUpperArm", "Left Arm", "Right Arm" }

local function materialNamed(name)
	local ok, material = pcall(function()
		return Enum.Material[name]
	end)
	return ok and material or Enum.Material.SmoothPlastic
end

-- Parts of your character itself, not of a tool you are holding.
local function characterParts(character)
	local parts = {}
	for _, item in ipairs(character:GetDescendants()) do
		if item:IsA("BasePart") and item.Name ~= "HumanoidRootPart" and not item:FindFirstAncestorOfClass("Tool") and item.Name ~= "NeverLoseHat" then
			table.insert(parts, item)
		end
	end
	return parts
end

-- Character highlight --
local highlight

local function applyHighlight()
	if highlight then
		highlight:Destroy()
		highlight = nil
	end

	local character = LocalPlayer.Character
	if not (PlayerVisual.Highlight and character) then
		return
	end

	highlight = Instance.new("Highlight")
	highlight.Name = "NeverLoseHighlight"
	highlight.FillColor = PlayerSettings.HighlightFill
	highlight.OutlineColor = PlayerSettings.HighlightOutline
	highlight.FillTransparency = 0.5
	highlight.DepthMode = Enum.HighlightDepthMode.Occluded
	highlight.Adornee = character
	highlight.Parent = character
end

-- Character material: remembers each part's look so it can be put back.
local materialOriginals = {}

local function restoreMaterial()
	for part, original in pairs(materialOriginals) do
		pcall(function()
			part.Material = original.Material
			part.Color = original.Color
		end)
	end
	table.clear(materialOriginals)
end

local function applyMaterial()
	restoreMaterial()

	local character = LocalPlayer.Character
	if not (PlayerVisual.Material and character) then
		return
	end

	local material = materialNamed(PlayerSettings.Material)
	for _, part in ipairs(characterParts(character)) do
		materialOriginals[part] = { Material = part.Material, Color = part.Color }
		part.Material = material
		part.Color = PlayerSettings.MaterialColor
	end
end

-- China hat: a glowing cone welded above your head.
local chinaHat

local function applyChinaHat()
	if chinaHat then
		chinaHat:Destroy()
		chinaHat = nil
	end

	local character = LocalPlayer.Character
	local head = character and character:FindFirstChild("Head")
	if not (PlayerVisual.ChinaHat and head) then
		return
	end

	local cone = Instance.new("Part")
	cone.Name = "NeverLoseHat"
	cone.Size = Vector3.new(1, 1, 1)
	cone.Material = Enum.Material.Neon
	cone.Color = PlayerSettings.HatColor
	cone.Transparency = 0.2
	cone.CanCollide = false
	cone.CanQuery = false
	cone.CanTouch = false
	cone.CastShadow = false
	cone.Massless = true

	local mesh = Instance.new("SpecialMesh")
	mesh.MeshType = Enum.MeshType.FileMesh
	mesh.MeshId = "rbxassetid://1033714"
	mesh.Scale = Vector3.new(PlayerSettings.HatScale, 1.1, PlayerSettings.HatScale)
	mesh.Parent = cone

	local weld = Instance.new("Weld")
	weld.Part0 = head
	weld.Part1 = cone
	weld.C0 = CFrame.new(0, 0.9, 0)
	weld.Parent = cone

	local light = Instance.new("PointLight")
	light.Color = PlayerSettings.HatLightColor
	light.Brightness = PlayerSettings.HatBrightness
	light.Range = 12
	light.Parent = cone

	cone.Parent = character
	chinaHat = cone
end

-- Particle aura: sparkles drifting around you.
local aura

local function applyAura()
	if aura then
		aura:Destroy()
		aura = nil
	end

	local character = LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not (PlayerVisual.Aura and root) then
		return
	end

	local attachment = Instance.new("Attachment")
	attachment.Name = "NeverLoseAura"

	local emitter = Instance.new("ParticleEmitter")
	emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
	emitter.Color = ColorSequence.new(PlayerSettings.AuraColor)
	emitter.LightEmission = 1
	emitter.Lifetime = NumberRange.new(1, 1.5)
	emitter.Rate = 20
	emitter.Speed = NumberRange.new(1, 2)
	emitter.SpreadAngle = Vector2.new(180, 180)
	emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.4), NumberSequenceKeypoint.new(1, 0) })
	emitter.Transparency = NumberSequence.new(0.2, 1)
	emitter.Parent = attachment

	attachment.Parent = root
	aura = attachment
end

local function applyCharacterVisuals()
	applyHighlight()
	applyMaterial()
	applyChinaHat()
	applyAura()
end

-- After a respawn the old parts are gone, so forget them before re-applying.
function refreshCharacterVisuals()
	table.clear(materialOriginals)
	applyCharacterVisuals()
end

-- Tools: material/colour, rainbow colour and sway on the tool you are holding.
local ToolStyle = { Tool = nil, Parts = {}, Grip = nil }

local function restoreTool()
	for part, original in pairs(ToolStyle.Parts) do
		pcall(function()
			part.Material = original.Material
			part.Color = original.Color
		end)
	end
	table.clear(ToolStyle.Parts)

	if ToolStyle.Tool and ToolStyle.Grip then
		pcall(function()
			ToolStyle.Tool.Grip = ToolStyle.Grip
		end)
	end
	ToolStyle.Tool, ToolStyle.Grip = nil, nil
end

local function styleTool(tool)
	ToolStyle.Tool = tool
	ToolStyle.Grip = tool.Grip

	if PlayerVisual.ToolMaterial or PlayerVisual.Rainbow then
		local material = materialNamed(PlayerSettings.ToolMaterial)
		for _, part in ipairs(tool:GetDescendants()) do
			if part:IsA("BasePart") then
				ToolStyle.Parts[part] = { Material = part.Material, Color = part.Color }
				part.Material = material
				part.Color = PlayerSettings.ToolColor
			end
		end
	end
end

local function refreshTool()
	restoreTool()
end

local function updateTool()
	local character = LocalPlayer.Character
	local tool = character and character:FindFirstChildOfClass("Tool")
	local wanted = PlayerVisual.ToolMaterial or PlayerVisual.Rainbow or PlayerVisual.Sway

	if tool ~= ToolStyle.Tool or not wanted then
		restoreTool()
		if tool and wanted then
			styleTool(tool)
		end
	end

	if not ToolStyle.Tool then
		return
	end

	local now = os.clock()

	if PlayerVisual.Rainbow then
		local hue = (now * PlayerSettings.RainbowSpeed / 100) % 1
		local color = Color3.fromHSV(hue, PlayerSettings.RainbowSaturation, PlayerSettings.RainbowBrightness)
		for part in pairs(ToolStyle.Parts) do
			part.Color = color
		end
	end

	if PlayerVisual.Sway and ToolStyle.Grip then
		local horizontal = math.rad(PlayerSettings.SwayHorizontal) * math.sin(now * PlayerSettings.SwayHorizontalSpeed * 0.1)
		local vertical = math.rad(PlayerSettings.SwayVertical) * math.sin(now * PlayerSettings.SwayVerticalSpeed * 0.1)
		ToolStyle.Tool.Grip = ToolStyle.Grip * CFrame.Angles(vertical, horizontal, 0)
	end
end

-- Show arms in first person: the camera hides them every frame, so this runs
-- right after the camera does and shows them again.
local function updateArms()
	if not PlayerVisual.Arms then
		return
	end

	local character = LocalPlayer.Character
	if not character then
		return
	end

	for _, name in ipairs(ARM_PARTS) do
		local part = character:FindFirstChild(name)
		if part and part:IsA("BasePart") then
			part.LocalTransparencyModifier = 0
		end
	end
end

local PLAYERS_BIND = "NeverLosePlayers"

-- a bind left behind by an earlier run would make the bind below throw and stop the rest of the menu from building
pcall(RunService.UnbindFromRenderStep, RunService, PLAYERS_BIND)

RunService:BindToRenderStep(PLAYERS_BIND, Enum.RenderPriority.Camera.Value + 2, function()
	if Session.Alive then
		updateArms()
		updateTool()
	end
end)

-- Hide other players' nametags (and health bars), remembering how they were.
local nametagOriginals = {}

local function hideNametag(humanoid)
	if not nametagOriginals[humanoid] then
		nametagOriginals[humanoid] = { Distance = humanoid.DisplayDistanceType, Health = humanoid.HealthDisplayType }
	end
	humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
	humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
end

local function applyNametags()
	if PlayerVisual.HideNametags then
		for _, player in ipairs(Players:GetPlayers()) do
			local humanoid = player ~= LocalPlayer and player.Character and player.Character:FindFirstChildOfClass("Humanoid")
			if humanoid then
				hideNametag(humanoid)
			end
		end
		return
	end

	for humanoid, original in pairs(nametagOriginals) do
		pcall(function()
			humanoid.DisplayDistanceType = original.Distance
			humanoid.HealthDisplayType = original.Health
		end)
	end
	table.clear(nametagOriginals)
end

function onOtherCharacter(player, character)
	if player == LocalPlayer then
		return
	end
	local humanoid = character:WaitForChild("Humanoid", 10)
	if humanoid and Session.Alive and PlayerVisual.HideNametags then
		hideNametag(humanoid)
	end
end

local function resetPlayers()
	pcall(RunService.UnbindFromRenderStep, RunService, PLAYERS_BIND)
	table.clear(PlayerVisual)
	applyCharacterVisuals()
	restoreTool()
	applyNametags()
end

table.insert(Session.Cleanups, resetPlayers)

---------- Building the Players tab ------------
local function playerToggle(section, name, flag, key, apply)
	local row = section:AddLabel(name)
	addBindableToggle(row, name, {
		Default = false,
		Flag = flag,
		Callback = function(enabled)
			if Session.Alive then
				PlayerVisual[key] = enabled
				if apply then
					apply()
				end
			end
		end,
	})
	return row
end

local function onPlayerSetting(key, apply)
	return function(value)
		if Session.Alive and value ~= nil then
			PlayerSettings[key] = value
			if apply then
				apply()
			end
		end
	end
end

local function playerSlider(options, name, flag, key, min, max, rounding, suffix, apply)
	options:AddLabel(name):AddSlider({
		Min = min,
		Max = max,
		Rounding = rounding or 0,
		Type = suffix or "",
		Default = PlayerSettings[key],
		Flag = flag,
		Callback = onPlayerSetting(key, apply),
	})
end

local function playerColor(options, name, flag, key, apply)
	options:AddLabel(name):AddColorPicker({
		Default = PlayerSettings[key],
		Flag = flag,
		Callback = onPlayerSetting(key, apply),
	})
end

local function playerDropdown(options, name, flag, key, values, apply)
	options:AddLabel(name):AddDropdown({
		Default = PlayerSettings[key],
		Values = values,
		Flag = flag,
		Callback = onPlayerSetting(key, apply),
	})
end

function buildPlayersTab()
	local PlayersTab = window:AddTab({
		Icon = "eye",
		Name = "Character",
	})

	-- Local character leads the right column. The engine's Player ESP section is added later and
	-- becomes the only left section, so it ends up at the top of the tab.
	local LocalSection = PlayersTab:AddSection({
		Name = "LOCAL CHARACTER",
		Position = "right",
	})
	Session.NativeSections.PlayersLocal = LocalSection

	local ToolsSection = PlayersTab:AddSection({
		Name = "TOOLS",
		Position = "right",
	})

	local OtherSection = PlayersTab:AddSection({
		Name = "OTHER",
		Position = "right",
	})

	-- Local character --
	playerToggle(LocalSection, "Show Arms in First Person", "player_show_arms", "Arms")

	local highlightRow = playerToggle(LocalSection, "Character Highlight", "player_highlight", "Highlight", applyHighlight)
	local highlightOptions = highlightRow:AddOption()
	playerColor(highlightOptions, "Fill Color", "player_highlight_fill", "HighlightFill", applyHighlight)
	playerColor(highlightOptions, "Outline Color", "player_highlight_outline", "HighlightOutline", applyHighlight)

	local materialRow = playerToggle(LocalSection, "Character Material", "player_material", "Material", applyMaterial)
	local materialOptions = materialRow:AddOption()
	playerDropdown(materialOptions, "Material", "player_material_value", "Material", MATERIALS, applyMaterial)
	playerColor(materialOptions, "Color", "player_material_color", "MaterialColor", applyMaterial)

	local hatRow = playerToggle(LocalSection, "China Hat", "player_china_hat", "ChinaHat", applyChinaHat)
	local hatOptions = hatRow:AddOption()
	playerColor(hatOptions, "Color", "player_china_hat_color", "HatColor", applyChinaHat)
	playerColor(hatOptions, "Light Color", "player_china_hat_light_color", "HatLightColor", applyChinaHat)
	playerSlider(hatOptions, "Scale", "player_china_hat_scale", "HatScale", 0.5, 4, 2, "", applyChinaHat)
	playerSlider(hatOptions, "Light Brightness", "player_china_hat_brightness", "HatBrightness", 0, 10, 1, "", applyChinaHat)

	local auraRow = playerToggle(LocalSection, "Particle Aura", "player_aura", "Aura", applyAura)
	playerColor(auraRow:AddOption(), "Color", "player_aura_color", "AuraColor", applyAura)

	-- Tools --
	local toolRow = playerToggle(ToolsSection, "Material Tools", "player_tool_material", "ToolMaterial", refreshTool)
	local toolOptions = toolRow:AddOption()
	playerDropdown(toolOptions, "Material", "player_tool_material_value", "ToolMaterial", MATERIALS, refreshTool)
	playerColor(toolOptions, "Color", "player_tool_color", "ToolColor", refreshTool)

	local rainbowRow = playerToggle(ToolsSection, "Rainbow Tools", "player_rainbow_tools", "Rainbow", refreshTool)
	local rainbowOptions = rainbowRow:AddOption()
	playerSlider(rainbowOptions, "Speed", "player_rainbow_speed", "RainbowSpeed", 1, 100, 0, "%")
	playerSlider(rainbowOptions, "Saturation", "player_rainbow_saturation", "RainbowSaturation", 0, 1, 2)
	playerSlider(rainbowOptions, "Brightness", "player_rainbow_brightness", "RainbowBrightness", 0, 1, 2)

	local swayRow = playerToggle(ToolsSection, "Animated Tools", "player_tool_sway", "Sway", refreshTool)
	local swayOptions = swayRow:AddOption()
	playerSlider(swayOptions, "Horizontal", "player_sway_horizontal", "SwayHorizontal", 0, 45, 0, "°")
	playerSlider(swayOptions, "Horizontal Speed", "player_sway_horizontal_speed", "SwayHorizontalSpeed", 1, 100, 0, "%")
	playerSlider(swayOptions, "Vertical", "player_sway_vertical", "SwayVertical", 0, 45, 0, "°")
	playerSlider(swayOptions, "Vertical Speed", "player_sway_vertical_speed", "SwayVerticalSpeed", 1, 100, 0, "%")

	-- Other --
	playerToggle(OtherSection, "Hide Player Nametags", "player_hide_nametags", "HideNametags", applyNametags)

	return PlayersTab
end
end

---------- Settings panels ------------
-- The gear menus behind the ragebot rows. Each control forwards its value to the femmyhac.cc
-- option of the same name through onChanged. The defaults are re-sent to the engine
-- once its listeners exist (Session.pushDefaults), so menu and engine start in sync.
function Session.buildSettingsPanels(rows)
	local defaults = {}
	Session.Defaults = defaults

	-- Re-sends every default so the engine's listeners pick up the menu's starting values.
	function Session.pushDefaults()
		if not Session.Alive then
			return
		end

		for key, default in pairs(defaults) do
			pcall(onChanged(key), default)
		end
	end

	_G.NL_PUSH_DEFAULTS = Session.pushDefaults

	-- The optional listener runs after the engine is told, so a control can show or hide others.
	local function forward(key, default, listener)
		defaults[key] = default
		local apply = onChanged(key)
		return function(value)
			if Session.Alive then
				apply(value)

				if listener then
					listener(value)
				end
			end
		end
	end

	-- True when a dropdown value ({ [name] = true } for multi, a string for single) includes name.
	local function isPicked(value, name)
		if type(value) == "table" then
			return value[name] == true or table.find(value, name) ~= nil
		end

		return value == name
	end

	-- Panel controls return the control and its row; hiding the row hides the control.
	local function panelToggle(options, name, key, default, listener)
		local label = options:AddLabel(name)
		Session.pinRow(label)
		local toggle = label:AddToggle({
			Default = default,
			Flag = key,
			Callback = forward(key, default, listener),
		})
		return toggle, label
	end

	-- nums swaps the text of a value, e.g. { [0] = "off" }. The library only reads it once the
	-- value changes, so the starting text is refreshed here.
	local function panelSlider(options, name, key, min, max, rounding, suffix, default, nums, listener)
		local label = options:AddLabel(name)
		Session.pinRow(label)
		local slider = label:AddSlider({
			Min = min,
			Max = max,
			Rounding = rounding,
			Type = suffix,
			Default = default,
			Nums = nums,
			Flag = key,
			Callback = forward(key, default, listener),
		})

		if nums and nums[default] ~= nil then
			pcall(slider.SetValue, slider, default)
		end

		return slider, label
	end

	local function panelColor(options, name, key, default)
		options:AddLabel(name):AddColorPicker({
			Default = default,
			Flag = key,
			Callback = forward(key, default),
		})
	end

	-- A table default is a multi pick, a string default is a single pick.
	local function panelList(options, name, key, values, default, listener)
		local config = {
			Default = default,
			Values = values,
			Flag = key,
			Callback = forward(key, default, listener),
		}
		if type(default) == "table" then
			config.Multi = true
		end

		local label = options:AddLabel(name)
		Session.pinRow(label)
		local dropdown = label:AddDropdown(config)
		return dropdown, label
	end

	local statuses = { "friendly", "neutral", "target", "enemy" }

	-- Spam resolver --
	local resolver = rows.spamResolver:AddOption()
	-- Two resolvers: "cluster" aims at the busiest cluster of the spots the target was seen at; "weighted" gives every spot a weight that fades,
	-- merges close spots and aims at the best scoring one. The distance penalty is shared; the rest belongs to one of them (the lerp is the weighted one's:
	-- the cluster resolver holds its spot and goes straight onto the target once it is close).
	local clusterRows, weightedRows = {}, {}
	panelList(resolver, "Type", "resolver_type", { "cluster", "weighted" }, "cluster", function(value)
		for _, row in ipairs(clusterRows) do
			row:SetVisible(isPicked(value, "cluster"))
		end

		for _, row in ipairs(weightedRows) do
			row:SetVisible(isPicked(value, "weighted"))
		end
	end)
	-- 0.1 to 10 seconds; click the number to type one (0.1, 1.1 ...)
	table.insert(clusterRows, select(2, panelSlider(resolver, "Refresh Time", "ue_resolver_refresh", 0.1, 10, 2, "s", 1)))
	table.insert(clusterRows, select(2, panelSlider(resolver, "Forgiveness", "ue_resolver_forgiveness", 0, 20, 1, "", 14.4)))
	table.insert(clusterRows, select(2, panelSlider(resolver, "Out Of Void Bonus", "ue_resolver_void_bonus", 0, 12, 1, "", 5)))
	table.insert(weightedRows, select(2, panelSlider(resolver, "Normal Position Trust", "void_spam_resolver_position_weight", 0.1, 5, 2, "", 1.5)))
	table.insert(weightedRows, select(2, panelSlider(resolver, "Forget Rate", "void_spam_resolver_forget_rate", 0, 1000, 2, "%", 80)))
	table.insert(weightedRows, select(2, panelSlider(resolver, "Void Trust", "void_spam_resolver_void_weight", 0.1, 5, 2, "", 0.2)))
	table.insert(weightedRows, select(2, panelSlider(resolver, "Accuracy", "void_spam_resolver_accuracy", 5, 110, 2, "%", 76.82)))
	panelSlider(resolver, "Distance Based Penalty", "ue_resolver_dist_penalty", 0, 5, 1, "x", 2)
	table.insert(weightedRows, select(2, panelSlider(resolver, "Lerp % When Close", "ue_resolver_lerp", 10, 100, 1, "%", 10, { [100] = "instant" })))

	-- The weighted rows only show for the weighted type.
	for _, row in ipairs(weightedRows) do
		row:SetVisible(false)
	end

	-- Target selection --
	local selection = rows.targetSelection:AddOption()
	local cooldownRow, forceRow
	panelToggle(selection, "Notification", "target_selection_notification", false)
	panelToggle(selection, "Automatic", "target_selection_automatic", false, function(value)
		cooldownRow:SetVisible(value)
	end)
	cooldownRow = select(2, panelSlider(selection, "Cooldown", "target_selection_cooldown", 0, 0.5, 2, "s", 0.03, { [0] = "none" }))
	cooldownRow:SetVisible(false)
	panelToggle(selection, "Target When Shot At", "target_selection_target_when_shot_at", false, function(value)
		forceRow:SetVisible(value)
	end)
	forceRow = select(2, panelToggle(selection, "Force", "target_selection_target_when_shot_at_force", false))
	panelToggle(selection, "Wait For Spawn Protection", "target_selection_wait_for_protection", true)
	-- off: the character is not hidden in the void while the target respawns, loads or has its spawn protection
	panelToggle(selection, "Void While Waiting", "target_selection_void_while_waiting", true)
	forceRow:SetVisible(false)
	panelList(selection, "Untarget When", "target_selection_untarget_when", { "better target", "knocked", "flung", "dead" }, { "dead" })
	panelList(selection, "Target Statuses", "target_statuses", { "friendly", "neutral", "enemy" }, { "neutral" })
	panelList(selection, "Prioritize By", "target_selection_prioritize_by", { "closest to character", "closest to mouse", "highest wanted", "lowest health", "random" }, "closest to mouse")
	panelList(selection, "Ignore If", "target_selection_ignore_if", { "knocked", "in void" }, {})
