---------- Engine tabs ------------
-- Rows for the femmyhac.cc options the engine defines: the Legit tab, the Players ESP, auto reload in the
-- Rage tab, the missing World rows and the Misc tab. The menu shim records every option the engine creates, so this walks those
-- records and builds matching rows. Values go back through the same stubs, so the engine's own
-- listeners run as they did in the original menu. A gear opens a menu with the option's settings.
-- Options that already have a native row (world time, hit sound, ...) are left out so nothing
-- shows up twice.
Session.installEngineTabs = function()
	-- Where each engine section goes. "only" lists the options still missing from the menu and
	-- "into" adds them to a section that already exists instead of making a new one.
	local LAYOUT = {
		{
			tab = "Legit",
			sections = {
				{ key = { "legitbot", "target selection" }, name = "TARGET SELECTION", position = "left" },
				{ key = { "legitbot", "assistance" }, name = "ASSISTANCE", position = "left" },
				{ key = { "legitbot", "redirection" }, name = "REDIRECTION", position = "left" },
				{ key = { "legitbot", "trigger" }, name = "TRIGGER", position = "right" },
			},
		},
		{
			tab = "World",
			sections = {
				{ key = { "general", "world" }, into = "WorldLighting", name = "WORLD", position = "left", only = { "weather" } },
				{
					key = { "general", "hud" },
					into = "WorldHud",
					name = "HUD",
					position = "left",
					only = { "server position indicator", "crosshair animations", "drawing crosshair", "center panel" },
				},
				{
					key = { "general", "game" },
					name = "GAME",
					position = "right",
					only = { "player bullet volume", "override armor pop", "shot notifications", "local bullet sound", "hit skeleton", "hit particle" },
				},
			},
		},
		{
			tab = "Rage",
			sections = {
				-- Auto reload lives with the other ragebot helpers instead of Misc.
				{ key = { "main", "utility" }, into = "RageOther", name = "OTHER", position = "right", only = { "auto reload" } },
			},
		},
		{
			tab = "Misc",
			sections = {
				{ key = { "main", "movement" }, name = "MOVEMENT", position = "left" },
				{ key = { "main", "other" }, name = "OTHER", position = "left", only = { "animation breaker", "animation player", "spinbot" } },
				{ key = { "main", "utility" }, name = "UTILITY", position = "right", except = { "auto reload" } },
				{ key = { "main", "server" }, name = "SERVER", position = "right" },
			},
		},
		{
			tab = "PlayerList",
			sections = {
				{ key = { "players", "player interactions" }, name = "PLAYER INTERACTIONS", position = "right" },
			},
		},
		{
			tab = "Players",
			sections = {
				{ key = { "players", "player esp" }, name = "PLAYER ESP", position = "left" },
				{ key = { "players", "local character" }, into = "PlayersLocal", name = "LOCAL CHARACTER", position = "left", only = { "custom character" } },
			},
		},
	}

	local neverlose = _G.neverlose_flags or {}
	local usedFlags = {}
	local pushes = {}
	local togglePushes = {}
	local controls = {}
	local built = false

	-- "aim assist" -> "Aim Assist"
	local function titleCase(text)
		return (tostring(text):gsub("(%a)([%w']*)", function(first, rest)
			return first:upper() .. rest
		end))
	end

	-- Config flags must be unique in the library, so engine flags get a prefix of their own.
	local function menuFlag(flag)
		if flag == nil then
			return nil
		end

		local base = "e_" .. tostring(flag)
		local flagName, count = base, 1
		while usedFlags[flagName] do
			count += 1
			flagName = base .. "_" .. count
		end

		usedFlags[flagName] = true
		return flagName
	end

	-- Runs the engine's listeners for one signal of a stub.
	local function fire(stub, signalName, ...)
		local engineSignal = rawget(stub, signalName)
		if not engineSignal then
			return
		end

		local ok, err = pcall(engineSignal.Fire, engineSignal, ...)
		if not ok then
			warn("[Visions hook] " .. signalName .. " listener failed: " .. tostring(err))
		end
	end

	-- Engine dropdowns keep their value as an array of names, single picks included.
	local function dropdownDefault(config)
		local default = config.default
		if type(default) == "string" then
			default = { default }
		end
		if type(default) ~= "table" then
			default = {}
		end

		local options = config.options or {}
		if not config.multi and #default == 0 and options[1] ~= nil then
			default = { options[1] }
		end

		return default
	end

	-- The names a dropdown value picks, in the order of the option list.
	local function pickedNames(value, options)
		local names = {}

		if type(value) == "table" then
			for _, option in ipairs(options) do
				if value[option] == true or table.find(value, option) ~= nil then
					table.insert(names, option)
				end
			end
		elseif value ~= nil then
			table.insert(names, tostring(value))
		end

		return names
	end

	-- Follows the engine's set_visible on the given rows, including a state it set while building.
	local function bindVisible(stub, rows)
		local function apply(visible)
			for _, row in ipairs(rows) do
				if type(row) == "table" and type(row.SetVisible) == "function" then
					if visible == false then
						pcall(Session.pinRow, row)
					end
					pcall(row.SetVisible, row, visible)
				end
			end
		end

		local initial = rawget(stub, "_visible")
		if initial ~= nil then
			apply(initial)
		end

		rawset(stub, "_ui_visible", apply)
	end

	-- A second control on an element that already has a toggle goes on its own row; name it after
	-- the part of its flag that follows the toggle's ("spin" + "spin_type" -> "Spin Type").
	local function extraSuffix(def, kind)
		local flag = def[kind].flag
		local base = def.toggle and def.toggle.flag

		if type(flag) == "string" and type(base) == "string" and flag:sub(1, #base + 1) == base .. "_" then
			return (flag:sub(#base + 2):gsub("_", " "))
		end

		return kind == "dropdown" and "mode" or "value"
	end

	controls.toggle = function(row, config, stub, name, inOption)
		local default = config.default == true
		local silent = false
		local flagName = menuFlag(config.flag)

		local toggleConfig = {
			Default = default,
			Flag = flagName,
			Callback = function(value)
				if not Session.Alive or silent then
					return
				end

				if config.flag ~= nil then
					neverlose[config.flag] = value
				end
				fire(stub, "on_toggle_change", value)
			end,
		}

		-- Rows in the sections can be bound to a key with a right-click; gear rows cannot.
		local toggle
		if inOption or flagName == nil then
			toggle = row:AddToggle(toggleConfig)
		else
			toggle = addBindableToggle(row, name, toggleConfig)
		end

		-- When the engine flips the toggle itself (set_toggle), the row follows without re-firing.
		rawset(stub, "_ui_toggle", function(value)
			silent = true
			pcall(toggle.SetValue, toggle, value)
			silent = false
		end)

		-- The starting value goes to the engine's flag as well as its listener: after a re-execute the engine's flags still hold the off
		-- values the last unload left in them, so an option on by default (Hit Checker, Follow Into Void) ran while its flag said off.
		if default then
			table.insert(togglePushes, function()
				local value = true

				if toggle and type(toggle.GetValue) == "function" then
					local okValue, current = pcall(toggle.GetValue, toggle)

					if okValue and type(current) == "boolean" then
						value = current
					end
				end

				if config.flag ~= nil then
					neverlose[config.flag] = value
				end

				fire(stub, "on_toggle_change", value)
			end)
		end
	end

	controls.slider = function(row, config, stub)
		local min = config.min or 0
		local max = config.max or 100
		local default = config.default or min

		-- The library swaps the text of a value through Nums, e.g. { [0] = "gun range" }.
		local nums = {}
		if config.min_text then
			nums[min] = config.min_text
		end
		if config.max_text then
			nums[max] = config.max_text
		end

		local slider = row:AddSlider({
			Min = min,
			Max = max,
			Rounding = config.decimals or 0,
			Type = config.suffix or "",
			Nums = nums,
			Default = default,
			Flag = menuFlag(config.flag),
			Callback = function(value)
				if not Session.Alive then
					return
				end

				if config.flag ~= nil then
					neverlose[config.flag] = value
				end
				fire(stub, "on_slider_change", value)
			end,
		})

		-- Nums is only read once the value changes, so the starting text is refreshed here.
		if nums[default] ~= nil then
			pcall(slider.SetValue, slider, default)
		end

		table.insert(pushes, function()
			if config.flag ~= nil then
				neverlose[config.flag] = default
			end
			fire(stub, "on_slider_change", default)
		end)
	end

	controls.dropdown = function(row, config, stub)
		local options = config.options or {}
		local multi = config.multi == true
		local default = dropdownDefault(config)
		local lastPicked = default

		-- The library only accepts defaults that are in the list.
		local shown = {}
		for _, option in ipairs(default) do
			if table.find(options, option) ~= nil then
				table.insert(shown, option)
			end
		end

		row:AddDropdown({
			Default = multi and shown or shown[1],
			Values = table.clone(options),
			Multi = multi,
			Flag = menuFlag(config.flag),
			Callback = function(value)
				if not Session.Alive then
					return
				end

				local names = pickedNames(value, options)
				if #names == 0 and config.requires_one then
					names = lastPicked
				end
				lastPicked = names

				if config.flag ~= nil then
					neverlose[config.flag] = names
				end
				fire(stub, "on_dropdown_change", names)
			end,
		})

		table.insert(pushes, function()
			if config.flag ~= nil then
				neverlose[config.flag] = default
			end
			fire(stub, "on_dropdown_change", default)
		end)
	end

	controls.keybind = function(row, config, stub, name)
		-- Start on the engine's own default key (E for the legitbot target bind).
		local defaultKey = config.default ~= nil and keyName(config.default) or "None"
		local entry = { stub = stub, key = defaultKey, name = name }

		row:AddKeybind({
			Default = defaultKey,
			Flag = menuFlag(config.flag),
			Callback = function(value)
				if not Session.Alive or value == nil then
					return
				end

				entry.key = keyName(value)
				refreshKeybindList()

				if config.flag ~= nil then
					local okKey, keyCode = pcall(function()
						return Enum.KeyCode[entry.key]
					end)
					neverlose[config.flag] = okKey and keyCode or entry.key
				end
			end,
		})

		-- Pressing the key fires the engine's on_key_press (see Session.onEngineKey).
		table.insert(Session.EngineKeys, entry)
	end

	controls.textbox = function(row, config, stub)
		if type(row.AddTextInput) ~= "function" then
			return
		end

		local default = config.default or ""

		row:AddTextInput({
			Default = default,
			Placeholder = "",
			Flag = menuFlag(config.flag),
			Callback = function(value)
				if not Session.Alive then
					return
				end

				if config.flag ~= nil then
					neverlose[config.flag] = value
				end
				fire(stub, "on_textbox_change", value)
			end,
		})

		if default ~= "" then
			table.insert(pushes, function()
				if config.flag ~= nil then
					neverlose[config.flag] = default
				end
				fire(stub, "on_textbox_change", default)
			end)
		end
	end

	-- Colour swatch. A colour with a transparency of its own gets an opacity bar in its popup.
	local function addColor(row, stub, colorFlag, default, transparencyFlag, defaultTransparency)
		default = default or Color3.new(1, 1, 1)

		row:AddColorPicker({
			Default = default,
			Flag = menuFlag(colorFlag),
			Callback = function(color)
				if not Session.Alive then
					return
				end

				if colorFlag ~= nil then
					neverlose[colorFlag] = color
				end
				fire(stub, "on_color_change", color)
			end,
			Transparency = transparencyFlag ~= nil and (defaultTransparency or 0) or nil,
			TransparencyFlag = transparencyFlag ~= nil and menuFlag(transparencyFlag) or nil,
			TransparencyCallback = function(value)
				if not Session.Alive then
					return
				end

				if transparencyFlag ~= nil then
					neverlose[transparencyFlag] = value
				end
				fire(stub, "on_transparency_change", value)
			end,
		})

		table.insert(pushes, function()
			if colorFlag ~= nil then
				neverlose[colorFlag] = default
			end
			fire(stub, "on_color_change", default)

			if transparencyFlag ~= nil then
				fire(stub, "on_transparency_change", defaultTransparency or 0)
			end
		end)
	end

	controls.colorpicker = function(row, config, stub)
		addColor(row, stub, config.color_flag, config.default_color, config.transparency_flag, config.default_transparency)
	end

	controls.color = function(row, config, stub)
		addColor(row, stub, config.flag, config.default)
	end

	local buildElement

	-- One engine option: a row (or button) with its controls, then its gear menu if it has settings.
	local function addElement(container, record, inOption)
		local stub, def = record.stub, record.def
		local base = record.name or "option"
		local name = titleCase(base)

		-- Buttons are section rows without a label.
		if def.button then
			if type(container.AddButton) ~= "function" then
				return
			end

			local button = container:AddButton({
				Name = name,
				Icon = "cube-vertexes",
				Callback = function()
					if Session.Alive then
						fire(stub, "on_clicked")
					end
				end,
			})

			bindVisible(stub, { button })
			return
		end

		local label = container:AddLabel(name)
		local rows = { label }

		local kinds = {}
		if def.toggle then
			table.insert(kinds, "toggle")
		end
		for _, kind in ipairs({ "slider", "dropdown", "keybind", "textbox", "colorpicker", "color" }) do
			if def[kind] then
				table.insert(kinds, kind)
			end
		end

		for index, kind in ipairs(kinds) do
			local row = label

			-- A second control that is not a swatch gets its own row under the first.
			if index > 1 and kind ~= "colorpicker" and kind ~= "color" then
				row = container:AddLabel(titleCase(base .. " " .. extraSuffix(def, kind)))
				table.insert(rows, row)
			end

			controls[kind](row, def[kind], stub, name, inOption)
		end

		bindVisible(stub, rows)

		-- Settings behind the gear. Settings nested inside a gear menu are flattened into it.
		local settings = rawget(stub, "_settings")
		local children = settings and rawget(settings, "_items")
		if children and #children > 0 then
			local window = inOption and container or label:AddOption()

			for _, child in ipairs(children) do
				buildElement(window, child, true)
			end
		end
	end

	buildElement = function(container, record, inOption)
		local ok, err = pcall(addElement, container, record, inOption)
		if not ok then
			warn(("[Visions hook] Could not add '%s': %s"):format(tostring(record.name), tostring(err)))
		end
	end

	local function findRecord(key)
		local engineUi = _G.NL_ENGINE_UI

		for _, record in ipairs(engineUi and engineUi.sections or {}) do
			if record.tab == key[1] and record.title == key[2] then
				return record
			end
		end

		return nil
	end

	local function addSection(tab, layout, record)
		local items = rawget(record.stub, "_items")
		if not items or #items == 0 then
			return
		end

		local wanted
		if layout.only then
			wanted = {}
			for _, optionName in ipairs(layout.only) do
				wanted[optionName] = true
			end
		end

		-- "except" lists options another section already took.
		local skipped
		if layout.except then
			skipped = {}
			for _, optionName in ipairs(layout.except) do
				skipped[optionName] = true
			end
		end

		local section = layout.into and Session.NativeSections[layout.into]
		if not section then
			section = tab:AddSection({
				Name = layout.name,
				Position = layout.position or "left",
			})
		end

		for _, item in ipairs(items) do
			if (not wanted or wanted[item.name]) and not (skipped and skipped[item.name]) then
				buildElement(section, item, false)
			end
		end
	end

	-- Called once the engine has defined all of its options.
	function Session.buildEngineTabs()
		if built or not Session.Alive or type(Session.EngineTabs) ~= "table" then
			return
		end
		built = true

		for _, tabLayout in ipairs(LAYOUT) do
			local tab = Session.EngineTabs[tabLayout.tab]

			for _, layout in ipairs(tab and tabLayout.sections or {}) do
				local record = findRecord(layout.key)

				if record then
					local ok, err = pcall(addSection, tab, layout, record)
					if not ok then
						warn(("[Visions hook] The %s section failed: %s"):format(layout.name, tostring(err)))
					end
				end
			end
		end

		-- The binds saved in binds.json are applied now that the engine's rows exist: the first read, right after the menu was built, had no row
		-- of the engine to give a key to.
		loadBinds()
		refreshKeybindList()

		-- The engine's crosshair animations act on the game's own crosshair, which Hide Game Crosshair keeps invisible. Switching the animations on
		-- switches the menu's Hide Game Crosshair off (the engine's own Hide row used to do this, but the menu's row replaced it).
		local animationRefs = Session.EngineRefs
		local animations = type(animationRefs) == "table" and animationRefs["crosshair_animations"]
		local animationsSignal = animations and rawget(animations, "on_toggle_change")
		if animationsSignal then
			track(animationsSignal:Connect(function(value)
				if value == true and Session.Alive then
					local hide = NeverLose.Flags and NeverLose.Flags["visual_hide_crosshair"]
					if hide and hide:GetValue() == true then
						pcall(hide.SetValue, hide, false)
					end
				end
			end))
		end

		-- Every listener exists now: send the starting values through them.
		for _, push in ipairs(pushes) do
			pcall(push)
		end
		for _, push in ipairs(togglePushes) do
			pcall(push)
		end

		-- The engine API exists now: hand it the Target List picks.
		pcall(Session.syncEngineTargets, selectedPlayers)

		-- The engine's confirmed-hit signal feeds the hit visuals (hit sound, markers, damage numbers, chams, logs).
		local hitSignal = _G.NL_HIT_SIGNAL
		if type(hitSignal) == "table" and type(hitSignal.Connect) == "function" and type(Session.onEngineHit) == "function" then
			local okHit, hitConnection = pcall(hitSignal.Connect, hitSignal, Session.onEngineHit)
			if okHit and hitConnection then
				Session.EngineHits = true
				table.insert(Session.Cleanups, function()
					Session.EngineHits = false
					pcall(hitConnection.Disconnect, hitConnection)
				end)
			end
		end

		-- Every flag of the menu exists now: load the Default config and keep it saved from here on.
		if NeverLose and type(NeverLose.LoadDefaultConfig) == "function" then
			local okDefault, defaultError = pcall(NeverLose.LoadDefaultConfig, NeverLose)
			if not okDefault then
				warn("[Visions hook] Loading the Default config failed: " .. tostring(defaultError))
			end
		end
	end

	-- The key of a keybind row fires the engine's on_key_press.
	function Session.onEngineKey(input)
		for _, entry in ipairs(Session.EngineKeys) do
			if inputMatchesKey(input, entry.key) then
				fire(entry.stub, "on_key_press")
			end
		end
	end

	_G.NL_BUILD_ENGINE_TABS = Session.buildEngineTabs

	table.insert(Session.Cleanups, function()
		if _G.NL_BUILD_ENGINE_TABS == Session.buildEngineTabs then
			_G.NL_BUILD_ENGINE_TABS = nil
		end
	end)
end

Session.installEngineTabs()

---------- Master switch ------------
-- One toggle that turns every other toggle in the menu off and remembers which ones it turned
-- off, so switching it off again puts exactly those back on. While it is on, key binds can't
-- switch options on either. Toggles whose flag starts with "ui_" (watermark, preview) belong to
-- the menu itself rather than a feature and are left alone. Only the Semi Rage tab carries
-- the master toggle.
do
	Session.MasterFlags = { master_switch_semi = true }

	-- The Anti Report's safety shutdown switches off the engine's own options and then runs the teardowns in neverlose_teardowns. The menu rows
	-- that belong to those options (they keep showing ON) and the Semi Rage options that shoot or move are not part of it, so a teardown
	-- registered by Semi (below) calls Session.afterSafetyShutdown to switch them off the way the user would.
	Session.SafetyShutdownFlags = {
		"Ragebot", "AutoFire", "auto_fire_bullet_manipulation", "follow_target", "void_hide_exploit", "void_hide",
		"target_selection_target_when_shot_at", "auto_equip", "auto_loadout", "auto_ammo", "auto_armor", "auto_mask", "auto_heal", "autostomp", "dt",
	}
	Session.SafetyShutdownSemi = {
		"silent aimbot enabled", "silent aimbot force fire", "silent aimbot force hit", "camera aimbot enabled", "trigger bot enabled", "speed modifications enabled",
		"spiderman enabled", "spread modifications enabled", "rapid fire enabled", "super jump enabled", "hitbox expander enabled",
	}
	Session.SafetyShutdownSet = {}

	for _, flag in ipairs(Session.SafetyShutdownFlags) do
		Session.SafetyShutdownSet[flag] = true
	end

	for _, key in ipairs(Session.SafetyShutdownSemi) do
		Session.SafetyShutdownSet["sr_" .. key:lower():gsub("[^%w]+", "_")] = true
	end

	-- The flags of every feature toggle that is on right now.
	local function activeToggles()
		local found = {}

		for flag, control in pairs(NeverLose.Flags) do
			if not Session.MasterFlags[flag] and string.sub(flag, 1, 3) ~= "ui_" and type(control) == "table" and type(control.GetValue) == "function" then
				local ok, value = pcall(control.GetValue, control)
				if ok and value == true then
					table.insert(found, flag)
				end
			end
		end

		table.sort(found)
		return found
	end

	---Turns the master switch on or off. On: every toggle that is on gets switched off and noted.
	---Off: exactly the noted toggles are switched back on.
	function Session.setMaster(active)
		active = active == true

		local master = Session.Master
		if not Session.Alive or master.Active == active then
			return
		end
		master.Active = active

		-- The master toggle shows the new state.
		for flag in pairs(Session.MasterFlags) do
			local control = NeverLose.Flags[flag]
			if control and control:GetValue() ~= active then
				pcall(control.SetValue, control, active)
			end
		end

		if active then
			master.Held = activeToggles()

			-- Held toggles a config brought along (see ui_master_held below) while the switch was already on at load.
			if master.PendingHeld then
				for _, flag in ipairs(master.PendingHeld) do
					if not table.find(master.Held, flag) then
						table.insert(master.Held, flag)
					end
				end
				master.PendingHeld = nil
				table.sort(master.Held)
			end

			for _, flag in ipairs(master.Held) do
				local control = NeverLose.Flags[flag]
				if control then
					pcall(control.SetValue, control, false)
				end
			end

			log("ps4-touchpad", ("Master switch on: %d options turned off"):format(#master.Held), 4)
		else
			local held = master.Held
			master.Held = {}
			master.PendingHeld = nil

			local restored = 0
			for _, flag in ipairs(held) do
				local control = NeverLose.Flags[flag]
				-- After a safety shutdown the options it switched off stay off; the switch only gives back the rest.
				if control and control:GetValue() ~= true and not (sharedEnv.neverlose_safety_shutdown and Session.SafetyShutdownSet[flag]) then
					if pcall(control.SetValue, control, true) then
						restored += 1
					end
				end
			end

			-- The Target List may have been picked from while the switch was on.
			Session.syncEngineTargets(selectedPlayers)

			log("ps4-touchpad", ("Master switch off: %d options restored"):format(restored), 4)
		end

		refreshKeybindList()
	end

	-- The options the master switch is holding off go into every config as a list, so a config saved with the switch on (or the Default one at
	-- unload) can still hand them back after a restart. Without it the switch would come back on with nothing to restore.
	NeverLose.Flags["ui_master_held"] = {
		Kind = "master_held",
		GetValue = function()
			local list = {}
			if Session.Master.Active then
				for _, flag in ipairs(Session.Master.Held) do
					table.insert(list, flag)
				end
			end
			return list
		end,
		SetValue = function(_, saved)
			if type(saved) ~= "table" then
				return
			end

			local master = Session.Master
			local list = {}
			for _, flag in ipairs(saved) do
				if type(flag) == "string" and string.sub(flag, 1, 3) ~= "ui_" and not Session.MasterFlags[flag] then
					table.insert(list, flag)
				end
			end

			if master.Active then
				for _, flag in ipairs(list) do
					if not table.find(master.Held, flag) then
						table.insert(master.Held, flag)
					end
				end
				table.sort(master.Held)
			elseif #list > 0 then
				master.PendingHeld = list
			end
		end,
	}

	---Switches off the rows of the options the Anti Report's safety shutdown turned off (and the Semi Rage ones that shoot or move), so the menu
	---shows what is running and the Semi Rage features stop. A normal unload never gets here: the flag is only set by the shutdown.
	function Session.afterSafetyShutdown()
		if not Session.Alive then
			return
		end

		local function off(control)
			if control and type(control.GetValue) == "function" and control:GetValue() == true then
				pcall(control.SetValue, control, false)
			end
		end

		for _, flag in ipairs(Session.SafetyShutdownFlags) do
			off(NeverLose.Flags[flag])
		end

		if Session.Semi and Session.Semi.Toggles then
			for _, key in ipairs(Session.SafetyShutdownSemi) do
				off(Session.Semi.Toggles[key])
			end
		end

		-- Whatever Semi had put on the walk speed.
		if Session.Semi and Session.Semi.resetSpeed then
			pcall(Session.Semi.resetSpeed)
		end
	end

	---True when a key bind may flip its option: never while the master switch is holding things off,
	---except for the master switches themselves.
	function Session.bindAllowed(flag)
		return not Session.Master.Active or Session.MasterFlags[flag] == true
	end

	---Adds the master toggle row to a section. `flag` is one of Session.MasterFlags.
	function Session.addMasterRow(section, flag)
		local row = section:AddLabel("Master Switch")
		row:ToolTip("Turns off every toggle in the menu. Turning it off again turns back on only the ones it turned off.")

		return addBindableToggle(row, "Master Switch", {
			Default = Session.Master.Active,
			Flag = flag,
			Callback = function(value)
				if Session.Alive then
					Session.setMaster(value)
				end
			end,
		})
	end
end

---------- Semi Rage (Glory v4) ------------
-- Glory v4 folded into the menu as the Semi Rage tab: silent aim (with Force Hit and Force Fire), camera aimbot, trigger bot, target line, shotgun spread,
-- rapid fire, hitbox expander, speed, super jump, wall jump, name ESP, headless and weapon skins (the skins and the mod detector are kept from before).
-- Semi.Config holds every option, the tab edits it, and nothing acts until its toggle is on.
-- Nothing in here sends data anywhere; the only network access is the library download above.
-- Luau allows at most 200 locals per scope, so all of it lives inside this do-block.
do
	local Semi = { Alive = false, Toggles = {}, Connections = {}, Cleanups = {} }
