	local SHOTGUN_NAMES = { ["Double-Barrel SG"] = true, ["TacticalShotgun"] = true, ["Shotgun"] = true, ["DrumShotgun"] = true }
	local PRIORITY_PARTS = { "Head", "UpperTorso", "LowerTorso" }

	-- Runs `callback` and keeps the connection so Semi.stop can drop it.
	local function connect(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(Semi.Connections, connection)
		return connection
	end

	-- Reads a game ModuleScript without handing it the executor's environment: the thread drops to
	-- identity 2 for the require and goes back afterwards.
	local function safeRequire(moduleScript)
		local previous = type(getthreadidentity) == "function" and getthreadidentity() or 8
		if type(setthreadidentity) == "function" then
			setthreadidentity(2)
		end

		local ok, result = pcall(require, moduleScript)

		if type(setthreadidentity) == "function" then
			setthreadidentity(previous)
		end

		return ok and result or nil
	end

	local NON_SKIN_WEAPONS = { ["[House]"] = true, ["[Mask]"] = true, ["[Wallet]"] = true, ["[Stomps]"] = true, ["[Vehicle]"] = true }

	local function readSkinData()
		local modules = game:GetService("ReplicatedStorage"):FindFirstChild("SkinModules")
		return modules and safeRequire(modules) or nil
	end

	---Tools that have skins this module can apply, sorted by name.
	function Semi.Skins.weapons()
		local data = readSkinData()
		local list = {}

		if type(data) == "table" then
			for toolName, skins in pairs(data) do
				if type(toolName) == "string" and type(skins) == "table" and not NON_SKIN_WEAPONS[toolName] and next(skins) ~= nil then
					table.insert(list, toolName)
				end
			end
		end

		table.sort(list, function(a, b)
			return a:lower() < b:lower()
		end)
		return list
	end

	---Skins the module can apply to a tool as { name, info } sorted by name. Knives are limited to the ones
	---with an entry in KNIFE_SKINS, because that table holds the offsets, sound and animation they need.
	function Semi.Skins.list(toolName)
		local data = readSkinData()
		local skins = type(data) == "table" and data[toolName] or nil
		local list = {}

		if type(skins) == "table" then
			for name, info in pairs(skins) do
				if type(name) == "string" and (toolName ~= "[Knife]" or KNIFE_SKINS[name]) then
					table.insert(list, { name = name, info = info })
				end
			end
		end

		table.sort(list, function(a, b)
			return a.name:lower() < b.name:lower()
		end)
		return list
	end

	Semi.Skins.knife = KNIFE_SKINS

	---Starts every loop, hook and listener. Safe to call once per session.
	function Semi.start()
		if Semi.Alive then
			return
		end
		Semi.Alive = true

		local config = Semi.Config
		local players = game:GetService("Players")
		local runservice = game:GetService("RunService")
		local userinputservice = game:GetService("UserInputService")
		local workspace = game:GetService("Workspace")
		local replicatedstorage = game:GetService("ReplicatedStorage")
		local localplayer = players.LocalPlayer
		local camera = workspace.CurrentCamera
		local mouse = localplayer:GetMouse()

		local triggerbotactive = false
		local triggerhold = false
		local currenttargetplayer = nil
		local leftctrlheld = false
		local targetplayer = nil
		local camlockactive = false
		local camlockhold = false
		local camlocktarget = nil
		local camlockpart = nil
		local haswalljumped = false
		local walljumpconnection = nil
		local walljumpchild = nil
		local backpackconnection = nil
		local sorting = false
		local speedactive = false
		local knifedata = {}
		local closestcache = {}
		local closestcacherate = 1 / 30

		local targetcache = {
			hitbox = nil,
			box = nil,
			trigger = nil,
			triggerbox = nil,
		}

		local espcache = {}
		local silentfov2d = nil
		local triggerfov2d = nil
		local camfov2d = nil

		-- Keep the camera reference current when the game swaps it out.
		connect(workspace:GetPropertyChangedSignal("CurrentCamera"), function()
			camera = workspace.CurrentCamera
		end)

		---Whether the menu's master switch is holding everything off.
		local function masterActive()
			return Session.Master ~= nil and Session.Master.Active == true
		end

		---Clears the target highlight parts.
		local function clearhitboxes()
			pcall(function()
				if targetcache.hitbox then
					targetcache.hitbox:Destroy()
					targetcache.hitbox = nil
				end
				if targetcache.box then
					targetcache.box:Destroy()
					targetcache.box = nil
				end
				if targetcache.trigger then
					targetcache.trigger:Destroy()
					targetcache.trigger = nil
				end
				if targetcache.triggerbox then
					targetcache.triggerbox:Destroy()
					targetcache.triggerbox = nil
				end
			end)
		end

		---Gives the equipped shotgun's name (without brackets) or nil.
		local function getequippedshotgun()
			local char = localplayer.Character
			if not char then
				return nil
			end

			local tool = char:FindFirstChildOfClass("Tool")
			if not tool then
				return nil
			end

			local toolname = tool.Name:gsub("%[", ""):gsub("%]", "")
			if SHOTGUN_NAMES[toolname] then
				return toolname
			end

			return nil
		end

		---------- Movement (Glory v4: speed, wall jump, super jump) ----------
		local function touchingwall()
			local char = localplayer.Character
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return false
			end

			local params = RaycastParams.new()
			params.FilterDescendantsInstances = { char }
			params.FilterType = Enum.RaycastFilterType.Exclude

			local dirs = { hrp.CFrame.LookVector, -hrp.CFrame.LookVector, hrp.CFrame.RightVector, -hrp.CFrame.RightVector }
			for _, d in ipairs(dirs) do
				if workspace:Raycast(hrp.Position, d * 2.5, params) then
					return true
				end
			end

			return false
		end

		local function getspidermanjumppower()
			local char = localplayer.Character
			local tool = char and char:FindFirstChildOfClass("Tool")
			if tool and tool.Name == "[Knife]" then
				return config["spiderman"]["knifejumppower"]
			end

			return config["spiderman"]["jumppower"]
		end

		-- Lets a wall jump happen again once the humanoid lands or runs. One listener per
		-- character, replaced whenever it is set up again.
		local function setupwalljumpreset()
			if walljumpconnection then
				walljumpconnection:Disconnect()
				walljumpconnection = nil
			end
			if walljumpchild then
				walljumpchild:Disconnect()
				walljumpchild = nil
			end

			haswalljumped = false

			local char = localplayer.Character
			if not char then
				return
			end

			local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 2)
			if not hum then
				return
			end

			walljumpconnection = hum.StateChanged:Connect(function(_, new)
				if new == Enum.HumanoidStateType.Landed or new == Enum.HumanoidStateType.Running or new == Enum.HumanoidStateType.RunningNoPhysics or new == Enum.HumanoidStateType.Jumping then
					haswalljumped = false
				end
			end)

			walljumpchild = char.ChildAdded:Connect(function(child)
				if child:IsA("Humanoid") then
					task.wait(0.1)
					setupwalljumpreset()
				end
			end)
		end

		local function applyspeed()
			local cfg = config["speed modifications"]
			if not cfg["enabled"] or not speedactive then
				return
			end

			-- The engine's Speed pins the walk speed the same way (from a property-changed handler): with both on, each write set the other off again.
			-- The engine's gets it; this one carries on when the engine's goes off.
			local api = sharedEnv.neverlose
			if type(api) == "table" and type(api.get_flag) == "function" and api.get_flag("speed") == true then
				return
			end

			local char = localplayer.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if not hum then
				return
			end

			local speed = 16 * (tonumber(cfg["multiplier"]) or 1)
			if hum.WalkSpeed ~= speed then
				hum.WalkSpeed = speed
			end
		end

		local function resetspeed()
			local char = localplayer.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if hum then
				hum.WalkSpeed = 16
			end
		end

		---Switches speed off and puts the walk speed back. Used when the speed option or the master switch turns off.
		function Semi.resetSpeed()
			speedactive = false
			resetspeed()
		end

		local function hookhumanoid(humanoid)
			connect(humanoid:GetPropertyChangedSignal("WalkSpeed"), function()
				if config["speed modifications"]["enabled"] and speedactive then
					applyspeed()
				end
			end)
			connect(humanoid.HealthChanged, function()
				if speedactive then
					applyspeed()
				end
			end)
		end

		---------- Skins ----------
		-- Takes the mesh parts a skin replaces out of the tool. The parts that were there before are only parked in `state.meshes`, so the
		-- default look can put them back; only a leftover skin clone is destroyed.
		local function clearmesh(tool, exclude, state)
			for _, v in ipairs(tool:GetChildren()) do
				if v:IsA("MeshPart") and v ~= exclude then
					if state and v.Name ~= "CurrentSkin" then
						state.meshes = state.meshes or {}
						table.insert(state.meshes, v)
						v.Parent = nil
					else
						v:Destroy()
					end
				end
			end
		end

		local function applybat(tool, name)
			local mesh = nil
			for _, v in ipairs(tool:GetDescendants()) do
				if v:IsA("MeshPart") and v.Transparency == 0 then
					mesh = v
					break
				end
			end
			if not mesh then
				return
			end

			local skinmodules = replicatedstorage:FindFirstChild("SkinModules")
			local batskins = skinmodules and skinmodules:FindFirstChild("Bats")
			local skin = batskins and batskins:FindFirstChild(name)
			if not skin then
				return
			end

			Semi.Skins.capture(tool, mesh)

			local clone = skin:Clone()
			clone.Parent = tool
			clone.CFrame = mesh.CFrame
			clone.Name = "CurrentSkin"

			local weld = Instance.new("Weld")
			weld.Part0 = clone
			weld.Part1 = mesh
			weld.Parent = clone

			mesh.Transparency = 1
		end

		local function applygun(tool, name)
			local orig = tool:FindFirstChildOfClass("MeshPart")
			if not orig then
				return
			end

			local skinmodules = replicatedstorage:FindFirstChild("SkinModules")
			if not skinmodules then
				return
			end

			local skinmodulesreq = safeRequire(skinmodules)
			if not skinmodulesreq then
				return
			end

			local info = skinmodulesreq[tool.Name] and skinmodulesreq[tool.Name][name]
			if not info then
				return
			end

			local state = Semi.Skins.capture(tool, orig)

			clearmesh(tool, orig, state)

			local skinpart = info.TextureID
			if typeof(skinpart) == "Instance" then
				local clone = skinpart:Clone()
				clone.Parent = tool
				clone.CFrame = orig.CFrame
				clone.Name = "CurrentSkin"

				local weld = Instance.new("Weld")
				weld.Part0 = clone
				weld.Part1 = orig
				weld.C0 = info.CFrame:Inverse()
				weld.Parent = clone

				orig.Transparency = 1
			else
				orig.TextureID = skinpart
				orig.Transparency = 0
			end

			local handle = tool:FindFirstChild("Handle")
			if not handle then
				return
			end

			local skinassets = replicatedstorage:FindFirstChild("SkinAssets")

			local shoot = handle:FindFirstChild("ShootSound")
			if shoot and skinassets then
				local gunsounds = skinassets:FindFirstChild("GunShootSounds")
				local sounds = gunsounds and gunsounds:FindFirstChild(tool.Name)
				local obj = sounds and sounds:FindFirstChild(name)
				if obj then
					if state.shoot == nil then
						state.shoot = shoot.SoundId
					end
					shoot.SoundId = obj.Value
				end
			end

			local particlefolder = skinassets and skinassets:FindFirstChild("GunHandleParticle")
			local particlesource = particlefolder and particlefolder:FindFirstChild(name)
			local pe = particlesource and particlesource:FindFirstChild("ParticleEmitter")
			if pe then
				-- The emitters that were there are parked instead of destroyed, so Default can bring them back.
				for _, existing in ipairs(handle:GetChildren()) do
					if existing:IsA("ParticleEmitter") and not table.find(state.added, existing) then
						table.insert(state.removed, existing)
						existing.Parent = nil
					end
				end

				local added = pe:Clone()
				added.Parent = handle
				table.insert(state.added, added)
			end

			if not state.attributeKept then
				state.attributeKept = true
				state.attribute = handle:GetAttribute("SkinName")
			end
			handle:SetAttribute("SkinName", name)
		end

		local function cleanknife(tool)
			local data = knifedata[tool]
			if data then
				if data.track then
					data.track:Stop()
					data.track:Destroy()
					data.track = nil
				end
				for _, weld in ipairs(data.welds or {}) do
					if weld then
						weld:Destroy()
					end
				end
				for _, sound in ipairs(data.sounds or {}) do
					if sound and sound.Parent then
						sound:Destroy()
					end
				end
			end

			local mesh = tool:FindFirstChild("Default")
			if mesh then
				for _, v in ipairs(mesh:GetChildren()) do
					if v.Name == "Handle.R" or v:IsA("Model") or (v:IsA("BasePart") and v.Name ~= "Default") then
						v:Destroy()
					end
				end
				mesh.Transparency = 0
			end

			knifedata[tool] = nil
		end

		local function applyknife(char, tool, skin)
			local cfg = KNIFE_SKINS[skin]
			if not cfg then
				return
			end

			local hum = char:FindFirstChild("Humanoid")
			local rhand = char:FindFirstChild("RightHand")
			if not hum or not rhand then
				return
			end

			cleanknife(tool)
			knifedata[tool] = { track = nil, welds = {}, sounds = {} }
			local data = knifedata[tool]

			local mesh = tool:FindFirstChild("Default")
			if not mesh then
				return
			end
			mesh.Transparency = 1

			local skinmodules = replicatedstorage:FindFirstChild("SkinModules")
			local knives = skinmodules and skinmodules:FindFirstChild("Knives")
			local skinmodel = knives and knives:FindFirstChild(skin)
			if not skinmodel then
				return
			end

			local clone = skinmodel:Clone()
			clone.Name = skin

			local handr = Instance.new("Part")
			handr.Name = "Handle.R"
			handr.Transparency = 1
			handr.CanCollide = false
			handr.Anchored = false
			handr.Size = Vector3.new(0.001, 0.001, 0.001)
			handr.Massless = true
			handr.Parent = mesh

			local m6d = Instance.new("Motor6D")
			m6d.Name = "Handle.R"
			m6d.Part0 = rhand
			m6d.Part1 = handr
			m6d.Parent = handr

			local offset = CFrame.new(cfg.positionoffset) * CFrame.Angles(math.rad(cfg.rotationoffset.X), math.rad(cfg.rotationoffset.Y), math.rad(cfg.rotationoffset.Z))

			if clone:IsA("Model") then
				if not clone.PrimaryPart then
					for _, child in ipairs(clone:GetChildren()) do
						if child:IsA("BasePart") then
							clone.PrimaryPart = child
							break
						end
					end
				end

				if clone.PrimaryPart then
					for _, part in ipairs(clone:GetDescendants()) do
						if part:IsA("BasePart") then
							part.CanCollide = false
							part.Massless = true
							part.Anchored = false

							local weld = Instance.new("Weld")
							weld.Part0 = handr
							weld.Part1 = part
							weld.C0 = offset
							weld.C1 = part.CFrame:ToObjectSpace(clone.PrimaryPart.CFrame)
							weld.Parent = part
							table.insert(data.welds, weld)
						end
					end
				end

				clone.Parent = mesh
			elseif clone:IsA("BasePart") then
				clone.CanCollide = false
				clone.Massless = true
				clone.Anchored = false

				if clone:IsA("MeshPart") and cfg.textureid then
					clone.TextureID = cfg.textureid
				end

				if cfg.particle then
					local skinassets = replicatedstorage:FindFirstChild("SkinAssets")
					local particlefolder = skinassets and skinassets:FindFirstChild("GunHandleParticle")
					local particlesource = particlefolder and particlefolder:FindFirstChild(skin)
					local pe = particlesource and particlesource:FindFirstChild("ParticleEmitter")
					if pe then
						pe:Clone().Parent = clone
					end
				end

				clone.Parent = mesh

				local weld = Instance.new("Weld")
				weld.Part0 = handr
				weld.Part1 = clone
				weld.C0 = offset
				weld.Parent = clone
				table.insert(data.welds, weld)
			end

			local animator = hum:FindFirstChildOfClass("Animator")
			if not animator then
				animator = Instance.new("Animator")
				animator.Parent = hum
			end

			if cfg.animationid and cfg.animationid ~= "" then
				local anim = Instance.new("Animation")
				anim.AnimationId = cfg.animationid

				local animtrack = animator:LoadAnimation(anim)
				animtrack.Looped = false
				animtrack:Play()
				data.track = animtrack
				anim:Destroy()

				animtrack.Ended:Once(function()
					if data.track == animtrack then
						data.track = nil
					end
					animtrack:Destroy()
				end)
			end

			if cfg.soundid and cfg.soundid ~= "" then
				local sound = Instance.new("Sound")
				sound.SoundId = cfg.soundid
				sound.Parent = workspace
				sound:Play()
				table.insert(data.sounds, sound)
				sound.Ended:Connect(function()
					sound:Destroy()
				end)
			end

			tool:SetAttribute("CurrentKnifeSkin", skin)
		end

		---------- Skin API used by the Skins tab ----------
		-- What a skin changed on a tool is remembered here, so the default look can be put back exactly.
		Semi.Skins.state = setmetatable({}, { __mode = "k" })

		function Semi.Skins.capture(tool, orig)
			local state = Semi.Skins.state[tool]

			if not state then
				state = { orig = orig, transparency = orig.Transparency, removed = {}, added = {} }

				if orig:IsA("MeshPart") then
					state.texture = orig.TextureID
				end

				Semi.Skins.state[tool] = state
			end

			return state
		end

		---Puts a tool back to the look it had before any skin was applied.
		function Semi.Skins.reset(tool)
			if tool.Name == "[Knife]" then
				cleanknife(tool)
				return
			end

			for _, v in ipairs(tool:GetChildren()) do
				if v.Name == "CurrentSkin" then
					v:Destroy()
				end
			end

			local state = Semi.Skins.state[tool]
			if not state then
				return
			end
			Semi.Skins.state[tool] = nil

			-- The mesh parts the skin moved out of the tool come back.
			for _, mesh in ipairs(state.meshes or {}) do
				pcall(function()
					mesh.Parent = tool
				end)
			end

			local orig = state.orig
			if orig and orig.Parent then
				if state.texture ~= nil then
					orig.TextureID = state.texture
				end
				orig.Transparency = state.transparency
			end

			local handle = tool:FindFirstChild("Handle")
			if not handle then
				return
			end

			local shoot = handle:FindFirstChild("ShootSound")
			if shoot and state.shoot ~= nil then
				shoot.SoundId = state.shoot
			end

			for _, emitter in ipairs(state.added) do
				emitter:Destroy()
			end
			for _, emitter in ipairs(state.removed) do
				emitter.Parent = handle
			end

			if state.attributeKept then
				handle:SetAttribute("SkinName", state.attribute)
			end
		end

		---Applies the configured skin to one tool (or the default look when none is configured).
		function Semi.Skins.applyTool(tool, char)
			Semi.Skins.reset(tool)

			local skin = config["skins"][tool.Name]
			if not Semi.Alive or not skin or skin == "" then
				return
			end

			if tool.Name == "[Knife]" then
				-- Knives need the character's hand, so they are skinned when equipped.
				if char then
					applyknife(char, tool, skin)
				end
			elseif tool.Name == "[Bat]" then
				applybat(tool, skin)
			else
				applygun(tool, skin)
			end
		end

		---Re-applies the configured skin to every tool with this name, in the character and the backpack.
		function Semi.Skins.refresh(toolName)
			local character = localplayer.Character
			local backpack = localplayer:FindFirstChildOfClass("Backpack")

			for _, holder in ipairs({ character or false, backpack or false }) do
				if holder then
					for _, tool in ipairs(holder:GetChildren()) do
						if tool:IsA("Tool") and tool.Name == toolName then
							Semi.Skins.applyTool(tool, holder == character and character or nil)
						end
					end
				end
			end
		end

		---Applies the configured skin to a tool the moment it is equipped.
		local function setuptool(tool)
			if not tool:IsA("Tool") or tool:GetAttribute("GlorySetup") then
				return
			end
			tool:SetAttribute("GlorySetup", true)

			local function applyskin(char)
				Semi.Skins.applyTool(tool, char)
			end

			connect(tool.Equipped, function()
				local char = tool.Parent
				if char ~= localplayer.Character then
					return
				end
				applyskin(char)
			end)

			connect(tool.Unequipped, function()
				if tool.Name ~= "[Knife]" then
					return
				end

				local data = knifedata[tool]
				if not data then
					return
				end

				for _, weld in ipairs(data.welds or {}) do
					if weld then
						weld:Destroy()
					end
				end
				data.welds = {}

				for _, sound in ipairs(data.sounds or {}) do
					if sound and sound.Parent then
						sound:Destroy()
					end
				end
				data.sounds = {}

				local mesh = tool:FindFirstChild("Default")
				if mesh then
					for _, v in ipairs(mesh:GetChildren()) do
						if v.Name == "Handle.R" or v:IsA("Model") or (v:IsA("MeshPart") and v.Name ~= "Default") then
							v:Destroy()
						end
					end
					mesh.Transparency = 0
				end
			end)

			if tool.Parent == localplayer.Character then
				task.spawn(applyskin, localplayer.Character)
			end
		end

		local function watchcharacter(char)
			if not char then
				return
			end

			for _, v in ipairs(char:GetChildren()) do
				if v:IsA("Tool") then
					setuptool(v)
				end
			end

			connect(char.ChildAdded, function(v)
				if v:IsA("Tool") then
					setuptool(v)
				end
			end)
		end

		-- The backpack is rebuilt on every respawn, so its listener is replaced each time.
		local function watchbackpack()
			if backpackconnection then
				backpackconnection:Disconnect()
				backpackconnection = nil
			end

			local backpack = localplayer:FindFirstChildOfClass("Backpack") or localplayer:WaitForChild("Backpack", 10)
			if not backpack then
				return
			end

			for _, v in ipairs(backpack:GetChildren()) do
				if v:IsA("Tool") then
					setuptool(v)
				end
			end

			backpackconnection = backpack.ChildAdded:Connect(function(v)
				if v:IsA("Tool") then
					setuptool(v)
				end
			end)
			table.insert(Semi.Connections, backpackconnection)
		end

		local function setupcharacter(char)
			if not char then
				return
			end

			haswalljumped = false

			local hum = char:WaitForChild("Humanoid", 10)
			if hum then
				hookhumanoid(hum)
				setupwalljumpreset()
			end

			watchcharacter(char)
			watchbackpack()
		end

		connect(localplayer.CharacterAdded, setupcharacter)
		if localplayer.Character then
			task.spawn(setupcharacter, localplayer.Character)
		end

		---------- Moderator detector ----------
		task.spawn(function()
			local communityid = 17215700

			local function checkmod(player)
				if not Semi.Alive or not config["global"]["mod detector"] or player == localplayer then
					return false
				end

				local ok, ismod = pcall(player.IsInGroup, player, communityid)
				if ok and ismod then
					localplayer:Kick("A moderator joined the server (mod detector)")
					return true
				end

				return false
			end

			for _, player in ipairs(players:GetPlayers()) do
				if checkmod(player) then
					break
				end
			end

			connect(players.PlayerAdded, function(player)
				task.wait()
				checkmod(player)
			end)

			-- The master switch turns the detector off like every other toggle, so players who joined meanwhile were never looked at: when it
			-- comes back on, everybody in the server is checked.
			function Semi.recheckMods()
				task.spawn(function()
					for _, player in ipairs(players:GetPlayers()) do
						if checkmod(player) then
							break
						end
					end
				end)
			end
		end)

		---------- Targeting (Glory v4) ----------
		-- Glory v4's targeting, camera aimbot, trigger bot, target line, rapid fire, hitbox expander, wall jump, name ESP and headless, with Force Hit and
		-- Force Fire kept on the silent aimbot. Its silent aim hooks mouse.Hit, which this game's guns no longer read, so the shot is redirected where the gun
		-- sends it (the ShootGun call), as the earlier Semi Rage did.
		local rayparams = RaycastParams.new()
		rayparams.FilterType = Enum.RaycastFilterType.Exclude
		rayparams.IgnoreWater = true

		local currenttarget = nil -- the body part the silent aimbot and the camera aimbot are on
		local silentaimactive = false
		local lastvisibletarget = nil
		local lasttriggerclick = 0
		local lasttargetscan = 0
		local scanrate = 1 / 20
		local superjumpenabled = false
		local isfiring = false
		local lastrapidfire = 0
		local originaljumppower = nil
		local expanded = setmetatable({}, { __mode = "k" }) -- hitbox expander: the size each root part had
		local latched = { silent = false, cam = false, trigger = false, superjump = false, speed = false, esp = false }

		local fovparts = {}
		local fov2dboxes = {}

		for _, key in ipairs({ "silent", "camlock", "trigger" }) do
			local part = Instance.new("Part")
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.CastShadow = false
			part.Transparency = 1
			part.BrickColor = BrickColor.new("Grey")
			part.Material = Enum.Material.Neon
			part.Name = "fovoutline3d_" .. key
			part.Parent = workspace
			fovparts[key] = part

			local lines = {}
			for index = 1, 4 do
				local line = Drawing.new("Line")
				line.Thickness = 1.5
				line.Color = Color3.fromRGB(150, 150, 150)
				line.Visible = false
				line.ZIndex = 5
				lines[index] = line
			end
			fov2dboxes[key] = lines
		end

		local targetline = Drawing.new("Line")
		targetline.Visible = false
		targetline.ZIndex = 999

		local function filterlist(...)
			local list = {}
			for index = 1, select("#", ...) do
				local instance = select(index, ...)
				if instance then
					table.insert(list, instance)
				end
			end
			return list
		end

		local function holdingknife()
			if not config["settings"]["knife check"] then
				return false
			end

			local char = localplayer.Character
			local tool = char and char:FindFirstChildOfClass("Tool")
			return tool ~= nil and tool.Name == "[Knife]"
		end

		local function getko(character)
			local effects = character and character:FindFirstChild("BodyEffects")
			if not effects then
				return false
			end

			local ko = effects:FindFirstChild("K.O")
			if ko and ko.Value == true then
				return true
			end

			local knocked = effects:FindFirstChild("Knocked")
			return knocked ~= nil and knocked.Value == true
		end

		local function playerknocked(player)
			if not config["settings"]["knock check"] then
				return false
			end

			return player.Character ~= nil and getko(player.Character)
		end

		local function selfknocked()
			if not config["settings"]["self knock check"] then
				return false
			end

			return getko(localplayer.Character)
		end

		---True while a character is behind a forcefield or still loading in (the game's own protection markers).
		function Semi.spawnprotected(character)
			if not character or not character.Parent then
				return true
			end

			if character:FindFirstChild("FORCEFIELD") or character:FindFirstChildOfClass("ForceField") then
				return true
			end

			if not character:FindFirstChild("FULLY_LOADED_CHAR") then
				return true
			end

			return character:GetAttribute("AdminInvisible") == true or character:GetAttribute("BatmanFlight") == true
		end

		local function cansee(part)
			if not config["settings"]["visible check"] then
				return true
			end

			if not part or not part.Parent then
				return false
			end

			local char = part.Parent
			local origin = camera.CFrame.Position

			rayparams.FilterDescendantsInstances = filterlist(localplayer.Character, char, fovparts.silent, fovparts.camlock, fovparts.trigger, workspace:FindFirstChild("Ignored"))

			local result = workspace:Raycast(origin, part.Position - origin, rayparams)
			return result == nil or result.Instance:IsDescendantOf(char)
		end

		local function withindistance(part, distcfg)
			if not distcfg or not distcfg["enabled"] then
				return true
			end

			if not part or not part.Parent then
				return false
			end

			local hrp = localplayer.Character and localplayer.Character:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return false
			end

			return (hrp.Position - part.Position).Magnitude <= distcfg["max distance"]
		end

		local BODY_PARTS = {
			"Head", "UpperTorso", "HumanoidRootPart", "LowerTorso", "LeftUpperArm", "RightUpperArm", "LeftLowerArm", "RightLowerArm",
			"LeftHand", "RightHand", "LeftUpperLeg", "RightUpperLeg", "LeftLowerLeg", "RightLowerLeg", "LeftFoot", "RightFoot",
		}

		---The body part on screen closest to the cursor.
		local function closestbodypart(char)
			local closestpart = nil
			local shortest = math.huge
			local mousepos = userinputservice:GetMouseLocation()

			for _, name in ipairs(BODY_PARTS) do
				local part = char:FindFirstChild(name)

				if part then
					local screenpos, onscreen = camera:WorldToViewportPoint(part.Position)

					if onscreen then
						local dist = math.sqrt((screenpos.X - mousepos.X) ^ 2 + (screenpos.Y - mousepos.Y) ^ 2)

						if dist < shortest then
							shortest = dist
							closestpart = part
						end
					end
				end
			end

			return closestpart
		end

		---The part a section aims at: its Hit Part setting, or the closest one to the cursor.
		local function withhitpart(part, hitpart)
			if not part or not part.Parent or hitpart == nil or hitpart == "Closest Part" then
				return part
			end

			return part.Parent:FindFirstChild(hitpart) or part
		end

		---Whether the line from the cursor goes through a box (a CFrame and its full size).
		local function cursorhitsbox(cf, fullsize)
			local mpos = userinputservice:GetMouseLocation()
			local ray = camera:ViewportPointToRay(mpos.X, mpos.Y)
			local size = fullsize / 2
			local localorigin = cf:PointToObjectSpace(ray.Origin)
			local localdir = cf:VectorToObjectSpace(ray.Direction * 1000)
			local tmin, tmax = -math.huge, math.huge

			for _, axis in ipairs({ "X", "Y", "Z" }) do
				local o = localorigin[axis]
				local d = localdir[axis]
				local s = size[axis]

				if math.abs(d) < 1e-8 then
					if o < -s or o > s then
						return false
					end
				else
					local t1 = (-s - o) / d
					local t2 = (s - o) / d
					if t1 > t2 then
						t1, t2 = t2, t1
					end
					tmin = math.max(tmin, t1)
					tmax = math.min(tmax, t2)
					if tmin > tmax then
						return false
					end
				end
			end

			return tmax > 0
		end

		---The corners of the 3D FOV box round a root part, as the screen box they cover (nil when it is behind the camera).
		local function getscreenbounds2d(hrp, fovcfg)
			local sx = (hrp.Size.X + fovcfg["size"]["x"]) / 2
			local sy = (hrp.Size.Y + fovcfg["size"]["y"]) / 2
			local sz = (hrp.Size.Z + fovcfg["size"]["z"]) / 2
			local cf = hrp.CFrame
			local minx, miny = math.huge, math.huge
			local maxx, maxy = -math.huge, -math.huge
			local valid = false

			for _, offset in ipairs({
				Vector3.new(sx, sy, sz), Vector3.new(-sx, sy, sz), Vector3.new(sx, -sy, sz), Vector3.new(-sx, -sy, sz),
				Vector3.new(sx, sy, -sz), Vector3.new(-sx, sy, -sz), Vector3.new(sx, -sy, -sz), Vector3.new(-sx, -sy, -sz),
			}) do
				local screen = camera:WorldToViewportPoint(cf:PointToWorldSpace(offset))

				if screen.Z > 0 then
					valid = true
					minx, miny = math.min(minx, screen.X), math.min(miny, screen.Y)
					maxx, maxy = math.max(maxx, screen.X), math.max(maxy, screen.Y)
				end
			end

			if not valid then
				return nil, nil
			end

			return Vector2.new(minx, miny), Vector2.new(maxx, maxy)
		end

		---Whether the cursor is inside a section's FOV box round the target (3D: the line from the cursor goes through it; 2D: the cursor is inside its screen box).
		local function mouseinfovconfig(fovcfg, targetpart)
			if not fovcfg["enabled"] then
				return true
			end

			if not targetpart or not targetpart.Parent then
				return false
			end

			local hrp = targetpart.Parent:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return false
			end

			if fovcfg["mode"] == "2D" then
				local tl, br = getscreenbounds2d(hrp, fovcfg)
				if not tl then
					return false
				end

				local mpos = userinputservice:GetMouseLocation()
				return mpos.X >= tl.X and mpos.X <= br.X and mpos.Y >= tl.Y and mpos.Y <= br.Y
			end

			return cursorhitsbox(hrp.CFrame, hrp.Size + Vector3.new(fovcfg["size"]["x"], fovcfg["size"]["y"], fovcfg["size"]["z"]))
		end

		local function setbox2d(lines, tl, br, color)
			lines[1].From = tl
			lines[1].To = Vector2.new(br.X, tl.Y)
			lines[2].From = Vector2.new(tl.X, br.Y)
			lines[2].To = br
			lines[3].From = tl
			lines[3].To = Vector2.new(tl.X, br.Y)
			lines[4].From = Vector2.new(br.X, tl.Y)
			lines[4].To = br

			for _, line in ipairs(lines) do
				line.Color = color
				line.Visible = true
			end
		end

		local function hidebox2d(lines)
			for _, line in ipairs(lines) do
				line.Visible = false
			end
		end

		---The best player for a section: on screen, inside its FOV, in the open and in range, the one closest to the cursor. Returns the part to aim at.
		local function findtarget(fovcfg, distcfg, knifecheck)
			if knifecheck and holdingknife() then
				return nil
			end

			local besttarget = nil
			local bestdist = math.huge
			local mpos = userinputservice:GetMouseLocation()

			for _, player in ipairs(players:GetPlayers()) do
				local char = player ~= localplayer and player.Character
				local hrp = char and char:FindFirstChild("HumanoidRootPart")

				if hrp and not playerknocked(player) then
					local screenpos, onscreen = camera:WorldToViewportPoint(hrp.Position)

					if onscreen
						and not (config["settings"]["forcefield check"] and Semi.spawnprotected(char))
						and not (fovcfg and fovcfg["enabled"] and not mouseinfovconfig(fovcfg, hrp))
						and cansee(hrp)
						and withindistance(hrp, distcfg)
					then
						local dist = math.sqrt((screenpos.X - mpos.X) ^ 2 + (screenpos.Y - mpos.Y) ^ 2)

						if dist < bestdist then
							bestdist = dist
							besttarget = hrp
						end
					end
				end
			end

			if besttarget then
				return closestbodypart(besttarget.Parent) or besttarget
			end

			return nil
		end

		---Where a part will be: its position plus its velocity times the section's prediction, per axis.
		local function predictedpos(part, section)
			if not section["use prediction"] then
				return part.Position
			end

			local vel = part.AssemblyLinearVelocity
			local prediction = section["prediction"]

			return part.Position + Vector3.new(
				vel.X * (tonumber(prediction["x"]) or 0.133),
				vel.Y * (tonumber(prediction["y"]) or 0.133),
				vel.Z * (tonumber(prediction["z"]) or 0.133)
			)
		end

		local function elasticout(t)
			local p = 0.3
			return math.pow(2, -10 * t) * math.sin((t - p / 4) * (2 * math.pi) / p) + 1
		end

		local function sineinout(t)
			return -(math.cos(math.pi * t) - 1) / 2
		end

		local function clearcurrenttarget()
			currenttarget = nil
			lastvisibletarget = nil
			targetline.Visible = false
		end

		---Puts the silent aimbot on a body part without a key press (nil lets it go).
		function Semi.setTarget(part)
			currenttarget = part
			lastvisibletarget = part
			silentaimactive = part ~= nil
		end

		-- The target of the camera aimbot: the part it is on (re-picked a few times a second when its Hit Part is Closest Part), or a new one.
		local function getcamlocktarget()
			local cam = config["camera aimbot"]

			if camlockactive and currenttarget then
				local player = players:GetPlayerFromCharacter(currenttarget.Parent)

				if player and not playerknocked(player) then
					local targetpart = nil

					if cam["hitpart"] == "Closest Part" then
						local now = os.clock()

						if now - lasttargetscan >= scanrate then
							lasttargetscan = now
							targetpart = closestbodypart(currenttarget.Parent)

							if targetpart then
								currenttarget = targetpart
							end
						else
							targetpart = currenttarget
						end
					else
						targetpart = currenttarget.Parent:FindFirstChild(cam["hitpart"])
					end

					if targetpart then
						if cansee(targetpart) and withindistance(targetpart, cam["distance check"]) then
							lastvisibletarget = targetpart
							return targetpart
						end
					end

					return nil
				end

				clearcurrenttarget()
				camlockactive = false
				return nil
			end

			return findtarget(cam["fov"], cam["distance check"], true)
		end

		local function applycamlock()
			if not camlockactive then
				return
			end

			if selfknocked() then
				clearcurrenttarget()
				camlockactive = false
				return
			end

			if holdingknife() then
				return
			end

			local cam = config["camera aimbot"]

			if cam["fov"]["enabled"] and currenttarget and not mouseinfovconfig(cam["fov"], currenttarget) then
				return
			end

			local target = getcamlocktarget()

			if target then
				local targetpos = predictedpos(target, cam)
				local camcf = camera.CFrame
				local targetcf = CFrame.new(camcf.Position, targetpos)
				local smoothing = cam["smoothing"]

				local bax = 1 / math.max(tonumber(smoothing["x"]) or 40, 1)
				local bay = 1 / math.max(tonumber(smoothing["y"]) or 40, 1)
				local baz = 1 / math.max(tonumber(smoothing["z"]) or 40, 1)

				local avgea = (elasticout(math.min(bax, 1)) + elasticout(math.min(bay, 1)) + elasticout(math.min(baz, 1))) / 3
				local avgba = (bax + bay + baz) / 3

				local smoothcf = camcf:Lerp(targetcf, avgea * avgba)
				camera.CFrame = smoothcf:Lerp(targetcf, sineinout(math.min(avgba, 1)) * avgba)
			elseif lastvisibletarget then
				local player = players:GetPlayerFromCharacter(lastvisibletarget.Parent)

				if player and not playerknocked(player) and cansee(lastvisibletarget) and withindistance(lastvisibletarget, cam["distance check"]) then
					currenttarget = lastvisibletarget
				end
			end
		end

		---Shows the FOV box round the current target for one section.
		local function updatefovbox(fovpart, lines2d, fovcfg, isactive)
			local hrp = isactive and fovcfg["enabled"] and currenttarget and currenttarget.Parent and currenttarget.Parent:FindFirstChild("HumanoidRootPart")

			if not hrp then
				fovpart.Transparency = 1
				hidebox2d(lines2d)
				return
			end

			if fovcfg["mode"] == "2D" then
				fovpart.Transparency = 1

				if fovcfg["visible"] then
					local tl, br = getscreenbounds2d(hrp, fovcfg)

					if tl and br then
						local mpos = userinputservice:GetMouseLocation()
						local inside = mpos.X >= tl.X and mpos.X <= br.X and mpos.Y >= tl.Y and mpos.Y <= br.Y
						setbox2d(lines2d, tl, br, inside and fovcfg["active color"] or Color3.fromRGB(150, 150, 150))
					else
						hidebox2d(lines2d)
					end
				else
					hidebox2d(lines2d)
				end
			else
				hidebox2d(lines2d)
				fovpart.Size = hrp.Size + Vector3.new(fovcfg["size"]["x"], fovcfg["size"]["y"], fovcfg["size"]["z"])
				fovpart.CFrame = hrp.CFrame

				if fovcfg["visible"] then
					fovpart.Transparency = 0.85
					fovpart.BrickColor = cursorhitsbox(fovpart.CFrame, fovpart.Size) and BrickColor.new(fovcfg["active color"]) or BrickColor.new("Grey")
				else
					fovpart.Transparency = 1
				end
			end
		end

		local function updatetargetline()
			local line = config["target line"]

			if not line["enabled"] or not currenttarget or not currenttarget.Parent or (not silentaimactive and not camlockactive) then
				targetline.Visible = false
				return
			end

			local hrp = currenttarget.Parent:FindFirstChild("HumanoidRootPart")
			if not hrp then
				targetline.Visible = false
				return
			end

			local screenpos, onscreen = camera:WorldToViewportPoint(hrp.Position)

			if onscreen and screenpos.Z > 0 then
				local mpos = userinputservice:GetMouseLocation()

				targetline.From = Vector2.new(mpos.X, mpos.Y)
				targetline.To = Vector2.new(screenpos.X, screenpos.Y)
				targetline.Thickness = line["thickness"]
				targetline.Transparency = line["transparency"]
				targetline.Color = cansee(currenttarget) and line["vulnerable"] or line["invulnerable"]
				targetline.Visible = true
			else
				targetline.Visible = false
			end
		end

		---Whether a tool is on a list of names (with or without the brackets).
		local function toolonlist(tool, list)
			for _, name in ipairs(list) do
				local clean = name:gsub("%[", ""):gsub("%]", "")
				if tool.Name == name or tool.Name:find(clean, 1, true) then
					return true
				end
			end

			return false
		end

		---------- Trigger bot ----------
		local function triggerenabled()
			local mode = config["trigger bot"]["mode"]
			return mode == "Always" or (mode == "Toggle" and triggerbotactive) or (mode == "Hold" and triggerhold)
		end

		local function triggerbot()
			local cfg = config["trigger bot"]

			if not cfg["enabled"] or not triggerenabled() or holdingknife() then
				return
			end

			if os.clock() - lasttriggerclick < cfg["delay"] then
				return
			end

			if cfg["require target"] and not currenttarget then
				return
			end

			if currenttarget then
				local char = currenttarget.Parent
				local player = char and players:GetPlayerFromCharacter(char)

				if not player or playerknocked(player) or not cansee(currenttarget) or not withindistance(currenttarget, cfg["distance check"]) then
					return
				end

				if cfg["fov"]["enabled"] and not mouseinfovconfig(cfg["fov"], currenttarget) then
					return
				end
			end

			local tool = localplayer.Character and localplayer.Character:FindFirstChildOfClass("Tool")
			if not tool or (cfg["specific weapons"]["enabled"] and not toolonlist(tool, cfg["specific weapons"]["weapons"])) then
				return
			end

			tool:Activate()
			lasttriggerclick = os.clock()
		end

		---------- Rapid fire ----------
		local function getrapidgun()
			local char = localplayer.Character
			if not char then
				return nil
			end

			for _, tool in ipairs(char:GetChildren()) do
				if tool:IsA("Tool") and tool:FindFirstChild("Ammo") then
					return tool
				end
			end

			return nil
		end

		-- Zeroes the numbers the gun's own script keeps for its delay.
		local function patchtool(tool)
			pcall(function()
				for _, conn in pairs(getconnections(tool.Activated)) do
					local info = debug.getinfo(conn.Function)
					for index = 1, info.nups do
						local val = debug.getupvalue(conn.Function, index)
						if type(val) == "number" then
							debug.setupvalue(conn.Function, index, 0)
						end
					end
				end
			end)
		end

		local function oncharrapidfire(char)
			isfiring = false
			connect(char.ChildAdded, function(tool)
				if tool:IsA("Tool") and config["rapid fire"]["enabled"] then
					patchtool(tool)
				end
			end)
		end

		local function rapidfire()
			local cfg = config["rapid fire"]

			if not cfg["enabled"] then
				isfiring = false
				return
			end

			if not isfiring or os.clock() - lastrapidfire < cfg["delay"] then
				return
			end

			local gun = getrapidgun()
			if not gun then
				return
			end

			if cfg["specific weapons"]["enabled"] and not toolonlist(gun, cfg["specific weapons"]["weapons"]) then
				isfiring = false
				return
			end

			gun:Activate()
			lastrapidfire = os.clock()
		end

		---------- Silent aim ----------
		-- The gun's own ShootGun call on MainEvent is caught and sent on aimed at the target instead (forcehit_silent), so the mouse is never touched.
		-- In Select mode with Force Hit on, the head takes the shot whatever the FOV and the walls say, and Force Fire shoots at it by itself (forcehit dh).
		local SHOOT_NORMAL = Vector3.new(0, 0, -1)
		local restorenamecall = setnamecallmethod or set_namecall_method or function() end

		---Where the silent aimbot wants a shot to land: { part, position }, or nil to leave the shot alone.
		local function getsilenthit()
			local silent = config["silent aimbot"]

			if not silent["enabled"] or masterActive() or not silentaimactive or not currenttarget or not currenttarget.Parent then
				return nil
			end

			local char = currenttarget.Parent
			local player = players:GetPlayerFromCharacter(char)

			if not player or playerknocked(player) then
				return nil
			end

			if silent["force hit"] and config["targeting"]["mode"] == "Select" then
				local head = char:FindFirstChild("Head")

				if head and head:IsA("BasePart") then
					return { part = head, position = predictedpos(head, silent) }
				end

				return nil
			end

			if not cansee(currenttarget) or not withindistance(currenttarget, silent["distance check"]) then
				return nil
			end

			if silent["fov"]["enabled"] and not mouseinfovconfig(silent["fov"], currenttarget) then
				return nil
			end

			return { part = currenttarget, position = predictedpos(currenttarget, silent) }
		end

		-- The engine's ragebot answers for the game's shots while it has an aim (its hook rewrote the shot before this one sees it): this module's silent
		-- aim then leaves them as they are, instead of sending them at its own target from its own origin.
		local function ragebotaims()
			local api = sharedEnv.neverlose
			if type(api) ~= "table" or type(api.get_ragebot_aim_position) ~= "function" then
				return false
			end

			local ok, position = pcall(api.get_ragebot_aim_position)
			return ok and position ~= nil
		end

		-- The hook goes in the first time silent aim is turned on and then stays; while the option
		-- is off (or the session is unloaded) it hands every call straight through.
		local silenthooked = false
		local originalnamecall

		function Semi.installSilentHook()
			if silenthooked or not Semi.Alive then
				return
			end
			silenthooked = true

			originalnamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
				-- Read first: every method call made in here replaces it.
				local method = getnamecallmethod()
				local clobbered = false

				if method == "FireServer" and Semi.Alive and not checkcaller() and (...) == "ShootGun" and self.Name == "MainEvent" and not ragebotaims() then
					-- Method calls are made in here (getsilenthit), so the method is put back before the call goes on. Every other call - almost all of the
					-- game's method calls pass through this hook - makes none, and used to pay the extra C call for nothing.
					clobbered = true
					local ok, hit = pcall(getsilenthit)
					local character = localplayer.Character
					local root = ok and hit and character and character:FindFirstChild("HumanoidRootPart")
					local handle = select(2, ...)

					if root and handle then
						-- Sent from the body at the part, as forcehit_silent does; a shotgun's time, spread and pellet follow.
						restorenamecall(method)
						return originalnamecall(self, "ShootGun", handle, root.Position, hit.position, hit.part, SHOOT_NORMAL, select(7, ...))
					end
				end

				if clobbered then
					restorenamecall(method)
				end

				return originalnamecall(self, ...)
			end))
		end

		-- forcehit dh: Force Fire shoots the target by itself, once per cooldown of the gun in the hand.
		-- A shotgun keeps its own script (the pellets need its numbers); the hook above aims them.
		local lastforcefire = 0

		connect(runservice.Heartbeat, function()
			local silent = config["silent aimbot"]
			if not (silent["enabled"] and silent["force fire"]) or masterActive() or Session.isTyping() or selfknocked() then
				return
			end

			local hit = getsilenthit()
			local character = localplayer.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			local tool = character and character:FindFirstChildOfClass("Tool")
			local handle = tool and tool:FindFirstChild("Handle")
			local ammo = tool and tool:FindFirstChild("Ammo")
			local remote = replicatedstorage:FindFirstChild("MainEvent")

			if not (hit and root and handle and ammo and remote) or tool.Name == "[Knife]" or (tonumber(ammo.Value) or 0) <= 0 then
				return
			end

			local cooldown = tool:FindFirstChild("ShootingCooldown")
			local now = os.clock()
			if now - lastforcefire < math.max(cooldown and tonumber(cooldown.Value) or 0, 0.05) then
				return
			end
			lastforcefire = now

			if getequippedshotgun() then
				pcall(function()
					tool:Activate()
				end)
			else
				remote:FireServer("ShootGun", handle, root.Position, hit.position, hit.part, SHOOT_NORMAL)
			end
		end)

		---------- Shotgun spread ----------
		-- The game keeps every shotgun's pellet spread in one table, { Scale = { ["[Name]"] = number }, roll = function }.
		-- Scaling an entry there changes the spread at the source. The math.random hook below is only used for a
		-- shotgun that has no entry in it. Spread Amount is the share of the spread that is kept, in percent.
		local spreadhooked = false
		local originalrandom
		local spreadtable
		local spreadoriginal = {}
		local spreadlooked = -math.huge
		local spreadtries = 0 -- heap searches that found nothing
		local spreadholding = false

		---Finds the game's spread table. A search walks the whole heap, so it repeats every few seconds only for a few tries; pulling out a
		---shotgun, or switching the option on again, earns a few more.
		local function findspreadtable()
			if spreadtable or type(filtergc) ~= "function" then
				return spreadtable ~= nil
			end

			local holding = getequippedshotgun() ~= nil
			if holding and not spreadholding then
				spreadtries = math.min(spreadtries, 3)
			end
			spreadholding = holding

			if os.clock() - spreadlooked < 5 or spreadtries >= 6 then
				return false
			end
			spreadlooked = os.clock()
			spreadtries += 1

			local ok, found = pcall(filtergc, "table", { Keys = { "Ahead", "Scale", "roll" } }, false)
			if not ok or type(found) ~= "table" then
				return false
			end

			for _, candidate in ipairs(found) do
				local scale = rawget(candidate, "Scale")
				if type(scale) == "table" and type(rawget(candidate, "roll")) == "function" then
					spreadtable = candidate
					for key, value in pairs(scale) do
						if type(value) == "number" then
							spreadoriginal[key] = value
						end
					end
					break
				end
			end

			return spreadtable ~= nil
		end

		---Lets the heap search start over (the option was switched on again).
		function Semi.rescanSpread()
			spreadtries = 0
			spreadlooked = -math.huge
		end

		---Whether the game's own table scales this shotgun, so the random hook leaves it alone.
		local function spreadhandled(name)
			return spreadtable ~= nil and spreadoriginal["[" .. name .. "]"] ~= nil
		end

		---Whether the spread settings reach a shotgun: all of them, or only the ones on the list.
		local function spreadapplies(name)
			local spreadmods = config["spread modifications"]
			local specific = spreadmods["specific weapons"]

			if not specific["enabled"] then
				return true
			end

			for _, listed in ipairs(specific["weapons"]) do
				if listed == "[" .. name .. "]" or listed == name then
					return true
				end
			end

			return false
		end

		local function spreadmultiplier()
			return math.clamp((tonumber(config["spread modifications"]["amount"]) or 100) / 100, 0, 1)
		end

		---Puts each shotgun's entry at its multiplier while the modification is on, and at the game's value otherwise.
		local function applyspread()
			if not findspreadtable() then
				return
			end

			local scale = rawget(spreadtable, "Scale")
			if type(scale) ~= "table" then
				return
			end

			local on = Semi.Alive and config["spread modifications"]["enabled"] and not masterActive()

			for name in pairs(SHOTGUN_NAMES) do
				local key = "[" .. name .. "]"
				local original = spreadoriginal[key]

				if original then
					local wanted = on and spreadapplies(name) and original * spreadmultiplier() or original
					if scale[key] ~= wanted then
						scale[key] = wanted
					end
				end
			end
		end

		local function restorespread()
			local scale = spreadtable and rawget(spreadtable, "Scale")
			if type(scale) ~= "table" then
				return
			end

			for name in pairs(SHOTGUN_NAMES) do
				local key = "[" .. name .. "]"
				if spreadoriginal[key] ~= nil then
					scale[key] = spreadoriginal[key]
				end
			end
		end

		function Semi.installSpreadHook()
			if spreadhooked or not Semi.Alive then
				return
			end
			spreadhooked = true

			-- The table is kept at the configured values and handed back when the module stops.
			table.insert(Semi.Cleanups, restorespread)
			task.spawn(function()
				while Semi.Alive do
					pcall(applyspread)
					task.wait(0.1)
				end
			end)

			-- Only a shotgun the table does not scale still needs the random hook.
			local needshook = not findspreadtable()
			for name in pairs(SHOTGUN_NAMES) do
				if not spreadhandled(name) then
					needshook = true
				end
			end
			if not needshook then
				return
			end

			originalrandom = hookfunction(math.random, newcclosure(function(...)
				local spreadmods = config["spread modifications"]
				if not Semi.Alive or not spreadmods["enabled"] or checkcaller() or masterActive() then
					return originalrandom(...)
				end

				local shotgun = getequippedshotgun()
				if not shotgun or spreadhandled(shotgun) or not spreadapplies(shotgun) then
					return originalrandom(...)
				end

				-- Only the calls the shotgun script makes for its pellet spread are touched.
				local count = select("#", ...)
				local a, b = ...
				local isspreadcall = false

				if count == 0 then
					isspreadcall = true
				elseif count == 2 and type(a) == "number" and type(b) == "number" then
					isspreadcall = (a == -0.1 and b == 0.05) or (a >= -0.15 and a <= -0.05 and b >= 0.03 and b <= 0.07)
				elseif count == 1 and type(a) == "number" then
					isspreadcall = a == -0.1 or a == -0.05 or (a >= -0.15 and a <= -0.03)
				end

				if not isspreadcall then
					return originalrandom(...)
				end

				return originalrandom(...) * spreadmultiplier()
			end))
		end

		---------- Name ESP (Glory v4) ----------
		local esplabels = {}

		local function removeesp(player)
			local esp = esplabels[player.UserId]
			if esp then
				pcall(function()
					esp.nametag:Remove()
				end)
				esplabels[player.UserId] = nil
			end
		end

		local function addesp(player)
			if player == localplayer or esplabels[player.UserId] then
				return
			end

			local nametag = Drawing.new("Text")
			nametag.Size = 14
			nametag.Center = true
			nametag.Outline = true
			nametag.OutlineColor = Color3.fromRGB(0, 0, 0)
			nametag.Color = config["esp"]["color"]
			nametag.Font = 2
			nametag.Visible = false
			nametag.ZIndex = 1000

			esplabels[player.UserId] = { player = player, nametag = nametag }
		end

		local function refreshesp()
			local cfg = config["esp"]

			if not cfg["enabled"] then
				for userid, esp in pairs(esplabels) do
					esp.nametag.Visible = false
				end
				return
			end

			for _, player in ipairs(players:GetPlayers()) do
				if player ~= localplayer and not esplabels[player.UserId] then
					addesp(player)
				end
			end

			for userid, esp in pairs(esplabels) do
				local player = esp.player
				local char = player and player.Parent and player.Character
				local head = char and char:FindFirstChild("Head")
				local hrp = char and char:FindFirstChild("HumanoidRootPart")
				local hum = char and char:FindFirstChildOfClass("Humanoid")

				if not (head and hrp and hum and hum.Health > 0) then
					esp.nametag.Visible = false
					if not (player and player.Parent) then
						removeesp({ UserId = userid })
					end
				else
					local worldpos = cfg["name above"] and head.Position + Vector3.new(0, 1.5, 0) or hrp.Position - Vector3.new(0, 2.8, 0)
					local esppos, onscreen = camera:WorldToViewportPoint(worldpos)

					if onscreen and esppos.Z > 0 then
						esp.nametag.Position = Vector2.new(esppos.X, esppos.Y)
						esp.nametag.Text = cfg["use display name"] and player.DisplayName or player.Name
						esp.nametag.Color = (currenttarget and currenttarget.Parent == char) and cfg["target color"] or cfg["color"]
						esp.nametag.Visible = true
					else
						esp.nametag.Visible = false
					end
				end
			end
		end

		---------- Headless ----------
		local function applyheadless(char)
			if not config["headless"]["enabled"] or not char then
				return
			end

			local head = char:FindFirstChild("Head")
			if head then
				head.Transparency = 1
				head.CanCollide = false

				local face = head:FindFirstChild("face")
				if face then
					face.Transparency = 1
				end
			end

			if config["headless"]["remove face accessories"] then
				for _, accessory in ipairs(char:GetChildren()) do
					if accessory:IsA("Accessory") and accessory.AccessoryType == Enum.AccessoryType.Face then
						local handle = accessory:FindFirstChild("Handle")
						if handle then
							handle.Transparency = 1
							handle.CanCollide = false
						end
					end
				end
			end
		end

		---------- Hitbox expander ----------
		local function expandhitboxes()
			local cfg = config["hitbox expander"]

			for _, player in ipairs(players:GetPlayers()) do
				local hrp = player ~= localplayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart")

				if hrp then
					if cfg["enabled"] then
						if not expanded[hrp] then
							expanded[hrp] = { size = hrp.Size, transparency = hrp.Transparency }
						end

						local size = Vector3.new(cfg["size"], cfg["size"], cfg["size"])
						if hrp.Size ~= size then
							hrp.Size = size
						end

						hrp.Transparency = cfg["visualize"] and 0.7 or 1
						hrp.CanCollide = false
					elseif expanded[hrp] then
						hrp.Size = expanded[hrp].size
						hrp.Transparency = expanded[hrp].transparency
						expanded[hrp] = nil
					end
				end
			end
		end

		---------- Keybinds ----------
		connect(userinputservice.InputBegan, function(input, gameprocessed)
			if gameprocessed or masterActive() or capturingEntry or (NeverLose.KeyCaptures or 0) > 0 then
				return
			end

			local binds = config["binds"]

			if input.KeyCode == Enum.KeyCode.Space and config["spiderman"]["enabled"] then
				local char = localplayer.Character
				local hum = char and char:FindFirstChild("Humanoid")
				local hrp = char and char:FindFirstChild("HumanoidRootPart")

				if hum and hrp and hum:GetState() == Enum.HumanoidStateType.Freefall and touchingwall() and not haswalljumped then
					haswalljumped = true
					local power = getspidermanjumppower()

					task.spawn(function()
						local elapsed = 0
						hum:ChangeState(Enum.HumanoidStateType.Jumping)

						while elapsed < 0.1 do
							elapsed += task.wait()

							if hrp and hrp.Parent then
								hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, power, hrp.AssemblyLinearVelocity.Z)
							end
						end
					end)
				end
			end

			if inputMatchesKey(input, binds["silent aim"]) and not latched.silent then
				latched.silent = true

				if config["targeting"]["mode"] == "Select" then
					local silent = config["silent aimbot"]

					if silent["mode"] == "Toggle" then
						silentaimactive = not silentaimactive

						if not silentaimactive then
							if not camlockactive then
								clearcurrenttarget()
							end
						else
							local target = findtarget(silent["fov"], silent["distance check"], false)

							if target then
								currenttarget = withhitpart(target, silent["hitpart"])
								lastvisibletarget = currenttarget
							end
						end
					elseif silent["mode"] == "Hold" then
						local target = findtarget(silent["fov"], silent["distance check"], false)

						if target then
							currenttarget = withhitpart(target, silent["hitpart"])
							lastvisibletarget = currenttarget
							silentaimactive = true
						end
					end
				end
			end

			if inputMatchesKey(input, binds["cam lock"]) and not latched.cam then
				latched.cam = true

				local cam = config["camera aimbot"]

				if cam["mode"] == "Toggle" and camlockactive then
					camlockactive = false

					if not silentaimactive and config["targeting"]["mode"] ~= "Automatic" then
						clearcurrenttarget()
					end
				else
					local target = findtarget(cam["fov"], cam["distance check"], true)

					if target then
						currenttarget = withhitpart(target, cam["hitpart"])
						lastvisibletarget = currenttarget
						camlockactive = true
						camlockhold = cam["mode"] == "Hold"
					end
				end
			end

			if inputMatchesKey(input, binds["triggerbot"]) and not latched.trigger then
				latched.trigger = true

				local mode = config["trigger bot"]["mode"]
				if mode == "Toggle" then
					triggerbotactive = not triggerbotactive
				elseif mode == "Hold" then
					triggerhold = true
				end
			end

			if inputMatchesKey(input, binds["super jump"]) and not latched.superjump then
				latched.superjump = true

				if config["super jump"]["enabled"] then
					superjumpenabled = not superjumpenabled

					if not superjumpenabled and originaljumppower then
						local hum = localplayer.Character and localplayer.Character:FindFirstChildOfClass("Humanoid")
						if hum then
							hum.JumpPower = originaljumppower
						end
					end
				end
			end

			if inputMatchesKey(input, binds["esp"]) and not latched.esp then
				latched.esp = true

				local toggle = Semi.Toggles["esp enabled"]
				if toggle then
					toggle:SetValue(not config["esp"]["enabled"])
				else
					config["esp"]["enabled"] = not config["esp"]["enabled"]
				end
			end

			if inputMatchesKey(input, binds["speed"]) and not latched.speed then
				latched.speed = true

				if config["speed modifications"]["enabled"] then
					speedactive = not speedactive

					if speedactive then
						applyspeed()
					else
						resetspeed()
					end
				end
			end

			-- a click on the open menu is not a shot
			local menuOpen = type(sharedEnv.neverlose_menu_open) == "function" and sharedEnv.neverlose_menu_open()

			if input.UserInputType == Enum.UserInputType.MouseButton1 and config["rapid fire"]["enabled"] and getrapidgun() and not menuOpen then
				isfiring = true
			end
		end)

		-- Releases are always handled, so a Hold bind can never get stuck.
		connect(userinputservice.InputEnded, function(input)
			local binds = config["binds"]

			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				isfiring = false
			end

			if inputMatchesKey(input, binds["silent aim"]) then
				latched.silent = false

				if config["silent aimbot"]["mode"] == "Hold" and config["targeting"]["mode"] == "Select" then
					silentaimactive = false

					if not camlockactive then
						clearcurrenttarget()
					end
				end
			end

			if inputMatchesKey(input, binds["cam lock"]) then
				latched.cam = false

				if config["camera aimbot"]["mode"] == "Hold" and camlockhold then
					camlockhold = false
					camlockactive = false

					if not silentaimactive and config["targeting"]["mode"] ~= "Automatic" then
						clearcurrenttarget()
					end
				end
			end

			if inputMatchesKey(input, binds["triggerbot"]) then
				latched.trigger = false

				if config["trigger bot"]["mode"] == "Hold" then
					triggerhold = false
				end
			end

			if inputMatchesKey(input, binds["super jump"]) then
				latched.superjump = false
			end
			if inputMatchesKey(input, binds["esp"]) then
				latched.esp = false
			end
			if inputMatchesKey(input, binds["speed"]) then
				latched.speed = false
			end
		end)

		-- A release that happens while the window is not focused never arrives, which would leave the holds and the latches stuck on.
		connect(userinputservice.WindowFocusReleased, function()
			triggerhold = false
			isfiring = false

			if camlockhold then
				camlockhold = false
				camlockactive = false
			end

			if config["silent aimbot"]["mode"] == "Hold" then
				silentaimactive = false
			end

			for key in pairs(latched) do
				latched[key] = false
			end
		end)

		---------- Per frame ----------
		connect(runservice.RenderStepped, function()
			local silent = config["silent aimbot"]

			if config["targeting"]["mode"] == "Automatic" and silent["enabled"] and not masterActive() then
				local now = os.clock()

				if now - lasttargetscan >= scanrate then
					lasttargetscan = now

					local target = findtarget(silent["fov"], silent["distance check"], false)
					currenttarget = target and withhitpart(target, silent["hitpart"]) or nil
				end

				silentaimactive = currenttarget ~= nil
			end

			if selfknocked() then
				currenttarget = nil
				silentaimactive = false
				camlockactive = false
				lastvisibletarget = nil
				targetline.Visible = false
			end

			if not masterActive() then
				triggerbot()
				rapidfire()
			end

			if superjumpenabled and config["super jump"]["enabled"] then
				local hum = localplayer.Character and localplayer.Character:FindFirstChildOfClass("Humanoid")

				if hum then
					originaljumppower = originaljumppower or hum.JumpPower

					if hum.JumpPower ~= config["super jump"]["jump power"] then
						hum.JumpPower = config["super jump"]["jump power"]
					end
				end
			end

			expandhitboxes()

			updatefovbox(fovparts.silent, fov2dboxes.silent, silent["fov"], silentaimactive and silent["enabled"])
			updatefovbox(fovparts.camlock, fov2dboxes.camlock, config["camera aimbot"]["fov"], camlockactive and config["camera aimbot"]["enabled"])
			updatefovbox(fovparts.trigger, fov2dboxes.trigger, config["trigger bot"]["fov"], config["trigger bot"]["enabled"] and triggerenabled())

			updatetargetline()
			refreshesp()

			if config["camera aimbot"]["enabled"] and not masterActive() then
				applycamlock()
			end
		end)

		---------- Players and characters ----------
		connect(players.PlayerRemoving, function(player)
			removeesp(player)
		end)

		connect(localplayer.CharacterAdded, function(char)
			speedactive = false
			oncharrapidfire(char)

			task.defer(function()
				applyheadless(char)
			end)
		end)

		if localplayer.Character then
			oncharrapidfire(localplayer.Character)
			applyheadless(localplayer.Character)
		end

		---------- Keybind list ----------
		---Every Semi Rage key that is bound, with its mode and whether it is on right now. The keybind
		---list draws these rows; a key with nothing set ("None") is left out.
		function Semi.keyStates()
			local binds = config["binds"]
			local live = not masterActive()
			local items = {}

			local function add(name, key, mode, on)
				if key and key ~= "None" then
					table.insert(items, { Name = name, Key = key, Mode = mode, On = live and on == true })
				end
			end

			add("Silent Aimbot", binds["silent aim"], config["silent aimbot"]["mode"], config["silent aimbot"]["enabled"] and silentaimactive)
			add("Camera Aimbot", binds["cam lock"], config["camera aimbot"]["mode"], config["camera aimbot"]["enabled"] and camlockactive)
			add("Trigger Bot", binds["triggerbot"], config["trigger bot"]["mode"], config["trigger bot"]["enabled"] and triggerenabled())
			add("Super Jump", binds["super jump"], "Toggle", config["super jump"]["enabled"] and superjumpenabled)
			add("Speed", binds["speed"], "Toggle", config["speed modifications"]["enabled"] and speedactive)
			add("Name ESP", binds["esp"], "Toggle", config["esp"]["enabled"])

			return items
		end

		-- The list is redrawn only when a key, its mode or its state changes.
		task.spawn(function()
			local last

			while Semi.Alive do
				local parts = {}
				for _, item in ipairs(Semi.keyStates()) do
					table.insert(parts, ("%s:%s:%s:%s"):format(item.Name, item.Key, item.Mode, tostring(item.On)))
				end

				local signature = table.concat(parts, "|")
				if signature ~= last then
					last = signature
					refreshKeybindList()
				end

				task.wait(0.1)
			end
		end)

		---------- Speed ----------
		task.spawn(function()
			while Semi.Alive do
				task.wait(0.48)
				if speedactive then
					applyspeed()
				end
			end
		end)

		-- Keeps the wall jump listener alive if the character was built without one.
		task.spawn(function()
			while Semi.Alive do
				task.wait(1)

				local char = localplayer.Character
				if char and char:FindFirstChildOfClass("Humanoid") and not walljumpconnection then
					setupwalljumpreset()
				end
			end
		end)

		-- A config that switched these on before Semi started could not install their hooks then: they go in now (each one only goes in once).
		if config["silent aimbot"]["enabled"] then
			Semi.installSilentHook()
		end

		if config["spread modifications"]["enabled"] then
			Semi.installSpreadHook()
		end

		-- Everything this start created goes away with Semi.stop.
		table.insert(Semi.Cleanups, function()
			resetspeed()

			for _, esp in pairs(esplabels) do
				pcall(function()
					esp.nametag:Remove()
				end)
			end
			table.clear(esplabels)

			for _, lines in pairs(fov2dboxes) do
				for _, line in ipairs(lines) do
					pcall(function()
						line:Remove()
					end)
				end
			end
			pcall(function()
				targetline:Remove()
			end)

			for _, part in pairs(fovparts) do
				pcall(function()
					part:Destroy()
				end)
			end

			for hrp, original in pairs(expanded) do
				if hrp.Parent then
					hrp.Size = original.size
					hrp.Transparency = original.transparency
				end
			end

			for tool in pairs(knifedata) do
				pcall(cleanknife, tool)
			end
		end)
	end

	---Stops the loops and listeners and puts back what the module changed. The two hooks (silent
	---aim's ShootGun catch and the shotgun spread) stay installed but pass everything through from here on.
	function Semi.stop()
		if not Semi.Alive then
			return
		end
		Semi.Alive = false

		for _, connection in ipairs(Semi.Connections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(Semi.Connections)

		for _, cleanup in ipairs(Semi.Cleanups) do
			local cleanupOk, cleanupError = pcall(cleanup)
			if not cleanupOk then
				warn("[Visions hook] A shotgun/Semi stop step failed: " .. tostring(cleanupError))
			end
		end
		table.clear(Semi.Cleanups)
	end

	table.insert(Session.Cleanups, Semi.stop)

	-- The Anti Report's safety shutdown runs these once the engine's options are off. Spawned, so a callback that yields can't hold up its kick.
	do
		local engineTeardowns = sharedEnv.neverlose_teardowns

		if type(engineTeardowns) == "table" then
			table.insert(engineTeardowns, function()
				if sharedEnv.neverlose_safety_shutdown == true then
					task.spawn(Session.afterSafetyShutdown)
				end
			end)
		end
	end

	---Builds the Semi Rage tab. Every control writes straight into Semi.Config; toggles are
	---registered like the rest of the menu, so they can be bound to keys and the master switch
	---can turn them off and back on.
	function Semi.buildTab(tab)
		local config = Semi.Config

		-- The table that holds the last key of a config path, and that key.
		local function holder(path)
			local node = config
			for index = 1, #path - 1 do
				node = node[path[index]]
			end
			return node, path[#path]
		end

		-- Library flags have to be unique, so each control gets one made from its config path.
		local function flagFor(path)
			local flag = "sr_" .. table.concat(path, "_"):lower():gsub("[^%w]+", "_")
			return flag
		end

		local function toggle(name, path, onChange)
			return { kind = "toggle", name = name, path = path, onChange = onChange }
		end

		local function slider(name, path, min, max, rounding, suffix)
			return { kind = "slider", name = name, path = path, min = min, max = max, rounding = rounding or 0, suffix = suffix or "" }
		end

		local function dropdown(name, path, values)
			return { kind = "dropdown", name = name, path = path, values = values }
		end

		local function keybind(name, path)
			return { kind = "keybind", name = name, path = path }
		end

		local function color(name, path)
			return { kind = "color", name = name, path = path }
		end

		local function text(name, path, placeholder)
			return { kind = "text", name = name, path = path, placeholder = placeholder }
		end

		-- A row that only holds a gear menu.
		local function gear(name, rows)
			return { kind = "gear", name = name, options = rows }
		end

		local addRow

		addRow = function(container, spec)
			local label = container:AddLabel(spec.name)
			local kind = spec.kind

			if kind ~= "gear" then
				local node, key = holder(spec.path)
				local flag = flagFor(spec.path)

				if kind == "toggle" then
					local control = addBindableToggle(label, spec.name, {
						Default = node[key] == true,
						Flag = flag,
						Callback = function(value)
							node[key] = value == true

							if spec.onChange then
								spec.onChange(value == true)
							end
						end,
					})
					Semi.Toggles[table.concat(spec.path, " ")] = control
				elseif kind == "slider" then
					label:AddSlider({
						Min = spec.min,
						Max = spec.max,
						Rounding = spec.rounding,
						Type = spec.suffix,
						Default = node[key],
						Flag = flag,
						Callback = function(value)
							node[key] = value
						end,
					})
				elseif kind == "dropdown" then
					label:AddDropdown({
						Default = node[key],
						Values = spec.values,
						Flag = flag,
						Callback = function(value)
							node[key] = value
						end,
					})
				elseif kind == "keybind" then
					label:AddKeybind({
						Default = node[key],
						Flag = flag,
						Callback = function(value)
							if value ~= nil then
								node[key] = keyName(value)
							end
						end,
					})
				elseif kind == "color" then
					label:AddColorPicker({
						Default = node[key],
						Flag = flag,
						Callback = function(value)
							node[key] = value
						end,
					})
				elseif kind == "text" then
					label:AddTextInput({
						Default = tostring(node[key] or ""),
						Placeholder = spec.placeholder or "",
						Flag = flag,
						Size = 110,
						Callback = function(value)
							node[key] = value
						end,
					})
				end
			end

			if spec.options then
				local window = label:AddOption()
				for _, child in ipairs(spec.options) do
					local ok, err = pcall(addRow, window, child)
					if not ok then
						warn(("[SemiRage] Could not add '%s': %s"):format(tostring(child.name), tostring(err)))
					end
				end
			end
		end

		local function addSection(name, position, rows)
			local section = tab:AddSection({ Name = name, Position = position })

			for _, spec in ipairs(rows) do
				local ok, err = pcall(addRow, section, spec)
				if not ok then
					warn(("[SemiRage] Could not add '%s': %s"):format(tostring(spec.name), tostring(err)))
				end
			end
		end

		local hitParts = { "Closest Part", "Head", "UpperTorso", "LowerTorso", "HumanoidRootPart" }
		local fovModes = { "3D", "2D" }

		-- A section's FOV box: whether it is on, whether it is drawn, 3D or 2D, and its three sizes in studs.
		local function fovRows(section, label)
			return {
				toggle(label .. " FOV", { section, "fov", "enabled" }),
				toggle(label .. " Show FOV", { section, "fov", "visible" }),
				dropdown(label .. " FOV Mode", { section, "fov", "mode" }, fovModes),
				color(label .. " FOV Color", { section, "fov", "active color" }),
				slider(label .. " FOV X", { section, "fov", "size", "x" }, 0, 50, 1, " studs"),
				slider(label .. " FOV Y", { section, "fov", "size", "y" }, 0, 50, 1, " studs"),
				slider(label .. " FOV Z", { section, "fov", "size", "z" }, 0, 50, 1, " studs"),
			}
		end

		local function distanceRows(section, label)
			return {
				toggle(label .. " Distance Check", { section, "distance check", "enabled" }),
				slider(label .. " Max Distance", { section, "distance check", "max distance" }, 10, 2000, 0, " studs"),
			}
		end

		local function predictionRows(section, label)
			return {
				toggle(label .. " Prediction", { section, "use prediction" }),
				slider(label .. " Prediction X", { section, "prediction", "x" }, 0, 1, 3),
				slider(label .. " Prediction Y", { section, "prediction", "y" }, 0, 1, 3),
				slider(label .. " Prediction Z", { section, "prediction", "z" }, 0, 1, 3),
			}
		end

		local function join(...)
			local out = {}
			for index = 1, select("#", ...) do
				for _, row in ipairs((select(index, ...))) do
					table.insert(out, row)
				end
			end
			return out
		end

		addSection("TARGETING", "left", {
			dropdown("Target Mode", { "targeting", "mode" }, { "Select", "Automatic" }),
			toggle("Mod Detector", { "global", "mod detector" }, function(value)
				if value and Semi.recheckMods then
					Semi.recheckMods()
				end
			end),
			toggle("Visible Check", { "settings", "visible check" }),
			toggle("Knock Check", { "settings", "knock check" }),
			toggle("Self Knock Check", { "settings", "self knock check" }),
			toggle("Knife Check", { "settings", "knife check" }),
			toggle("Forcefield Check", { "settings", "forcefield check" }),
		})

		addSection("SILENT AIMBOT", "left", join({
			toggle("Silent Aimbot", { "silent aimbot", "enabled" }, function(value)
				if value and Semi.installSilentHook then
					Semi.installSilentHook()
				end
			end),
			dropdown("Silent Mode", { "silent aimbot", "mode" }, { "Toggle", "Hold" }),
			keybind("Silent Key", { "binds", "silent aim" }),
			toggle("Force Hit", { "silent aimbot", "force hit" }),
			toggle("Force Fire", { "silent aimbot", "force fire" }),
			dropdown("Silent Hit Part", { "silent aimbot", "hitpart" }, hitParts),
		}, predictionRows("silent aimbot", "Silent"), fovRows("silent aimbot", "Silent"), distanceRows("silent aimbot", "Silent")))

		addSection("CAMERA AIMBOT", "left", join({
			toggle("Camera Aimbot", { "camera aimbot", "enabled" }),
			dropdown("Camera Mode", { "camera aimbot", "mode" }, { "Toggle", "Hold" }),
			keybind("Camera Key", { "binds", "cam lock" }),
			dropdown("Camera Hit Part", { "camera aimbot", "hitpart" }, hitParts),
			slider("Smoothing X", { "camera aimbot", "smoothing", "x" }, 1, 100, 0),
			slider("Smoothing Y", { "camera aimbot", "smoothing", "y" }, 1, 100, 0),
			slider("Smoothing Z", { "camera aimbot", "smoothing", "z" }, 1, 100, 0),
		}, predictionRows("camera aimbot", "Camera"), fovRows("camera aimbot", "Camera"), distanceRows("camera aimbot", "Camera")))

		addSection("TRIGGER BOT", "right", join({
			toggle("Trigger Bot", { "trigger bot", "enabled" }),
			dropdown("Trigger Mode", { "trigger bot", "mode" }, { "Always", "Toggle", "Hold" }),
			keybind("Trigger Key", { "binds", "triggerbot" }),
			slider("Trigger Delay", { "trigger bot", "delay" }, 0, 1, 2, "s"),
			toggle("Require Target", { "trigger bot", "require target" }),
			toggle("Specific Weapons", { "trigger bot", "specific weapons", "enabled" }),
		}, fovRows("trigger bot", "Trigger"), distanceRows("trigger bot", "Trigger")))

		addSection("TARGET LINE", "right", {
			toggle("Target Line", { "target line", "enabled" }),
			slider("Line Thickness", { "target line", "thickness" }, 0.5, 6, 1),
			slider("Line Transparency", { "target line", "transparency" }, 0, 1, 2),
			color("Vulnerable Color", { "target line", "vulnerable" }),
			color("Invulnerable Color", { "target line", "invulnerable" }),
		})

		addSection("SHOTGUN SPREAD", "right", {
			toggle("Spread Modifications", { "spread modifications", "enabled" }, function(value)
				if value and Semi.installSpreadHook then
					-- Switching the option on lets a search that gave up look for the game's spread table again.
					if Semi.rescanSpread then
						Semi.rescanSpread()
					end
					Semi.installSpreadHook()
				end
			end),
			slider("Spread Amount", { "spread modifications", "amount" }, 0, 100, 0, "%"),
			toggle("Spread Specific Weapons", { "spread modifications", "specific weapons", "enabled" }),
		})

		addSection("RAPID FIRE", "right", {
			toggle("Rapid Fire", { "rapid fire", "enabled" }),
			slider("Rapid Fire Delay", { "rapid fire", "delay" }, 0, 1, 2, "s"),
			toggle("Rapid Fire Specific Weapons", { "rapid fire", "specific weapons", "enabled" }),
		})

		addSection("MOVEMENT", "right", {
			toggle("Speed", { "speed modifications", "enabled" }, function(value)
				if not value and Semi.resetSpeed then
					Semi.resetSpeed()
				end
			end),
			keybind("Speed Key", { "binds", "speed" }),
			slider("Speed Multiplier", { "speed modifications", "multiplier" }, 1, 100, 0, "x"),
			toggle("Super Jump", { "super jump", "enabled" }),
			keybind("Super Jump Key", { "binds", "super jump" }),
			slider("Super Jump Power", { "super jump", "jump power" }, 50, 500, 0),
			toggle("Spiderman", { "spiderman", "enabled" }),
			slider("Wall Jump Power", { "spiderman", "jumppower" }, 10, 150, 0),
			slider("Knife Wall Jump Power", { "spiderman", "knifejumppower" }, 10, 150, 0),
		})

		addSection("HITBOX", "right", {
			toggle("Hitbox Expander", { "hitbox expander", "enabled" }),
			slider("Hitbox Size", { "hitbox expander", "size" }, 2, 30, 0),
			toggle("Show Hitboxes", { "hitbox expander", "visualize" }),
		})

		addSection("ESP", "right", {
			toggle("Name ESP", { "esp", "enabled" }),
			keybind("ESP Key", { "binds", "esp" }),
			toggle("Use Display Name", { "esp", "use display name" }),
			toggle("Name Above", { "esp", "name above" }),
			color("ESP Color", { "esp", "color" }),
			color("ESP Target Color", { "esp", "target color" }),
		})

		addSection("HEADLESS", "right", {
			toggle("Headless", { "headless", "enabled" }),
			toggle("Remove Face Accessories", { "headless", "remove face accessories" }),
		})
	end
end

---------- Skins tab ------------
-- A browser for the skins the Semi Rage module can apply: a weapon list, a searchable skin list and a 3D
-- preview that can be rotated. Browsing a skin only previews it; Apply is a separate action. The browser is
-- drawn on top of the Skins tab page inside the window, so it moves with the window and is only visible
-- while that tab is open. What was applied is saved to SKINS_FILE and restored on the next run.
local SKINS_FILE = CONFIG_FOLDER .. "/skins.json"
local SKIN_DEFAULT = "Default"

local function loadSavedSkins()
	if type(readfile) ~= "function" or type(isfile) ~= "function" then
		return
	end

	pcall(function()
		if not isfile(SKINS_FILE) then
			return
		end

		local saved = HttpService:JSONDecode(readfile(SKINS_FILE))
		local skins = Session.Semi.Config["skins"]

		for toolName, skinName in pairs(saved) do
			if type(toolName) == "string" and type(skinName) == "string" then
				skins[toolName] = skinName
			end
		end
	end)
end

local function saveSkins()
	if type(writefile) ~= "function" then
		return
	end

	pcall(function()
		if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(CONFIG_FOLDER) then
			makefolder(CONFIG_FOLDER)
		end

		local data = {}
		for toolName, skinName in pairs(Session.Semi.Config["skins"]) do
			if skinName ~= "" then
				data[toolName] = skinName
			end
		end

		writefile(SKINS_FILE, HttpService:JSONEncode(data))
	end)
end

local function buildSkinsTab()
	local Semi = Session.Semi
	local Skins = Semi.Skins
	local skins = Semi.Config["skins"]
	local replicatedStorage = game:GetService("ReplicatedStorage")
	local skinModules = replicatedStorage:FindFirstChild("SkinModules")
	local skinAssets = replicatedStorage:FindFirstChild("SkinAssets")

	loadSavedSkins()

	-- Semi Rage starts before the saved skins are read, so the tool in hand was left with the default look: it gets its skin now.
	if type(Skins.applyTool) == "function" then
		local appliedOk, appliedError = pcall(function()
			local character = Players.LocalPlayer.Character
			local held = character and character:FindFirstChildOfClass("Tool")
			local saved = held and skins[held.Name]

			if saved and saved ~= "" then
				Skins.applyTool(held, character)
			end
		end)
		if not appliedOk then
			warn("[Visions hook] Applying the saved skin failed: " .. tostring(appliedError))
		end
	end

	local tab = window:AddTab({
		Icon = "paint-bucket",
		Name = "Skins",
	})

	-- The tab's page is empty, so the browser fills the tab's page.
	local content = tab.Content

	if not content then
		warn("[Visions hook] Could not find the window content area; the Skins tab stays empty.")
		return tab
	end

	local weapons = Skins.weapons()
	if #weapons == 0 then
		warn("[Visions hook] No skins were found in this game; the Skins tab stays empty.")
		return tab
	end

	local CARD_FILL = Color3.fromRGB(20, 22, 27)
	local MUTED_TEXT = Color3.fromRGB(150, 154, 168)

	local page = Instance.new("Frame")
	page.Name = "SkinBrowser"
	page.Active = true
	page.BackgroundColor3 = PANEL_COLOR
	page.BorderSizePixel = 0
	page.ClipsDescendants = true
	page.Position = UDim2.fromOffset(0, 0)
	page.Size = UDim2.new(1, 0, 1, 0)
	page.Visible = false
	page.ZIndex = 20
	page.Parent = content
	newCorner(page, 0)

	local function newCard(position, size)
		local card = Instance.new("Frame")
		card.BackgroundColor3 = CARD_FILL
		card.BackgroundTransparency = 0.5
		card.BorderSizePixel = 0
		card.Position = position
		card.Size = size
		card.ZIndex = 21
		card.Parent = page
		newCorner(card, 10)

		local stroke = Instance.new("UIStroke")
		stroke.Color = STROKE_COLOR
		stroke.Transparency = 0.65
		stroke.Parent = card

		return card
	end

	local function newTitle(parent, text)
		local title = newText(parent, text, 11, 22)
		title.Position = UDim2.fromOffset(12, 6)
		title.Size = UDim2.new(1, -24, 0, 16)
		return title
	end

	local function newList(parent, position, size)
		local list = Instance.new("ScrollingFrame")
		list.Active = true
		list.AutomaticCanvasSize = Enum.AutomaticSize.Y
		list.BackgroundTransparency = 1
		list.BorderSizePixel = 0
		list.CanvasSize = UDim2.new()
		list.Position = position
		list.ScrollBarImageColor3 = (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)
		list.ScrollBarThickness = 2
		list.Size = size
		list.ZIndex = 22
		list.Parent = parent

		local layout = Instance.new("UIListLayout")
		layout.Padding = UDim.new(0, 2)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = list

		return list
	end

	-- One selectable row; the caller fills in the label text and decides what selected means.
	local function newRow(parent, text, order)
		local button = Instance.new("TextButton")
		button.AutoButtonColor = false
		button.BackgroundColor3 = (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)
		button.BackgroundTransparency = 1
		button.BorderSizePixel = 0
		button.LayoutOrder = order
		button.Size = UDim2.new(1, -6, 0, 26)
		button.Text = ""
		button.ZIndex = 23
		button.Parent = parent
		newCorner(button, 6)

		local label = newText(button, text, 12, 24)
		label.Position = UDim2.fromOffset(10, 0)
		label.Size = UDim2.new(1, -20, 1, 0)
		label.TextTransparency = 0.25
		label.TextTruncate = Enum.TextTruncate.AtEnd

		-- Marks the row of whatever is currently applied.
		local dot = Instance.new("Frame")
		dot.AnchorPoint = Vector2.new(1, 0.5)
		dot.BackgroundColor3 = (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)
		dot.BorderSizePixel = 0
		dot.Position = UDim2.new(1, -8, 0.5, 0)
		dot.Size = UDim2.fromOffset(6, 6)
		dot.Visible = false
		dot.ZIndex = 24
		dot.Parent = button
		newCorner(dot, 3)

		return button, label, dot
	end

	local function setRowSelected(row, selected)
		row.Button.BackgroundTransparency = selected and 0.75 or 1
		row.Label.TextTransparency = selected and 0 or 0.25
	end

	-- Layout: weapon list | skin list | preview, sharing the page's width (19% / 32% / the rest, 8px gaps), so it fills whichever window it is in.
	local weaponCard = newCard(UDim2.fromOffset(8, 8), UDim2.new(0.19, -12, 1, -16))
	newTitle(weaponCard, "WEAPON")
	local weaponList = newList(weaponCard, UDim2.fromOffset(6, 28), UDim2.new(1, -12, 1, -34))

	local skinCard = newCard(UDim2.new(0.19, 4, 0, 8), UDim2.new(0.32, -8, 1, -16))
	local skinTitle = newTitle(skinCard, "SKINS")

	local searchBox = Instance.new("TextBox")
	searchBox.BackgroundColor3 = CARD_COLOR
	searchBox.BorderSizePixel = 0
	searchBox.ClearTextOnFocus = false
	searchBox.Font = Enum.Font.GothamMedium
	searchBox.PlaceholderColor3 = MUTED_TEXT
	searchBox.PlaceholderText = "search skins"
	searchBox.Position = UDim2.fromOffset(8, 28)
	searchBox.Size = UDim2.new(1, -16, 0, 26)
	searchBox.Text = ""
	searchBox.TextColor3 = Color3.fromRGB(255, 255, 255)
	searchBox.TextSize = 12
	searchBox.TextXAlignment = Enum.TextXAlignment.Left
	searchBox.ZIndex = 22
	searchBox.Parent = skinCard
	newCorner(searchBox, 6)

	local searchStroke = newStroke(searchBox)
	searchStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

	local searchPadding = Instance.new("UIPadding")
	searchPadding.PaddingLeft = UDim.new(0, 8)
	searchPadding.PaddingRight = UDim.new(0, 8)
	searchPadding.Parent = searchBox

	local skinList = newList(skinCard, UDim2.fromOffset(6, 60), UDim2.new(1, -12, 1, -66))

	local previewCard = newCard(UDim2.new(0.51, 4, 0, 8), UDim2.new(0.49, -12, 1, -16))
	newTitle(previewCard, "PREVIEW")

	local viewport = Instance.new("ViewportFrame")
	viewport.Ambient = Color3.fromRGB(150, 150, 165)
	viewport.BackgroundColor3 = PANEL_COLOR
	viewport.BackgroundTransparency = 0.3
	viewport.LightColor = Color3.fromRGB(255, 255, 255)
	viewport.LightDirection = Vector3.new(-1, -1, -1)
	viewport.Position = UDim2.fromOffset(8, 28)
	viewport.Size = UDim2.new(1, -16, 0, 270)
	viewport.ZIndex = 22
	viewport.Parent = previewCard
	newCorner(viewport, 8)

	local camera = Instance.new("Camera")
	camera.FieldOfView = 30
	camera.Parent = viewport
	viewport.CurrentCamera = camera

	-- Everything the preview can do with the mouse goes through this invisible button.
	local dragArea = Instance.new("TextButton")
	dragArea.AutoButtonColor = false
	dragArea.BackgroundTransparency = 1
	dragArea.Size = UDim2.fromScale(1, 1)
	dragArea.Text = ""
	dragArea.ZIndex = 25
	dragArea.Parent = viewport

	local hint = newText(viewport, "drag to rotate, scroll to zoom", 10, 26)
	hint.AnchorPoint = Vector2.new(0, 1)
	hint.Position = UDim2.new(0, 8, 1, -4)
	hint.Size = UDim2.new(1, -16, 0, 14)
	hint.TextColor3 = MUTED_TEXT

	local emptyLabel = newText(viewport, "", 12, 26)
	emptyLabel.AnchorPoint = Vector2.new(0.5, 0.5)
	emptyLabel.Position = UDim2.fromScale(0.5, 0.5)
	emptyLabel.Size = UDim2.new(1, -32, 0, 60)
	emptyLabel.TextColor3 = MUTED_TEXT
	emptyLabel.TextWrapped = true
	emptyLabel.TextXAlignment = Enum.TextXAlignment.Center

	local nameLabel = newText(previewCard, "", 13, 22)
	nameLabel.Position = UDim2.fromOffset(12, 304)
	nameLabel.Size = UDim2.new(1, -24, 0, 18)
	nameLabel.TextTruncate = Enum.TextTruncate.AtEnd

	local detailLabel = newText(previewCard, "", 11, 22)
	detailLabel.Position = UDim2.fromOffset(12, 326)
	detailLabel.Size = UDim2.new(1, -24, 0, 96)
	detailLabel.TextColor3 = MUTED_TEXT
	detailLabel.TextWrapped = true
	detailLabel.TextYAlignment = Enum.TextYAlignment.Top

	local noteLabel = newText(previewCard, "Effects are applied in game, but a 3D preview can't draw particles.", 10, 22)
	noteLabel.AnchorPoint = Vector2.new(0, 1)
	noteLabel.Position = UDim2.new(0, 12, 1, -42)
	noteLabel.Size = UDim2.new(1, -24, 0, 26)
	noteLabel.TextColor3 = MUTED_TEXT
	noteLabel.TextTransparency = 0.3
	noteLabel.TextWrapped = true
	noteLabel.TextYAlignment = Enum.TextYAlignment.Bottom

	local function newActionButton(text, position, width)
		local button = newButton(previewCard, text, 23)
		button.AnchorPoint = Vector2.new(0, 1)
		button.Position = position
		button.Size = UDim2.fromOffset(width, 28)
		return button
	end

	local applyButton = newActionButton("Apply", UDim2.new(0, 8, 1, -8), 112)
	local spinButton = newActionButton("Spin: on", UDim2.new(0, 126, 1, -8), 70)
	local soundButton = newActionButton("Sound", UDim2.new(0, 202, 1, -8), 68)

	-- the three buttons share the card's width too (Apply the widest)
	applyButton.Size = UDim2.new(0.42, -10, 0, 28)
	spinButton.Position = UDim2.new(0.42, 2, 1, -8)
	spinButton.Size = UDim2.new(0.29, -6, 0, 28)
	soundButton.Position = UDim2.new(0.71, 0, 1, -8)
	soundButton.Size = UDim2.new(0.29, -8, 0, 28)

	-- State of the browser. skin is what is being previewed, skins[tool] is what is applied.
	local view = { weapon = nil, skin = SKIN_DEFAULT, search = "", rows = {}, weaponRows = {}, built = {} }
	local preview = { model = nil, base = CFrame.identity, align = CFrame.identity, radius = 2, yaw = 0, pitch = 0.15, zoom = 1, spin = true, dragging = false, lastDrag = Vector3.zero, token = 0 }

	local function appliedSkin(toolName)
		local name = skins[toolName]
		return (name == nil or name == "") and SKIN_DEFAULT or name
	end

	-- The skin list of a weapon is read from the game once and kept.
	local entryCache = {}
	local function entriesFor(toolName)
		if not entryCache[toolName] then
			entryCache[toolName] = Skins.list(toolName)
		end
		return entryCache[toolName]
	end

	local function displayName(toolName)
		return (toolName:gsub("^%[", ""):gsub("%]$", ""))
	end

	-- Looks up the extra things the module applies for a skin: sounds and particles.
	local function skinEffects(toolName, skinName)
		local effects = {}
		local soundId

		if skinName == SKIN_DEFAULT then
			return effects, soundId
		end

		if toolName == "[Knife]" then
			local config = Skins.knife[skinName]
			if config then
				if config.soundid and config.soundid ~= "" then
					table.insert(effects, "equip sound")
					soundId = config.soundid
				end
				if config.animationid and config.animationid ~= "" then
					table.insert(effects, "equip animation")
				end
				if config.particle then
					table.insert(effects, "particles")
				end
			end
			return effects, soundId
		end

		local gunSounds = skinAssets and skinAssets:FindFirstChild("GunShootSounds")
		local toolSounds = gunSounds and gunSounds:FindFirstChild(toolName)
		local sound = toolSounds and toolSounds:FindFirstChild(skinName)
		if sound and sound.Value ~= "" then
			table.insert(effects, "shoot sound")
			soundId = sound.Value
		end

		local particles = skinAssets and skinAssets:FindFirstChild("GunHandleParticle")
		local source = particles and particles:FindFirstChild(skinName)
		if source and source:FindFirstChild("ParticleEmitter") then
			table.insert(effects, "handle particles")
		end

		return effects, soundId
	end

	-- Builds the model shown in the preview, or nil and the reason it can't be shown.
	local function buildPreviewModel(toolName, skinName)
		if not skinModules then
			return nil, "skin data is not available"
		end

		local source

		if toolName == "[Knife]" then
			local knives = skinModules:FindFirstChild("Knives")
			source = knives and knives:FindFirstChild(skinName == SKIN_DEFAULT and "Default" or skinName)
		elseif toolName == "[Bat]" then
			if skinName == SKIN_DEFAULT then
				-- The bat's own look is not stored in the skin data, so it is taken from the bat you hold.
				local character = Players.LocalPlayer.Character
				local backpack = Players.LocalPlayer:FindFirstChildOfClass("Backpack")
				local bat = (character and character:FindFirstChild(toolName)) or (backpack and backpack:FindFirstChild(toolName))
				if bat then
					for _, item in ipairs(bat:GetDescendants()) do
						if item:IsA("MeshPart") and item.Name ~= "CurrentSkin" then
							source = item
							break
						end
					end
				end
				if not source then
					return nil, "The default bat can only be previewed while you own one."
				end
			else
				local bats = skinModules:FindFirstChild("Bats")
				source = bats and bats:FindFirstChild(skinName)
			end
		else
			local models = skinModules:FindFirstChild("GunModels")
			local base = models and models:FindFirstChild(toolName)
			if skinName == SKIN_DEFAULT then
				source = base
			else
				local info = nil
				for _, entry in ipairs(entriesFor(toolName)) do
					if entry.name == skinName then
						info = entry.info
						break
					end
				end

				local texture = type(info) == "table" and info.TextureID or nil
				if typeof(texture) == "Instance" then
					source = texture
				elseif type(texture) == "string" and base then
					source = base:Clone()
					local mesh = source:IsA("MeshPart") and source or source:FindFirstChildWhichIsA("MeshPart", true)
					if mesh then
						mesh.TextureID = texture
					end
				end
			end
		end

		if not source then
			return nil, "No model was found for this skin."
		end

		local copy = source.Parent and source:Clone() or source
		if toolName == "[Bat]" and skinName == SKIN_DEFAULT and copy:IsA("BasePart") then
			-- The original mesh is hidden while a skin is applied.
			copy.Transparency = 0
		end
		if toolName == "[Knife]" and skinName ~= SKIN_DEFAULT and copy:IsA("MeshPart") then
			local config = Skins.knife[skinName]
			if config and config.textureid then
				copy.TextureID = config.textureid
			end
		end

		local model = copy
		if not copy:IsA("Model") then
			model = Instance.new("Model")
			copy.Parent = model
			if copy:IsA("BasePart") then
				model.PrimaryPart = copy
			end
		end

		-- Only the looks are shown: nothing that could run, make noise or move.
		for _, item in ipairs(model:GetDescendants()) do
			if item:IsA("BaseScript") or item:IsA("Sound") or item:IsA("ParticleEmitter") or item:IsA("Light") then
				item:Destroy()
			elseif item:IsA("BasePart") then
				item.Anchored = true
				item.CanCollide = false
				item.CanQuery = false
				item.CanTouch = false
			end
		end

		if not model:FindFirstChildWhichIsA("BasePart", true) then
			model:Destroy()
			return nil, "This skin has no model to show."
		end

		return model
	end

	-- Turns the model so its longest side runs left to right and its second longest side points up, then
	-- frames it so it fits however it is rotated.
	local function placePreview(model)
		local boxCFrame, boxSize = model:GetBoundingBox()
		local axes = {
			{ size = boxSize.X, vector = boxCFrame.RightVector },
			{ size = boxSize.Y, vector = boxCFrame.UpVector },
			{ size = boxSize.Z, vector = boxCFrame.LookVector },
		}
		table.sort(axes, function(a, b)
			return a.size > b.size
		end)

		local x, y = axes[1].vector, axes[2].vector
		preview.align = CFrame.fromMatrix(Vector3.zero, x, y, x:Cross(y)):Inverse()
		preview.base = CFrame.new(-boxCFrame.Position) * model:GetPivot()
		preview.radius = math.max(boxSize.Magnitude / 2, 0.5)
		preview.model = model
	end

	local function updateCamera()
		local distance = preview.radius / math.sin(math.rad(camera.FieldOfView / 2)) * 1.1 / preview.zoom
		camera.CFrame = CFrame.lookAt(Vector3.new(0, preview.radius * 0.12, distance), Vector3.zero)
	end

	local function clearPreview()
		if preview.model then
			preview.model:Destroy()
			preview.model = nil
		end
	end

	local function showPreview()
		clearPreview()
		preview.token += 1

		local model, reason = buildPreviewModel(view.weapon, view.skin)
		emptyLabel.Text = model and "" or (reason or "")

		if model then
			model.Parent = viewport
			placePreview(model)
			preview.yaw = 0
			preview.pitch = 0.15
			preview.zoom = 1
			updateCamera()
			model:PivotTo(CFrame.Angles(preview.pitch, preview.yaw, 0) * preview.align * preview.base)
		end
	end

	local soundPlayer = Instance.new("Sound")
	soundPlayer.Volume = 0.5
	soundPlayer.Parent = page
	local previewSoundId

	local function updateInfo()
		local toolName, skinName = view.weapon, view.skin
		local isApplied = appliedSkin(toolName) == skinName

		nameLabel.Text = displayName(toolName) .. "  /  " .. skinName

		local lines = {}
		local info
		for _, entry in ipairs(entriesFor(toolName)) do
			if entry.name == skinName then
				info = entry.info
				break
			end
		end

		if skinName == SKIN_DEFAULT then
			table.insert(lines, "The original look of this weapon.")
		else
			if type(info) == "table" and info.Rarity then
				table.insert(lines, "Rarity: " .. tostring(info.Rarity))
			end

			local kind = "Texture on the original model"
			if toolName == "[Knife]" or toolName == "[Bat]" then
				kind = "Replacement model"
			elseif type(info) == "table" and typeof(info.TextureID) == "Instance" then
				kind = "Replacement model"
			end
			table.insert(lines, "Type: " .. kind)
		end

		local effects, soundId = skinEffects(toolName, skinName)
		previewSoundId = soundId
		table.insert(lines, "Effects: " .. (#effects > 0 and table.concat(effects, ", ") or "none"))
		table.insert(lines, isApplied and "Currently applied." or "Not applied yet.")

		detailLabel.Text = table.concat(lines, "\n")

		applyButton.Text = isApplied and "Applied" or "Apply"
		applyButton.TextTransparency = isApplied and 0.5 or 0
		applyButton.BackgroundColor3 = isApplied and CARD_COLOR or (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)
		soundButton.Visible = soundId ~= nil
	end

	-- Highlights the browsed skin and marks the applied one.
	local function updateSkinRows()
		local applied = view.weapon and appliedSkin(view.weapon)
		for _, row in ipairs(view.rows[view.weapon] or {}) do
			setRowSelected(row, row.Name == view.skin)
			row.Dot.Visible = row.Name == applied
		end
	end

	local function updateWeaponRows()
		for toolName, row in pairs(view.weaponRows) do
			setRowSelected(row, toolName == view.weapon)
			row.Dot.Visible = appliedSkin(toolName) ~= SKIN_DEFAULT
		end
	end

	local function filterSkinRows()
		local needle = view.search:lower()
		local shown = 0

		for _, row in ipairs(view.rows[view.weapon] or {}) do
			local visible = row.Name == SKIN_DEFAULT or needle == "" or row.Name:lower():find(needle, 1, true) ~= nil
			row.Button.Visible = visible
			if visible and row.Name ~= SKIN_DEFAULT then
				shown += 1
			end
		end

		local total = #(view.rows[view.weapon] or {}) - 1
		skinTitle.Text = needle == "" and ("SKINS (" .. total .. ")") or ("SKINS (" .. shown .. " of " .. total .. ")")
	end

	local function selectSkin(skinName)
		if not view.weapon then
			return
		end

		view.skin = skinName
		updateSkinRows()
		updateInfo()
		showPreview()
	end

	-- The skin rows of a weapon are built the first time it is opened and kept after that.
	local function buildSkinRows(toolName)
		if view.rows[toolName] then
			return
		end

		local rows = {}
		view.rows[toolName] = rows

		local entries = { { name = SKIN_DEFAULT } }
		for _, entry in ipairs(entriesFor(toolName)) do
			table.insert(entries, entry)
		end

		for order, entry in ipairs(entries) do
			local button, label, dot = newRow(skinList, entry.name, order)
			button.Visible = false

			local row = { Name = entry.name, Button = button, Label = label, Dot = dot }
			table.insert(rows, row)

			if type(entry.info) == "table" and entry.info.Rarity then
				label.Size = UDim2.new(1, -78, 1, 0)

				local rarity = newText(button, tostring(entry.info.Rarity), 10, 24)
				rarity.AnchorPoint = Vector2.new(1, 0)
				rarity.Position = UDim2.new(1, -20, 0, 0)
				rarity.Size = UDim2.new(0, 56, 1, 0)
				rarity.TextColor3 = MUTED_TEXT
				rarity.TextXAlignment = Enum.TextXAlignment.Right
			end

			track(button.MouseButton1Click:Connect(function()
				selectSkin(entry.name)
			end))
			track(button.MouseEnter:Connect(function()
				if view.skin ~= entry.name then
					button.BackgroundTransparency = 0.9
				end
			end))
			track(button.MouseLeave:Connect(function()
				if view.skin ~= entry.name then
					button.BackgroundTransparency = 1
				end
			end))
		end
	end

	local function selectWeapon(toolName)
		if view.weapon then
			for _, row in ipairs(view.rows[view.weapon] or {}) do
				row.Button.Visible = false
			end
		end

		view.weapon = toolName
		buildSkinRows(toolName)
		skinList.CanvasPosition = Vector2.zero

		-- The browser opens on what is applied, so the preview matches what is on the weapon.
		local applied = appliedSkin(toolName)
		local exists = false
		for _, row in ipairs(view.rows[toolName]) do
			if row.Name == applied then
				exists = true
			end
		end
		view.skin = exists and applied or SKIN_DEFAULT

		filterSkinRows()
		updateWeaponRows()
		updateSkinRows()
		updateInfo()
		showPreview()
	end

	for order, toolName in ipairs(weapons) do
		local button, label, dot = newRow(weaponList, displayName(toolName), order)
		view.weaponRows[toolName] = { Button = button, Label = label, Dot = dot }

		track(button.MouseButton1Click:Connect(function()
			if view.weapon ~= toolName then
				selectWeapon(toolName)
			end
		end))
	end

	local function applyBrowsed()
		local toolName, skinName = view.weapon, view.skin
		if appliedSkin(toolName) == skinName then
			return
		end

		skins[toolName] = skinName == SKIN_DEFAULT and "" or skinName
		saveSkins()

		if type(Skins.refresh) == "function" then
			local ok, err = pcall(Skins.refresh, toolName)
			if not ok then
				warn("[Visions hook] Applying the skin failed: " .. tostring(err))
			end
		end

		updateWeaponRows()
		updateSkinRows()
		updateInfo()
		log("paint-bucket", (skinName == SKIN_DEFAULT and "Restored the default look of " or ("Applied " .. skinName .. " to ")) .. displayName(toolName), 4)
	end

	track(applyButton.MouseButton1Click:Connect(applyBrowsed))

	track(spinButton.MouseButton1Click:Connect(function()
		preview.spin = not preview.spin
		spinButton.Text = preview.spin and "Spin: on" or "Spin: off"
	end))

	track(soundButton.MouseButton1Click:Connect(function()
		if previewSoundId then
			soundPlayer:Stop()
			soundPlayer.SoundId = previewSoundId
			soundPlayer:Play()
		end
	end))

	track((searchBox:GetPropertyChangedSignal("Text") or searchBox.Changed):Connect(function()
		view.search = searchBox.Text
		filterSkinRows()
	end))

	-- Mouse: drag rotates, the wheel zooms.
	track(dragArea.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			preview.dragging = true
			preview.lastDrag = input.Position
		end
	end))

	track(UserInputService.InputChanged:Connect(function(input)
		if preview.dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local delta = input.Position - preview.lastDrag
			preview.lastDrag = input.Position
			preview.yaw += delta.X * 0.012
			preview.pitch = math.clamp(preview.pitch + delta.Y * 0.008, -1.2, 1.2)
		end
	end))

	track(UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			preview.dragging = false
		end
	end))

	track(dragArea.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseWheel then
			preview.zoom = math.clamp(preview.zoom + input.Position.Z * 0.1, 0.5, 3)
			updateCamera()
		end
	end))

	-- The preview only costs anything while the tab is open on screen.
	local renderConnection

	local function stopRender()
		if renderConnection then
			renderConnection:Disconnect()
			renderConnection = nil
		end
	end

	local function startRender()
		if renderConnection then
			return
		end

		renderConnection = RunService.RenderStepped:Connect(function(dt)
			local model = preview.model
			if not model or not model.Parent or not menuIsOpen() then
				return
			end

			if preview.spin and not preview.dragging then
				preview.yaw += dt * 0.6
			end

			model:PivotTo(CFrame.Angles(preview.pitch, preview.yaw, 0) * preview.align * preview.base)
		end)
	end

	local function syncVisible()
		local open = tab.Signal:GetValue() and true or false
		page.Visible = open

		if open then
			-- The window can only be open when the tab is clicked, so now is when the data is freshest.
			if not view.weapon then
				local first = skins["[Revolver]"] ~= nil and "[Revolver]" or weapons[1]
				selectWeapon(first)
			else
				updateWeaponRows()
				updateSkinRows()
				updateInfo()
			end
			startRender()
		else
			stopRender()
		end
	end

	tab.Signal:Connect(syncVisible)
	table.insert(Session.Cleanups, function()
		stopRender()
		soundPlayer:Stop()
		clearPreview()
		page:Destroy()
	end)

	syncVisible()

	-- Exposed so the browser can be driven from outside (testing, other scripts).
	Session.SkinBrowser = {
		Tab = tab,
		Page = page,
		Viewport = viewport,
		View = view,
		Preview = preview,
		SelectWeapon = selectWeapon,
		SelectSkin = selectSkin,
		Apply = applyBrowsed,
	}

	return tab
end

---------- The Player List tab ------------
-- Every player in the server with their status, and an editor for the one picked. Picking someone and pressing a button runs the
-- engine's own player editor listeners (selection first, then the button), so the actions do what they did in the original menu.
local PLAYER_STATUS_NAMES = { "neutral", "friendly", "enemy" }
local PLAYER_STATUS_IDS = { neutral = 1, friendly = 2, enemy = 3 }
local PLAYER_STATUS_COLORS = {
	Color3.fromRGB(175, 175, 175),
	Color3.fromRGB(130, 215, 100),
	Color3.fromRGB(235, 85, 85),
}

local function buildPlayerListTab()
	local tab = window:AddTab({
		Icon = "eye",
		Name = "Player List",
	})

	local listSection = tab:AddSection({ Name = "PLAYERS", Position = "left" })
	local editor = tab:AddSection({ Name = "PLAYER EDITOR", Position = "right" })

	local selected = nil
	local syncing = false
	local rows = {}

	local function api()
		return sharedEnv.neverlose
	end

	-- A stub the engine recorded in its "player editor" section.
	local function editorStub(itemName)
		local ui = _G.NL_ENGINE_UI

		for _, record in ipairs(ui and ui.sections or {}) do
			if record.tab == "players" and record.title == "player editor" then
				for _, item in ipairs(rawget(record.stub, "_items") or {}) do
					if item.name == itemName then
						return item.stub
					end
				end
			end
		end
	end

	local function fireStub(stub, signalName, ...)
		local engineSignal = stub and rawget(stub, signalName)

		if not engineSignal then
			return false
		end

		local ok, err = pcall(engineSignal.Fire, engineSignal, ...)
		if not ok then
			warn("[Visions hook] Player List " .. signalName .. " listener failed: " .. tostring(err))
		end

		return ok
	end

	local function statusOf(player)
		local engine = api()

		if type(engine) == "table" and type(engine.get_player_status) == "function" then
			local ok, status = pcall(engine.get_player_status, player)
			if ok and PLAYER_STATUS_NAMES[status] then
				return status
			end
		end

		return 1
	end

	local function wantedOf(player)
		local data = player:FindFirstChild("DataFolder")
		local information = data and data:FindFirstChild("Information")
		local wanted = information and information:FindFirstChild("Wanted")

		return wanted and tostring(wanted.Value) or "?"
	end

	---------- the list ----------
	local scroll = Instance.new("ScrollingFrame")
	scroll.Name = "PlayerRows"
	scroll.Active = true
	scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
	scroll.BackgroundColor3 = Color3.fromRGB(26, 26, 26)
	scroll.BorderColor3 = STROKE_COLOR
	scroll.BorderSizePixel = 1
	scroll.CanvasSize = UDim2.new()
	scroll.LayoutOrder = listSection.NextOrder()
	scroll.ScrollBarImageColor3 = (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)
	scroll.ScrollBarThickness = 3
	scroll.Size = UDim2.new(1, 0, 0, 330)

	-- Search: only the rows whose name or display name has the text in it
	local searchBox = Instance.new("TextBox")
	searchBox.Name = "PlayerSearch"
	searchBox.BackgroundColor3 = Color3.fromRGB(32, 32, 32)
	searchBox.BorderColor3 = STROKE_COLOR
	searchBox.BorderSizePixel = 1
	searchBox.ClearTextOnFocus = false
	searchBox.Font = Enum.Font.SourceSans
	searchBox.LayoutOrder = scroll.LayoutOrder
	searchBox.PlaceholderColor3 = Color3.fromRGB(120, 120, 120)
	searchBox.PlaceholderText = "search players..."
	searchBox.Size = UDim2.new(1, 0, 0, 24)
	searchBox.Text = ""
	searchBox.TextColor3 = Color3.fromRGB(255, 255, 255)
	searchBox.TextSize = 15
	searchBox.TextXAlignment = Enum.TextXAlignment.Left
	local searchPadding = Instance.new("UIPadding")
	searchPadding.PaddingLeft = UDim.new(0, 8)
	searchPadding.Parent = searchBox
	scroll.LayoutOrder = listSection.NextOrder()
	searchBox.Parent = listSection.Body
	scroll.Parent = listSection.Body

	local layout = Instance.new("UIListLayout")
	layout.Padding = UDim.new(0, 1)
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	layout.Parent = scroll

	local emptyLabel = Instance.new("TextLabel")
	emptyLabel.BackgroundTransparency = 1
	emptyLabel.Font = Enum.Font.SourceSans
	emptyLabel.Size = UDim2.new(1, 0, 0, 24)
	emptyLabel.Text = "Nobody else is in the server"
	emptyLabel.TextColor3 = Color3.fromRGB(150, 150, 150)
	emptyLabel.TextSize = 15
	emptyLabel.Visible = false
	emptyLabel.Parent = scroll

	---------- the editor ----------
	-- the picked player's avatar picture (their Roblox headshot)
	local avatar = Instance.new("ImageLabel")
	avatar.Name = "PlayerAvatar"
	avatar.BackgroundColor3 = Color3.fromRGB(26, 26, 26)
	avatar.BorderColor3 = STROKE_COLOR
	avatar.BorderSizePixel = 1
	avatar.Image = ""
	avatar.LayoutOrder = editor.NextOrder()
	avatar.ScaleType = Enum.ScaleType.Fit
	avatar.Size = UDim2.fromOffset(96, 96)
	avatar.Visible = false
	avatar.Parent = editor.Body
	local avatarFor = nil

	local function showAvatar(player)
		avatarFor = player
		avatar.Visible = player ~= nil
		avatar.Image = ""

		if player then
			task.spawn(function()
				local ok, image = pcall(function()
					return Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
				end)

				if ok and avatarFor == player and Session.Alive then
					avatar.Image = image
				end
			end)
		end
	end

	local selectedLabel = editor:AddLabel("Selected: nobody")
	local wantedLabel = editor:AddLabel("Wanted: -")

	local statusDropdown
	statusDropdown = editor:AddLabel("Status"):AddDropdown({
		Default = "neutral",
		Values = { "friendly", "neutral", "enemy" },
		Callback = function(value)
			if syncing or not Session.Alive or not selected then
				return
			end

			if type(value) == "table" then
				for key, picked in pairs(value) do
					value = type(key) == "number" and picked or key
					break
				end
			end

			local id = PLAYER_STATUS_IDS[value]
			local engine = api()

			if id and type(engine) == "table" and type(engine.set_player_status) == "function" then
				if pcall(engine.set_player_status, selected, id) then
					log("user", selected.Name .. " is now " .. value, 3)
				end
				Session.PlayerList.refresh()
			end
		end,
	})

	local function needPlayer()
		if selected and selected.Parent == Players then
			return selected
		end

		log("user", "Pick a player in the list first", 3)
	end

	local function pressEditorButton(itemName)
		local player = needPlayer()
		if not player then
			return
		end

		local ui = _G.NL_ENGINE_UI
		local panel = ui and ui.panels and ui.panels["players"]

		-- The engine's editor acts on whoever it was last told was picked.
		fireStub(panel, "on_selection_change", player.Name)

		if not fireStub(editorStub(itemName), "on_clicked") then
			log("triangle-exclamation", "The engine has no \"" .. itemName .. "\" action", 3)
		end
	end

	editor:AddButton({
		Name = "Teleport To",
		Callback = function()
			pressEditorButton("teleport to")
		end,
	})

	editor:AddButton({
		Name = "Set Ragebot Target",
		Callback = function()
			local ragebot = NeverLose.Flags["Ragebot"]

			if not (ragebot and ragebot:GetValue() == true) then
				log("crosshairs-slash", "Turn the ragebot on first", 3)
				return
			end

			pressEditorButton("set ragebot target")
		end,
	})

	local targetButton
	local function updateTargetButton()
		if targetButton then
			targetButton.Root.Text = (selected and table.find(selectedPlayers, selected.Name)) and "Remove From Target List" or "Add To Target List"
		end
	end

	targetButton = editor:AddButton({
		Name = "Add To Target List",
		Callback = function()
			local player = needPlayer()
			if not (player and targetList) then
				return
			end

			local picked = {}
			for _, name in ipairs(selectedPlayers) do
				picked[name] = true
			end

			picked[player.Name] = not picked[player.Name] or nil
			targetList:SetValue(picked)
			updateTargetButton()
		end,
	})

	editor:AddButton({
		Name = "Copy Crew Link",
		Callback = function()
			pressEditorButton("copy crew link")
		end,
	})

	editor:AddButton({
		Name = "Copy Profile Link",
		Callback = function()
			pressEditorButton("copy profile link")
		end,
	})

	---------- keeping both in step ----------
	local function describeSelected()
		local player = selected

		if not player then
			selectedLabel:SetText("Selected: nobody")
			wantedLabel:SetText("Wanted: -")
			updateTargetButton()
			return
		end

		selectedLabel:SetText("Selected: " .. player.Name .. " (" .. player.DisplayName .. ")")
		wantedLabel:SetText("Wanted: " .. wantedOf(player))

		syncing = true
		pcall(statusDropdown.SetValue, statusDropdown, PLAYER_STATUS_NAMES[statusOf(player)])
		syncing = false

		updateTargetButton()
	end

	local function paintRow(player, row, order)
		local status = statusOf(player)
		local isSelected = selected == player

		row.Button.LayoutOrder = order
		row.Button.BackgroundColor3 = isSelected and Color3.fromRGB(58, 58, 58) or Color3.fromRGB(32, 32, 32)
		row.Marker.Visible = isSelected
		row.Status.Text = PLAYER_STATUS_NAMES[status] .. (table.find(selectedPlayers, player.Name) and "  [target]" or "")
		row.Status.TextColor3 = PLAYER_STATUS_COLORS[status]
		row.Name.Text = player.Name == player.DisplayName and player.Name or (player.Name .. "  (" .. player.DisplayName .. ")")
	end

	local function select(player)
		selected = player
		if avatarFor ~= player then
			showAvatar(player)
		end
		describeSelected()

		for other, row in pairs(rows) do
			paintRow(other, row, row.Button.LayoutOrder)
		end
	end

	local function addRow(player)
		local button = Instance.new("TextButton")
		button.Name = player.Name
		button.AutoButtonColor = false
		button.BackgroundColor3 = Color3.fromRGB(32, 32, 32)
		button.BorderSizePixel = 0
		button.Size = UDim2.new(1, -4, 0, 24)
		button.Text = ""
		button.Parent = scroll

		local marker = Instance.new("Frame")
		marker.BackgroundColor3 = (NeverLose.Accent and NeverLose:Accent() or ACCENT_COLOR)
		marker.BorderSizePixel = 0
		marker.Size = UDim2.new(0, 3, 1, 0)
		marker.Visible = false
		marker.Parent = button

		local nameLabel = Instance.new("TextLabel")
		nameLabel.BackgroundTransparency = 1
		nameLabel.Font = Enum.Font.SourceSans
		nameLabel.Position = UDim2.fromOffset(10, 0)
		nameLabel.Size = UDim2.new(0.62, -10, 1, 0)
		nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		nameLabel.TextSize = 16
		nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
		nameLabel.TextXAlignment = Enum.TextXAlignment.Left
		nameLabel.Parent = button

		local statusLabel = Instance.new("TextLabel")
		statusLabel.BackgroundTransparency = 1
		statusLabel.Font = Enum.Font.SourceSans
		statusLabel.Position = UDim2.new(0.62, 0, 0, 0)
		statusLabel.Size = UDim2.new(0.38, -8, 1, 0)
		statusLabel.TextSize = 15
		statusLabel.TextXAlignment = Enum.TextXAlignment.Right
		statusLabel.Parent = button

		button.MouseButton1Click:Connect(function()
			if Session.Alive then
				select(player)
			end
		end)

		local row = { Button = button, Marker = marker, Name = nameLabel, Status = statusLabel }
		rows[player] = row
		return row
	end

	local function refresh()
		if not Session.Alive then
			return
		end

		local present = {}
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer then
				table.insert(present, player)
			end
		end
		table.sort(present, function(a, b)
			return a.Name:lower() < b.Name:lower()
		end)

		local keep = {}
		local query = string.lower(searchBox.Text or "")
		for index, player in ipairs(present) do
			keep[player] = true
			local row = rows[player] or addRow(player)
			paintRow(player, row, index)
			row.Button.Visible = query == "" or string.find(string.lower(player.Name), query, 1, true) ~= nil or string.find(string.lower(player.DisplayName), query, 1, true) ~= nil
		end

		for player, row in pairs(rows) do
			if not keep[player] then
				row.Button:Destroy()
				rows[player] = nil
			end
		end

		emptyLabel.Visible = #present == 0

		if selected and not keep[selected] then
			select(nil)
		end
	end

	track((searchBox:GetPropertyChangedSignal("Text") or searchBox.Changed):Connect(function()
		if Session.Alive then
			refresh()
		end
	end))

	track(Players.PlayerAdded:Connect(function()
		task.defer(refresh)
	end))
	track(Players.PlayerRemoving:Connect(function()
		task.defer(refresh)
	end))

	tab.Signal:Connect(function(open)
		if open then
			refresh()
			describeSelected()
		end
	end)

	-- Statuses, wanted levels and the Target List change while the tab is open.
	task.spawn(function()
		while Session.Alive do
			task.wait(1)

			-- while the menu is open, whatever tab or look is showing, so the list always has everyone
			if Session.Alive and (tab.Signal:GetValue() or menuIsOpen()) then
				refresh()
				describeSelected()
			end
		end
	end)

	table.insert(Session.Cleanups, function()
		for player, row in pairs(rows) do
			row.Button:Destroy()
			rows[player] = nil
		end
	end)

	Session.PlayerList = {
		Tab = tab,
		Select = select,
		Selected = function()
			return selected
		end,
		refresh = refresh,
	}

	refresh()
	return tab
end

---------- Full Auto ------------
-- Holding the left mouse button keeps pulling the trigger of the gun in your hands. The gun's own script still refuses a pull inside its cooldown,
-- so Speed is a share of the gun's own fire rate: 100 is as fast as the gun allows, 50 is every second shot, 1 the slowest (0 counts as 1).
-- It only reacts to a click that reached the game (not one on the menu or on a game window), only with a gun that has ammo in it, and never
-- after an Anti Report shutdown.
local FullAuto = { Held = false, Last = 0 }

local function startFullAuto()
	track(UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if input.UserInputType == Enum.UserInputType.MouseButton1 and not gameProcessed and not menuIsOpen() then
			FullAuto.Held = true
			-- the click itself already fired the first shot
			FullAuto.Last = os.clock()
		end
	end))

	track(UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			FullAuto.Held = false
		end
	end))

	-- A release that happens while the window is not focused never arrives: the hold of the left button, and of every Hold bind, ends with the focus.
	track(UserInputService.WindowFocusReleased:Connect(function()
		FullAuto.Held = false

		for _, entry in pairs(Binds.Entries) do
			if entry.Held then
				entry.Held = false
				pcall(entry.Toggle.SetValue, entry.Toggle, false)
			end
		end
	end))

	track(RunService.Heartbeat:Connect(function()
		if not (FullAuto.Held and Session.Alive) or sharedEnv.neverlose_safety_shutdown then
			return
		end

		local enabled = NeverLose.Flags["full_auto"]
		if not (enabled and enabled:GetValue() == true) or Session.isTyping() then
			return
		end

		local character = LocalPlayer.Character
		local tool = character and character:FindFirstChildOfClass("Tool")
		local ammo = tool and tool:FindFirstChild("Ammo")

		-- only guns, and not one with an empty clip
		if not (tool and ammo and ammo.Value > 0) then
			return
		end

		local cooldownValue = tool:FindFirstChild("ShootingCooldown")
		local cooldown = cooldownValue and tonumber(cooldownValue.Value) or 0.3

		-- Rapid Fire takes part of the gun's own cooldown away: the trigger is pulled that much sooner.
		local rapid = NeverLose.Flags["dt"]
		if rapid and rapid:GetValue() == true then
			local rapidSpeed = NeverLose.Flags["rapid_fire_speed"]
			cooldown = cooldown * (1 - math.clamp(rapidSpeed and tonumber(rapidSpeed:GetValue()) or 100, 0, 100) / 100)
		end
		local speedItem = NeverLose.Flags["full_auto_speed"]
		local speed = speedItem and tonumber(speedItem:GetValue()) or 100
		local interval = (cooldown + 0.015) / (math.max(speed, 1) / 100)
		local now = os.clock()

		if now - FullAuto.Last >= interval then
			FullAuto.Last = now
			pcall(tool.Activate, tool)
		end
	end))
end

---------- Building the interface ------------
local function buildInterface()
	-- Creating Notification --
	Notification = NeverLose:CreateNotification()

	-- Creating Logger --
	Logging = NeverLose:CreateLogger()

	-- Engine notifications (shot notifications, purchases, staff detection, ...) were only printed to the console. They go to the on-screen log now.
	-- The same line within 0.75 s is dropped and no more than 6 lines a second get through, so a ragebot firing at 100+ shots a second with Shot
	-- Notifications on can't bury the screen.
	do
		local lastShown, shownCount = {}, 0
		local windowStart, shownInWindow = 0, 0

		Session.engineLog = function(text)
			if not Session.Alive then
				return
			end

			local now = os.clock()
			local last = lastShown[text]

			if last and now - last < 0.75 then
				return
			end

			if now - windowStart > 1 then
				windowStart, shownInWindow = now, 0
			end

			if shownInWindow >= 6 then
				return
			end

			shownInWindow += 1

			if not last then
				shownCount += 1

				if shownCount > 64 then
					lastShown, shownCount = {}, 1
				end
			end

			lastShown[text] = now
			log("ps4-touchpad", text, 3)
		end

		_G.NL_LOG = Session.engineLog
	end

	-- >> ( Visions hook intro and pictures )
	-- The VISIONS HOOK intro (4.2 s, 84 frames at 20 fps, its black background taken out so the game shows through) and the razor the Visions
	-- look hangs off its corner. Both are kept in here as base64 PNGs, written to the workspace once and shown through getcustomasset; with
	-- no file functions there is simply no intro and no razor. The intro's video has no sound: an audio file at workspace/visions_intro.mp3
	-- (or .ogg) plays with it. getgenv().VISIONS_NO_INTRO = true skips it. (One local only: this function is near the local limit.)
	local VisionsAssets = (function()
		local RAZOR_PNG = ""
		local INTRO_SHEETS = {
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		}
		local INTRO = { FrameWidth = 640, FrameHeight = 240, Columns = 1, PerSheet = 4, Frames = 84, Fps = 20, Version = 2 }

		local function decode(data)
			local ok, decoded = pcall(function()
				if crypt and crypt.base64decode then return crypt.base64decode(data) end
				if crypt and crypt.base64 and crypt.base64.decode then return crypt.base64.decode(data) end
				return nil
			end)
			if ok and type(decoded) == "string" then
				return decoded
			end

			local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
			local lookup = {}
			for i = 1, #alphabet do
				lookup[alphabet:sub(i, i)] = i - 1
			end
			data = data:gsub("[^%w%+/=]", "")
			local out = {}
			for i = 1, #data, 4 do
				local a, b, c, d = lookup[data:sub(i, i)], lookup[data:sub(i + 1, i + 1)], lookup[data:sub(i + 2, i + 2)], lookup[data:sub(i + 3, i + 3)]
				local n = (a or 0) * 262144 + (b or 0) * 4096 + (c or 0) * 64 + (d or 0)
				out[#out + 1] = string.char(math.floor(n / 65536) % 256)
				if c then out[#out + 1] = string.char(math.floor(n / 256) % 256) end
				if d then out[#out + 1] = string.char(n % 256) end
			end
			return table.concat(out)
		end

		local function asset(path, data)
			local ok, result = pcall(function()
				if not isfile(path) then
					writefile(path, decode(data))
				end
				return getcustomasset(path)
			end)
			return ok and result or nil
		end

		local assets = {}

		function assets.Razor()
			return asset("visions_razor.png", RAZOR_PNG)
		end

		-- plays the intro in the middle of the screen and returns once it has faded out
		function assets.PlayIntro()
			if getgenv and getgenv().VISIONS_NO_INTRO then
				return
			end

			local images = {}
			for index, data in ipairs(INTRO_SHEETS) do
				images[index] = asset(string.format("visions_intro_v%d_%d.png", INTRO.Version, index), data)
				if not images[index] then
					return
				end
			end

			pcall(function()
				game:GetService("ContentProvider"):PreloadAsync(images)
			end)

			local introGui = Instance.new("ScreenGui")
			introGui.Name = "VisionsIntro"
			introGui.IgnoreGuiInset = true
			introGui.ResetOnSpawn = false
			introGui.DisplayOrder = 100000
			local okParent = pcall(function()
				introGui.Parent = (type(gethui) == "function" and gethui()) or game:GetService("CoreGui")
			end)
			if not okParent then
				introGui.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
			end

			local image = Instance.new("ImageLabel")
			image.AnchorPoint = Vector2.new(0.5, 0.5)
			image.Position = UDim2.fromScale(0.5, 0.45)
			image.Size = UDim2.fromScale(0.6, 0.6)
			image.BackgroundTransparency = 1
			image.Image = images[1]
			image.ImageRectSize = Vector2.new(INTRO.FrameWidth, INTRO.FrameHeight)
			image.ScaleType = Enum.ScaleType.Fit
			image.Parent = introGui
			local ratio = Instance.new("UIAspectRatioConstraint")
			ratio.AspectRatio = INTRO.FrameWidth / INTRO.FrameHeight
			ratio.Parent = image

			local sound = nil
			pcall(function()
				for _, path in ipairs({ "visions_intro.mp3", "visions_intro.ogg" }) do
					if isfile(path) then
						sound = Instance.new("Sound")
						sound.SoundId = getcustomasset(path)
						sound.Parent = game:GetService("SoundService")
						sound:Play()
						break
					end
				end
			end)

			-- frames follow the clock, so a slow client skips frames instead of playing it slower
			local started = os.clock()
			while true do
				local frame = math.floor((os.clock() - started) * INTRO.Fps)
				if frame >= INTRO.Frames then
					break
				end
				local cell = frame % INTRO.PerSheet
				image.Image = images[math.floor(frame / INTRO.PerSheet) + 1]
				image.ImageRectOffset = Vector2.new((cell % INTRO.Columns) * INTRO.FrameWidth, math.floor(cell / INTRO.Columns) * INTRO.FrameHeight)
				task.wait()
			end

			task.wait(0.4)
			pcall(function()
				game:GetService("TweenService"):Create(image, TweenInfo.new(0.5), { ImageTransparency = 1 }):Play()
			end)
			task.wait(0.5)

			if sound then
				sound:Destroy()
			end
			introGui:Destroy()
		end

		return assets
	end)()

	NeverLose.RazorAsset = VisionsAssets.Razor()

	-- Creating Window --
	window = NeverLose:CreateWindow({
		Logo = NeverLose.GlobalLogo,
		Name = WINDOW_NAME,
