---------- Input: keybinds, target key, popup ------------
track(UserInputService.InputBegan:Connect(function(input, gameProcessed)
	if not Session.Alive then
		return
	end

	-- The next key after clicking "Key" in the popup becomes the bind.
	if capturingEntry then
		finishCapture(input)
		return
	end

	-- A left click outside the popup closes it.
	if BindPopup.Frame and BindPopup.Frame.Visible and input.UserInputType == Enum.UserInputType.MouseButton1 and not mouseIsOver(BindPopup.Frame) then
		closeBindPopup()
	end

	-- gameProcessed is true while typing in chat or a text box. A key being picked for a keybind control is not a press of the option bound
	-- to it, or of the target key.
	if gameProcessed or (NeverLose.KeyCaptures or 0) > 0 then
		return
	end

	onBindInputBegan(input)

	if Session.onEngineKey then
		Session.onEngineKey(input)
	end

	if inputMatchesKey(input, targetKey) then
		Session.addTarget()
	end
end))

-- Always handle releases, so a Hold bind can never get stuck on.
track(UserInputService.InputEnded:Connect(function(input)
	if Session.Alive then
		onBindInputEnded(input)
	end
end))

-- Defer so a leaving player is already gone from GetPlayers().
