local create_real_drawing = LPH_NO_VIRTUALIZE(function(class, properties)
    local object = real_drawing["new"](class)

    for property, value in properties do
        object[property] = value
    end

    return object
end)

local create_fake_drawing = LPH_NO_VIRTUALIZE(function(class, properties)
    -- Not every executor that is asked for fake drawings has them (Potassium has none): the real Drawing library does the same job there.
    local object = (fake_drawing or real_drawing)["new"](class)

    for property, value in properties do
        object[property] = value
    end

    return object
end)

