-- > ( bypass: key logging notice )
-- The game's KeyRelay script sends every key press and release to the server over ReplicatedStorage.Logging, but only once the
-- server has sent that remote a true (a false stops it again). Nothing on screen says when that happens, so this does. It only
-- listens: the game's own listener is left alone and nothing is blocked, so the server still gets what it asked for.

do
    local logging_enabled = false

    local function key_logging_changed(enabled)
        if enabled == logging_enabled then
            return
        end

        logging_enabled = enabled

        if enabled then
            new_notification("the server turned key logging on: every key you press is being sent to it", 3)
        else
            new_notification("the server turned key logging off", 2)
        end
    end

    task.spawn(function()
        local logging = replicated_storage:WaitForChild("Logging", 10)

        if not logging then
            return
        end

        create_connection(logging["OnClientEvent"], function(value)
            key_logging_changed(value and true or false)
        end)

        -- it may already be on when this runs: read the flag the game's own listener keeps (its one upvalue)
        pcall(function()
            for _, connection in getconnections(logging["OnClientEvent"]) do
                local callback = connection["Function"]

                if callback and not isexecutorclosure(callback) then
                    local environment = getfenv(callback)
                    local owner = environment and rawget(environment, "script")

                    if owner and owner["Name"] == "KeyRelay" then
                        for _, upvalue in debug.getupvalues(callback) do
                            if upvalue == true then
                                key_logging_changed(true)
                            end
                        end
                    end
                end
            end
        end)
    end)
end
-- > ( client stuff )

local local_server_position = cframe_new()
local local_client_position = cframe_new()
local local_bought_count = 0
local local_character = local_player["Character"]
local local_reloading = false
local local_armor = 0
local local_parts = {}
local local_tool = nil
local local_cash = 0
local local_ping = 50
local local_fps = 200
local local_gun = nil
local local_following = false

local purchasing = nil
local vehicle_data = {}
local vehicle = nil

do
    local function apply_hrp_fix(hrp)
        local old = getrawmetatable(hrp)
        -- F-C4: respawn used to re-install on top of an already-hooked metatable,
        -- stacking __index closures one per life. Guard with a sentinel.
        -- The sentinel is the run's generation: a part hooked by an older run (whose positions are long out of date) is hooked
        -- again on top of the original __index, not skipped.
        local generation = getgenv()["neverlose_bypass_generation"] or true
        if old and rawget(old, "__neverlose_hrp_hooked") == generation then
            return
        end
        local old_index = rawget(old, "__neverlose_hrp_original_index") or old["__index"]

        local new = {
            __neverlose_hrp_hooked = generation,
            __neverlose_hrp_original_index = old_index,
            ["__index"] = newcclosure(LPH_NO_VIRTUALIZE(function(self, index)
                if not checkcaller() and self and index == "CFrame" and (#anti_aim ~= 0 or purchasing) and not vehicle then
                    return local_client_position
                end
                return old_index(self, index)
            end))
        }

        for _, v in old do
            if not new[_] then
                new[_] = v
            end
        end

        setrawmetatable(hrp, new)
    end

    local function hook_humanoid(humanoid)
        local old = getrawmetatable(humanoid)
        -- F-C4: sentinel-guarded; see apply_hrp_fix for the stacking bug it prevents. The sentinel is the run's generation, so a humanoid hooked by
        -- an earlier run (whose flags are long switched off) is hooked again on top of the original __index and __newindex, not skipped.
        local generation = getgenv()["neverlose_bypass_generation"] or true
        if old and rawget(old, "__neverlose_humanoid_hooked") == generation then
            return
        end
        local old_index = rawget(old, "__neverlose_humanoid_original_index") or old["__index"]
        local old_newindex = rawget(old, "__neverlose_humanoid_original_newindex") or old["__newindex"]

        local s = {
            ["WalkSpeed"] = humanoid["WalkSpeed"],
            ["JumpPower"] = humanoid["JumpPower"]
        }

        local new = {
            __neverlose_humanoid_hooked = generation,
            __neverlose_humanoid_original_index = old_index,
            __neverlose_humanoid_original_newindex = old_newindex,
            ["__index"] = newcclosure(LPH_NO_VIRTUALIZE(function(self, index)
                if not checkcaller() and self and (index == "WalkSpeed" or index == "JumpPower") then
                    return s[index]
                end
                return old_index(self, index)
            end)),
            ["__newindex"] = newcclosure(LPH_NO_VIRTUALIZE(function(self, index, value)
                if not checkcaller() and self then
                    if index == "WalkSpeed" and flags["lock_walk_speed"] then
                        return
                    elseif index == "WalkSpeed" and flags["remove_slowdowns"] and value < 16 then
                        s[index] = value
                        if flags["remove_slowdowns"] then
                            return
                        end
                    elseif index == "JumpPower" then
                        if flags["remove_jump_cooldown"] and value == 0 then
                            s[index] = 0
                            return
                        else
                            value = flags["jump_power"] and flags["jump_power_value"] or value
                        end
                    end
                end
                return old_newindex(self, index, value)
            end))
        }

        for _, v in old do
            if not new[_] then
                new[_] = v
            end
        end

        setrawmetatable(humanoid, new)
    end

    local ammo_signal = signals["on_local_ammo_changed"]

    local on_child_added = LPH_NO_VIRTUALIZE(function(child)
        local_parts[child["Name"]] = child
        if child["ClassName"] == "Tool" then
            local handle = find_first_child(child, "Handle")

            if handle then
                local_tool = child

                signals["on_local_tool_equipped"]:Fire(child)

                local range = find_first_child(child, "Range")
                local ammo = find_first_child(child, "Ammo")

                local new_local_gun = {}

                if range then
                    local_gun = range["Value"]

                    new_local_gun = {handle, local_gun, ammo["Value"]}
                end

                if ammo and range then
                    new_local_gun[4] = create_connection(ammo:GetPropertyChangedSignal("Value"), function()
                        local ammo = ammo["Value"]
                        new_local_gun[3] = ammo
                        ammo_signal:Fire(local_guns[handle], ammo)
                    end)

                    local_guns[handle] = new_local_gun
                end
            end
        end
    end)

    local on_child_removed = LPH_NO_VIRTUALIZE(function(child)
        if local_parts[child["Name"]] == child then
            local_parts[child["Name"]] = nil
        end
        if child["ClassName"] == "Tool" then
            signals["on_local_tool_equipped"]:Fire(false, child)

            local handle = find_first_child(child, "Handle")

            if handle then
                local old = local_guns[handle]
                if old then
                    local connection = old[4]
                    if connection then
                        connection:Disconnect()
                    end
                    local_guns[handle] = nil
                end
            end

            local found = nil
            for _, b in local_guns do
                found = _
                break
            end

            local_gun = found and local_gun or nil
            local_tool = found and found["Parent"] or nil
        end
    end)

    local on_character_added = LPH_NO_VIRTUALIZE(function(character)
        vehicle = nil
        -- Left over from the previous life until the new character has loaded otherwise.
        local_knocked = false
        local_reloading = false
        local_gun = nil
        local_tool = nil
        local_guns = {}

        local hrp = wait_for_child(character, "HumanoidRootPart", 5)

        -- A part that never arrived (or a metatable that cannot be replaced) must not end the setup of the rest of this life.
        if hrp then
            pcall(apply_hrp_fix, hrp)
        end

        local_parts = {
            ["HumanoidRootPart"] = hrp
        }

        local humanoid = wait_for_child(character, "Humanoid", 5)

        create_connection(humanoid:GetPropertyChangedSignal("Health"), function()
            signals["on_local_health_changed"]:Fire(humanoid["Health"])
        end)

        hook_humanoid(humanoid)

        wait_for_child(character, "Head", 5)

        local children = get_children(character)
        for i = 1, #children do
            local child = children[i]
            local_parts[child["Name"]] = child

            if child["ClassName"] == "Tool" then
                on_child_added(child)
            end
        end

        create_connection(character["ChildAdded"], on_child_added)
        create_connection(character["ChildRemoved"], on_child_removed)

        local_character = character

        signals["on_local_character_added"]:Fire(1)

        wait_for_child(character, "FULLY_LOADED_CHAR", 9e9)

        local body_effects = wait_for_child(character, "BodyEffects", 9e9)
        local knocked = wait_for_child(body_effects, "K.O", 9e9)
        local reload = wait_for_child(body_effects, "Reload", 9e9)
        local armor = wait_for_child(body_effects, "Armor", 9e9)

        create_connection(armor:GetPropertyChangedSignal("Value"), function()
            local_armor = armor["Value"]
            signals["on_local_armor_changed"]:Fire(local_armor)
        end)

        create_connection(knocked:GetPropertyChangedSignal("Value"), function()
            signals["on_local_knocked"]:Fire(knocked["Value"])
            local_knocked = knocked["Value"]
        end)

        create_connection(reload:GetPropertyChangedSignal("Value"), function()
            signals["on_local_reload"]:Fire(local_tool)
            local_reloading = reload["Value"]
        end)

        local_reloading = false
        local_armor = armor["Value"]
        local_knocked = knocked["Value"]

        signals["on_local_character_loaded"]:Fire(true)
    end)

    if local_character then
        spawn(on_character_added, local_character)
    end

    create_connection(local_player["CharacterAdded"], on_character_added)
end

-- >> ( vehicles )

do
    local name = local_player["Name"]
    local signal = signals["on_vehicle_sat_in"]
        
    local on_vehicle_removed = LPH_JIT_MAX(function(new_vehicle, new_player)
        for i = 1, #vehicle_data do
            if vehicle_data[i][1] == new_vehicle then
                local player = new_player or vehicle_data[i][3]

                if player == local_player then
                    vehicle = nil
                    signal["Fire"](signal, nil)
                    if new_player then
                        vehicle_blocked = true
                        delay(5, function()
                            vehicle_blocked = false
                        end)
                    end
                elseif player then
                    local data = player_data[player]

                    if data then
                        data[19] = nil
                    end
                end

                remove(vehicle_data, i)
                break
            end
        end
    end)

    local on_vehicle_added = LPH_JIT_MAX(function(new_vehicle)
        local data = {
            new_vehicle,
            wait_for_child(new_vehicle, "Ride", 9e9),
            find_first_child(players_service, new_vehicle["Name"])
        }
        vehicle_data[#vehicle_data+1] = data

        local humanoid = nil

        create_connection(new_vehicle["GetPropertyChangedSignal"](new_vehicle, "Name"), function()
            local player = find_first_child(players_service, new_vehicle["Name"])
            local old_player = data[3]

            if old_player then
                local data = player_data[old_player]

                if data then
                    data[19] = nil
                end
            end

            if player == local_player then
                vehicle = new_vehicle
                signal["Fire"](signal, vehicle)
            elseif data[3] == local_player then
                vehicle = nil
                signal["Fire"](signal, nil)
            end
            
            if player then
                local data = player_data[player]

                if data then
                    data[19] = new_vehicle
                end
            end

            data[3] = player
        end)

        humanoid = wait_for_child(new_vehicle, "Humanoid", 5)

        if humanoid then
            local health = humanoid["GetAttribute"](humanoid, "Health")

            if health and health <= 0 then
                on_vehicle_removed(new_vehicle, data[3])
            end

            create_connection(humanoid["GetAttributeChangedSignal"](humanoid, "Health"), function()
                local health = humanoid["GetAttribute"](humanoid, "Health")

                if health and health <= 0 then
                    on_vehicle_removed(new_vehicle, data[3])
                end
            end)
        end
    end)

    -- No Vehicles folder in the workspace: no vehicle features, but the rest of the script still loads.
    if vehicles then
        create_connection(vehicles["ChildAdded"], on_vehicle_added)
        create_connection(vehicles["ChildRemoved"], on_vehicle_removed)

        for _, part in get_children(vehicles) do
            spawn(on_vehicle_added, part)
        end
    end
end

-- > ( hit detection )

local shot_count = 0

-- the menu's hit visuals listen to this one (see Session.connectEngineHits)
_G.NL_HIT_SIGNAL = signals["on_local_bullet_confirmed"]

do
    -- >> ( variables )

    local setthreadidentity = setthreadidentity
    local getnamecallmethod = getnamecallmethod
    local checkcaller = checkcaller
    local tostring = tostring

    local older_health = nil
    local older_data = nil

    -- >> ( event setup )

    get_bullet_result = LPH_JIT_MAX(function(player, part, old_server_position, aim_position, target_velocity, did_defensive)
        setthreadidentity(8)

        local data = player_data[player]

        if not data then
            return
        end

        local old_count = shot_count
        local old_health = data[9]

        local start = clock()
        repeat wait() until clock() - start > 0.25 + local_ping/1000 or shot_count > old_count

        if data and older_health ~= data[9] or older_data ~= data then
            older_health = data[9]
            older_data = data

            local message = old_server_position and " (pred miss: "..tostring(round((aim_position-part["Position"])["Magnitude"], 1))..") (velocity: "..tostring(round((target_velocity or vector3_zero)["Magnitude"], 1))..(did_defensive and ") (defensive: true)" or ") (defensive: false)")

            if shot_count == old_count then
                return signals["on_local_bullet_failed"]:Fire(player, part, not local_parts["Head"] and "death" or "unknown"..(message or ""), shot_count)
            end

            local new_health = data[9]

            if new_health < old_health then
                return signals["on_local_bullet_confirmed"]:Fire(player, part, tostring(floor(new_health-old_health)), shot_count, message)
            else
                return signals["on_local_bullet_failed"]:Fire(player, part, "unknown"..(message or ""), shot_count)
            end
        end
    end)

    -- >> ( remote hook )

    local game_on_client_event = nil

    -- guard: on a re-injection the event's OnClientEvent is already our table, not a signal
    if typeof(event) == "Instance" and typeof(event["OnClientEvent"]) == "RBXScriptSignal" then
        for _, v in getconnections(event["OnClientEvent"]) do
            local func = v["Function"]
            if func then
                local info = getinfo(func)
                if info then
                    for _, constant in getconstants(func) do
                        if tostring(constant) == "ShootingRecoil" then
                            game_on_client_event = func
                            v:Disable()
                            break
                        end
                    end
                end
            end
        end
    end

    local old = getrawmetatable(event)
    local old_namecall = old["__namecall"]
    local o_i = old["__index"]
    local f = {
        Connect = function(_, callback)
            game_on_client_event = callback
            return {
                Disconnect = function() end
            }
        end
    }

    f["connect"] = f["Connect"]

    local last_client_bullet_position = vector3_zero
    local last_client_bullet_shooter = nil
    local on_shot_at = signals["on_shot_at"]

    create_connection(event["OnClientEvent"], LPH_JIT_MAX(function(packet, ...)
        -- While the ragebot has a target nothing of the shooting shows on this client: the game's hit marker and the camera kick are not passed on.
        if (packet == "HitMarker" or packet == "ShootingRecoil") and flags["ragebot"] and ragebot_target ~= nil then
            if packet == "ShootingRecoil" then
                shot_count += 1
            end

            return
        end

        if packet == "ShootingRecoil" then
            shot_count += 1

            -- Remove Recoil: the game's answer to this packet is a kick of the camera and nothing else, so it is simply not passed on
            if flags["remove_recoil"] then
                return
            end
        elseif packet == "ClientBullet" then
            local shooter, v350, v351, position, v353, v354 = ...
            last_client_bullet_position = position
            last_client_bullet_shooter = find_first_child(players_service, shooter["Name"])
        elseif packet == "ShotFrom" and last_client_bullet_shooter then
            setthreadidentity(8)
            on_shot_at:Fire(last_client_bullet_shooter, last_client_bullet_position)
            last_client_bullet_shooter = nil
            last_client_bullet_position = nil
        end
        if game_on_client_event then
            setthreadidentity(4)
            return game_on_client_event(packet, ...)
        end
    end))

    -- A newer run of the script cannot take this hook out of the chain, it can only be wrapped. Left alone, the older hook kept
    -- rewriting every shot with its own frozen state (an aim position and a server position from a character that is long gone):
    -- shots were accepted by the server but never landed. Once a newer run exists this one just hands the call on.
    local hook_generation = getgenv()["neverlose_bypass_generation"]

    local new = {
        ["__namecall"] = newcclosure(LPH_JIT_MAX(function(self, ...)
            if getgenv()["neverlose_bypass_generation"] ~= hook_generation then
                return old_namecall(self, ...)
            end

            setthreadidentity(4)
            if getnamecallmethod() == "FireServer" then
                local args = {...}
                local packet = args[1]
                
                if packet == "ShootGun" then
                    -- A shot the gun's own script made (not the ragebot's forged call): bullet manipulation's watchdog needs to know the pull did shoot.
                    if not checkcaller() then
                        local marks = hide_manager["bm_sent"]
                        local shot_handle = args[2]
                        local shot_tool = marks and typeof(shot_handle) == "Instance" and shot_handle["Parent"] or nil

                        if shot_tool then
                            marks[shot_tool] = clock()
                        end
                    end

                    if ragebot_aim_position and ragebot_target then
                        local handle = args[2]

                        local pos = ragebot_aim_position + vector3_new(math_random(101,105)/100,0.008,-0.008)
                        -- claimed from where the server most likely has the body (Origin Lag, getgenv().neverlose_origin_lag, seconds; 0 = where it is now)
                        local lag_origin = hide_manager["lagged_position"] and hide_manager["lagged_position"](getgenv()["neverlose_origin_lag"] or 0.09)
                        local origin = (lag_origin or local_server_position["p"]) + vector3_new(0.004,3.0208,-0.048)

                        -- Following the target closely: the body is somewhere within the follow's reach of the target (hide_manager.follow_reach; a strafe at
                        -- Speed 75 is all round the circle every frame), and the server has it there about 0.1 s late, so a shot claimed from where the body
                        -- is now was refused about half the time. Claimed from 1.5 studs off the target instead (towards the body), the origin is within
                        -- reach + 1.5 of wherever on that circle the server has the body, inside the 17 studs it forgives, whichever point that is.
                        local follow_reach = local_following and hide_manager["follow_reach"] and hide_manager["follow_reach"]()

                        if follow_reach and follow_reach <= 15 then
                            local away = (lag_origin or local_server_position["p"]) - ragebot_aim_position
                            local away_length = away["Magnitude"]

                            if away_length == away_length and away_length > 0.1 and away_length < 40 then
                                origin = ragebot_aim_position + away["Unit"] * 1.5
                            end
                        end

                        -- Walls: the server takes a shot only when nothing blocks the line from this origin to where the hit is claimed (a Rifle sent at a
                        -- target behind a house from 160 studs, and a DB from 60, were refused every time; from 20 studs with a clear line both were taken).
                        -- Force Hit still always names the head as the part hit; only the claimed point is moved, to the nearest open point beside the target
                        -- that has a clear line (hide_manager.walls_aim, 4 to 16 studs, within the gun's Range). With no such point the shot goes as it is,
                        -- except a shotgun's: every refused shotgun call counts against its SecurityTolerance, and past it the gun is locked for the server.
                        -- (No method calls in here: one before old_namecall replaces the namecall method and the shot is never sent.)
                        -- Over the wall (hide_manager.walls_route): the shot may also start from a point above or beside the body that clears the wall.
                        local walls_route = hide_manager["walls_route"]

                        if walls_route then
                            local walls_tool = typeof(handle) == "Instance" and handle["Parent"] or nil
                            local walls_range = walls_tool and find_first_child(walls_tool, "Range")
                            local walls_ok, routed_origin, claimed = pcall(walls_route, origin, pos, walls_range and walls_range["Value"] or nil)

                            if walls_ok then
                                if claimed then
                                    origin, pos = routed_origin, claimed
                                elseif walls_tool and string.find(walls_tool["Name"], "Shotgun") or (walls_tool and walls_tool["Name"] == "[Double-Barrel SG]") then
                                    return
                                end
                            end
                        end
                
                        -- An origin thousands of studs from the claim (the body was in the void when it was taken, or the claim is the target's void spot):
                        -- the server refuses it whatever the gun, so it is not sent (measured: a third of a fight's shots went out from 1e9 studs).
                        local reach_gap = (origin - pos)["Magnitude"]

                        if reach_gap ~= reach_gap or reach_gap > 2000 then
                            return
                        end

                        local dir = (origin-pos)["Unit"]
                        local Magnitude = dir["Magnitude"]
                        local part = ragebot_target[4]["Head"] or ragebot_target[4][flags["ragebot_hitbox"][1] == "head" and "Head" or "UpperTorso"]
                        
                        spawn(get_bullet_result, ragebot_target[2], part)

                        -- getgenv().neverlose_debug_shots = {} makes every rebuilt shot leave its arguments here (for finding out why one is refused)
                        local debug_shots = getgenv()["neverlose_debug_shots"]

                        if debug_shots and #debug_shots < 200 then
                            debug_shots[#debug_shots+1] = {clock(), handle, origin, pos, part, dir, ragebot_target[2], ragebot_aim_position, #args, args, debug.traceback(), getthreadidentity(), checkcaller()}
                        end

                        -- Whatever follows the direction is kept: a shotgun's shot carries the server's time, a spread number and the pellet
                        -- number (from the gun's own script, or from the auto fire), and a call cut down to five arguments is taken by the
                        -- server only until its SecurityTolerance runs out.
                        local shot_direction = (Magnitude <= 0 or Magnitude ~= Magnitude) and (handle["Position"]-pos)["Unit"] or dir

                        local first = old_namecall(self, "ShootGun", handle, origin, pos, part, shot_direction, unpack(args, 7))
                        hide_manager["manipulated_at"] = clock()
                        -- where this shot was claimed to hit (the local bullet tracers end there)
                        local claim_tool = typeof(handle) == "Instance" and handle["Parent"] or nil
                        hide_manager["last_claim"] = {pos, clock(), claim_tool ~= nil and hide_manager["pellets_of"] ~= nil and hide_manager["pellets_of"](claim_tool) > 1}
                        getgenv()["neverlose_last_claim"] = hide_manager["last_claim"]

                        -- Double Tap (flag auto_fire_salvo): the shot once more, for the server to hold behind this one (hide_manager.salvo_extra says when). It is decided after the shot has
                        -- gone: a method call made in here before old_namecall (tool:GetAttribute, say) replaces the namecall method and the shot is never
                        -- sent (that is what turned every shot away in the first tests: 100 sends, none taken). The second goes out a frame later as a call
                        -- of its own, which comes back through this hook and is rebuilt like any shot. Measured with two accounts: the first was taken at
                        -- +0.03 s and the second 1.29 s later (twice), and two plain calls in a frame did the same (+0.05 s, +1.35 s).
                        local salvo_extra = hide_manager["salvo_extra"]

                        if salvo_extra and salvo_extra(handle) then
                            local remote = self

                            local salvo_delay = getgenv()["neverlose_salvo_delay"] or 0
                            local send_held = function()
                                -- (this call comes back through the hook: salvo_busy keeps it from asking for a held shot of its own)
                                hide_manager["salvo_busy"] = true
                                pcall(function()
                                    remote:FireServer("ShootGun", handle, origin, pos, part, shot_direction, unpack(args, 7))
                                end)
                                hide_manager["salvo_busy"] = false
                            end

                            if salvo_delay > 0 then
                                task["delay"](salvo_delay, send_held)
                            else
                                task["defer"](send_held)
                            end
                        end

                        return first
                    end

                    -- Legit tab: Bullet Manipulation claims the silent aim shot on its target the way the ragebot's shots are claimed, and Force Hit
                    -- sends it at the head whatever the hit checker says (hide_manager.legit_rebuild: nil = leave the shot alone, false = do not send it)
                    local legit_rebuild = hide_manager["legit_rebuild"]

                    if legit_rebuild then
                        local rebuild_ok, rebuilt = pcall(legit_rebuild, args)

                        if rebuild_ok and rebuilt == false then
                            return
                        end

                        if rebuild_ok and rebuilt then
                            local first = old_namecall(self, "ShootGun", args[2], rebuilt[1], rebuilt[2], rebuilt[3], rebuilt[4], unpack(args, 7))
                            hide_manager["manipulated_at"] = clock()
                            local claim_tool = typeof(args[2]) == "Instance" and args[2]["Parent"] or nil
                            hide_manager["last_claim"] = {rebuilt[2], clock(), claim_tool ~= nil and hide_manager["pellets_of"] ~= nil and hide_manager["pellets_of"](claim_tool) > 1}
                            getgenv()["neverlose_last_claim"] = hide_manager["last_claim"]
                            spawn(get_bullet_result, rebuilt[5], rebuilt[3])
                            return first
                        end
                    end

                    -- bullet manipulation's hit checker: a shot that would miss the locked target is never sent
                    if silent_shot_gate and not silent_shot_gate(args) then
                        return
                    end

                    local part = args[5]

                    if part then
                        local parent = part["Parent"]

                        if parent then
                            local player = find_first_child(players_service, parent["Name"]) or find_first_child(players_service, parent["Parent"]["Name"])

                            if player then
                                if parent["GetAttribute"](parent, "1") then
                                    part = player_data[player][4][part["Name"]]
                                    args[5] = part
                                    spawn(get_bullet_result, player, part)
                                    return old_namecall(self, unpack(args))
                                end

                                spawn(get_bullet_result, player, part)
                            end
                        end
                    end
                elseif packet == "UpdateCursorImage" and flags["unlock_custom_crosshair"] then
                    local value = args[2]
                    inventory["Parent"]["CursorImage"]["Value"] = value
                    return
                elseif packet == "CHECKER_4" or packet == "CalculateShootClient" then
                    print(packet)
                    return
                end
            end
            return old_namecall(self, ...)
        end)),
        ["__index"] = newcclosure(function(s, i)
            if i == "OnClientEvent" and not getfenv(0).closeTop25Button then
                return f
            end
            return o_i(s, i)
        end)
    }

    for _, v in old do
        if not new[_] then
            new[_] = v
        end
    end

    setrawmetatable(event, new)
end

-- > ( shop )

do
    local item_section = menu["groups"]["misc."]:create_panel_section("shop", "items", 1, true)
    menu_references["items_section"] = item_section
    menu_references["panel_section"] = menu["groups"]["misc."]:create_section("shop", "panel", 2, 0.65)
    menu_references["theme_section"] = menu["groups"]["misc."]:create_section("shop", "settings", 2, 0.35, 0.65)

    local guns = {}

    LPH_JIT_MAX(function()
        local armor_image_data = base64_decode("")
        local food_image_data = base64_decode("")
        local gun_image_data = base64_decode("")
        local misc_image_data = base64_decode("")

        local gun_names = get_children(wait_for_child(wait_for_child(replicated_storage, "SkinModules", 9e9), "GunModels", 9e9))

        for i = 1, #gun_names do
            -- a model without a [name] in its name has no gun to list
            local name = string["lower"](gun_names[i]["Name"]:match("%[(.-)%]") or "")
            if name ~= "knife" and name ~= "" then
                guns[name] = true
            end
        end

        -- Ignored or its Shop folder missing: no shop items, but the rest of the script still loads.
        local shop_folder = ignored and find_first_child(ignored, "Shop")
        local parts = shop_folder and get_children(shop_folder) or {}

        for i = 1, #parts do
            local shop = parts[i]
            local item = string["lower"](shop["Name"])

            local ammo, name, price = item:match("^(%d*)%s*%[(.-)%]%s*[%-%=]%s*%$(%d+)")

            if price then
                price = tonumber(price)
            end

            if name ~= "flashlight" and name ~= "flowers" and name ~= "antibodies" and name and price and price > 0 then
                local head = find_first_child(shop, "Head")
                local click_detector = find_first_child_of_class(shop, "ClickDetector")

                if head and click_detector then
                    local old = shops[name]
                    local show = old and (old[2] > price)
                    if not old or show then
                        if show then
                            item_section:remove_item(name)
                        end

                        shops[name] = {
                            head["Position"],
                            price,
                            click_detector,
                            tonumber(ammo) or false,
                            false,
                            name,
                            head
                        }
                    end
                end
            end
        end

        for item, shop in shops do
            if item:find("armor") then
                shop[5] = 1
                item_section:add_item({
                    ["text"] = item,
                    ["icons"] = {
                        armor_image_data
                    },
                    ["favoriting"] = true
                })
            end
        end

        for item, shop in shops do
            if guns[item] then
                shop[5] = 1
                item_section:add_item({
                    ["text"] = item,
                    ["icons"] = {
                        gun_image_data
                    },
                    ["favoriting"] = true
                })
            end
        end

        for item, shop in shops do
            if shop[2] < 13 then
                shop[5] = 1
                item_section:add_item({
                    ["text"] = item,
                    ["icons"] = {
                        food_image_data
                    },
                    ["favoriting"] = true
                })
            end
        end

        for item, shop in shops do
            if not shop[5] and not shop[4] then
                item_section:add_item({
                    ["text"] = item,
                    ["icons"] = {
                        misc_image_data
                    },
                    ["favoriting"] = true
                })
            end
        end
    end)()

    -- >> ( purchasing )

    local new_bought_count = 0
    local purchase_count = 1
    local start_time = clock()
    local old_equipped = {}

    local position = nil
    local detector = nil
    local is_ammo = false

    -- Backoff for a purchase the server keeps refusing. Auto ammo, armour, food, mask and loadout all go through purchase_item and
    -- would ask again every few frames for ever (an ammo pack the server would not sell was being asked for about every 0.8 s), a
    -- stream of shop clicks at the server. Every refusal doubles the wait for that item, 0.5 s up to 8 s, and a sale resets it.
    local PURCHASE_BACKOFF_MAX = 8
    local purchase_failures = {}
    local purchase_blocked_until = {}
    local purchase_function = nil; purchase_function = LPH_JIT_MAX(function(dt, hrp)
        local stop = false
        if flags["safe_purchasing"] and purchasing then
            local avoid_enemy = false
            local avoid_target = false
            local avoid_friendly = false
            local avoid_neutral = false

            local shop_position = purchasing[1]
            for _, option in flags["safe_purchasing_avoid_statuses"] do
                if option == "enemy" then
                    avoid_enemy = true
                elseif option == "target" then
                    avoid_target = true
                elseif option == "friendly" then
                    avoid_friendly = true
                elseif option == "neutral" then
                    avoid_neutral = true
                end
            end

            for player, data in player_data do
                if not data[7] and not data[18] then
                    local status = data[1]

                    if (status == 3 and avoid_enemy) or (status == 2 and avoid_friendly) or (status == 1 and avoid_neutral) or (ragebot_target == data and avoid_target) then
                        local hrp = data[4]["HumanoidRootPart"]

                        if hrp and (shop_position-hrp["Position"])["magnitude"] < 50 then
                            stop = true
                            break
                        end
                    end
                end
            end
        end
        
        -- "<" so a counter that overshot (two cash drops in one frame) still ends the loop.
        local didnt_buy = local_bought_count < new_bought_count
        local ping = local_ping/1000
        local skip = purchasing and purchasing[6]:find("armor") or not purchasing
        
        if not stop and (didnt_buy and hrp and clock() - start_time < (local_reloading and 2 + ping * 2 or ping*2 + purchase_count*0.36) and (not is_ammo or not local_reloading)) then
            if not skip then
                for gun, data in local_guns do
                    local gun = gun["Parent"]
                    if gun and gun["Parent"] == local_character then
                        setscriptable(gun, "Parent", true)
                        gun["Parent"] = local_player["Backpack"]
                    end
                end
            end

            fireclickdetector(detector)
            -- Position saved before this frame's other anti aim steps moved the character: reading the part here can return a void one.
            local old_cframe = local_client_position

            if not in_void then
                hrp["CFrame"] = cframe_new(position - vector3_new(0,8.8,0))
            end

            render_stepped_wait(render_stepped)
            hrp["CFrame"] = old_cframe
        else
            local old_purchasing = purchasing
            -- The count this purchase was waiting for: the next one may have moved new_bought_count on by the time the check below runs, which made
            -- a sale that went through look like a refusal.
            local counted = new_bought_count

            -- Held back by safe purchasing: the auto buys would ask again at once (every 0.05 s or so), each time with two notifications.
            if stop and old_purchasing then
                purchase_blocked_until[old_purchasing[6]] = clock() + 1
            end

            spawn(function()
                wait(local_ping/250)
                if local_bought_count < counted then
                    -- only the server's own refusal counts, not a purchase safe purchasing held back
                    if not stop then
                        local failures = (purchase_failures[old_purchasing[6]] or 0) + 1

                        purchase_failures[old_purchasing[6]] = failures
                        purchase_blocked_until[old_purchasing[6]] = clock() + math.min(0.5 * 2^(failures - 1), PURCHASE_BACKOFF_MAX)
                    end

                    new_notification(
                        stop and "failed to purchase "..old_purchasing[6].." (due to safe purchasing)" or "failed to purchase "..old_purchasing[6],
                        3
                    )
                else
                    purchase_failures[old_purchasing[6]] = nil
                    purchase_blocked_until[old_purchasing[6]] = nil

                    new_notification(
                        "successfully purchased "..old_purchasing[6],
                        1
                    )
                end
            end)

            for i = 1, #anti_aim do
                if anti_aim[i] == purchase_function then
                    remove(anti_aim, i)
                    purchasing = false
                    break
                end
            end

            if not skip or old_equipped["carry"] then
                if #old_equipped > 0 then
                    for _, tool in old_equipped do
                        if typeof(tool) == "Instance" then
                            setscriptable(tool, "Parent", true)
                            tool["Parent"] = local_character
                        end
                    end
                end

                old_equipped["carry"] = nil
            end
        end
    end)

    purchase_item = LPH_JIT_MAX(function(item, ammo)
        -- A pack count of 0 (the auto ammo and auto loadout sliders go down to 0) buys nothing: it would only run a purchase cycle and notify about it.
        if type(ammo) == "number" and ammo <= 0 then
            return
        end

        local shop = shops[item]
        -- old_equipped is rebuilt below once the purchase really starts; clearing it here would forget what a purchase that is
        -- still running has to put back in the hand.
        if shop then
            if purchasing then
                if not item:find("armor") or purchasing[6]:find("armor") then
                    return
                end
            end

            -- A pack of ammo cannot be bought while a reload runs: the click is refused and the item then waits out a longer backoff
            -- every time, so with the reload gate busy the guns never got restocked. Ask again once the reload is over instead.
            if item:find("ammo") and local_reloading then
                return
            end

            local blocked_until = purchase_blocked_until[shop[6]]

            if blocked_until and clock() < blocked_until then
                return
            end

            local item = shop[6]

            new_notification(
                "attempting to purchase "..item,
                2
            )

            start_time = clock()
            local found = false

            for i = 1, #anti_aim do
                if anti_aim[i] == purchase_function then
                    found = true
                end
            end

            is_ammo = item:find("ammo")
            position, detector = shop[1], shop[3]
            new_bought_count = ammo and local_bought_count + ammo or local_bought_count + 1
            purchase_count = ammo or 1

            if purchasing then
                -- Armor started over a purchase that is still running: that one has already put the guns in the bag (they are no longer in the hand to be read
                -- again), and nothing else would give them back, so the list stays and the armor purchase puts them back when it is done.
                old_equipped["carry"] = true
            else
                old_equipped = {local_tool}
                for gun, data in local_guns do
                    old_equipped[#old_equipped+1] = gun["Parent"]
                end
            end

            purchasing = shop

            if not found then
                anti_aim[#anti_aim+1] = purchase_function
            end
        end
    end)

    -- >> ( purchase coordination )
    -- A purchase has to walk the character to the shop, and a void step in the same frame leaves in_void set, which makes
    -- the purchase skip that walk and fail. So the void hide (the Void Hide toggle and the spam, and the hide manager's own
    -- reasons) steps aside for as long as a purchase runs, whichever auto buy started it (ammo, armour, food, mask,
    -- loadout all go through purchase_item), plus a short gap after it so back to back purchases don't dip in and out of
    -- the void between them. Nothing is switched off: the void hide settings stay as the user saved them and its steps
    -- simply carry on once this lets go. It lets go on its own (the purchase runner is gone, or the gap ran out), so a
    -- purchase that failed, was cancelled or ended with the character dying can't leave the void held back.
    local PURCHASE_RESUME_GAP = 0.25
    local purchase_hold_until = 0

    hide_manager["purchase_holds_void"] = LPH_NO_VIRTUALIZE(function()
        local now = clock()

        if purchasing then
            for i = 1, #anti_aim do
                if anti_aim[i] == purchase_function then
                    purchase_hold_until = now + PURCHASE_RESUME_GAP
                    return true
                end
            end
        end

        return now < purchase_hold_until
    end)

    -- a new character starts clean
    create_connection(signals["on_local_character_added"], function()
        purchase_hold_until = 0
    end)
    local item_cost = menu_references["panel_section"]:create_element({["name"] = "cost"}, {["info"] = {}})
    item_cost:set_visible(false)
    item_cost:set_info("Color", color3_fromrgb(129, 173, 126))

    create_connection(menu_references["items_section"]["on_selection_change"], function(selected)
        if selected then
            local item = shops[selected]
            local has_ammo = shops[selected.." ammo"] ~= nil
            item_cost:set_info("Text", "$"..item[2])
            item_cost:set_visible(true)
            menu_references["purchase_item"]:set_visible(true)
            menu_references["purchase_ammo"]:set_visible(has_ammo)
            menu_references["ammo_amount"]:set_visible(has_ammo)
        else
            item_cost:set_visible(false)
            menu_references["purchase_item"]:set_visible(false)
            menu_references["purchase_ammo"]:set_visible(false)
            menu_references["ammo_amount"]:set_visible(false)
        end
    end)

    menu_references["purchase_item"] = menu_references["panel_section"]:create_element({["name"] = "purchase item"}, {["button"] = {}})
    create_connection(menu_references["purchase_item"]["on_clicked"], function()
        local selected = menu_references["items_section"]["selected"]["name"]
        if selected then
            local shop = shops[selected]
            if local_cash > shop[2] then
                purchase_blocked_until[shop[6]] = nil
                purchase_item(selected)
            else
                new_notification(
                    "failed to purchase item due to insufficient funds",
                    3
                )
            end
        end
    end)
    menu_references["purchase_item"]:set_visible(false)

    menu_references["ammo_amount"] = menu_references["panel_section"]:create_element({["name"] = "ammo amount"}, {["slider"] = {["min"] = 1, ["max"] = 50, ["suffix"] = "x", ["flag"] = "ammo_amount", ["prefix"] = "", ["default"] = 1}})
    menu_references["ammo_amount"]:set_visible(false)

    menu_references["purchase_ammo"] = menu_references["panel_section"]:create_element({["name"] = "purchase ammo"}, {["button"] = {}})
    menu_references["purchase_ammo"]:set_visible(false)

    create_connection(menu_references["purchase_ammo"]["on_clicked"], LPH_JIT_MAX(function()
        local selected = menu_references["items_section"]["selected"]["name"]
        if selected then
            local ammo_name = selected.." ammo"
            local shop = shops[ammo_name]
            local ammo = flags["ammo_amount"]
            if local_cash > shop[2] * ammo then
                local has = false
                local name = selected.."]"
                for _, tool in get_children(local_player["Backpack"]) do
                    if string.find(tool["Name"]:lower(), name, 1, true) then
                        has = true
                        break
                    end
                end

                if local_tool and not has then
                    has = local_tool["Name"]:lower():find(selected, 1, true)
                end

                if has then
                    purchase_blocked_until[shop[6]] = nil
                    purchase_item(ammo_name, ammo)
                else
                    new_notification(
                        "failed to purchase ammo due to missing gun",
                        3
                    )
                end
            else
                new_notification(
                    "failed to purchase ammo due to insufficient funds",
                    3
                )
            end
        end
    end))
end

-- > ( movement )

do
    menu_references["movement_section"] = menu["groups"]["misc."]:create_section("main", "movement", 1, 0.6, 0)

    -- >> ( removals )

    menu_references["remove_jump_cooldown"] = menu_references["movement_section"]:create_element({["name"] = "remove jump cooldown"}, {["toggle"] = {["flag"] = "remove_jump_cooldown"}})
    menu_references["remove_slowdowns"] = menu_references["movement_section"]:create_element({["name"] = "remove slowdowns"}, {["toggle"] = {["flag"] = "remove_slowdowns"}})
    menu_references["lock_walk_speed"] = menu_references["movement_section"]:create_element({["name"] = "lock walk speed"}, {["toggle"] = {["flag"] = "lock_walk_speed"}})

    -- >> ( jump power )

    menu_references["jump_power"] = menu_references["movement_section"]:create_element({["name"] = "jump power"}, {["toggle"] = {["flag"] = "jump_power"}})
    menu_references["jump_power_settings"] = menu_references["jump_power"]:create_settings()
    menu_references["jump_power_value"] = menu_references["jump_power_settings"]:create_element({["name"] = "power"}, {["slider"] = {["flag"] = "jump_power_value", ["min"] = 0, ["max"] = 1000, ["default"] = 50}})

    -- >> ( anti sit )

    menu_references["anti_trip"] = menu_references["movement_section"]:create_element({["name"] = "anti trip"}, {["toggle"] = {["flag"] = "anti_trip"}})

    local anti_trip_sat_connection = nil
    local anti_trip_character_added_connection = nil

    local do_anti_trip = LPH_NO_VIRTUALIZE(function()
