            ["Brick"] = "http://www.roblox.com/asset/?id=10777285622",
            ["Concrete"] = "http://www.roblox.com/asset/?id=15622710576",
            ["CorrodedMetal"] = "rbxassetid://78612695839404",
            ["Metal"] = "http://www.roblox.com/asset/?id=121650613091353",
            ["WoodPlanks"] = "http://www.roblox.com/asset/?id=8676581022"
        },
    }
    local restores = {}
    local textures = texture_packs["minecraft"]
    local variants = {}

    menu_references["textures"] = menu_references["lighting_section"]:create_element({["name"] = "textures"}, {["toggle"] = {["flag"] = "textures"}})
        menu_references["textures_settings"] = menu_references["textures"]:create_settings()
        menu_references["textures_pack"] = menu_references["textures_settings"]:create_element({["name"] = "pack"}, {["dropdown"] = {["flag"] = "textures_pack", ["options"] = {"minecraft"}, ["default"] = {"minecraft"}, ["use_custom_extensions"] = {"json", "txt", "ink", "textures"}, ["requires_one"] = true}})

    local apply_texture = LPH_NO_VIRTUALIZE(function(descendant)
        local class_name = descendant["ClassName"]
        local white = color3_fromrgb(254, 253, 255)

        if class_name == "MeshPart" or class_name == "Part" then
            local texture = textures[descendant["Material"]["Name"]]

            if (texture or descendant["Color"] == white) and descendant["Transparency"] < 0.8 then
                if not restores[descendant] then
                    restores[descendant] = descendant["Color"]

                    descendant["Color"] = white
                end
            end
        end
    end)

    local apply_textures = LPH_NO_VIRTUALIZE(function()
        for i = 1, #variants do
            destroy(variants[i])
            variants[i] = nil
        end

        for name, id in textures do
            if name ~= "Glass" then
                local material = create_instance("MaterialVariant", {
                    ["MetalnessMap"] = id,
                    ["NormalMap"] = id,
                    ["BaseMaterial"] = Enum["Material"][name],
                    ["Name"] = name,
                    ["StudsPerTile"] = 5,
                    ["RoughnessMap"] = id,
                    ["Parent"] = material_service,
                    ["ColorMap"] = id,
                })
                variants[#variants+1] = material
            end
        end

        local descendants = workspace["MAP"]:GetDescendants()

        for i = 1, #descendants do
            apply_texture(descendants[i])

            -- A frame's worth at a time instead of the whole map at once (the toggle froze the game for a moment). Stops if textures went off meanwhile.
            if i % 1500 == 0 then
                wait()

                if not textures_connection then
                    return
                end
            end
        end
    end)

    local get_textures = LPH_JIT_MAX(function(value)
        local path = "neverlose recode/custom/"..value

        if isfile(path) then
            local s, data = pcall(function()
                return http_service:JSONDecode(readfile(path))
            end)

            if s and data then
                local texture_pack = {}

                for property, value in data do
                    texture_pack[property] = value
                end

                texture_packs[value] = texture_pack

                textures = texture_pack
                if textures_connection then
                    apply_textures()
                end
            else
                new_notification(
                    "failed to load file "..value,
                    3
                )
            end
        end
    end)

    create_connection(menu_references["textures"]["on_toggle_change"], LPH_JIT_MAX(function(value)
        if textures_connection then
            textures_connection:Disconnect()
            textures_connection = nil
        end

        if value then
            textures_connection = create_connection(workspace["MAP"]["DescendantAdded"], apply_texture)
            apply_textures()
        else
            for i = 1, #variants do
                destroy(variants[i])
                variants[i] = nil
            end
            for part, data in restores do
                part["Color"] = data
                restores[part] = nil
            end
        end
    end))

    create_connection(menu_references["textures_pack"]["on_dropdown_change"], LPH_NO_VIRTUALIZE(function(value)
        local value = value[1]
        textures = texture_packs[value]

        if not textures then
            get_textures(value)
            textures = texture_packs[value]
        end

        textures = texture_packs[value]
    end))

    -- >> ( ambient )

    menu_references["ambient"] = menu_references["lighting_section"]:create_element({["name"] = "ambient"}, {["toggle"] = {["flag"] = "ambient"}})
        menu_references["ambient_settings"] = menu_references["ambient"]:create_settings()
        menu_references["ambient_outdoor_color"] = menu_references["ambient_settings"]:create_element({["name"] = "outdoor color"}, {["colorpicker"] = {["color_flag"] = "outdoor_color", ["default_color"] = lighting["OutdoorAmbient"], ["default_transparency"] = 0, ["transparency_flag"] = "outdoor_transparency"}})
        menu_references["ambient_color"] = menu_references["ambient_settings"]:create_element({["name"] = "color"}, {["colorpicker"] = {["color_flag"] = "ambient_color", ["default_color"] = lighting["Ambient"], ["default_transparency"] = 0, ["transparency_flag"] = "ambient_transparency"}})

    create_connection(menu_references["ambient"]["on_toggle_change"], function(value)
        if value then
            spoofing["Ambient"] = true
            lighting["Ambient"] = flags["ambient_color"]
            spoofing["OutdoorAmbient"] = true
            lighting["OutdoorAmbient"] = flags["outdoor_color"]
        else
            spoofing["Ambient"] = false
            spoofing["OutdoorAmbient"] = false
            lighting["Ambient"] = original["Ambient"]
            lighting["OutdoorAmbient"] = original["OutdoorAmbient"]
        end
    end)

    create_connection(menu_references["ambient_color"]["on_color_change"], function(color)
        if flags["ambient"] then
            lighting["Ambient"] = color
        end
    end)

    create_connection(menu_references["ambient_outdoor_color"]["on_color_change"], function(color)
        if flags["ambient"] then
            lighting["OutdoorAmbient"] = color
        end
    end)

    -- >> ( weather )

    menu_references["weather"] = menu_references["lighting_section"]:create_element({["name"] = "weather"}, {["toggle"] = {["flag"] = "weather"}})
        menu_references["weather_settings"] = menu_references["weather"]:create_settings()
        menu_references["weather_type"] = menu_references["weather_settings"]:create_element({["name"] = "type"}, {["dropdown"] = {["flag"] = "weather_type", ["options"] = {"light rain", "rain", "snow"}, ["default"] = {"rain"}, ["requires_one"] = true}})
        menu_references["weather_color"] = menu_references["weather_settings"]:create_element({["name"] = "color"}, {["colorpicker"] = {["color_flag"] = "weather_color", ["default_color"] = color3_fromrgb(255, 255, 255), ["default_transparency"] = 0, ["transparency_flag"] = "weather_transparency"}})
        menu_references["weather_rate"] = menu_references["weather_settings"]:create_element({["name"] = "rate"}, {["slider"] = {["flag"] = "weather_rate", ["min"] = 1, ["max"] = 100, ["default"] = 100, ["suffix"] = "%"}})

    local weather_part = nil
    local weather_particle = nil
    local weather_settings = {
        ["type"] = "rain",
        ["color"] = color3_fromrgb(255, 255, 255),
        ["transparency"] = 0,
        ["rate"] = 1
    }

    -- The weather draws its own textures: the game's particle textures are sparkles, which looked like falling glitter. Rain is a thin streak
    -- drawn along the texture's X axis (that is the axis VelocityParallel lines up with the fall; drawn up and down it lay on its side),
    -- snow is a soft round dot. They are small PNGs written next to the configs.
    local weather_texture_data = {
        ["streak"] = "",
        ["dot"] = ""
    }
    local weather_textures = {}

    local weather_texture = LPH_NO_VIRTUALIZE(function(kind)
        local cached = weather_textures[kind]

        if cached then
            return cached
        end

        -- a new name for the turned streak: a file name that was loaded before can come back from the executor's cache as the old picture
        local path = "NeverLoseConfigs/weather_"..kind.."_v2.png"

        local written = pcall(function()
            if not isfolder("NeverLoseConfigs") then
                makefolder("NeverLoseConfigs")
            end

            writefile(path, base64_decode(weather_texture_data[kind]))
        end)

        local loaded, asset = pcall(getcustomasset, path)

        cached = (written and loaded and asset) or "rbxasset://textures/particles/sparkles_main.dds"
        weather_textures[kind] = cached

        return cached
    end)

    -- emitter settings per type; particles fall from a plate that hovers over the camera and follows it.
    -- The plate is small and the rates high: spread thin over a big plate there were only a few specks in view.
    -- The fall (speed * lifetime) is long enough to pass the camera and reach well below it.
    -- "alpha" is the type's own see-through amount (the menu's transparency adds to it), "spin" turns snow, "spread" scatters it sideways.
    weather_settings["height"] = 45
    local weather_types = {
        ["light rain"] = {["texture"] = "streak", ["streak"] = true, ["rate"] = 1500, ["speed"] = 85, ["size"] = 2.2, ["lifetime"] = 1.05, ["drift"] = 0, ["light"] = 0.25, ["alpha"] = 0.5, ["spin"] = 0, ["spread"] = 0},
        ["rain"] = {["texture"] = "streak", ["streak"] = true, ["rate"] = 3600, ["speed"] = 125, ["size"] = 3.4, ["lifetime"] = 0.85, ["drift"] = 0, ["light"] = 0.3, ["alpha"] = 0.3, ["spin"] = 0, ["spread"] = 0},
        ["snow"] = {["texture"] = "dot", ["streak"] = false, ["rate"] = 500, ["speed"] = 9, ["size"] = 0.4, ["lifetime"] = 11, ["drift"] = 2, ["light"] = 0.15, ["alpha"] = 0.05, ["spin"] = 35, ["spread"] = 18}
    }

    local apply_weather = LPH_NO_VIRTUALIZE(function()
        if not weather_particle then
            return
        end

        local preset = weather_types[weather_settings["type"]] or weather_types["rain"]

        weather_particle["Texture"] = weather_texture(preset["texture"])
        weather_particle["Orientation"] = preset["streak"] and Enum["ParticleOrientation"]["VelocityParallel"] or Enum["ParticleOrientation"]["FacingCamera"]
        weather_particle["Rate"] = preset["rate"] * weather_settings["rate"]
        weather_particle["Speed"] = NumberRange["new"](preset["speed"] * 0.9, preset["speed"] * 1.1)
        weather_particle["Lifetime"] = NumberRange["new"](preset["lifetime"] * 0.9, preset["lifetime"] * 1.1)
        weather_particle["Size"] = NumberSequence["new"](preset["size"])
        weather_particle["Acceleration"] = vector3_new(preset["drift"], 0, 0)
        weather_particle["LightEmission"] = preset["light"]
        weather_particle["Color"] = ColorSequence["new"](weather_settings["color"])
        weather_particle["Transparency"] = NumberSequence["new"](1 - (1 - preset["alpha"]) * (1 - weather_settings["transparency"]))
        weather_particle["Rotation"] = NumberRange["new"](0, preset["spin"] > 0 and 360 or 0)
        weather_particle["RotSpeed"] = NumberRange["new"](-preset["spin"], preset["spin"])
        weather_particle["SpreadAngle"] = vector2_new(preset["spread"], preset["spread"])
    end)

    -- the plate lives in the terrain: the game removes everything that is parented to the camera
    local do_weather = LPH_NO_VIRTUALIZE(function()
        local current_camera = workspace["CurrentCamera"]

        if weather_part and current_camera then
            if weather_part["Parent"] ~= workspace["Terrain"] then
                pcall(function()
                    weather_part["Parent"] = workspace["Terrain"]
                end)
            end

            weather_part["CFrame"] = cframe_new(current_camera["CFrame"]["Position"] + vector3_new(0, weather_settings["height"], 0))
        end
    end)

    local stop_weather = LPH_NO_VIRTUALIZE(function()
        for i = 1, #heartbeat do
            if heartbeat[i] == do_weather then
                remove(heartbeat, i)
                break
            end
        end

        if weather_part then
            destroy(weather_part)
            weather_part = nil
            weather_particle = nil
        end
    end)

    create_connection(menu_references["weather"]["on_toggle_change"], function(value)
        stop_weather()

        if not value then
            return
        end

        local current_camera = workspace["CurrentCamera"]

        if not current_camera then
            return
        end

        weather_part = create_instance("Part", {
            ["Name"] = "\0",
            ["Anchored"] = true,
            ["CanCollide"] = false,
            ["CanQuery"] = false,
            ["CanTouch"] = false,
            ["Transparency"] = 1,
            ["Size"] = vector3_new(90, 1, 90),
            ["CFrame"] = cframe_new(current_camera["CFrame"]["Position"] + vector3_new(0, weather_settings["height"], 0)),
            ["Parent"] = workspace["Terrain"]
        })

        -- particles stay where they were emitted, so moving the camera sweeps through the rain
        weather_particle = create_instance("ParticleEmitter", {
            ["EmissionDirection"] = Enum["NormalId"]["Bottom"],
            ["LightInfluence"] = 0,
            ["LockedToPart"] = false,
            ["Parent"] = weather_part
        })

        apply_weather()
        heartbeat[#heartbeat+1] = do_weather
    end)

    create_connection(menu_references["weather_type"]["on_dropdown_change"], function(value)
        weather_settings["type"] = value[1] or "rain"
        apply_weather()
    end)

    create_connection(menu_references["weather_color"]["on_color_change"], function(value)
        weather_settings["color"] = value
        apply_weather()
    end)

    create_connection(menu_references["weather_color"]["on_transparency_change"], function(value)
        weather_settings["transparency"] = value
        apply_weather()
    end)

    create_connection(menu_references["weather_rate"]["on_slider_change"], function(value)
        weather_settings["rate"] = value/100
        apply_weather()
    end)

