-- >> ( game )

do
    local numbersequencekeypointnew = NumberSequenceKeypoint["new"]
    local numbersequencenew = NumberSequence["new"]
    local get_attribute = local_player["GetAttribute"]
    local local_name = local_player["Name"]

    local on_player_bullet_fired = signals["on_player_bullet_fired"]
    local on_local_bullet_fired = signals["on_local_bullet_fired"]
    local on_rpg_fired = signals["on_rpg_fired"]

    create_connection(ignored["Siren"]["Radius"]["ChildAdded"], LPH_NO_VIRTUALIZE(function(object)
        wait()
        local name = object["Name"]
        if name == "BULLET_RAYS" then
            -- A skin with a tracer of its own (SkinAssets.GunBeam) puts its beam in the shot as well, and it may not be the first one or have its
            -- end set yet: the first beam (anywhere in the shot) that has both ends is used, waiting up to twenty frames for one.
            local beam = nil

            for _ = 1, 20 do
                for _, item in object:GetDescendants() do
                    if item:IsA("Beam") and item["Attachment0"] and item["Attachment1"] then
                        beam = item
                        break
                    end
                end

                if beam or not object["Parent"] then
                    break
                end

                wait()
            end

            if beam then
                local cframe = beam["Attachment1"]["WorldCFrame"]
                if get_attribute(object, "OwnerCharacter") == local_name then
                    local now = clock()
                    local start = beam["Attachment0"] and beam["Attachment0"]["WorldPosition"] or cframe["Position"]

                    -- One Line For Shotguns: the pellets of one shotgun shot come in the same moment from the same muzzle; only the first is drawn
                    local last = hide_manager["last_local_ray"]
                    hide_manager["last_local_ray"] = {now, start}

                    if flags["local_bullet_tracers_one_line"] and flags["local_bullet_tracers"] and last and now - last[1] < 0.05 and (last[2] - start)["Magnitude"] < 3 then
                        destroy(object)
                        return
                    end

                    -- The game draws the shot where the gun was pointed; a shot the ragebot or the silent aim claimed somewhere else ends at that
                    -- claim (the target) instead, so the tracer shows where the bullet was sent.
                    local claim = hide_manager["last_claim"]

                    -- (not a shotgun's: its pellets keep the ends the game gave them, so the spread shows)
                    if claim and not claim[3] and now - claim[2] < 0.5 and typeof(claim[1]) == "Vector3" then
                        cframe = cframe_new(claim[1])
                    end

                    on_local_bullet_fired:Fire(object, beam, cframe, true)
                else
                    on_player_bullet_fired:Fire(object, beam, cframe, false)
                end
            end
        end
    end))

    create_connection(ignored["ChildAdded"], LPH_NO_VIRTUALIZE(function(object)
        wait()
        if object["Name"] == "Model" then
            local launcher = wait_for_child(object, "Launcher", 5)

            if launcher then
                on_rpg_fired:Fire(launcher, launcher["CFrame"]["lookVector"]*-1000)
            end
        end
    end))

    menu_references["hud_section"] = menu["groups"]["visuals"]:create_section("general", "hud", 1, 0.35, 0.65)
