    -- >> show chat

    do
        local text_chat_service = cloneref(game["GetService"](game, "TextChatService"))

        create_connection(menu_references["show_chat"]["on_toggle_change"], function(value)
            text_chat_service["ChatWindowConfiguration"]["Enabled"] = value
        end)
    end

    -- >> ( aspect ratio )

    local multiplier = cframe_new(0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0, 1)
    local last_tween_value = 0

    local tween_function = nil

    local do_aspect_ratio = LPH_NO_VIRTUALIZE(function(dt)
        render_stepped_wait(render_stepped)
        camera["CFrame"]*=multiplier
    end)

    local tween_ratio = LPH_JIT_MAX(function(new_value, force)
        if tween_function then
            for i = 1, #heartbeat do
                if heartbeat[i] == tween_function then
                    remove(heartbeat, i)
                    break
                end
            end
        end

        local elapsed_time = 0
        local old_last_tween_value = last_tween_value

        local new_tween_function = function(dt)
            elapsed_time+=dt
            last_tween_value = old_last_tween_value + (new_value - old_last_tween_value) * get_value(tween_service, elapsed_time/0.16, circular, out)
            multiplier = cframe_new(0, 0, 0, 1, 0, 0, 0, last_tween_value, 0, 0, 0, 1)
            if force then
                render_stepped_wait(render_stepped)
                camera["CFrame"]*=multiplier
            end
        end

        tween_function = new_tween_function

        multiplier = cframe_new(0, 0, 0, 1, 0, 0, 0, last_tween_value, 0, 0, 0, 1)

        heartbeat[#heartbeat+1] = tween_function

        delay(0.16, function()
            for i = 1, #heartbeat do
                if heartbeat[i] == new_tween_function then
                    remove(heartbeat, i)
                    multiplier = cframe_new(0, 0, 0, 1, 0, 0, 0, new_value, 0, 0, 0, 1)
                    break
                end
            end
        end)
    end)

    create_connection(menu_references["aspect_ratio"]["on_toggle_change"], function(value)
        for i = 1, #heartbeat do
            if heartbeat[i] == do_aspect_ratio then
                remove(heartbeat, i)
                break
            end
        end

        if value then
            last_tween_value = 1
            multiplier = cframe_new(0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0, 1)
            tween_ratio(flags["aspect_ratio_value"])
            heartbeat[#heartbeat+1] = do_aspect_ratio
        else
            tween_ratio(1, true)
        end
    end)

    create_connection(menu_references["aspect_ratio"]["on_slider_change"], function(value)
        tween_ratio(value)
    end)

    -- >> ( score against the target )
    -- Kills and deaths against each player, for the center panel's target line. A player counts for me when they go down (knocked, or dead without it)
    -- while the game's own LastDamager (BodyEffects) names me; I count for them the same way. Once per life, so a knock followed by the death is one.
    hide_manager["scores"] = {}
    hide_manager["scored"] = setmetatable({}, {["__mode"] = "k"})

    hide_manager["damager_of"] = function(character)
        local body = character and find_first_child(character, "BodyEffects")
        local value = body and find_first_child(body, "LastDamager")
        local damager = value and value["Value"]

        if typeof(damager) == "Instance" then
            return damager["Name"]
        end

        return nil
    end

    hide_manager["score_of"] = function(player)
        local entry = hide_manager["scores"][player]

        if not entry then
            entry = {["mine"] = 0, ["theirs"] = 0}
            hide_manager["scores"][player] = entry
        end

        return entry
    end

    do
        local function credit(data)
            local character = data[3]

            if not character or data[2] == local_player or hide_manager["scored"][character] then
                return
            end

            if hide_manager["damager_of"](character) == local_player["Name"] then
                hide_manager["scored"][character] = true
                hide_manager["score_of"](data[2])["mine"] += 1
            end
        end

        local function lost()
            local character = local_character

            if not character or hide_manager["scored"][character] then
                return
            end

            local name = hide_manager["damager_of"](character)
            local attacker = name and name ~= local_player["Name"] and find_first_child(players_service, name) or nil

            if attacker then
                hide_manager["scored"][character] = true
                hide_manager["score_of"](attacker)["theirs"] += 1
            end
        end

        create_connection(signals["on_player_knocked"], function(data, knocked)
            if knocked then
                credit(data)
            end
        end)

        create_connection(signals["on_player_died"], function(data)
            credit(data)
        end)

        create_connection(signals["on_local_knocked"], function(value)
            if value then
                lost()
            end
        end)

        create_connection(signals["on_local_health_changed"], function(health)
            if type(health) == "number" and health <= 0 then
                lost()
            end
        end)
    end

    -- the line under the center panel's state: who is being killed, how sure the resolver is, and the score
    hide_manager["cp_target_update"] = function(anchor)
        local line = hide_manager["cp_target"]

        if not line then
            return
        end

        local player = ragebot_target and ragebot_target[2] or nil

        if flags["center_panel_show_target"] == false or not flags["ragebot"] or not player or not player["Parent"] then
            if line["Visible"] then
                line["Visible"] = false
            end

            return
        end

        local entry = hide_manager["score_of"](player)
        local text = string.format("killing: %s(resolved:%.3f:%s) [%d-%d]", player["Name"], hide_manager["resolver_confidence"] or 0, tostring(hide_manager["resolver_active"] == true), entry["mine"], entry["theirs"])

        if line["Text"] ~= text then
            line["Text"] = text
        end

        line["Transparency"] = 0.7 * (1 - (flags["center_panel_secondary_transparency"] or 0))
        line["Position"] = anchor["Position"] + vector2_new(0, 15)

        if not line["Visible"] then
            line["Visible"] = true
        end
    end

    -- >> ( center panel )

    do
        local heart_image_data = base64_decode("")
        local heart_overlay_image_data = base64_decode("")

        local text = nil
        local text2 = nil
        local text3 = nil
        local heart = nil
        local shadow = nil
        local heart_overlay = nil

        local center_panel_mouse_behavior_connection = nil
        local center_panel_viewport_size_connection = nil
        local last_beat = clock()
        local linear = Enum["EasingStyle"]["Linear"]

        local update_center_panel = LPH_JIT_MAX(function(bypass)
            local screen_size = camera["ViewportSize"]/2

            local neverlose_textbounds = text["TextBounds"]
            local build_textbounds = text2["TextBounds"]

            local total_size = neverlose_textbounds["X"] + build_textbounds["X"] + 13
            local shadow_size = floor(total_size/11)

            -- Under the crosshair, centred: the state ("ragebot: reloading..."), then the name, then the target / resolver line (cp_target_update).
            local center_x = screen_size["X"]
            local below = screen_size["Y"] + 22

            local new_text3_position = vector2_new(center_x, below)
            local new_text_position = vector2_new(center_x, below + 13)
            local new_text2_position = new_text_position
            local new_heart_position = new_text_position

            local new_shadow_position = new_text_position - vector2_new(shadow_size / 2, 0)

            shadow["Size"] = vector2_new(total_size + shadow_size, 14)
            if bypass == 1 then
                text["Position"] = new_text_position
                text2["Position"] = new_text2_position
                text3["Position"] = new_text3_position
                heart["Position"] = new_heart_position
                shadow["Position"] = new_shadow_position
                heart_overlay["Position"] = new_heart_position
            elseif flags["center_panel"] then
                tween(text, {Position = new_text_position}, circular, out, 0.12)
                tween(text2, {Position = new_text2_position}, circular, out, 0.12)
                tween(text3, {Position = new_text3_position}, circular, out, 0.12)
                tween(heart, {Position = new_heart_position}, circular, out, 0.12)
                tween(shadow, {Position = new_shadow_position}, circular, out, 0.12)
                tween(heart_overlay, {Position = new_heart_position}, circular, out, 0.12)
            end
        end)

        local do_center_panel = LPH_JIT_MAX(function(dt)
            -- Nothing of it while the menu is open (a drawing shows through any menu)
            local menu_open_check = getgenv()["neverlose_menu_open"]

            if menu_open_check and menu_open_check() then
                if text["Visible"] or text3["Visible"] then
                    text["Visible"] = false
                    text3["Visible"] = false
                end

                local target_line = hide_manager["cp_target"]

                if target_line and target_line["Visible"] then
                    target_line["Visible"] = false
                end

                return
            elseif not text["Visible"] then
                text["Visible"] = true
                text3["Visible"] = flags["center_panel_show_state"] ~= false
            end

            hide_manager["cp_target_update"](text)

            local old = text3["Text"]
            local state = local_reloading and "reloading" or local_following and "following" or stomping and "stomping" or purchasing and "purchasing" or (in_void or in_void == nil) and "void" or (local_parts["ForceField"] and "invulnerable" or "unsafe")
            local new = "ragebot: " .. state .. "..."
            text3["Text"] = new
            if old ~= new then
                local secondary = 1 - (flags["center_panel_secondary_transparency"] or 0)

                tween(text3, {["Transparency"] = 0.6 * secondary}, linear, out, 0.09)
                delay(0.07, tween, text3, {["Transparency"] = 0.85 * secondary}, linear, out, 0.09)
            end
            local tick = clock()
            -- (the heart and its beat are gone from the new look)
            if false and tick - last_beat > 0.8 then
                last_beat = tick
                local heart_position = heart["Position"]

                heart_overlay["Transparency"] = 0.65 * (1 - (flags["center_panel_primary_transparency"] or 0))
                heart_overlay["Size"] = vector2_new(9, 9)
                heart_overlay["Position"] = heart_position

                tween(heart, {Size = vector2_new(7, 7)}, linear, out, 0.08)
                local new_position = heart_position + vector2_new(1, 1)
                heart["Position"] = new_position
                tween(heart_overlay, {Size = vector2_new(24, 24), Transparency = 0, Position = heart_position - vector2_new(7, 7)}, linear, out, 0.5)
                wait(0.08)

                -- switched off while this waited
                if not heart then
                    return
                end

                tween(heart, {Size = vector2_new(9, 9)}, linear, out, 0.08)
                if heart["Position"] == new_position then
                    heart["Position"] = heart_position
                end
            end
        end)

        create_connection(menu_references["center_panel"]["on_toggle_change"], LPH_JIT_MAX(function(value)
            if hide_manager["cp_target"] then
                pcall(function()
                    hide_manager["cp_target"]:Destroy()
                end)

                hide_manager["cp_target"] = nil
            end

            if text then
                text:Destroy()
                text = nil
            end

            if text2 then
                text2:Destroy()
                text2 = nil
            end

            if text3 then
                text3:Destroy()
                text3 = nil
            end

            if heart then
                heart:Destroy()
                heart = nil
            end

            if shadow then
                shadow:Destroy()
                shadow = nil
            end

            if heart_overlay then
                heart_overlay:Destroy()
                heart_overlay = nil
            end

            if center_panel_viewport_size_connection then
                center_panel_viewport_size_connection:Disconnect()
                center_panel_viewport_size_connection = nil
            end

            if center_panel_mouse_behavior_connection then
                center_panel_mouse_behavior_connection:Disconnect()
                center_panel_mouse_behavior_connection = nil
            end

            for i = 1, #heartbeat do
                if heartbeat[i] == do_center_panel then
                    remove(heartbeat, i)
                    break
                end
            end

            last_beat = clock()

            if value then
                heartbeat[#heartbeat+1] = do_center_panel
                center_panel_viewport_size_connection = create_connection(camera:GetPropertyChangedSignal("ViewportSize"), update_center_panel)
                center_panel_mouse_behavior_connection = create_connection(user_input_service:GetPropertyChangedSignal("MouseBehavior"), update_center_panel)
                text = create_real_drawing("Text", {
                    ["Color"] = flags["center_panel_secondary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 2,
                    ["Visible"] = true,
                    ["Center"] = true,
                    ["Text"] = "Visions hook",
                    ["Size"] = 14,
                    ["Font"] = 2,
                    ["Outline"] = true,
                    ["Position"] = vector2_new(0, 0),
                })

                text2 = create_real_drawing("Text", {
                    ["Color"] = flags["center_panel_secondary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 2,
                    ["Visible"] = true,
                    ["Text"] = (LRM_ScriptName == "da hood" or LRM_ScriptName == "da hood copies") and "live" or "Enhancements",
                    ["Size"] = 12,
                    ["Font"] = 2,
                    ["Outline"] = true,
                    ["Position"] = vector2_new(0, 0),
                })
                -- the new look has no "live" tag, no glow and no heart
                text2["Visible"] = false

                text3 = create_real_drawing("Text", {
                    ["Color"] = flags["center_panel_secondary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 2,
                    ["Center"] = true,
                    ["Text"] = "ragebot: void...",
                    ["Size"] = 12,
                    ["Visible"] = flags["center_panel_show_state"] ~= false,
                    ["Font"] = 2,
                    ["Outline"] = true,
                    ["Position"] = vector2_new(0, 0),
                })

                hide_manager["cp_target"] = create_real_drawing("Text", {
                    ["Color"] = flags["center_panel_secondary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 2,
                    ["Center"] = true,
                    ["Text"] = "",
                    ["Size"] = 12,
                    ["Visible"] = false,
                    ["Font"] = 2,
                    ["Outline"] = true,
                    ["Position"] = vector2_new(0, 0),
                })

                shadow = create_real_drawing("Image", {
                    ["Color"] = flags["center_panel_primary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 3,
                    ["Visible"] = false,
                    ["Data"] = shadow_image_data,
                    ["Position"] = vector2_new(0, 0),
                    ["Size"] = vector2_new(76, 18),
                })

                heart = create_real_drawing("Image", {
                    ["Color"] = flags["center_panel_primary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 2,
                    ["Visible"] = false,
                    ["Data"] = heart_image_data,
                    ["Position"] = vector2_new(0, 0),
                    ["Size"] = vector2_new(9, 9),
                })

                heart_overlay = create_real_drawing("Image", {
                    ["Color"] = flags["center_panel_primary_color"],
                    ["Transparency"] = 0,
                    ["ZIndex"] = 1,
                    ["Visible"] = false,
                    ["Data"] = heart_overlay_image_data,
                    ["Position"] = vector2_new(0, 0),
                    ["Size"] = vector2_new(9, 9),
                })

                -- The pickers' opacity (full by default) scales the look the panel always had.
                local primary = 1 - (flags["center_panel_primary_transparency"] or 0)
                local secondary = 1 - (flags["center_panel_secondary_transparency"] or 0)

                tween(text, {["Transparency"] = secondary}, quad, out, 0.3)
                tween(shadow, {["Transparency"] = 0.2 * primary}, quad, out, 0.3)
                tween(heart, {["Transparency"] = primary}, quad, out, 0.3)
                tween(text2, {["Transparency"] = secondary}, quad, out, 0.3)
                tween(text3, {["Transparency"] = 0.85 * secondary}, quad, out, 0.3)

                update_center_panel(1)
            end
        end))

        create_connection(menu_references["center_panel_primary_color"]["on_color_change"], function(color)
            if heart_overlay then
                heart["Color"] = color
                shadow["Color"] = color
                heart_overlay["Color"] = color
            end
        end)

        create_connection(menu_references["center_panel_secondary_color"]["on_color_change"], function(color)
            if text then
                text["Color"] = color
                text2["Color"] = color
                text3["Color"] = color
            end
        end)

        create_connection(menu_references["center_panel_primary_color"]["on_transparency_change"], function(value)
            if heart_overlay then
                local primary = 1 - value

                heart["Transparency"] = primary
                shadow["Transparency"] = 0.2 * primary
            end
        end)

        create_connection(menu_references["center_panel_secondary_color"]["on_transparency_change"], function(value)
            if text then
                local secondary = 1 - value

                text["Transparency"] = secondary
                text2["Transparency"] = secondary
                text3["Transparency"] = 0.85 * secondary
            end
        end)

        create_connection(menu_references["center_panel_show_state"]["on_toggle_change"], function(value)
            if text3 then
                text3["Visible"] = value
            end
        end)
    end


    -- >> ( custom crosshair )

    do
        local lines = {}

        local gap_offset, length, rot = 10, 6, 0
        local cos = math["cos"]
        local sin = math["sin"]
        local pi = math["pi"]
        local rad = pi / 180

        local rotation = 0
        local thickness = 2
        local animation_speed = 1

        local old_position = nil
        local animation = "none"
        local connection = nil

        local do_drawing_crosshair = LPH_JIT_MAX(function(dt)
            local new_position = nil
            
            if flags["drawing_crosshair_follow_target"] and ragebot_target then
                local hrp = ragebot_target[4]["UpperTorso"]

                if hrp then
                    local pos, on_screen = world_to_viewport_point(camera, hrp["Position"])
                    
                    if on_screen then
                        new_position = vector2_new(pos["X"], pos["Y"])
                    end
                end
            end
            if not new_position then
                new_position = get_mouse_location(user_input_service)
            end

            if not old_position then
                old_position = new_position
            end
    
            local position = old_position + (new_position - old_position) * dt * 16
            local px = position["X"]
            local py = position["Y"]
    
            local anim_time = clock()
    
            local current_gap = gap_offset
            local current_len = length
    
            local current_effective_rotation_speed = 0
            local current_oscillation_offset = 0
    
            if rotation == 0 then
                rot = 0
            else
                current_effective_rotation_speed = rotation
            end
    
            if animation == "none" then
    
            elseif animation == "ripple" then
                current_gap = gap_offset + sin(anim_time * (10 * animation_speed)) * 2
                current_len = length + sin(anim_time * (10 * animation_speed) + pi/2) * 2
                if rotation > 0 then
                    current_oscillation_offset = sin(anim_time * (15 * animation_speed)) * 5
                end
            elseif animation == "expand" then
                local expand_factor = (sin(anim_time * (8 * animation_speed)) + 1) / 2
                current_len = length + 20 * expand_factor
                current_gap = gap_offset + 10 * expand_factor
                if rotation > 0 then
                    current_effective_rotation_speed = current_effective_rotation_speed + (300 * expand_factor * animation_speed)
                end
            elseif animation == "glitch" then
                current_gap = gap_offset + sin(anim_time * (50 * animation_speed)) * 5
                current_len = length + cos(anim_time * (50 * animation_speed)) * 5
                if rotation > 0 then
                    current_oscillation_offset = sin(anim_time * (70 * animation_speed)) * 30
                end
            elseif animation == "spiral" then
                if rotation > 0 then
                    current_effective_rotation_speed = current_effective_rotation_speed + (15 * animation_speed)
                end
                current_gap = gap_offset + sin(anim_time * (3 * animation_speed)) * 5
                local effective_angle_for_len = (rot + dt * current_effective_rotation_speed) * rad
                current_len = length + 10 * ( (sin(effective_angle_for_len * 4) + 1) / 2 )
            end
    
            rot = (rot + dt * current_effective_rotation_speed) % 360
    
            -- The oscillation is an offset on top of the rotation, not part of it: kept in rot it was added again every frame and the crosshair drifted.
            local rot_rad = (rot + current_oscillation_offset) * rad
            local gap = current_gap
            local len = current_len

            local has_target = ragebot_target ~= nil
            local use_indicator = flags["drawing_crosshair_indicator"]
            local line_color = has_target and flags["drawing_crosshair_target_line_color"] or flags["drawing_crosshair_line_color"]
            local outline_color = has_target and flags["drawing_crosshair_target_outline_color"] or flags["drawing_crosshair_outline_color"]

            -- indicator: pulse the line color when target acquired
            local indicator_opacity = nil

            if use_indicator and has_target then
                local pulse = (sin(anim_time * 8) + 1) / 2
                line_color = flags["drawing_crosshair_indicator_color"]
                    :Lerp(flags["drawing_crosshair_target_line_color"], pulse * 0.4)
                -- the indicator's own opacity on top of the target line's (both full by default)
                indicator_opacity = (1 - (flags["drawing_crosshair_target_line_transparency"] or 0)) * (1 - (flags["drawing_crosshair_indicator_transparency"] or 0))
            end

            local _cs = flags["drawing_crosshair_style"]
            local crosshair_style = (type(_cs) == "table" and _cs[1]) or (type(_cs) == "string" and _cs) or "classic"

            local angles = {rot_rad, pi / 2 + rot_rad, pi + rot_rad, 3 * pi / 2 + rot_rad}

            if crosshair_style == "symbol" then
                -- symbol style: 4 sharp triangles pointing outward
                -- base width scales with arm length for a proper pointed look
                local half_base = len * 0.35 + 1.5  -- wide enough to see, scales with length

                for i = 1, 4 do
                    local angle   = angles[i]
                    local perp    = angle + pi / 2

                    -- tip (sharp point at end of arm)
                    local tx  = px + (gap + len) * cos(angle)
                    local ty  = py + (gap + len) * sin(angle)
                    -- base corners (at gap from center)
                    local blx = px + gap * cos(angle) + half_base * cos(perp)
                    local bly = py + gap * sin(angle) + half_base * sin(perp)
                    local brx = px + gap * cos(angle) - half_base * cos(perp)
                    local bry = py + gap * sin(angle) - half_base * sin(perp)

                    -- outline: 1px bigger all around
                    local ob = half_base + 1
                    local otx  = px + (gap + len + 1) * cos(angle)
                    local oty  = py + (gap + len + 1) * sin(angle)
                    local oblx = px + (gap - 0.5) * cos(angle) + ob * cos(perp)
                    local obly = py + (gap - 0.5) * sin(angle) + ob * sin(perp)
                    local obrx = px + (gap - 0.5) * cos(angle) - ob * cos(perp)
                    local obry = py + (gap - 0.5) * sin(angle) - ob * sin(perp)

                    local idx_fill    = (i - 1) * 2 + 1
                    local idx_outline = idx_fill + 1

                    -- draw outline first (lower ZIndex = behind)
                    lines[idx_outline]["PointA"]  = vector2_new(otx,  oty)
                    lines[idx_outline]["PointB"]  = vector2_new(oblx, obly)
                    lines[idx_outline]["PointC"]  = vector2_new(obrx, obry)
                    lines[idx_outline]["Color"]   = outline_color
                    lines[idx_outline]["Filled"]  = true
                    lines[idx_outline]["Visible"] = true

                    -- draw fill on top
                    lines[idx_fill]["PointA"]  = vector2_new(tx,  ty)
                    lines[idx_fill]["PointB"]  = vector2_new(blx, bly)
                    lines[idx_fill]["PointC"]  = vector2_new(brx, bry)
                    lines[idx_fill]["Color"]   = line_color
                    lines[idx_fill]["Filled"]  = true
                    lines[idx_fill]["Visible"] = true
                end

                -- center dot
                local dot_r = math.max(2, thickness)
                if lines[17] then
                    lines[17]["Position"] = vector2_new(px - dot_r,     py - dot_r)
                    lines[17]["Size"]     = vector2_new(dot_r * 2,       dot_r * 2)
                    lines[17]["Color"]    = line_color
                    lines[17]["Visible"]  = true
                end
                if lines[18] then
                    lines[18]["Position"] = vector2_new(px - dot_r - 1, py - dot_r - 1)
                    lines[18]["Size"]     = vector2_new(dot_r * 2 + 2,  dot_r * 2 + 2)
                    lines[18]["Color"]    = outline_color
                    lines[18]["Visible"]  = true
                end
            else
                -- classic style (original)
                for i = 1, 4 do
                    local angle = angles[i]
                    local idx_base    = (i - 1) * 2 + 1
                    local idx_outline = idx_base + 1

                    local sx  = px + gap * cos(angle)
                    local sy  = py + gap * sin(angle)
                    local ex  = px + (gap + len) * cos(angle)
                    local ey  = py + (gap + len) * sin(angle)
                    local osx = px + (gap - 1) * cos(angle)
                    local osy = py + (gap - 1) * sin(angle)
                    local oex = px + (gap + len + 1) * cos(angle)
                    local oey = py + (gap + len + 1) * sin(angle)

                    lines[idx_base]["From"]    = vector2_new(sx,  sy)
                    lines[idx_base]["To"]      = vector2_new(ex,  ey)
                    lines[idx_base]["Color"]   = line_color
                    lines[idx_outline]["From"] = vector2_new(osx, osy)
                    lines[idx_outline]["To"]   = vector2_new(oex, oey)
                    lines[idx_outline]["Color"]= outline_color
                end

                -- hide dot drawings if any
                if lines[17] then lines[17]["Visible"] = false end
                if lines[18] then lines[18]["Visible"] = false end
            end
    
            if indicator_opacity then
                for i = 1, 7, 2 do
                    if lines[i] then
                        lines[i]["Transparency"] = indicator_opacity
                    end
                end

                if lines[17] then
                    lines[17]["Transparency"] = indicator_opacity
                end

                lines["indicator_on"] = true
            elseif lines["indicator_on"] then
                -- The indicator is off again: the plain line opacity back (a change of target does it too, through the fade).
                lines["indicator_on"] = nil

                local plain = 1 - (flags[has_target and "drawing_crosshair_target_line_transparency" or "drawing_crosshair_line_transparency"] or 0)

                for i = 1, 7, 2 do
                    if lines[i] then
                        lines[i]["Transparency"] = plain
                    end
                end

                if lines[17] then
                    lines[17]["Transparency"] = plain
                end
            end

            old_position = position
        end)

        local update_fov_color = function()
            local outline_tween = {["Color"] = ragebot_target and flags["drawing_crosshair_target_outline_color"] or flags["drawing_crosshair_outline_color"], ["Transparency"] = ragebot_target and -flags["drawing_crosshair_target_outline_transparency"]+1 or -flags["drawing_crosshair_outline_transparency"]+1}
            local line_tween = {["Color"] = ragebot_target and flags["drawing_crosshair_target_line_color"] or flags["drawing_crosshair_line_color"], ["Transparency"] = ragebot_target and -flags["drawing_crosshair_target_line_transparency"]+1 or -flags["drawing_crosshair_line_transparency"]+1}
            for i = 1, 8 do
                if lines[i] then
                    tween(lines[i], i % 2 == 0 and outline_tween or line_tween, quad, out, 0.11)
                end
            end
            if lines[17] then tween(lines[17], line_tween, quad, out, 0.11) end
            if lines[18] then tween(lines[18], outline_tween, quad, out, 0.11) end
        end

        create_connection(menu_references["drawing_crosshair"]["on_toggle_change"], function(value)
            for i = 1, #heartbeat do
                if heartbeat[i] == do_drawing_crosshair then
                    remove(heartbeat, i)
                    break
                end
            end

            if connection then
                connection:Disconnect()
                connection = nil
            end

            old_position = nil

            for i = 1, 18 do
                if lines[i] then
                    pcall(function() lines[i]:Remove() end)
                    lines[i] = nil
                end
            end

            if value then
                connection = create_connection(signals["on_ragebot_target_changed"], update_fov_color)

                local line_transparency = ragebot_target and -flags["drawing_crosshair_target_line_transparency"]+1 or -flags["drawing_crosshair_line_transparency"]+1
                local outline_transparency = ragebot_target and -flags["drawing_crosshair_target_outline_transparency"]+1 or -flags["drawing_crosshair_outline_transparency"]+1
                local line_color = ragebot_target and flags["drawing_crosshair_target_line_color"] or flags["drawing_crosshair_line_color"]
                local outline_color = ragebot_target and flags["drawing_crosshair_target_outline_color"] or flags["drawing_crosshair_outline_color"]

                local _cs2 = flags["drawing_crosshair_style"]
                local crosshair_style = (type(_cs2) == "table" and _cs2[1]) or (type(_cs2) == "string" and _cs2) or "classic"

                for i = 1, 8 do
                    if crosshair_style == "symbol" then
                        lines[i] = create_real_drawing("Triangle", {
                            ["Color"]        = i % 2 == 0 and outline_color or line_color,
                            ["Filled"]       = true,
                            ["Visible"]      = true,
                            ["ZIndex"]       = i % 2 == 0 and 15 or 16,
                            ["Transparency"] = i % 2 == 0 and outline_transparency or line_transparency
                        })
                    else
                        lines[i] = create_real_drawing("Line", {
                            ["Color"]        = i % 2 == 0 and outline_color or line_color,
                            ["Thickness"]    = i % 2 == 0 and thickness+2 or thickness,
                            ["Visible"]      = true,
                            ["ZIndex"]       = i % 2 == 0 and 15 or 16,
                            ["Transparency"] = i % 2 == 0 and outline_transparency or line_transparency
                        })
                    end
                end

                -- center dot (only for symbol style, hidden otherwise)
                lines[17] = create_real_drawing("Square", {
                    ["Color"]       = line_color,
                    ["Filled"]      = true,
                    ["Visible"]     = false,
                    ["ZIndex"]      = 17,
                    ["Transparency"]= line_transparency,
                    ["Size"]        = vector2_new(4, 4),
                    ["Position"]    = vector2_new(0, 0)
                })
                lines[18] = create_real_drawing("Square", {
                    ["Color"]       = outline_color,
                    ["Filled"]      = true,
                    ["Visible"]     = false,
                    ["ZIndex"]      = 14,
                    ["Transparency"]= outline_transparency,
                    ["Size"]        = vector2_new(6, 6),
                    ["Position"]    = vector2_new(0, 0)
                })

                heartbeat[#heartbeat+1] = do_drawing_crosshair
            end
        end)

        create_connection(menu_references["drawing_crosshair_line_color"]["on_color_change"], function(value)
            local line1 = lines[1]

            if line1 and not ragebot_target then
                line1["Color"] = value
                lines[3]["Color"] = value
                lines[5]["Color"] = value
                lines[7]["Color"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_outline_color"]["on_color_change"], function(value)
            local line2 = lines[2]

            if line2 and not ragebot_target then
                line2["Color"] = value
                lines[4]["Color"] = value
                lines[6]["Color"] = value
                lines[8]["Color"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_line_color"]["on_transparency_change"], function(value)
            local line1 = lines[1]

            if line1 and not ragebot_target then
                local value = -value+1
                line1["Transparency"] = value
                lines[3]["Transparency"] = value
                lines[5]["Transparency"] = value
                lines[7]["Transparency"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_outline_color"]["on_transparency_change"], function(value)
            local line2 = lines[2]

            if line2 and not ragebot_target then
                local value = -value+1
                line2["Transparency"] = value
                lines[4]["Transparency"] = value
                lines[6]["Transparency"] = value
                lines[8]["Transparency"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_target_line_color"]["on_color_change"], function(value)
            local line1 = lines[1]

            if line1 and ragebot_target then
                line1["Color"] = value
                lines[3]["Color"] = value
                lines[5]["Color"] = value
                lines[7]["Color"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_target_outline_color"]["on_color_change"], function(value)
            local line2 = lines[2]

            if line2 and ragebot_target then
                line2["Color"] = value
                lines[4]["Color"] = value
                lines[6]["Color"] = value
                lines[8]["Color"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_target_line_color"]["on_transparency_change"], function(value)
            local line1 = lines[1]

            if line1 and ragebot_target then
                local value = -value+1
                line1["Transparency"] = value
                lines[3]["Transparency"] = value
                lines[5]["Transparency"] = value
                lines[7]["Transparency"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_target_outline_color"]["on_transparency_change"], function(value)
            local line2 = lines[2]

            if line2 and ragebot_target then
                local value = -value+1
                line2["Transparency"] = value
                lines[4]["Transparency"] = value
                lines[6]["Transparency"] = value
                lines[8]["Transparency"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_line_size"]["on_slider_change"], function(value)
            length = value
        end)

        create_connection(menu_references["drawing_crosshair_gap_size"]["on_slider_change"], function(value)
            gap_offset = value
        end)

        create_connection(menu_references["drawing_crosshair_rotation"]["on_slider_change"], function(value)
            rotation = value*5
        end)

        create_connection(menu_references["drawing_crosshair_animation_speed"]["on_slider_change"], function(value)
            animation_speed = value/100
        end)

        create_connection(menu_references["drawing_crosshair_line_thickness"]["on_slider_change"], function(value)
            thickness = value

            local line2 = lines[2]

            if line2 then
                local new_thickness = value + 2
                line2["Thickness"] = new_thickness
                lines[4]["Thickness"] = new_thickness
                lines[6]["Thickness"] = new_thickness
                lines[8]["Thickness"] = new_thickness
                lines[1]["Thickness"] = value
                lines[3]["Thickness"] = value
                lines[5]["Thickness"] = value
                lines[7]["Thickness"] = value
            end
        end)

        create_connection(menu_references["drawing_crosshair_animation"]["on_dropdown_change"], function(value)
            animation = value and value[1] or nil
            menu_references["drawing_crosshair_animation_speed"]:set_visible((animation or "none") ~= "none")
        end)

        create_connection(menu_references["drawing_crosshair_style"]["on_dropdown_change"], function(value)
            -- rebuild lines with correct drawing type
            if not lines[1] then return end
            local style = value and value[1] or "classic"
            local line_color = ragebot_target and flags["drawing_crosshair_target_line_color"] or flags["drawing_crosshair_line_color"]
            local outline_color = ragebot_target and flags["drawing_crosshair_target_outline_color"] or flags["drawing_crosshair_outline_color"]
            local line_t = ragebot_target and -flags["drawing_crosshair_target_line_transparency"]+1 or -flags["drawing_crosshair_line_transparency"]+1
            local out_t  = ragebot_target and -flags["drawing_crosshair_target_outline_transparency"]+1 or -flags["drawing_crosshair_outline_transparency"]+1
            for i = 1, 18 do
                if lines[i] then pcall(function() lines[i]:Remove() end) lines[i] = nil end
            end
            for i = 1, 8 do
                if style == "symbol" then
                    lines[i] = create_real_drawing("Triangle", {["Color"] = i%2==0 and outline_color or line_color, ["Filled"] = true, ["Visible"] = true, ["ZIndex"] = i%2==0 and 15 or 16, ["Transparency"] = i%2==0 and out_t or line_t})
                else
                    lines[i] = create_real_drawing("Line", {["Color"] = i%2==0 and outline_color or line_color, ["Thickness"] = i%2==0 and thickness+2 or thickness, ["Visible"] = true, ["ZIndex"] = i%2==0 and 15 or 16, ["Transparency"] = i%2==0 and out_t or line_t})
                end
            end
            lines[17] = create_real_drawing("Square", {["Color"] = line_color, ["Filled"] = true, ["Visible"] = false, ["ZIndex"] = 17, ["Transparency"] = line_t, ["Size"] = vector2_new(4,4), ["Position"] = vector2_new(0,0)})
            lines[18] = create_real_drawing("Square", {["Color"] = outline_color, ["Filled"] = true, ["Visible"] = false, ["ZIndex"] = 14, ["Transparency"] = out_t, ["Size"] = vector2_new(6,6), ["Position"] = vector2_new(0,0)})
        end)
    end

    -- >> ( crosshair animations )

    do
        -- >> ( variables )

        local crosshair_animations_tool_added_connection = nil
        local crosshair_animations_update_connection = nil

        -- >> ( fake metatable )

        local aim_frame = nil
        local old_metatable = getrawmetatable(game)
        local old_new_index = old_metatable["__newindex"]

        local fake_frame = {
            ["__newindex"] = newcclosure(LPH_NO_VIRTUALIZE(function(self, key, value)
                if not checkcaller() and (key == "Visible" or key == "BackgroundTransparency") and crosshair_animations_tool_added_connection then
                    return
                end
                return old_new_index(self, key, value)
            end))
        }

        for _, v in old_metatable do
            if _ ~= "__newindex" then
                fake_frame[_] = v
            end
        end

        -- >> ( core )

        local fade_aim_frame = function(show)
            if aim_frame then
                local transparency = show and 0 or 1
                local children = get_children(aim_frame)
                local cursor_image = nil
                for i = 1, #children do
                    local child = children[i]
                    if child["Name"] == "CursorImage" then
                        cursor_image = child
                        break
                    end
                end
                local frame_transparency = {["BackgroundTransparency"] = (cursor_image and cursor_image["Visible"]) and 1 or transparency}
                for i = 1, #children do
                    local frame = children[i]
                    if frame["ClassName"] == "ImageLabel" then
                        tween(frame, {["ImageTransparency"] = transparency, ["BackgroundTransparency"] = 1}, exponential, out, 0.25)
                    else
                        tween(frame, frame_transparency, exponential, out, 0.25)
                    end
                end
                tween(aim_frame, frame_transparency, exponential, out, 0.25)
                aim_frame["Visible"] = true
                if not show then
                    delay(0.26, function()
                        if not local_tool then
                            aim_frame["Visible"] = false
                        end
                    end)
                end
            end
        end

        local get_aim_frame = function()
            local player_gui = local_player["PlayerGui"]

            if player_gui then
                local main_screen_gui = wait_for_child(player_gui, "MainScreenGui", 5)

                if main_screen_gui then
                    aim_frame = wait_for_child(main_screen_gui, "Aim", 5)

                    if aim_frame then
                        setrawmetatable(aim_frame, fake_frame)
                    end
                end
            end
        end

        local spin_speed = 1*((101-15)/100)
        local spin_type = "ease"
        local do_crosshair_spin = LPH_NO_VIRTUALIZE(function(dt)
            if aim_frame then
                local time = (clock() % spin_speed) / spin_speed

                aim_frame["Rotation"] = spin_type == "ease" and (time * time * (3 - 2 * time)) * 360 or time * 360
            end
        end)

        create_connection(menu_references["crosshair_animations"]["on_toggle_change"], function(value)
            if flags["hide_game_crosshair"] then
                menu_references["hide_game_crosshair"]:set_toggle(false)
            end

            if crosshair_animations_tool_added_connection then
                crosshair_animations_tool_added_connection:Disconnect()
                crosshair_animations_tool_added_connection = nil
            end

            if crosshair_animations_update_connection then
                crosshair_animations_update_connection:Disconnect()
                crosshair_animations_update_connection = nil
            end

            for i = 1, #heartbeat do
                if heartbeat[i] == do_crosshair_spin then
                    remove(heartbeat, i)
                    break
                end
            end

            if value then
                get_aim_frame()

                crosshair_animations_update_connection = create_connection(signals["on_local_character_added"], get_aim_frame)

                if flags["crosshair_animations_fade_in_and_out"] then
                    crosshair_animations_tool_added_connection = create_connection(signals["on_local_tool_equipped"], fade_aim_frame)
                end

                if flags["crosshair_animations_spin"] then
                    heartbeat[#heartbeat+1] = do_crosshair_spin
                end
            elseif aim_frame then
                aim_frame["Visible"] = local_tool ~= nil
                local children = get_children(aim_frame)
                for i = 1, #children do
                    local child = children[i]
                    if child["ClassName"] == "ImageLabel" then
                        child["ImageTransparency"] = 0
                    else
                        child["BackgroundTransparency"] = 0
                    end
                end
                aim_frame["BackgroundTransparency"] = 0
                if old_metatable then
                    setrawmetatable(aim_frame, old_metatable)
                end
                delay(0, function()
                    if aim_frame then
                        aim_frame["Rotation"] = 0
                        aim_frame = nil
                    end
                end)
            end
        end)

        create_connection(menu_references["crosshair_animations_fade_in_and_out"]["on_toggle_change"], function(value)
            -- The fade listener also is what keeps the game's own writes to the frame blocked (see the fake metatable), so it must go when fading goes
            -- off, and a second one must not be added on top of the first.
            if crosshair_animations_tool_added_connection then
                crosshair_animations_tool_added_connection:Disconnect()
                crosshair_animations_tool_added_connection = nil
            end

            if value and aim_frame then
                crosshair_animations_tool_added_connection = create_connection(signals["on_local_tool_equipped"], fade_aim_frame)
            elseif aim_frame then
                -- Fading is off: whatever the last fade left is put back to fully shown.
                aim_frame["Visible"] = local_tool ~= nil

                local children = get_children(aim_frame)

                for i = 1, #children do
                    local child = children[i]

                    if child["ClassName"] == "ImageLabel" then
                        child["ImageTransparency"] = 0
                    else
                        child["BackgroundTransparency"] = 0
                    end
                end

                aim_frame["BackgroundTransparency"] = 0
            end
        end)

        create_connection(menu_references["crosshair_animations_spin"]["on_toggle_change"], function(value)
            menu_references["crosshair_animations_spin_speed"]:set_visible(value)

            for i = 1, #heartbeat do
                if heartbeat[i] == do_crosshair_spin then
                    remove(heartbeat, i)
                    break
                end
            end

            if value then
                heartbeat[#heartbeat+1] = do_crosshair_spin
            elseif aim_frame then
                delay(0, function()
                    if aim_frame then
                        aim_frame["Rotation"] = 0
                    end
                end)
            end
        end)

        create_connection(menu_references["crosshair_animations_spin_speed"]["on_slider_change"], function(value)
            spin_speed = 1*((101-value)/100)
        end)

        create_connection(menu_references["crosshair_animations_spin"]["on_dropdown_change"], function(value)
            spin_type = value[1]
        end)
    end

    -- >> ( server position indicator )

    local visible = false
    local circle = nil
    local image = nil
    local glow = nil
    local shadow_transparency = {["Transparency"] = 0.09}
    local circle_transparency = {["Transparency"] = 0.8}
    local image_transparency = {["Transparency"] = 0.8}
    local offset = vector3_new(0, 0.5, 0)
    local data = base64_decode("")
    local last_pos = nil
    local do_smooth_server_position_indicator = nil

    local do_server_position_indicator = LPH_JIT_MAX(function(dt)
        if local_client_position ~= local_server_position then
            local local_server_position = local_server_position["p"]
            
            local pos, on_screen = world_to_viewport_point(camera, local_server_position)

            if do_smooth_server_position_indicator then
                if not last_pos then
                    last_pos = pos
                end
                pos = last_pos + (pos - last_pos) * dt*4^2
            end

            last_pos = pos
            if not on_screen and visible then
                tween(glow, hide_transparency, circular, out, 0)
                tween(image, hide_transparency, circular, out, 0)
                tween(circle, hide_transparency, circular, out, 0)
                visible = false
                return
            elseif not visible and on_screen then
                spawn(function()
                    tween(glow, shadow_transparency, circular, out, 0.07)
                    tween(image, image_transparency, circular, out, 0.07)
                    tween(circle, circle_transparency, circular, out, 0.07)
                end)
                visible = true
            elseif not visible and not on_screen then
                visible = false
                return
            end

            local pos2, _ = world_to_viewport_point(camera, local_server_position + offset)

            local size = clamp((pos["Y"]-pos2["Y"])*10, 35, 45)

            local pos = vector2_new(pos["X"], pos["Y"])
            circle["Size"] = vector2_new(size, size)
            circle["Position"] = pos - vector2_new(size/2, size/2)

            local image_size = vector2_new(size*0.6, size*0.6)
            image["Position"] = pos - image_size/2
            image["Size"] = image_size

            local glow_size = vector2_new(size*1.08, size*1.08)
            glow["Position"] = pos - glow_size/2
            glow["Size"] = glow_size
        elseif visible then
            visible = false
            tween(glow, hide_transparency, circular, out, 0.09)
            tween(image, hide_transparency, circular, out, 0.09)
            tween(circle, hide_transparency, circular, out, 0.09)
        end
    end)

    local create_drawing = identifyexecutor() == "Wave" and create_fake_drawing or create_real_drawing

    create_connection(menu_references["smooth_server_position_indicator"]["on_toggle_change"], function(value)
        last_pos = nil
        do_smooth_server_position_indicator = value
    end)

    create_connection(menu_references["server_position_indicator"]["on_toggle_change"], function(value)
        last_pos = nil
        for i = 1, #heartbeat do
            if heartbeat[i] == do_server_position_indicator then
                remove(heartbeat, i)
                break
            end
        end

        visible = false

        if circle then
            circle:Destroy()
            circle = nil
        end

        if image then
            image:Destroy()
            image = nil
        end

        if glow then
            glow:Destroy()
            glow = nil
        end

        visible = false

        if value then
            circle = create_drawing("Image", {
                ["Color"] = flags["server_position_indicator_background_color"],
                ["Transparency"] = 0,
                ["ZIndex"] = 1,
                ["Visible"] = true,
                ["Data"] = pixel_image_data,
                ["Rounding"] = 30,
                ["Position"] = vector2_new(0, 0),
                ["Size"] = vector2_new(65, 65),
            })

            image = create_drawing("Image", {
                ["Color"] = flags["server_position_indicator_icon_color"],
                ["Transparency"] = 0,
                ["ZIndex"] = 2,
                ["Visible"] = true,
                ["Data"] = data,
                ["Position"] = vector2_new(0, 0),
                ["Size"] = vector2_new(29, 29),
            })

            glow = create_drawing("Image", {
                ["Color"] = flags["server_position_indicator_glow_color"],
                ["Transparency"] = 0,
                ["ZIndex"] = 3,
                ["Visible"] = true,
                ["Data"] = shadow_image_data,
                ["Rounding"] = 36,
                ["Position"] = vector2_new(0, 0),
                ["Size"] = vector2_new(73, 73)
            })

            heartbeat[#heartbeat+1] = do_server_position_indicator
        end
    end)

    create_connection(menu_references["server_position_indicator_glow_color"]["on_color_change"], function(value)
        if glow then
            glow["Color"] = value
        end
    end)

    create_connection(menu_references["server_position_indicator_glow_color"]["on_transparency_change"], function(value)
        if glow and visible then
            glow["Transparency"] = -value+1
            shadow_transparency["Transparency"] = -value+1
        end
    end)

    create_connection(menu_references["server_position_indicator_icon_color"]["on_color_change"], function(value)
        if image then
            image["Color"] = value
        end
    end)

    create_connection(menu_references["server_position_indicator_icon_color"]["on_transparency_change"], function(value)
        if image and visible then
            image["Transparency"] = -value+1
            image_transparency["Transparency"] = -value+1
        end
    end)

    create_connection(menu_references["server_position_indicator_background_color"]["on_color_change"], function(value)
        if circle then
            circle["Color"] = value
        end
    end)

    create_connection(menu_references["server_position_indicator_background_color"]["on_transparency_change"], function(value)
        if circle and visible then
            circle["Transparency"] = -value+1
            circle_transparency["Transparency"] = -value+1
        end
    end)

    -- >> ( ghost character )
    -- Server Position Indicator's Ghost Character: a copy of the character, drawn in the ghost colour, that stands where the server has the character
    -- and moves the way the real one does (the joints are copied every frame). It only shows while the two differ (desync, follow target, void
    -- spam) and while the server position is on the map. The copy is built again for every new character and is only ever drawn on this client.
    -- The game clears whatever is parented to Workspace.CurrentCamera within a frame (a Folder parked there was gone after 0.017 s, a Folder in Workspace
    -- stayed), so the copy lives in Workspace.Terrain and is rebuilt if it is ever removed from there.
    hide_manager["ghost"] = {["model"] = nil, ["root"] = nil, ["motors"] = {}, ["owner"] = nil, ["shown"] = false, ["retry_at"] = 0, ["last_cf"] = nil, ["last_seen"] = 0}

    -- the material of the copy, from the Ghost Material dropdown
    hide_manager["ghost_material"] = function()
        local chosen = hide_manager["ghost_material_pick"] or flags["server_position_ghost_material"]

        chosen = type(chosen) == "table" and chosen[1] or chosen

        local materials = {
            ["forcefield"] = Enum["Material"]["ForceField"],
            ["neon"] = Enum["Material"]["Neon"],
            ["glass"] = Enum["Material"]["Glass"],
            ["ice"] = Enum["Material"]["Ice"],
            ["foil"] = Enum["Material"]["Foil"],
            ["metal"] = Enum["Material"]["Metal"],
            ["smooth plastic"] = Enum["Material"]["SmoothPlastic"],
            ["plastic"] = Enum["Material"]["Plastic"]
        }

        return materials[chosen] or materials["forcefield"]
    end

    hide_manager["ghost_destroy"] = function()
        local ghost = hide_manager["ghost"]

        if ghost["model"] then
            pcall(function()
                ghost["model"]:Destroy()
            end)
        end

        ghost["model"] = nil
        ghost["root"] = nil
        ghost["motors"] = {}
        ghost["owner"] = nil
        ghost["shown"] = false
        ghost["last_cf"] = nil
    end

    hide_manager["ghost_paint"] = function()
        local ghost = hide_manager["ghost"]
        local model = ghost["model"]

        if not model then
            return
        end

        local color = flags["server_position_ghost_color"]
        local transparency = flags["server_position_ghost_transparency"]

        transparency = type(transparency) == "number" and transparency or 0.55

        local material = hide_manager["ghost_material"]()

        for _, part in model:GetDescendants() do
            if part:IsA("BasePart") and part ~= ghost["root"] then
                part["Color"] = color
                part["Transparency"] = transparency
                part["Material"] = material
            end
        end
    end

    hide_manager["ghost_build"] = function()
        hide_manager["ghost_destroy"]()

        local ghost = hide_manager["ghost"]
        local character = local_character

        ghost["retry_at"] = clock() + 1

        if not character or not character["Parent"] then
            return
        end

        local archivable = character["Archivable"]

        character["Archivable"] = true

        local ok, copy = pcall(function()
            return character:Clone()
        end)

        character["Archivable"] = archivable

        if not ok or not copy then
            return
        end

        local real_motors = {}

        for _, motor in character:GetDescendants() do
            if motor:IsA("Motor6D") and motor["Part1"] then
                real_motors[motor["Part1"]["Name"].."/"..motor["Name"]] = motor
            end
        end

        local motors = {}

        for _, object in copy:GetDescendants() do
            pcall(function()
                if object:IsA("BaseScript") or object:IsA("Tool") or object:IsA("Humanoid") or object:IsA("ForceField") or object:IsA("Sound") or object:IsA("Decal")
                    or object:IsA("Texture") or object:IsA("Shirt") or object:IsA("Pants") or object:IsA("ShirtGraphic") or object:IsA("BodyColors")
                    or object:IsA("BillboardGui") or object:IsA("SurfaceGui") or object:IsA("ParticleEmitter") or object:IsA("Highlight") or object:IsA("Constraint") then
                    object:Destroy()
                elseif object:IsA("BasePart") then
                    object["Anchored"] = false
                    object["CanCollide"] = false
                    object["CanQuery"] = false
                    object["CanTouch"] = false
                    object["Massless"] = true
                    object["CastShadow"] = false
                    object["Material"] = hide_manager["ghost_material"]()

                    if object:IsA("MeshPart") then
                        object["TextureID"] = ""
                    end
                elseif object:IsA("Motor6D") and object["Part1"] then
                    local real = real_motors[object["Part1"]["Name"].."/"..object["Name"]]

                    if real then
                        motors[#motors+1] = {real, object}
                    end
                end
            end)
        end

        local root = copy["PrimaryPart"] or find_first_child(copy, "HumanoidRootPart")

        if not root then
            copy:Destroy()
            return
        end

        root["Anchored"] = true
        root["Transparency"] = 1
        copy["PrimaryPart"] = root
        copy["Name"] = "ghost"

        ghost["model"] = copy
        ghost["root"] = root
        ghost["motors"] = motors
        ghost["owner"] = character
        ghost["shown"] = false

        hide_manager["ghost_paint"]()
    end

    hide_manager["ghost_step"] = LPH_NO_VIRTUALIZE(function(dt)
        local ghost = hide_manager["ghost"]

        if ghost["owner"] ~= local_character or not ghost["model"] then
            if local_character and local_character["Parent"] and clock() >= ghost["retry_at"] then
                hide_manager["ghost_build"]()
            end

            return
        end

        local now = clock()
        local server = local_server_position
        local client = local_client_position
        local visible = false

        if server and client then
            local server_position = server["p"]

            if server_position["Magnitude"] < 9e5 and (server_position - client["p"])["Magnitude"] > 2 then
                visible = true
                ghost["last_cf"] = server
                ghost["last_seen"] = now
            end
        end

        -- void spam sends the server position off the map between shots; the copy waits at the last place it was seen instead of blinking out
        if not visible and ghost["shown"] and ghost["last_cf"] and now - ghost["last_seen"] < 0.4 then
            visible = true
            server = ghost["last_cf"]
        end

        local container = workspace["Terrain"]

        if ghost["shown"] and ghost["model"]["Parent"] ~= container then
            -- something removed the copy: drop it and build a fresh one a little later
            hide_manager["ghost_destroy"]()
            ghost["retry_at"] = now + 2

            return
        end

        if visible then
            if not ghost["shown"] then
                if not pcall(function()
                    ghost["model"]["Parent"] = container
                end) then
                    hide_manager["ghost_destroy"]()
                    ghost["retry_at"] = now + 2

                    return
                end

                ghost["shown"] = true
            end

            ghost["root"]["CFrame"] = server

            for _, pair in ghost["motors"] do
                pair[2]["Transform"] = pair[1]["Transform"]
            end
        elseif ghost["shown"] then
            ghost["shown"] = false
            ghost["model"]["Parent"] = nil
        end
    end)

    create_connection(menu_references["server_position_ghost"]["on_toggle_change"], function(value)
        for i = 1, #heartbeat do
            if heartbeat[i] == hide_manager["ghost_step"] then
                remove(heartbeat, i)
                break
            end
        end

        hide_manager["ghost_destroy"]()

        if value then
            hide_manager["ghost"]["retry_at"] = 0
            heartbeat[#heartbeat+1] = hide_manager["ghost_step"]
        end
    end)

    create_connection(menu_references["server_position_ghost_color"]["on_color_change"], function()
        hide_manager["ghost_paint"]()
    end)

    create_connection(menu_references["server_position_ghost_color"]["on_transparency_change"], function()
        hide_manager["ghost_paint"]()
    end)

    create_connection(menu_references["server_position_ghost_material"]["on_dropdown_change"], function(value)
        hide_manager["ghost_material_pick"] = type(value) == "table" and value[1] or value
        hide_manager["ghost_paint"]()
    end)

    do
        local teardowns = getgenv()["neverlose_teardowns"]

        if teardowns then
            teardowns[#teardowns+1] = function()
                hide_manager["ghost_destroy"]()
            end
        end
    end

