        menu_references["auto_heal_purchase_if_below"] = menu_references["auto_heal_settings"]:create_element({["name"] = "purchase if below"}, {["slider"] = {["flag"] = "auto_heal_purchase_if_below", ["min"] = 0, ["max"] = 100, ["default"] = 70, ["suffix"] = "%"}})
        menu_references["auto_heal_try_cooldown"] = menu_references["auto_heal_settings"]:create_element({["name"] = "try cooldown"}, {["slider"] = {["flag"] = "auto_heal_try_cooldown", ["min"] = 0, ["max"] = 2, ["default"] = 0.05, ["decimals"] = 2, ["suffix"] = "s"}})
        menu_references["auto_heal_stop_following"] = menu_references["auto_heal_settings"]:create_element({["name"] = "stop following while healing"}, {["toggle"] = {["flag"] = "auto_heal_stop_following", ["default"] = false}})
        menu_references["anti_taser"] = menu_references["utility_section"]:create_element({["name"] = "anti taser"}, {["toggle"] = {["flag"] = "anti_taser"}})
        menu_references["anti_afk"] = menu_references["utility_section"]:create_element({["name"] = "anti afk"}, {["toggle"] = {["flag"] = "anti_afk", ["default"] = true}})
        menu_references["rapid_fire"] = menu_references["utility_section"]:create_element({["name"] = "rapid fire"}, {["toggle"] = {["flag"] = "rapid_fire", ["default"] = false}})
        menu_references["rapid_fire_settings"] = menu_references["rapid_fire"]:create_settings()
        menu_references["rapid_fire_glory_patch"] = menu_references["rapid_fire_settings"]:create_element({["name"] = "glory patch"}, {["toggle"] = {["flag"] = "rapid_fire_glory_patch", ["default"] = false}})
        menu_references["rapid_fire_hold"] = menu_references["rapid_fire_settings"]:create_element({["name"] = "hold to fire"}, {["toggle"] = {["flag"] = "rapid_fire_hold", ["default"] = false}})
        menu_references["rapid_fire_delay"] = menu_references["rapid_fire_settings"]:create_element({["name"] = "fire delay"}, {["slider"] = {["flag"] = "rapid_fire_delay", ["min"] = 0, ["max"] = 1, ["default"] = 0.01, ["decimals"] = 2, ["suffix"] = "s"}})
        menu_references["rapid_fire_speed"] = menu_references["rapid_fire_settings"]:create_element({["name"] = "speed"}, {["slider"] = {["flag"] = "rapid_fire_speed", ["min"] = 0, ["max"] = 100, ["default"] = 100, ["suffix"] = "%"}})
        --[[
        menu_references["control"] = menu_references["utility_section"]:create_element({["name"] = "control"}, {["toggle"] = {["flag"] = "control", ["default"] = false}})
        menu_references["control_settings"] = menu_references["control"]:create_settings()
        menu_references["control_chat_replies"] = menu_references["control_settings"]:create_element({["name"] = "chat replies"}, {["toggle"] = {["flag"] = "control_chat_replies", ["default"] = true}})
        --]]
    -- >> ( ragebot )

    local automatic = false
    local do_notification = false
    local ragebot_hitbox = "Head"
    local target_distance = true
    local ragebot_field_of_view = true
    local ragebot_untarget_when_better_target = false
    local ragebot_untarget_when_dead = true
    local ragebot_untarget_when_knocked = false
    local ragebot_untarget_when_flung = false
    local ragebot_ignore_if_in_void = false
    local ragebot_ignore_if_knocked = false
    local resolver_rate = 0.043

    local target_last_position = nil
    local target_velocity = nil

    local target_friendly = false
    local target_neutral = true
    local target_enemy = false

    local last_refresh = clock()
    local last_fire = clock()
    -- A shot delay yields inside the ragebot step, which runs again every frame: only one delayed burst may be waiting at a time.
    local shot_pending = false

    -- Per gun readiness. Shotguns are the guns the server polices (they carry a SecurityTolerance attribute). Their own script turns a
    -- shot away before its ShootingCooldown (+ 0.0095 + 0.05) is over, so asking sooner only wastes the pull. Readiness is read from
    -- the game's own state instead of a flag of ours, so it can't go stale: the tool's Cooldown attribute, the LocalLastShotAt stamp
    -- GunHandler.shoot leaves on it (and our own send time), and the reload rule from GunHandler.CanShoot.
    --
    -- Measured on two accounts: this gate does not stop the Double-Barrel going quiet. The ragebot's forged shotgun call (five
    -- arguments, none of the time stamp, spread seed and pellet number the gun's own script sends with every pellet) is taken by the
    -- server exactly five times in a server (SecurityTolerance), after which that account's shotgun is locked out for the rest of that
    -- server, legit pulls included. A fresh server resets it. A shot the gun made itself and aimed at the target through
    -- GunHandler.getAim was taken 16 of 16 across 8 reloads when the body was not desynced, but wired into the ragebot (whose server
    -- body sits away from the real one) it was refused, so it is not used here.
    hide_manager["gun_fired_at"] = setmetatable({}, {["__mode"] = "k"})

    -- Slow guns (the Rifle's 1.3 s, the Flintlock's 2 s) used to be asked for a shot on every step the ragebot ran (the fire cooldown
    -- defaults to 5 ms) while the gun can only fire once per ShootingCooldown. They are now sent once that cooldown (+ 0.0095, the game's own
    -- slack) is over. A send the server did not take (the ammo is still what it was) is asked again after a round trip instead, so a
    -- refusal for some other reason never costs a whole cooldown. Fast guns (the AUG's 0.05 s) are left to the server's own limit.
    -- hide_manager.pace_slow_guns = false puts the old behaviour back.
    hide_manager["pace_slow_guns"] = true
    hide_manager["gun_ammo_sent"] = setmetatable({}, {["__mode"] = "k"})
    -- Sends in a row after which the ammo had not moved (the server took nothing): a gun that keeps being turned away (a shotgun past its
    -- SecurityTolerance is locked out for the rest of the server; any gun while the target is out of reach) is only tried now and then.
    hide_manager["gun_refused"] = setmetatable({}, {["__mode"] = "k"})

    -- One Tap: which gun goes at this target now so that it is knocked in as few shots as possible, from what the hub and the game's armor rule say.
    -- Armor takes the whole value of a hit and the health 22.5% of it while there is any; the Rifle (99) takes all the armor that is left whatever its
    -- damage; one Double-Barrel shell is five pellets of 23.1 (115.5; the head's double is not counted against armor, measured on a body with 130 armor:
    -- 104 off the armor and 23 off the health from a shell at the head). So a full body (100 health, 130 armor) falls to the Rifle and then a shell, 0.15 s
    -- apart, or to two shells 0.35 s apart; with no armor one shell is enough. Returns the gun to send (nil: no gun in particular) and whether the shell
    -- should wait for the Rifle, which is about to be ready to strip the armor first.
    local function hit_on_body(damage, strips, armor, health)
        if armor > 0 then
            if strips then
                return 0, health - damage * 0.225
            elseif damage <= armor then
                return armor - damage, health - damage * 0.225
            end

            return 0, health - armor * 0.225 - (damage - armor)
        end

        return 0, health - damage
    end

    hide_manager["one_tap_plan"] = function(target, guns, distance)
        local armor = target[14] or 0
        local health = target[9] or 100
        local rifle, shell = nil, nil

        for _, gun in guns do
            local tool = gun[1]["Parent"]

            if tool and gun[3] > 0 then
                if tool["Name"] == "[Rifle]" then
                    rifle = {tool, gun}
                elseif tool["Name"] == "[Double-Barrel SG]" then
                    shell = {tool, gun}
                end
            end
        end

        local rifle_ready = rifle and distance <= 230 and hide_manager["gun_ready"](rifle[1], rifle[2][3])
        local shell_ready = shell and distance <= 110 and hide_manager["gun_ready"](shell[1], shell[2][3])

        -- Auto Equip's Prioritize DB: the shell goes whenever it can (in reach and ready), the Rifle only when it cannot
        if shell_ready and flags["auto_equip_prioritize_db"] == true then
            return shell[1], false
        end

        if shell_ready then
            local damage_value = find_first_child(shell[1], "Damage")
            local _, left = hit_on_body((damage_value and damage_value["Value"] or 23.1) * hide_manager["pellets_of"](shell[1]), false, armor, health)

            if left <= 0.5 then
                return shell[1], false
            end
        end

        if rifle_ready then
            local damage_value = find_first_child(rifle[1], "Damage")
            local _, left = hit_on_body(damage_value and damage_value["Value"] or 99, true, armor, health)

            if left <= 0.5 or armor >= 20 then
                return rifle[1], false
            end
        end

        if shell_ready then
            -- armored and the Rifle comes back within 0.4 s: the shell waits for it
            if armor >= 20 and rifle and not rifle_ready and distance <= 230 then
                local sent = hide_manager["gun_fired_at"][rifle[1]]
                local cooldown = find_first_child(rifle[1], "ShootingCooldown")

                if sent and cooldown and sent + cooldown["Value"] + 0.0095 - clock() <= 0.4 then
                    return nil, true
                end
            end

            return shell[1], false
        end

        return nil, false
    end

    -- Distance Check (Auto Equip's gear): while the target is past the Double-Barrel's own Range but within the Rifle's, and the Rifle is there with a
    -- round in it, the Double-Barrel is not sent (the server turns its shot away, and every refused shotgun call counts against its SecurityTolerance)
    -- and the Rifle goes first. Both ranges are the guns' own Range values; with either unknown nothing changes. It switches back once the target is
    -- 4 studs inside the DB's range again, and holds each switch for at least half a second, so a target on the edge does not flip the guns every
    -- frame. Nothing is rewritten: the gun order, the Auto Equip list and the shot counts stay as they are. hide_manager.distance_check_active says
    -- whether it is on now (Auto Equip brings the Rifle out for it).
    local distance_check_state = {["active"] = false, ["since"] = 0}

    local gun_range = function(tool, known)
        local range = tool and find_first_child(tool, "Range")

        return range and tonumber(range["Value"]) or tonumber(known)
    end

    hide_manager["distance_check"] = function(guns, distance)
        local state = distance_check_state

        if flags["auto_equip_distance_check"] ~= true or type(distance) ~= "number" or distance ~= distance then
            state["active"] = false
            hide_manager["distance_check_active"] = false
            return false
        end

        local shell, rifle, rifle_ammo, rifle_known = nil, nil, 0, nil

        for _, gun in guns do
            local tool = gun[1]["Parent"]

            if tool and tool["Name"] == "[Double-Barrel SG]" then
                shell = {tool, gun[2]}
            elseif tool and tool["Name"] == "[Rifle]" then
                rifle, rifle_ammo, rifle_known = tool, gun[3], gun[2]
            end
        end

        -- a Rifle still in the backpack counts too: Auto Equip brings it out while this is on
        if not rifle then
            local backpack = find_first_child(local_player, "Backpack")
            local stored = backpack and find_first_child(backpack, "[Rifle]")
            local ammo = stored and find_first_child(stored, "Ammo")

            if stored and ammo then
                rifle, rifle_ammo = stored, ammo["Value"]
            end
        end

        local shell_range = shell and gun_range(shell[1], shell[2])
        local rifle_range = rifle and gun_range(rifle, rifle_known)
        local now = clock()
        local wanted = state["active"]

        if not (shell_range and rifle_range) or rifle_ammo <= 0 or distance > rifle_range then
            wanted = false
        elseif state["active"] then
            wanted = distance > shell_range - 4
        else
            wanted = distance > shell_range
        end

        -- the Rifle running dry or going out of reach ends it at once; otherwise a switch is held for half a second
        local forced_off = not (shell_range and rifle_range) or rifle_ammo <= 0 or (rifle_range and distance > rifle_range)

        if wanted ~= state["active"] and (forced_off or now - state["since"] >= 0.5) then
            state["active"] = wanted
            state["since"] = now
        end

        hide_manager["distance_check_active"] = state["active"]

        return state["active"]
    end

    -- Pellets in one shot: the shotguns fire five, a call each.
    local pellet_guns = {["[Double-Barrel SG]"] = 5, ["[Shotgun]"] = 5, ["[TacticalShotgun]"] = 5, ["[Drum-Shotgun]"] = 5}

    hide_manager["pellets_of"] = function(tool)
        return pellet_guns[tool["Name"]] or (tool:GetAttribute("SecurityTolerance") ~= nil and 5 or 1)
    end

    -- Double Tap (flag auto_fire_salvo; it was called Salvo; BASED Hub's Da Hood ragebot, measured there): the server holds a second shot of a gun behind the one it is firing, and fires it when the cooldown is
    -- over without looking at the claim again (two Rifle shots sent together were taken 0.02 s and 1.32 s later; a held one knocked a target that had gone 4,400
    -- studs off by then). So one claim that was good for a moment is worth two hits: a slow gun with a round to spare is sent its shot twice. Guns the server
    -- polices (the shotguns, which count every refused call) and the fast ones are left out. A reload cancels a held shot, so salvo_holding says when one may be
    -- pending and the reloads wait. Measured here on two accounts (the server takes no shot at a map part, so it was done on a player): with the second call sent in
    -- the same frame the Rifle's ammo dropped at +0.04 s and again 1.30 s later (6 of 7 tries), and the held shot did its damage (armor 130 and 42 health after it);
    -- sent 0.016, 0.1 or 0.3 s later it was not held. The call has to go out after the shot (see the remote hook).
    hide_manager["salvo_sent"] = setmetatable({}, {["__mode"] = "k"})
    hide_manager["salvo_until"] = setmetatable({}, {["__mode"] = "k"})

    hide_manager["salvo_extra"] = function(handle)
        if flags["auto_fire_salvo"] ~= true or hide_manager["salvo_busy"] == true or typeof(handle) ~= "Instance" then
            return false
        end

        local tool = handle["Parent"]

        if not tool or tool:GetAttribute("SecurityTolerance") ~= nil or hide_manager["pellets_of"](tool) > 1 then
            return false
        end

        local cooldown = find_first_child(tool, "ShootingCooldown")
        local ammo = find_first_child(tool, "Ammo")

        if not cooldown or cooldown["Value"] < 0.25 or not ammo or ammo["Value"] < 2 then
            return false
        end

        local now = clock()

