        local dead = body_effects and find_first_child(body_effects, "Dead")
        local really_dead = body_effects and find_first_child(body_effects, "SDeath")

        if (dead and dead["Value"]) or (really_dead and really_dead["Value"]) then
            return "respawning"
        end

