        if not handler then
            return false, "module"
        end

        local current = handler["getAim"]

        if type(current) ~= "function" then
            return false, "module"
        end

        aim_chain["original"] = current
        aim_chain["dispatch"] = function(origin, ...)
            for i = 1, #aim_chain["order"] do
                local provider = aim_chain["providers"][aim_chain["order"][i]]

