                            break
                        end
                    end
                end
            end

            cache["at"], cache["origin"], cache["position"], cache["range"] = now, origin, position, range
            cache["out_origin"], cache["out_claim"] = out_origin, out_claim

            return out_origin, out_claim
        end)
