        end

        hide_manager["bm_pulling"][tool] = clock()

        return pull_trigger(tool, pulled)
    end)

    -- lets go a moment later, so an automatic gun fires its one shot and stops
    local release_triggers = LPH_NO_VIRTUALIZE(function(pulled)
        delay(0.03, function()
            for _, tool in pulled do
                pcall(function() tool:Deactivate() end)
            end
        end)
    end)

    create_connection(menu_references["auto_fire_bullet_manipulation"]["on_toggle_change"], function(value)
        local ok, reason = set_rage_bullet_manipulation(value)

        if value and not ok then
            new_notification("bullet manipulation: gun module not found, auto fire keeps forging its shots", 3)
        end
    end)

    -- Velocity Source: other ways to read how the target is moving than the position change between two reads. The humanoid's MoveDirection and the
    -- body's LookVector (each times the walk speed) are what the velocity resolvers of other Da Hood cheats use against targets that fake their velocity.
    hide_manager["velocity_source"] = type(flags["velocity_source"]) == "table" and flags["velocity_source"][1] or "delta"

    -- Estimator (the movement estimator of Entry, a recency weighted straight line fit through the last few positions, with a confidence): it knows when
    -- the target is standing still (jitter in the replicated position is not movement), throws the history away at a reversal or a jump (a void hop) and
    -- says how consistent the last positions are. Measured on made-up paths (0.15 s ahead, 23 samples a second, mean error in studs, delta -> this):
    -- standing 0.40 -> 0.08, straight run 0.40 -> 0.13, stop and go 0.72 -> 0.70, zig-zag 0.93 -> 0.78, fast run with turns 1.35 -> 1.19, but a circle
    -- 0.58 -> 0.93. So it is used as a hybrid: standing still gives no lead, a consistent fit gives its velocity, anything else falls back to the delta.
    do
        local function finite(n)
            return type(n) == "number" and n == n and math["abs"](n) < math["huge"]
        end

        local function is_vector(p)
            return typeof(p) == "Vector3" and finite(p["X"]) and finite(p["Y"]) and finite(p["Z"])
        end

        hide_manager["new_estimator"] = function()
            local config = {["memory"] = 0.4, ["decay"] = 0.12, ["turnHold"] = 0.1, ["stale"] = 0.15, ["turnAngle"] = math["deg"](math["acos"](0.25))}
            local samples, cursor, count = table["create"](24), 0, 0
            local velocity, confidence, reason = vector3_zero, 0, "warming"
            local last, segment, hold_until = nil, nil, 0
            local self = {}

            local function clear()
                table["clear"](samples)
                cursor, count = 0, 0
                velocity, confidence, reason = vector3_zero, 0, "warming"
                last, segment, hold_until = nil, nil, 0
            end

            self["reset"] = clear

            function self:push(position, now, window)
                if not is_vector(position) or not finite(now) then
                    return false
                end

                window = finite(window) and math["clamp"](math["floor"](window), 3, 24) or 8

                local dt = last and now - last["time"]

                -- positions come in at most 30 times a second, and never twice at one moment
                if dt and dt < 1/30 then
                    return false
                end

                local newest_segment

                if last then
                    local delta = position - last["position"]

                    if dt > 0.35 then
                        clear()
                        reason, hold_until = "gap", now + config["turnHold"]
                    elseif delta["Magnitude"] > math["max"](24, 600 * dt) then
                        clear()
                        reason, hold_until = "discontinuity", now + config["turnHold"]
                    else
                        newest_segment = delta / dt

                        if segment and segment["Magnitude"] > 1 and newest_segment["Magnitude"] > 1 and segment["Unit"]:Dot(newest_segment["Unit"]) < math["cos"](math["rad"](config["turnAngle"])) then
                            -- the old direction is dropped at a turn instead of being blended across it
                            local previous = last

                            clear()
                            reason, hold_until = "reversal", now + config["turnHold"]
                            cursor, count = 1, 1
                            samples[1] = previous
                        end
                    end
                end

                cursor = cursor % 24 + 1
                count = math["min"](24, count + 1)
                last = {["position"] = position, ["time"] = now}
                samples[cursor] = last
                segment = newest_segment

                if count < 3 then
                    confidence, velocity = 0, vector3_zero

                    return true
                end

                -- fitted around the newest position (large coordinates lose precision), recent samples weigh more
                local weight_sum, time_sum, position_sum, used, span = 0, 0, vector3_zero, 0, 0

                for offset = 0, math["min"](count, window) - 1 do
                    local sample = samples[(cursor - 1 - offset) % 24 + 1]
                    local age = now - sample["time"]

                    if age <= config["memory"] then
                        local weight = math["exp"](-age / config["decay"])

                        weight_sum += weight
                        time_sum += weight * (sample["time"] - now)
                        position_sum += (sample["position"] - position) * weight
                        used += 1
                        span = math["max"](span, age)
                    end
                end

                if used < 3 then
                    confidence, velocity, reason = 0, vector3_zero, "warming"

                    return true
                end

                local mean_time, mean_position = time_sum / weight_sum, position_sum / weight_sum
                local denominator, numerator = 0, vector3_zero

                for offset = 0, math["min"](count, window) - 1 do
                    local sample = samples[(cursor - 1 - offset) % 24 + 1]
                    local age = now - sample["time"]

                    if age <= config["memory"] then
                        local weight = math["exp"](-age / config["decay"])
                        local t = sample["time"] - now - mean_time

                        denominator += weight * t * t
                        numerator += (sample["position"] - position - mean_position) * (weight * t)
                    end
                end

                velocity = denominator > 1e-8 and numerator / denominator or vector3_zero

                -- jitter in the replicated position is not movement
                local oldest = samples[(cursor - 1 - math["min"](count - 1, 4)) % 24 + 1]

                if oldest and now - oldest["time"] >= 0.10 then
                    local stable = true

                    for offset = 0, math["min"](count - 1, 4) do
                        if (samples[(cursor - 1 - offset) % 24 + 1]["position"] - position)["Magnitude"] > 0.28 then
                            stable = false

                            break
                        end
                    end

                    if stable then
                        velocity, confidence, reason = vector3_zero, 1, "stationary"

                        return true
                    end
                end

                if newest_segment and newest_segment["Magnitude"] < 0.5 then
                    velocity, confidence, reason = vector3_zero, 1, "stationary"

                    return true
                end

                local squared_error = 0

                for offset = 0, math["min"](count, window) - 1 do
                    local sample = samples[(cursor - 1 - offset) % 24 + 1]
                    local age = now - sample["time"]

                    if age <= config["memory"] then
                        local residual = sample["position"] - position - mean_position - velocity * (sample["time"] - now - mean_time)

                        squared_error += math["exp"](-age / config["decay"]) * residual:Dot(residual)
                    end
                end

                local rms = math["sqrt"](squared_error / weight_sum)
                local travel = velocity["Magnitude"] * span
                local alignment = 1

                if newest_segment and newest_segment["Magnitude"] > 1 and velocity["Magnitude"] > 1 then
                    alignment = math["clamp"](newest_segment["Unit"]:Dot(velocity["Unit"]), 0, 1)
                end

                confidence = math["clamp"](1 - rms / math["max"](0.1, travel * 0.4), 0, 1) * alignment * math["min"](1, (used - 2) / 3)

                if now < hold_until then
                    confidence, reason = 0, "turn hold"
                else
                    reason = confidence > 0.6 and "consistent" or "inconsistent"
                end

                return true
            end

            function self:status()
                return {["confidence"] = confidence, ["velocity"] = velocity, ["reason"] = reason}
            end

            return self
        end

        hide_manager["estimator"] = hide_manager["new_estimator"]()
    end

    hide_manager["source_velocity"] = function(source, target, torso)
        if source == "none" then
            return vector3_zero
        end

        if source == "estimator" then
            local estimator = hide_manager["estimator"]

            -- a new target starts a new history
            if hide_manager["estimator_part"] ~= torso then
                estimator:reset()
                hide_manager["estimator_part"] = torso
            end

            estimator:push(torso["Position"], clock(), 8)

            local status = estimator:status()

            if status["reason"] == "stationary" then
                return vector3_zero
            elseif status["reason"] == "consistent" then
                return status["velocity"]
            end

            -- not sure enough: the plain delta read stands
            return nil
        end

        local humanoid = find_first_child(target[3], "Humanoid")
        local walk_speed = humanoid and humanoid["WalkSpeed"] or 16

        if source == "move direction" then
            return humanoid and humanoid["MoveDirection"] * walk_speed or nil
        elseif source == "look vector" then
            return torso["CFrame"]["LookVector"] * walk_speed
        end

        return nil
    end

    create_connection(menu_references["velocity_source"]["on_dropdown_change"], function(value)
        hide_manager["velocity_source"] = value[1] or "delta"
    end)

    local is_defensive = false
    local params = RaycastParams["new"]()
    params["FilterType"] = Enum["RaycastFilterType"]["Exclude"]
    params["FilterDescendantsInstances"] = {}
    local raycast = workspace["Raycast"]

    local do_ragebot = LPH_JIT_MAX(function(dt, hrp)
        local target = ragebot_target
        local tick = clock()

        if (automatic or target_list["count"] > 0) and not target and (target_list["refresh"] or tick - last_auto > target_cooldown) and flags["ragebot"] then
            target_list["refresh"] = false
            last_auto = tick
            pick_ragebot_target(dt, hrp)
            target = ragebot_target
        end

        local did_defensive = false

        if ragebot_target == nil and ragebot_aim_position then
            ragebot_aim_position = nil
            target_last_position = nil
            target_velocity = vector3_zero
        end

        local mouse_position = get_mouse_location(user_input_service)

        if fov_circle then
            local old_position = fov_circle["Position"]
            local goal_position = flags["ragebot_field_of_view_follow_target"] and ragebot_aim_position or nil
            if goal_position then
                local position, on_screen = world_to_viewport_point(camera, goal_position)

                if on_screen then
                    goal_position = vector2_new(position["X"], position["Y"])
                else
                    goal_position = nil
                end
            end

            local new_position = old_position + ((goal_position or mouse_position) - old_position) * clamp(dt*4^2, 0, 1)
            fov_circle["Position"] = new_position
            fov_circle_outline["Position"] = new_position
        end

        -- With automatic targeting or a Target List: when the active target can't be hit right now (respawning, still
        -- loading or protected) another target that can be hit takes over, in the Prioritize By order. The hide only
        -- holds while nobody else can be hit. A target chosen with the target key is never swapped out.
        if target and hrp and (automatic or target_list["count"] > 0) then

            if get_target_phase(target) ~= nil and not wait_out_protection(target) then
                local standin = hide_manager["find_standin"](dt, hrp)

                if standin then
                    set_ragebot_target(standin, "ragebot target set to "..standin[2]["Name"].." ("..target[2]["Name"].." can't be hit yet)")
                    target = ragebot_target
                    hide_episode_target = nil
                end
            end
        end

        if target and hrp then
            local parts = target[4]
            -- Force Hit (always on): the head takes the shot whatever the Target Hitbox says
            local hitbox = parts["Head"] or parts[ragebot_hitbox]

            if flags["auto_fire_at_target_vehicle"] then
                hitbox = target[19] or hitbox
            end

            local torso = parts["HumanoidRootPart"]
            local grabbing_constraint = parts["GRABBING_CONSTRAINT"]

            -- Targets that are respawning, still loading or invulnerable are never dropped: we hide in the void and
            -- wait for them. A dead target is kept for as long as its player is in the server.
            local phase = get_target_phase(target)
            update_hide_episode(target, phase)

            if (ragebot_untarget_when_dead and target[7] and not should_hold_target(target)) or (ragebot_untarget_when_knocked and target[18]) or (ragebot_untarget_when_flung and torso and hide_episode_target ~= target and torso["Velocity"]["Magnitude"] > 100) then
                set_ragebot_target(nil, "ragebot target set to nobody due to condition met")
            elseif ragebot_untarget_when_better_target and hide_episode_target ~= target and not target[18] and not target[7] then
                -- A knocked or dead target is never replaced here: the pickers skip knocked players, so it would always lose
                -- to any other player (or to nobody) and auto stomp would lose the target it is about to stomp.
                local target = pick_ragebot_target(dt, hrp, true)
                if target and ragebot_target ~= target then
                    set_ragebot_target(target, "ragebot target set to "..target[2]["Name"].." due to better target")
                end
            end

            if ragebot_target == nil then
                target_velocity = vector3_zero
                ragebot_aim_position = nil
                target_last_position = nil
                torso = nil
                last_refresh = clock()
            elseif torso then
                if clock() - last_refresh > resolver_rate then
                    local torso_position = torso["Position"]

                    if target_last_position then
                        local distance = (torso_position - target_last_position)
                        local velocity = distance / (clock() - last_refresh)
                        local speed = velocity["Magnitude"]

                        -- the resolver below trusts a target that moves like a player only when it has not jumped faster than anyone runs for a while
                        if speed ~= speed or speed > 80 or torso_position["Magnitude"] >= 9e5 then
                            hide_manager["target_jumped_at"] = clock()
                        end

                        -- A void hop or a teleport is not movement. Fed into the prediction it grows every step when two followers chase
                        -- each other's predicted position, until both sit in the void for good.
                        if speed ~= speed or speed > 500 or torso_position["Magnitude"] >= 9e5 or target_last_position["Magnitude"] >= 9e5 then
                            velocity = vector3_zero
                        end

                        target_velocity = velocity
                    end

                    -- Velocity Source other than delta: the velocity read above is replaced
                    local source = hide_manager["velocity_source"]

                    if source and source ~= "delta" then
                        target_velocity = hide_manager["source_velocity"](source, target, torso) or target_velocity
                    end

                    target_last_position = torso_position
                    last_refresh = clock()
                end
            end

            if hitbox then
                local hitbox_position = hitbox["Position"]

                -- A target in the void whose spot there jumps about (a new random place far out on every update, as one opponent's script does) can
                -- not be hit or followed: the server has it somewhere else by the time a shot or the body gets there, and out there a position is only
                -- kept to tens of studs anyway. Marked here (hide_manager.target_void_jitter_at) for the fire gate below, the follow and the shot hook.
                do
                    local last_void = hide_manager["target_void_last"]

                    if hitbox_position["Magnitude"] >= 9e5 then
                        if last_void and last_void[1] == target and (hitbox_position - last_void[2])["Magnitude"] > 5000 then
                            hide_manager["target_void_jitter_at"] = clock()
                        end

                        hide_manager["target_void_last"] = {target, hitbox_position}
                    else
                        hide_manager["target_void_last"] = nil
                    end
                end

                local current_time = clock()

                local old_time = clock()

                -- Prediction: the lead from the target's measured velocity. It is worked out on its own, whatever the resolver does, so the two work
                -- together: the resolver says WHERE the target really is, the prediction where it will be by the time the shot lands.
                local lead = vector3_zero

                if target_velocity then
                    local velocity = target_velocity

                    -- With the resolver on, a "velocity" faster than anyone runs is the target's desync jumping about, not movement: no lead from it
                    if flags["auto_fire_defensive"] and velocity["Magnitude"] > 80 then
                        velocity = vector3_zero
                    end

                    local raw = velocity*(prediction == 0 and 0 or prediction == 2 and local_ping/500 or prediction)
                    local lead_length = raw["Magnitude"]

                    -- The lead is capped, so a bad velocity sample can never throw the aim far away from the target.
                    if lead_length == lead_length then
                        lead = lead_length > 60 and raw["Unit"]*60 or raw
                    end
                end

                ragebot_aim_position = hitbox_position + lead

                local local_server_position = local_server_position["p"]
                if flags["auto_fire_defensive"] then
                    local weighted = hide_manager["resolver_weighted"] == true
                    local resolved

                    if weighted then
                        resolved = hide_manager["weighted_resolve"](hitbox_position, current_time)
                    else
                        resolved = ue_resolve(hitbox_position, current_time)
                    end

                    if resolved then
                        -- The resolved spot is the target itself (within the cluster's radius of where it shows): the aim is the target with the
                        -- prediction's lead. A spot somewhere else (the target is faking its position): the aim stays on that spot and flicks to the next
                        -- one every Refresh Time, with no lead (a guess of where the server has the body does not move with the faked velocity).
                        -- The prediction's own readings (target_velocity, target_last_position) are not touched any more: they used to be zeroed and
                        -- set to the resolved spot every frame, so the next velocity was measured from a spot the target never stood on.
                        -- A target that moves like a player (under 80 studs/s, not in the void) is where it shows: measured against one walking back and
                        -- forth, the resolver's spot (the middle of its recent positions, kept for the Refresh Time) put the aim 5.6 studs off the head and
                        -- behind it. The resolver's spot is used only while the target jumps about faster than anyone runs (a desync, void spam).
                        -- (a jump faster than that in the last 0.75 s counts too: between two jumps a faking target reads as standing still)
                        local moves_like_a_player = hitbox_position["Magnitude"] < 9e5 and target_velocity ~= nil and target_velocity["Magnitude"] <= 80
                            and clock() - (hide_manager["target_jumped_at"] or -1) > 0.75

                        if moves_like_a_player or (resolved - hitbox_position)["Magnitude"] <= ue_resolver_radius then
                            ragebot_aim_position = hitbox_position + lead
                        else
                            ragebot_aim_position = resolved
                        end

                        did_defensive = true
                    end
                end

                hide_manager["resolver_active"] = did_defensive
                ragebot_aim_position = ragebot_force_position or ragebot_aim_position

                if custom_ragebot_aim_position then
                    ragebot_aim_position = custom_ragebot_aim_position
                    custom_ragebot_aim_position = nil
                end

                -- Nothing real sits past this: an aim position that is not a number or that far out means the tracking has run away.
                local aim_length = ragebot_aim_position["Magnitude"]
                local aim_valid = aim_length == aim_length and aim_length < 1e10

                -- While the void spam cycle runs, a shot sent from inside the void is thrown away by the server: hold it for the windows
                -- the character is out (in_void is the state the character was left in by the last step), and for a moment into each
                -- window, so the server has the character at the target by the time the shot reaches it.
                if aim_valid and not invulnerable_void_active and clock() - (hide_manager["spam_cycle_at"] or -1) < 0.1 then
                    local settle = getgenv()["neverlose_spam_settle"] or math.min(local_ping/1000 + 0.03, 0.15)

                    if in_void == true or clock() - (hide_manager["spam_cycle_start"] or 0) < settle then
                        aim_valid = false
                    end
                end

                -- The target sits in the void at a spot that keeps jumping (above): nothing sent at it can land, and every refused shotgun call costs
                -- SecurityTolerance, so nothing is sent until it comes back out.
                if aim_valid and hide_manager["is_void_jittering"] and hide_manager["is_void_jittering"](target, hitbox_position) then
                    aim_valid = false
                end

                -- Hidden in the void for a reload (the one hide that runs while the target can be hit): a shot sent from there is thrown away by the
                -- server, as in the spam cycle above, so it is held until the character is back instead of being sent from the void.
                if aim_valid and invulnerable_void_active and in_void == true then
                    aim_valid = false
                end

                -- Follow Target has just taken the character to the target. The server has the body about 0.1 s late, so a shot sent at once is claimed
                -- from a place where the server does not have it yet and is refused (measured: the first Rifle, Flintlock and DB shots all refused, and
                -- the refused Rifle then sat out its whole 1.3 s cooldown before the shot that hit). The shots wait until the server has had the body
                -- there for a round trip and a little more (ping + 0.06 s, at most 0.25 s), and then go with no wait for the gun gap, the fire cooldown
                -- or the shot delay.
                local follow_burst = false

                if local_following and not hide_manager["was_following"] then
                    hide_manager["follow_started_at"] = clock()
                    hide_manager["follow_burst_due"] = true
                end

                hide_manager["was_following"] = local_following

                if local_following and hide_manager["follow_started_at"] then
                    local settle = math.min(local_ping / 1000 + 0.06, 0.25)

                    if clock() - hide_manager["follow_started_at"] < settle then
                        aim_valid = false
                    elseif hide_manager["follow_burst_due"] then
                        hide_manager["follow_burst_due"] = false
                        last_fire = -math.huge
                        hide_manager["last_sent_at"] = nil
                        follow_burst = true
                    end
                end

                -- Shot Lock. Measured with Distance 26 and Reposition Every 0.02 s: the body was put somewhere new on a 30 stud circle round the target
                -- every frame, the server had it at one place and the shot was claimed from another (the follow's reach is past the 17 studs it forgives),
                -- so 9 shots of 11 did nothing (the DB none of 6). With a follow that can put the body more than 15 studs out, the place is now held still
                -- (hide_manager.shot_lock, as an offset from the target) once a shot is wanted, the shots wait until the server has had the body there
                -- for a round trip and a little (ping + 0.06 s, at least 0.1 s), and the follow goes back to moving 0.25 s after the last shot.
                if aim_valid and local_following and flags["auto_fire"] then
                    local reach = hide_manager["follow_reach"] and hide_manager["follow_reach"]()
                    local now = clock()
                    local lock = hide_manager["shot_lock"]

                    if reach == nil or reach > 15 then
                        if not lock or now >= lock[1] then
                            local offset = local_server_position - ragebot_aim_position

                            if offset["Magnitude"] == offset["Magnitude"] and offset["Magnitude"] < 200 then
                                hide_manager["shot_lock"] = {now + 0.6, offset, now}
                                aim_valid = false
                            end
                        elseif now - lock[3] < math.max(local_ping / 1000 + 0.06, 0.1) then
                            aim_valid = false
                        end
                    end
                end

                -- Distance Check: the target only has to be in reach of one of the guns in hand with a round in it (the Rifle while the DB cannot reach),
                -- not of the gun equipped last; the gun choice below then sends the one that can reach.
                local fire_reach = local_gun

                if fire_reach and flags["auto_equip_distance_check"] == true then
                    for _, held in local_guns do
                        if held[2] and held[3] and held[3] > 0 and held[2] > fire_reach then
                            fire_reach = held[2]
                        end
                    end
                end

                if aim_valid and local_gun and (((not local_reloading or auto_fire_always_fire) and not target[18] and not target[7] and phase == nil and not grabbing_constraint) and (flags["auto_fire"] and (auto_fire_always_fire or (((local_server_position-ragebot_aim_position)["Magnitude"] <= fire_reach) or flags["follow_target"] or did_defensive)) and old_time-last_fire > fire_cooldown and not shot_pending)) then
                    local delay = follow_burst and 0 or flags["shot_delay"]
                    local stale = false

                    if delay > 0 then
                        shot_pending = true
                        wait(delay/1000)
                        shot_pending = false

                        -- Everything above was decided before the wait. The target is looked at again for every gun below; what is not is whether auto fire /
                        -- the ragebot is still on (a volley still went out after being switched off, even after an unload), whether it is still the same
                        -- target, and whether the character is in the void now (a shot from there is thrown away, and the spam cycle holds them).
                        stale = not flags["auto_fire"] or not flags["ragebot"] or ragebot_target ~= target or not hrp["Parent"]
                            or (in_void == true and (invulnerable_void_active or clock() - (hide_manager["spam_cycle_at"] or -1) < 0.1))
                    end

                    if local_gun and not stale then
                        local new_local_guns = {}
                        for handle, local_gun in local_guns do
                            local parent = handle["Parent"]

                            if parent and parent["Name"] == "[Rifle]" then
                                new_local_guns[#new_local_guns+1] = local_gun
                            end
                        end
                        for handle, local_gun in local_guns do
                            local parent = handle["Parent"]

                            if parent and parent["Name"] ~= "[Rifle]" then
                                new_local_guns[#new_local_guns+1] = local_gun
                            end
                        end

                        -- The server takes one shot per short window across ALL of the guns: of a volley sent in one tick only the first gun is
                        -- taken (measured: Rifle taken, AUG refused until about 0.1 s later, Flintlock never), and a fast gun sending on every
                        -- frame always arrives first and starves the slow ones. So one gun is sent per tick: the slow guns first (the one that
                        -- has waited longest), a fast gun only while no slow gun is waiting for its turn, and a different gun only once the
                        -- window since the last shot is over (getgenv().neverlose_gun_gap, seconds). The same gun repeats on its own cooldown.
                        --
                        -- The gaps are the ones another hub measured on the live server: a different gun is taken 0.14 s after another (48 of 48,
                        -- 0.125 s not always; inside a tenth of a second one of the two is lost), and the game's SwitchCooldown keeps any two of the
                        -- Deagle, Rifle, Glock and Silencer 0.5 s apart (0.52 here). A gun repeats on its cooldown plus 0.015 s (the AUG sent every
                        -- 0.065 s had all of its shots counted).
                        --
                        -- Fire All Guns (on by default): every gun takes its turn, with no One Tap choice of one gun out of the Rifle and the Double-Barrel, and the
                        -- turns follow each other at the Gun Gap (140 ms, the smallest gap that was taken every time; 0 sends them in consecutive frames, the
                        -- nearest to "at once": the server is said to keep the first and drop the others sent inside a tenth of a second, and a dropped gun is only
                        -- asked again after its own wait, so the gap is there to be tried).
                        local all_guns = auto_fire_always_fire == true -- Fire All Guns is part of Always Fire
                        local volley_gap = getgenv()["neverlose_gun_gap"] or (all_guns and (tonumber(flags["auto_fire_gun_gap"]) or 140)/1000 or 0.15)
                        local switch_slow = {["[Deagle]"] = true, ["[Rifle]"] = true, ["[Glock]"] = true, ["[Silencer]"] = true}
                        local gap_between = function(from_name, to_name)
                            if switch_slow[from_name] and switch_slow[to_name] then
                                return math.max(0.52, volley_gap)
                            end

                            return volley_gap
                        end
                        local sent_gun = hide_manager["last_sent_gun"]
                        local sent_at = hide_manager["last_sent_at"] or -math.huge
                        local fired_at = hide_manager["gun_fired_at"]

                        local is_slow_gun = function(tool)
                            local cooldown = find_first_child(tool, "ShootingCooldown")

                            return cooldown ~= nil and cooldown["Value"] >= 0.25
                        end

                        -- One Tap (see hide_manager.one_tap_plan): with the Rifle and the Double-Barrel in hand the gun that knocks this target soonest goes first,
                        -- and the other waits its turn
                        local plan_tool, plan_hold = nil, false

                        if not all_guns then
                            plan_tool, plan_hold = hide_manager["one_tap_plan"](target, new_local_guns, (ragebot_aim_position - local_server_position)["Magnitude"])
                        end

                        -- Distance Check: the DB cannot reach the target but the Rifle can, so the Rifle goes and the DB waits
                        local rifle_over_shell = hide_manager["distance_check"](new_local_guns, (ragebot_aim_position - local_server_position)["Magnitude"])

                        if rifle_over_shell then
                            plan_hold = false

                            if plan_tool and plan_tool["Name"] == "[Double-Barrel SG]" then
                                plan_tool = nil
                            end

                            for _, gun in new_local_guns do
                                local tool = gun[1]["Parent"]

                                if tool and tool["Name"] == "[Rifle]" then
                                    plan_tool = tool
                                    break
                                end
                            end
                        end

                        table.sort(new_local_guns, function(a, b)
                            local tool_a, tool_b = a[1]["Parent"], b[1]["Parent"]

                            if not tool_a or not tool_b then
                                return tool_a ~= nil and tool_b == nil
                            end

                            if plan_tool and (tool_a == plan_tool) ~= (tool_b == plan_tool) then
                                return tool_a == plan_tool
                            end

                            local slow_a, slow_b = is_slow_gun(tool_a), is_slow_gun(tool_b)

                            if slow_a ~= slow_b then
                                return slow_a
                            end

                            return (fired_at[tool_a] or -math.huge) < (fired_at[tool_b] or -math.huge)
                        end)

                        local chosen_gun = nil
                        local slow_waiting = false
                        local pick_time = clock()

                        for i = 1, #new_local_guns do
                            local candidate = new_local_guns[i]
                            local tool = candidate[1]["Parent"]

                            if plan_tool and tool ~= plan_tool and (tool["Name"] == "[Rifle]" or tool["Name"] == "[Double-Barrel SG]") then
                                -- the plan names the other of the two: this one waits
                                continue
                            end

                            if plan_hold and tool and tool["Name"] == "[Double-Barrel SG]" then
                                continue
                            end

                            if rifle_over_shell and tool and tool["Name"] == "[Double-Barrel SG]" then
                                continue
                            end

                            if tool and candidate[3] > 0 and hide_manager["gun_ready"](tool, candidate[3]) then
                                local since = pick_time - sent_at
                                local cooldown = find_first_child(tool, "ShootingCooldown")
                                local window_over = sent_gun == nil or (sent_gun == tool and since >= (cooldown and cooldown["Value"] or 0.05) + 0.015) or (sent_gun ~= tool and since >= gap_between(sent_gun["Name"], tool["Name"]))

                                if is_slow_gun(tool) then
                                    if window_over then
                                        chosen_gun = candidate
                                        break
                                    end

                                    slow_waiting = true
                                elseif window_over and not slow_waiting then
                                    chosen_gun = candidate
                                    break
                                end
                            end
                        end

                        local pos = ragebot_aim_position
                        local origin = local_server_position

                        -- Bullet Manipulation's shot checks (they used to be the Skip Out Of Reach and Walls toggles; Bullet TP is gone). Reach: the server turns
                        -- away a shot whose hit position is farther from its origin than the gun's Range, and a shotgun's refused call is counted against its
                        -- SecurityTolerance (past it the gun is locked out for the rest of the server). Measured on a target that hides in the void most of the
                        -- time: 63% of all sends were aimed at a void position, from a body hundreds of millions of studs away, and the server took 1 of 709. The
                        -- shot waits for the target to be within reach (the gun's range, and the 17 studs the server forgives between the origin and its copy of
                        -- the body; BASED Hub measured both; it used to be a quarter more than the range). Walls: the server looks at the line from the
                        -- shot's origin to the claimed hit; a shot with no clear line to the target and no open point near it to claim the hit at is only turned
                        -- away, so it is not sent either (hide_manager.walls_aim, worked out from the origin the rebuilt shot gets).
                        -- Force Hit is always on now, so neither check runs: the shot is sent at the head however far it is and whatever stands in the way.
                        if false and chosen_gun and rage_bullet_manipulation["enabled"] and rage_bullet_manipulation["installed"] then
                            local reach = chosen_gun[2] or 250

                            if (origin - pos)["Magnitude"] > reach + 17 then
                                chosen_gun = nil
                            else
                                local walls_aim = hide_manager["walls_aim"]

                                if walls_aim and walls_aim(origin + vector3_new(0, 3.0208, 0), pos, reach) == nil then
                                    chosen_gun = nil
                                end
                            end
                        end

                        local pulled = {}

                        for i = 1, #new_local_guns do
                            -- F-C2: re-check target liveness on every gun in the burst; a target
                            -- that died/knocked/forcefielded between guns must not take trailing shots.
                            if ragebot_target ~= target or target[7] or target[18] or target[4]["GRABBING_CONSTRAINT"] or get_target_phase(target) ~= nil then
                                break
                            end

                            local local_gun = new_local_guns[i]

                            -- only the gun picked above is sent this tick
                            if local_gun ~= chosen_gun then
                                continue
                            end

                            local handle = local_gun[1]
                            local ammo = local_gun[3]

                            if ammo > 0 and handle["Parent"] and hide_manager["gun_ready"](handle["Parent"], ammo) then
                                last_fire = clock()
                                hide_manager["gun_fired_at"][handle["Parent"]] = last_fire

                                if hide_manager["gun_ammo_sent"][handle["Parent"]] == ammo then
                                    hide_manager["gun_refused"][handle["Parent"]] = (hide_manager["gun_refused"][handle["Parent"]] or 0) + 1
                                else
                                    hide_manager["gun_refused"][handle["Parent"]] = 0
                                end

                                hide_manager["gun_ammo_sent"][handle["Parent"]] = ammo
                                hide_manager["last_sent_gun"] = handle["Parent"]
                                hide_manager["last_sent_at"] = last_fire

                                -- the held place stays until a moment after the last shot (Shot Lock above)
                                local lock = hide_manager["shot_lock"]
                                if lock and clock() < lock[1] then
                                    lock[1] = math.max(lock[1], clock() + 0.25)
                                end

                                -- bullet manipulation: the gun shoots by itself, aimed by the hook above
                                if rage_bullet_manipulation["enabled"] and rage_bullet_manipulation["installed"] and hide_manager["bm_try_pull"](handle["Parent"], ammo, pulled) then
                                    continue
                                end

                                setthreadidentity(8)
                                if shoot then getfenv(shoot)["require"] = require end
                                -- (with a target the shot is not drawn either: no shooting visuals on this client while the ragebot is on someone)
                                if shoot and not flags["auto_fire_dont_render"] and not (flags["ragebot"] and ragebot_target) then
                                    shoot({
                                        Shooter = local_character,
                                        Handle = handle,
                                        ForcedOrigin = origin,
                                        AimPosition = pos,
                                        BeamColor = color3_fromrgb(1, 0.545098, 0.14902),
                                        Range = local_gun[2]
                                    })
                                end

                                local dir = (pos-origin)
                                local Magnitude = dir["Magnitude"]
                                
                                local shot_direction = (Magnitude <= 0 or Magnitude ~= Magnitude) and ((handle["Position"])-pos)["Unit"] or dir
                                local pellets = hide_manager["pellets_of"](handle["Parent"])

                                if pellets > 1 then
                                    -- A shotgun's shot is a call a pellet, all under the server's time and one spread number (the gun's own script sends
                                    -- it so). The plain five argument call is taken only until the server's SecurityTolerance is used up, and the gun
                                    -- is then locked out for the rest of the server.
                                    hide_manager["spread_count"] = (hide_manager["spread_count"] or 0) + 1
                                    local stamp = workspace:GetServerTimeNow()

                                    for pellet = 1, pellets do
                                        event:FireServer("ShootGun", handle, origin, pos, hitbox, shot_direction, stamp, hide_manager["spread_count"], pellet)
                                    end
                                else
                                    for i = 1, ragebot_force_position and 2 or 1 do
                                        event:FireServer("ShootGun", handle, origin, pos, hitbox, shot_direction)
                                    end
                                end

                                spawn(get_bullet_result, target[2], hitbox, origin, pos, target_velocity, did_defensive)

                                if shoot then getfenv(shoot)["require"] = nil end
                                setthreadidentity(4)
                            end
                        end

                        if #pulled > 0 then
                            release_triggers(pulled)
                        end
                    end
                end
            else
                target_last_position = nil
                ragebot_aim_position = nil
            end
        end

        -- The hide reasons (respawning, loading, protected, reload) are kept by hide_manager.update, which runs on
        -- its own every tick while the ragebot is on.

        is_defensive = did_defensive
    end)

    -- The pickers filter the players themselves on every call (is_target_eligible); there is no cached list of targets to keep up to date.
    local update_targets = LPH_NO_VIRTUALIZE(function()
    end)

    local update_field_of_view = function()
        local value = flags["ragebot_field_of_view"]
        ragebot_field_of_view = value == 180 and true or (camera["ViewportSize"]["Magnitude"]/(pi/2))*(value/180)

        local is_number = type(ragebot_field_of_view) == "number"

        if fov_circle_outline then
            fov_circle_outline["Visible"] = is_number
            fov_circle_outline["Radius"] = is_number and ragebot_field_of_view or 0
        end

        if fov_circle then
            fov_circle["Visible"] = is_number
            fov_circle["Radius"] = is_number and ragebot_field_of_view or 0
        end
    end

    force_aim_position = function(character, position, timer)
        if ragebot_target and character and ragebot_target[3] == character then
            ragebot_force_position = position
            defensive_positions = {}
            delay(timer or local_ping/500, function()
                ragebot_force_position = nil
            end)
        end
    end

    is_defensive_active = LPH_NO_VIRTUALIZE(function()
        return is_defensive
    end)

    -- >> ( ragebot setting updaters )

    create_connection(menu_references["auto_fire_defensive"]["on_toggle_change"], function(value)
        defensive_positions = {}
    end)

