        aim_assist_field_of_view = (camera["ViewportSize"]["Magnitude"]/(pi/2))*(flags["aim_assist_field_of_view"]/180)
        aim_assist_dead_zone = aim_assist_field_of_view*(flags["aim_assist_dead_zone"]/100)

