        last_target_dt = nil
        silent_aim_position = nil

        if not value and not flags["triggerbot"] and not flags["aim_assist"] then
            delay(0.01, function()
                set_legitbot_target(nil)
                last_target_dt = nil
                silent_aim_position = nil
            end)
