        if not value then
            delay(0.15, function()
                -- Switched back on within the delay: the step was put back by the on branch and has to stay.
                if flags["silent_aim"] then
                    return
                end

                for i = 1, #heartbeat do
                    if heartbeat[i] == do_silent_aim then
                        remove(heartbeat, i)
                        break
                    end
                end

                -- The step wrote the point again while it ran on for aim assist or the triggerbot; nothing would clear it now.
                silent_aim_position = nil
                custom_silent_aim_position = nil
            end)
        else
            for i = 1, #heartbeat do
                if heartbeat[i] == do_silent_aim then
