    create_connection(menu_references["silent_aim_field_of_view"]["on_slider_change"], update_silent_aim_field_of_view)

    create_connection(menu_references["silent_aim_multipoint"]["on_slider_change"], function(value)
        silent_aim_multipoint = value/200
    end)

    create_connection(menu_references["silent_aim_redirect_chance"]["on_slider_change"], function(value)
        silent_aim_redirect_chance = 100 - value
    end)

    create_connection(menu_references["silent_aim_max_distance"]["on_slider_change"], function(value)
        silent_aim_max_distance = value
    end)

    -- >> ( bullet manipulation )
    -- Every gun asks ReplicatedStorage.Modules.GunHandler.getAim where it is aimed at the moment it fires.
    -- Answering that with a direction to the silent aim target makes the gun's own script do the shot, with
    -- its own spread, effects and arguments, so no remote is forged. The hit checker then drops any shot
    -- the game's own raycast did not land on the target. The hook is only in the module while the toggle is on.

    local hit_params = RaycastParams["new"]()
    hit_params["FilterType"] = Enum["RaycastFilterType"]["Exclude"]
    hit_params["IgnoreWater"] = true

    local last_blocked = 0

    -- whether a bullet from origin to position would land on this target
    local predict_hit = LPH_NO_VIRTUALIZE(function(origin, position, data)
        local parts = data[4]

        if data[7] or data[18] or hide_manager["is_protected"](data) then
            return false
        end

        local offset = position-origin
        local distance = offset["Magnitude"]

        if distance < 0.05 then
            return false
        end

        if silent_aim_max_distance ~= 2500 and local_gun and distance > local_gun then
            return false
        end

        local filter = {}
        for _, instance in {local_character, ignored, bush, vehicles} do
            filter[#filter+1] = instance
        end

        hit_params["FilterDescendantsInstances"] = filter

        local character = data[3]

        if not character then
            return false
        end

        local result = raycast(workspace, origin, offset["Unit"]*(distance+4), hit_params)

        return result ~= nil and result["Instance"]:IsDescendantOf(character)
    end)

    -- the direction the gun should aim in, or nil to leave its own aim alone
    local compute_aim = LPH_NO_VIRTUALIZE(function(origin)
        bullet_manipulation.aim = nil

        local target = legitbot_target
        local data = target and target[1]
        local position = flags["silent_aim"] and silent_aim_position or nil

        -- Silent aim on its own aims the gun here too: the guns take their aim from getAim, not from mouse.Hit, so the mouse redirect alone moved no shot
        if not ((bullet_manipulation.enabled or flags["silent_aim"] == true) and data and position and not ragebot_aim_position and typeof(origin) == "Vector3") then
            return nil
        end

        if math_random(1,100) <= silent_aim_redirect_chance then
            return nil
        end

        local offset = position-origin
        local distance = offset["Magnitude"]

        if distance < 0.05 then
            return nil
        end

        local hit = not flags["silent_aim_hit_checker"] or predict_hit(origin, position, data)

        bullet_manipulation.aim = {data = data, time = clock(), hit = hit}

        -- a shot that would miss is left alone here and dropped by the gate before it is sent
        if not hit then
            return nil
        end

        return offset["Unit"], distance
    end)

    -- Bullet Manipulation (Legit tab), the ragebot's way: the shot the gun's script sends is rebuilt with its hit claimed on the silent aim target
    -- (the part nearest to the silent aim position), from the gun's own origin, when the target is in the gun's range and (with Hit Checker) has a
    -- clear line from that origin; otherwise it is left alone. Force Hit (silent aim's gear), like the ragebot's: the hit is claimed on the head,
    -- with no range or line check. Called from the remote hook, so nothing in here may be a method call (a:B()): it would replace the namecall
    -- method and the shot would never be sent.
    local is_a = game["IsA"]

    hide_manager["legit_rebuild"] = LPH_NO_VIRTUALIZE(function(args)
        if not flags["silent_aim"] or ragebot_aim_position then
            return nil
        end

        local force = flags["silent_aim_force_hit"] == true
        local manipulate = bullet_manipulation.enabled == true

        if not force and not manipulate then
            return nil
        end

        local target = legitbot_target
        local data = target and target[1]
        local position = silent_aim_position
        local origin = args[3]
        local handle = args[2]

        if not (data and position and typeof(origin) == "Vector3" and typeof(handle) == "Instance") or data[7] or data[18] then
            return nil
        end

        local character, parts = data[3], data[4]

        if not character or type(parts) ~= "table" then
            return nil
        end

        local part

        if force then
            part = parts["Head"]
            position = part and part["Position"] or position
        else
            local best = math.huge

            for _, candidate in parts do
                if typeof(candidate) == "Instance" and is_a(candidate, "BasePart") and candidate["Parent"] == character then
                    local away = (candidate["Position"] - position)["Magnitude"]

                    if away < best then
                        best, part = away, candidate
                    end
                end
            end
        end

        if not part then
            return nil
        end

        local offset = position - origin
        local distance = offset["Magnitude"]

        if distance < 0.05 or distance ~= distance then
            return nil
        end

        local tool = handle["Parent"]
        local range = tool and find_first_child(tool, "Range")

        if not force and range and distance > range["Value"] then
            return nil
        end

        -- Over the wall (hide_manager.walls_route, the ragebot's): a line the wall blocks is sent from a point above or beside the body that clears it,
        -- with its claim moved to an open point by the target when it has to be. Hit Checker: a shot with no such way at all is left alone (and the gate
        -- drops it); Force Hit sends it anyway.
        local walls_route = hide_manager["walls_route"]

        if walls_route then
            hide_manager["walls_target"] = data
            local route_ok, routed_origin, claimed = pcall(walls_route, origin, position, range and range["Value"] or nil)
            hide_manager["walls_target"] = nil

            if route_ok and claimed then
                origin, position = routed_origin, claimed
            elseif not force and flags["silent_aim_hit_checker"] then
                return nil
            end
        end

        return {origin, position, part, (origin - position)["Unit"], data[2]}
    end)

    -- Whether a shot sent now would be rebuilt onto a target that can take it. The ragebot: it is aiming at a live, hittable target that is within the
    -- gun's Range of where the server has the body. The legitbot: Bullet Manipulation or Force Hit would rebuild a shot from the gun in hand right now.
    -- Only when it would really hit: a gun in hand with a round in it and in range, a target that can be hurt (not knocked, dead, respawning, loading
    -- or under a forcefield), and a clear way for the shot (straight, or over the wall: hide_manager.walls_route).
    hide_manager["can_manipulate"] = LPH_NO_VIRTUALIZE(function()
        local aim = ragebot_aim_position
        local target = ragebot_target
        local route = hide_manager["walls_route"]

        if flags["ragebot"] and target and aim and aim["Magnitude"] < 1e9 and not target[7] and not target[18] and hide_manager["get_target_phase"](target) == nil then
            local body = local_server_position and local_server_position["p"]
            local best = nil

            for _, gun in local_guns do
                if gun[3] and gun[3] > 0 and gun[2] and (not best or gun[2] > best) then
                    best = gun[2]
                end
            end

            if body and best and (body - aim)["Magnitude"] <= best then
                local origin = body + vector3_new(0, 3.0208, 0)
                local ok, _, claim = pcall(route, origin, aim, best)

                if ok and claim then
                    return true
                end
            end
        end

        local tool = local_character and find_first_child_of_class(local_character, "Tool")
        local handle = tool and find_first_child(tool, "Handle")
        local ammo = tool and find_first_child(tool, "Ammo")
        local head = local_character and find_first_child(local_character, "Head")
        local legit = legitbot_target and legitbot_target[1]

        if handle and head and ammo and ammo["Value"] > 0 and legit and hide_manager["legit_rebuild"] and not hide_manager["is_protected"](legit) then
            local ok, rebuilt = pcall(hide_manager["legit_rebuild"], {"ShootGun", handle, head["Position"]})

            -- Force Hit builds a shot even past the gun's Range: the server turns that one away, so it is not "manipulatable"
            local range = find_first_child(tool, "Range")

            if ok and type(rebuilt) == "table" and range and (rebuilt[2] - rebuilt[1])["Magnitude"] > range["Value"] + 2 then
                return false
            end

            if ok and type(rebuilt) == "table" then
                -- Force Hit sends a shot even with no clear way; that one would not hit
                hide_manager["walls_target"] = legit
                local clear_ok, clear = pcall(hide_manager["walls_clear"], rebuilt[1], rebuilt[2])
                hide_manager["walls_target"] = nil

                return clear_ok and clear == true
            end
        end

        return false
    end)

    -- Manipulated Indicator (Bullet Manipulation's gear): "manipulated" under the crosshair while a shot would be manipulated onto the target (above), and
    -- for a moment after every rebuilt shot (the ragebot's too)
    do
        local indicator = nil

        pcall(function()
            indicator = Drawing.new("Text")
            indicator.Text = "manipulated"
            indicator.Center = true
            indicator.Outline = true
            indicator.Size = 14
            indicator.Color = color3_fromrgb(255, 194, 254)
            indicator.Visible = false
        end)

        hide_manager["manipulated_indicator"] = indicator

        if indicator then
            local can_now, checked_at = false, 0

            create_connection(render_stepped, function()
                local wanted = flags["silent_aim_manipulated_indicator"] ~= false

                -- looked at 20 times a second (it may cast a ray)
                if wanted and clock() - checked_at >= 0.05 then
                    checked_at = clock()
                    local ok, can = pcall(hide_manager["can_manipulate"])
                    can_now = ok and can == true
                end

                -- only while the target can be hit by a manipulated shot right now (no longer for a moment after every shot as well)
                local shown = wanted and can_now

                if shown then
                    local mouse = get_mouse_location(user_input_service)
                    indicator.Position = Vector2.new(mouse.X, mouse.Y + 22)
                end

                indicator.Visible = shown
            end)

            local teardowns = getgenv()["neverlose_teardowns"]

            if teardowns then
                teardowns[#teardowns+1] = function()
                    pcall(function()
                        indicator:Remove()
                    end)
                end
            end
        end
    end

    -- the legitbot's answer to the gun module's getAim, asked after the ragebot's (there is one hook for both, see the ragebot's)
    hide_manager["aim_chain"]["providers"]["legit"] = {
        enabled = function()
            return bullet_manipulation.enabled == true or flags["silent_aim"] == true
        end,
        answer = compute_aim
    }

    -- the last stop before a shot is sent: only a shot that landed on the locked target goes through
    silent_shot_gate = LPH_NO_VIRTUALIZE(function(args)
        local aim = bullet_manipulation.aim

        if not (aim and bullet_manipulation.enabled and bullet_manipulation.hooked and flags["silent_aim_hit_checker"]) or clock()-aim["time"] > 0.5 then
            return true
        end

        local hit = aim["hit"]

        if hit then
            local ok, landed = pcall(function()
                local part = args[5]
                local parent = typeof(part) == "Instance" and part["Parent"] or nil
                local grandparent = parent and parent["Parent"] or nil
                local player = parent and (find_first_child(players_service, parent["Name"]) or (grandparent and find_first_child(players_service, grandparent["Name"])))

                return player == aim["data"][2]
            end)

            hit = not ok or landed
        end

        if hit then
            return true
        end

        if do_notification and clock()-last_blocked > 1.5 then
            last_blocked = clock()
            new_notification("silent aim: shot blocked, it would not hit", 1)
        end

        return false
    end)

    local set_bullet_manipulation = LPH_NO_VIRTUALIZE(function(value)
        bullet_manipulation.enabled = value
        bullet_manipulation.aim = nil

        if not value then
            bullet_manipulation.hooked = false
            hide_manager["release_aim_hook"]()

            return
        end

        bullet_manipulation.hooked = hide_manager["ensure_aim_hook"]() == true
    end)

    -- see the ragebot's: the hook is taken out with the script
    do
        local teardowns = getgenv()["neverlose_teardowns"]

        if teardowns then
            teardowns[#teardowns+1] = function()
                pcall(set_bullet_manipulation, false)
            end
        end
    end

    create_connection(menu_references["silent_aim_bullet_manipulation"]["on_toggle_change"], function(value)
        set_bullet_manipulation(value)

        if not value then
            return
        end

        if not bullet_manipulation.hooked then
            new_notification("bullet manipulation: gun module not found, silent aim keeps the mouse redirect", 3)
        elseif not flags["silent_aim"] then
            new_notification("bullet manipulation: turn silent aim on too", 3)
        end
    end)

    -- >> ( triggerbot )

    do
        local viewport_point_to_ray = camera["ViewportPointToRay"]

        local triggerbot_do_head = true
        local triggerbot_do_torso = true
        local triggerbot_do_arms = false
        local triggerbot_do_legs = false
        local triggerbot_cooldown = 0
        local triggerbot_hover_time = 0
        local triggerbot_delay = 0
        local last_triggerbot_part = nil
        local triggerbot_max_distance = 0

        local triggerbot_hover_tick = clock()
        local triggerbot_tick = clock()
        -- clicking: a click is on its way (pressed, or waiting out its delay); checked_at: when the refresh rate last let the triggerbot look
        local triggerbot_state = { clicking = false, checked_at = 0 }

        local do_triggerbot = LPH_JIT_MAX(function(dt, hrp)
            -- Refresh rate: how often the triggerbot looks (0 = every frame). The slider was not read anywhere.
            local refresh_rate = flags["triggerbot_refresh_rate"]

            if refresh_rate and refresh_rate > 0 then
                local now = clock()

                if now - triggerbot_state.checked_at < refresh_rate then
                    return
                end

                triggerbot_state.checked_at = now
            end

            local mouse_position = get_mouse_location(user_input_service)

            if dt ~= last_target_dt then
                get_legitbot_target(dt)
            end

            if legitbot_target and not legitbot_dont_aim and local_gun then
                local ray = viewport_point_to_ray(camera, mouse_position["X"], mouse_position["Y"])
                local data = legitbot_target[1]
                local parts = data[4]
                local target_hrp = parts["HumanoidRootPart"]
                if not data[7] and not data[18] and not hide_manager["is_protected"](data) and target_hrp then
                    local max = (triggerbot_max_distance == 0 and (local_gun or 250) or triggerbot_max_distance)
                    if triggerbot_max_distance == 2500 or (hrp["Position"]-target_hrp["Position"])["Magnitude"] <= max then
                        local ignore = {local_character, ignored, bush, vehicles, data[13]}

                        for name, part in parts do
                            if part["ClassName"] == "Accessory" then
                                ignore[#ignore+1] = part
                            elseif part:IsA("BasePart") and part["Transparency"] == 1 then
                                ignore[#ignore+1] = part
                            end
                        end

                        params["FilterDescendantsInstances"] = ignore

                        local result = raycast(workspace, ray["Origin"], ray["Direction"] * (max), params)

                        if result then
                            local instance = result["Instance"]

                            if instance then
                                local name = instance["Name"]

                                if parts[name] == instance then
                                    local do_triggerbot = false

                                    if triggerbot_do_head and name == "Head" then
                                        do_triggerbot = instance
                                    elseif triggerbot_do_torso and (name == "UpperTorso" or name == "LowerTorso" or name == "HumanoidRootPart") then
                                        do_triggerbot = instance
                                    elseif triggerbot_do_arms and (name == "LeftUpperArm" or name == "RightUpperArm" or name == "LeftLowerArm" or name == "RightLowerArm" or name == "LeftHand" or name == "RightHand") then
                                        do_triggerbot = instance
                                    elseif triggerbot_do_legs and (name == "LeftUpperLeg" or name == "RightUpperLeg" or name == "LeftLowerLeg" or name == "RightLowerLeg" or name == "LeftFoot" or name == "RightFoot") then
                                        do_triggerbot = instance
                                    end

                                    if do_triggerbot then
                                        local tick = clock()

                                        if tick-triggerbot_tick > triggerbot_cooldown or triggerbot_cooldown == 0 then
                                            triggerbot_tick = tick

                                            if last_triggerbot_part ~= instance then
                                                triggerbot_hover_tick = tick
                                            end

                                            -- One click at a time: with a delay a new one used to be queued every frame (up to 45 landing after the crosshair
                                            -- had left the target), and without one the presses and releases of consecutive frames overlapped.
                                            if (tick - triggerbot_hover_tick > triggerbot_hover_time or triggerbot_hover_time == 0) and not triggerbot_state.clicking then
                                                triggerbot_state.clicking = true

                                                local function click()
                                                    pcall(mouse1press)
                                                    wait()
                                                    pcall(mouse1release)
                                                    triggerbot_state.clicking = false
                                                end

                                                if triggerbot_delay > 0 then
                                                    delay(triggerbot_delay, function()
                                                        -- The crosshair left the target (or the triggerbot went off) while the click waited.
                                                        if not flags["triggerbot"] or last_triggerbot_part == nil then
                                                            triggerbot_state.clicking = false
                                                            return
                                                        end

                                                        click()
                                                    end)
                                                else
                                                    click()
                                                end
                                            end
                                        end
                                    end

                                    last_triggerbot_part = instance

                                    return
                                end
                            end
                        end
                    end
                end
            end

            last_triggerbot_part = nil
        end)

        create_connection(menu_references["triggerbot"]["on_toggle_change"], function(value)
            last_target_dt = nil

            if not value and not flags["silent_aim"] and not flags["aim_assist"] then
                delay(0.01, function()
                    set_legitbot_target(nil)
                    last_target_dt = nil
                    silent_aim_position = nil
                end)
            end

            for i = 1, #heartbeat do
                if heartbeat[i] == do_triggerbot then
                    remove(heartbeat, i)
                    break
                end
            end

            if value then
                heartbeat[#heartbeat+1] = do_triggerbot
            end
        end)

        create_connection(menu_references["triggerbot_hitboxes"]["on_dropdown_change"], function(value)
            triggerbot_do_legs = false
            triggerbot_do_torso = false
            triggerbot_do_arms = false
            triggerbot_do_head = false

            for i = 1, #value do
                local value = value[i]

                if value == "head" then
                    triggerbot_do_head = true
                elseif value == "torso" then
                    triggerbot_do_torso = true
                elseif value == "arms" then
                    triggerbot_do_arms = true
                elseif value == "legs" then
                    triggerbot_do_legs = true
                end
            end
        end)

        create_connection(menu_references["triggerbot_cooldown"]["on_slider_change"], function(value)
            triggerbot_cooldown = value
        end)

        create_connection(menu_references["triggerbot_max_distance"]["on_slider_change"], function(value)
            triggerbot_max_distance = value
        end)

        create_connection(menu_references["triggerbot_delay"]["on_slider_change"], function(value)
            triggerbot_delay = value
        end)

        create_connection(menu_references["triggerbot_hover_time"]["on_slider_change"], function(value)
            triggerbot_hover_time = value
        end)
    end

    -- >> ( reduce shotgun spread )

    do
        local func_cache = {}
        local connection = nil
        local connection2 = nil
        -- share of the spread that is left: 1 keeps all of it, 0 removes all of it (starts at the slider's 100%)
        local reduce_amount = 0

        local on_tool_added = function(tool)
            if not tool then
                return
            end

            local connection = getconnections(tool["Activated"])[1]

            if not connection then
                return
            end

            local old = connection["Function"]

            if not old or isourclosure(getfenv(old)["math"]["random"]) or not getinfo(old)["source"]:find("GunClientShotgun") then
                return
            end

            -- Only random is replaced; the rest of math stays what the gun script had (the whole table used to be swapped for one holding random alone),
            -- and a call with arguments is a different use of random and gets the real one.
            getfenv(old)["math"] = setmetatable({
                ["random"] = newcclosure(function(...)
                    if select("#", ...) > 0 then
                        return math_random(...)
                    end

                    return math_random()*reduce_amount
                end)
            }, {["__index"] = math})

            func_cache[#func_cache+1] = old
        end

        local reset = function()
            func_cache = {}
        end

        create_connection(menu_references["reduce_shotgun_spread"]["on_toggle_change"], function(value)
            for i = 1, #func_cache do
                getfenv(func_cache[i])["math"] = nil
                func_cache[i] = nil
            end

            if connection then
                connection:Disconnect()
                connection = nil
            end

            if connection2 then
                connection2:Disconnect()
                connection2 = nil
            end

            if value then
                for handle, data in local_guns do
                    local tool = handle["Parent"]

                    if tool then
                        on_tool_added(tool)
                    end
                end

                connection = create_connection(signals["on_local_tool_equipped"], on_tool_added)
                connection2 = create_connection(signals["on_local_character_added"], reset)
            end
        end)

        create_connection(menu_references["reduce_shotgun_spread_amount"]["on_slider_change"], function(value)
            reduce_amount = 1 - math.clamp(tonumber(value) or 0, 0, 100)/100
        end)
    end 

end)()

-- > ( finalization )

do
    -- Roblox creates ServerStatsItem lazily, so it can be missing; the ping then keeps its last value.
    local data_ping = nil
    local get_data_ping = function()
        if not data_ping then
            local server_stats = game:GetService("Stats")["Network"]:FindFirstChild("ServerStatsItem")
            data_ping = server_stats and server_stats:FindFirstChild("Data Ping") or nil
        end

        return data_ping
    end
    local last_ping_check = clock()
    local ping_data = {}

    -- Where the body has been, one point a frame for the last half second. The server has the body a little late (0.06 to 0.12 s, measured by
    -- BASED Hub) and takes a shot only from within 17 studs of where it has it: with a follow style that moves the body every frame, a shot
    -- claimed from where the body is now is often refused. hide_manager.lagged_position(lag) is where the body was `lag` seconds ago.
    hide_manager["trail_times"] = {}
    hide_manager["trail_points"] = {}

    -- The ragebot's target is in the void and its spot there has jumped in the last half second (do_ragebot marks it).
    hide_manager["is_void_jittering"] = function(target, position)
        return target ~= nil and position ~= nil and position["Magnitude"] >= 9e5 and clock() - (hide_manager["target_void_jitter_at"] or -1) < 0.5
    end

    hide_manager["lagged_position"] = function(lag)
        local times, points = hide_manager["trail_times"], hide_manager["trail_points"]
        local count = #times

        if count == 0 or not lag or lag <= 0 then
            return nil
        end

        local wanted = clock() - lag
        local latest = points[count]
        local found = points[1]

        for i = count, 1, -1 do
            if times[i] <= wanted then
                found = points[i]
                break
            end
        end

        -- the body has only just been taken there (follow starting, out of the void): the old place is too far from the target for any shot, so
        -- the shot goes from where it is now
        if (found - latest)["Magnitude"] > 17 then
            return latest
        end

        return found
    end

    local update_server_position = LPH_NO_VIRTUALIZE(function(hrp)
        local_server_position = hrp["CFrame"]

        local times, points = hide_manager["trail_times"], hide_manager["trail_points"]
        local now = clock()

        times[#times+1] = now
        points[#points+1] = local_server_position["p"]

        while times[1] and now - times[1] > 0.5 do
            remove(times, 1)
            remove(points, 1)
        end
    end)

    local last_fps = clock()

    -- When the last frame was drawn (the anti aim steps in the Heartbeat below wait for it).
    create_connection(game:GetService("RunService")["RenderStepped"], function()
        hide_manager["rendered_at"] = clock()
        getgenv()["neverlose_rendered_at"] = hide_manager["rendered_at"]
    end)

    create_connection(game:GetService("RunService")["Heartbeat"], LPH_NO_VIRTUALIZE(function(dt)
        -- F-C5: finalization used to flip in_void to nil/false every tick, clobbering
        -- what do_void_hide set. do_void_hide now owns the whole lifecycle of in_void.

        local frame_time = clock()
        local_fps = 1/math.max(frame_time - last_fps, 1e-4)
        last_fps = frame_time

        if clock()-last_ping_check > 2 then
            last_ping_check = clock()

            if #ping_data >= 10 then
                remove(ping_data, 1)
            end

            local stats_item = get_data_ping()
            local new_ping = stats_item and stats_item:GetValue() or nil

            if new_ping then
                ping_data[#ping_data+1] = new_ping

                local total = 0
                for _, ping in ping_data do
                    total+=ping
                end
                local_ping = 3 + floor(total/#ping_data)
            end
        end

        local hrp = vehicle or local_parts["HumanoidRootPart"]

        -- Steps add and remove entries while they run (spawn runs them inline up to their first yield), which shifts the
        -- list under the loop: walk a copy and skip anything that is gone.
        local steps = table.move(heartbeat, 1, #heartbeat, 1, {})

        for i = 1, #steps do
            spawn(steps[i], dt, hrp)
        end

    end))

    -- The anti aim steps (follow, void hide and the rest: they move the body for the server and put it back on the next drawn frame) run at Stepped,
    -- before the physics step, not at Heartbeat after it. The server is sent the body as it is at the physics step: a body moved at Heartbeat and put
    -- back at the next RenderStepped was never seen there at all (measured from another player's client: 0 of 530 samples), so Follow Target moved the
    -- body only on this screen and every shot claimed from next to the target was refused until chance put the real body in reach. Moved at Stepped
    -- and put back at the next RenderStepped, the server had it there in 409 of 505 samples. They run whether or not frames are drawn: with none drawn
    -- their wait for the next frame falls back to the next physics step (render_stepped_wait).
    create_connection(game:GetService("RunService")["Stepped"], LPH_NO_VIRTUALIZE(function(_, dt)
        local hrp = vehicle or local_parts["HumanoidRootPart"]

        if hrp then
            local_client_position = hrp["CFrame"]
        end

        local anti_aim_steps = table.move(anti_aim, 1, #anti_aim, 1, {})

        for i = 1, #anti_aim_steps do
            spawn(anti_aim_steps[i], dt, hrp)
        end

        if hrp then
            spawn(update_server_position, hrp)
        end
    end))

    local old_vehicle = nil

    create_connection(signals["on_vehicle_sat_in"], function(new_vehicle)
        if old_vehicle then
            setrawmetatable(old_vehicle, getrawmetatable(game))
        end
        if new_vehicle then
            local old = getrawmetatable(new_vehicle)
            local old_index = old["__index"]
            local old_new_index = old["__newindex"]

            local new = {
                ["__index"] = newcclosure(LPH_NO_VIRTUALIZE(function(self, index)
                    if not checkcaller() and self then
                        local is_cframe = index == "CFrame" 
                        if (is_cframe or index == "Position") and (#anti_aim ~= 0 or purchasing) then
                            return is_cframe and local_client_position or local_client_position["p"]
                        end
                    end
                    return old_index(self, index)
                end)),
                ["__newindex"] = newcclosure(LPH_NO_VIRTUALIZE(function(self, index, value)
                    if checkcaller() and self and index == "CFrame" and (#anti_aim ~= 0 or purchasing) then
                        return old_new_index(self, index, value)
                    end
                    return old_new_index(self, index, value)
                end))
            }

            for _, v in old do
                if not new[_] then
                    new[_] = v
                end
            end

            setrawmetatable(new_vehicle, new)
        end
        old_vehicle = new_vehicle
    end)
end

-- > ( addons )

do
    local running_image_data = base64_decode("")
    local lua_image_data = base64_decode("")
    local addon_list = menu_references["addon_list"]

    for _, addon in menu["get_addon_list"]() do
        addon_list:add_item({
            ["text"] = addon,
            ["icons"] = {
                lua_image_data
            }
        })
    end

    -- >> ( addons )

    local addon_panel = menu_references["addon_panel"]
    local load_addon = menu_references["load_addon"]

    if load_addon then
        local unload_addon = menu_references["unload_addon"]
        local refresh_addon_list = menu_references["refresh_addon_list"]

        create_connection(addon_list["on_selection_change"], function(addon)
            local addon = addon or ""
            local path = "neverlose recode/addons/"..addon..".luau"

            if addon ~= "" and isfile(path) then
                if addon_data[addon] then
                    load_addon:set_visible(false)
                    unload_addon:set_visible(true)
                else
                    load_addon:set_visible(true)
                    unload_addon:set_visible(false)
                end
                refresh_addon_list:set_visible(false)
            else
                refresh_addon_list:set_visible(true)
                unload_addon:set_visible(false)
                load_addon:set_visible(false)
            end
        end)

        local do_refresh = function()
            local elements = addon_list["elements"]
            for _, element in elements do
                addon_list:remove_item(element["name"], true)
                elements[_] = nil
            end

            local addons = menu["get_addon_list"]()
            for i = 1, #addons do
                addon_list:add_item({
                    ["text"] = addons[i],
                    ["icons"] = addon_data[addons[i]] and {running_image_data, lua_image_data} or {
                        lua_image_data
                    }
                })
            end
        end

        create_connection(refresh_addon_list["on_clicked"], do_refresh)
        create_connection(menu["on_config_loaded"], do_refresh)

        create_connection(unload_addon["on_clicked"], function()
            local selected_addon = addon_list["selected"]
            local selected = selected_addon and selected_addon["name"]
            if selected_addon and addon_data[selected] then
                menu["unload_addon"](selected)
                new_notification("successfully unloaded addon "..selected, 1)
                addon_list:remove_icon(selected, running_image_data)
                load_addon:set_visible(true)
                unload_addon:set_visible(false)
            end
        end)

        create_connection(load_addon["on_clicked"], function()
            local selected_addon = addon_list["selected"]
            local selected = selected_addon and selected_addon["name"]

            if selected_addon and not addon_data[selected] then
                local did_error = menu["load_addon"](selected)
                if did_error then
                    new_notification("failed to load addon "..selected.." ("..did_error..")", 3)
                    error(did_error)
                    return
                end
                new_notification("successfully loaded addon "..selected, 1)
                unload_addon:set_visible(true)
                addon_list:add_icon(selected, running_image_data)
                load_addon:set_visible(false)
            end
        end)

        unload_addon:set_visible(false)
        load_addon:set_visible(false)
    end

    local typeof = typeof
    local g = menu["get_active_binds"]
    local old = getgenv()["neverlose"]
    local new = {
        create_connection = function(signal, callback)
            local type = typeof(signal)

            if type ~= "RBXScriptSignal" and type ~= "table" then
                error("Visions hook: create_connection arg #1 expected RBXScriptSignal or table got "..type)
                return
            end

            local type = typeof(callback)

            if type ~= "function" then
                error("Visions hook: create_connection arg #2 expected function got "..type)
                return
            end

            local identifier = getfenv(0).__IDENTIFIER or getfenv(1).__IDENTIFIER or getfenv(2).__IDENTIFIER or getfenv(3).__IDENTIFIER

            if identifier then
                local data = addon_data[identifier]

                if data then
                    local data = addon_data[identifier]
                    local connections = data[3]

                    local connection = signal:Connect(callback)

                    connections[#connections+1] = connection

                    return connection
                end
            end
        end,
        find_element = LPH_JIT_MAX(function(parent, name)
            local type = typeof(name)

            if type ~= "string" then
                error("Visions hook: find_element arg #1 expected string got "..type)
                return
            end

            local type = typeof(parent)

            if type ~= "string" then
                error("Visions hook: find_element arg #2 expected string got "..type)
                return
            end

            local name = name:lower()

            if name:find("config") or name:find("unload") then
                error("Visions hook: find_element arg #2 expected string got <?>")
                return
            end

            local parent = parent:lower()

            for _, group in menu["groups"] do
                for _, tab in group["tabs"] do
                    for _, section in tab["sections"] do
                        if section["name"]:lower() == parent then
                            local elements = section["elements"]
                            for i = 1, #elements do
                                local element = elements[i]
                                if (element["name"]):lower() == name then
                                    return element
                                end
                            end
                        end
                    end
                end
            end

            for element_settings, settings in menu["settings"] do
                if element_settings["name"]:lower() == parent then
                    local elements = settings["elements"]
                    for i = 1, #elements do
                        local element = elements[i]
                        if (element["name"]:lower()) == name then
                            return element
                        end
                    end
                end
            end

            error("Visions hook: find_element failed to find element "..name)
        end),
        create_section = function(name, side, size, offset)
            local type = typeof(name)

            if type ~= "string" then
                error("Visions hook: create_section arg #1 expected string got "..type)
                return
            end

            local type = typeof(side)

            if type ~= "number" then
                error("Visions hook: create_section arg #2 expected number got "..type)
                return
            elseif side ~= 1 and side ~= 2 then
                error("Visions hook: create_section arg #2 expected number 1 or 2 got "..side)
                return
            end

            local type = typeof(size)

            if type ~= "number" then
                error("Visions hook: create_section arg #3 expected number got "..type)
                return
            elseif size < 0 or size > 1 then
                error("Visions hook: create_section arg #3 expected number between 0 and 1 got "..size)
                return
            end

            local type = typeof(offset)

            if type ~= "number" then
                error("Visions hook: create_section arg #4 expected number got "..type)
                return
            elseif offset < 0 or offset > 0.9 then
                error("Visions hook: create_section arg #4 expected number between 0 and 0.9 got "..offset)
                return
            end

            local identifier = getfenv(0).__IDENTIFIER or getfenv(1).__IDENTIFIER or getfenv(2).__IDENTIFIER or getfenv(3).__IDENTIFIER

            if identifier then
                local data = addon_data[identifier]

                if data then
                    local tab = data[2]

                    if tab and tab["destroy"] then
                        return menu["groups"]["addons"]:create_section(data[5], name, side, size, offset)
                    end
                end
            end
        end,
        create_element = function(section, info, elements)
            local type = typeof(section)

            if type ~= "string" then
                if not elements and type == "table" then
                    local new_info = section
                    local new_elements = info

                    if typeof(new_info) == "table" and typeof(new_elements) == "table" then
                        local identifier = getfenv(0).__IDENTIFIER or getfenv(1).__IDENTIFIER or getfenv(2).__IDENTIFIER or getfenv(3).__IDENTIFIER

                        local data = addon_data[identifier]

                        if data then
                            local tab = data[2]
        
                            if not tab or not tab["destroy"] then
                                getgenv()["neverlose"]["create_tab"]()
                                data[6] = getgenv()["neverlose"]["create_section"]("update yo addon twin", 1, 1, 0)
                            end

                            return data[6]:create_element(new_info, new_elements)
                        end
                    end
                end
                error("Visions hook: create_element arg #1 expected string got "..type)
                return
            end

            local type = typeof(info)

            if type ~= "table" then
                error("Visions hook: create_element arg #2 expected table got "..type)
                return
            end

            local type = typeof(elements)

            if type ~= "table" then
                error("Visions hook: create_element arg #3 expected table got "..type)
                return
            end

            local identifier = getfenv(0).__IDENTIFIER or getfenv(1).__IDENTIFIER or getfenv(2).__IDENTIFIER or getfenv(3).__IDENTIFIER
            
            if identifier then
                local data = addon_data[identifier]

                if data then
                    local tab = data[2]

                    if not tab or not tab["destroy"] then
                        error("Visions hook: create_element failed due to missing tab")
                        return 
                    end

                    local section = tab["sections"][section]

                    if not section or not section["destroy"] then
                        error("Visions hook: create_element failed due to missing section \'"..section.."\''")
                        return 
                    end

                    return section:create_element(info, elements)
                end
            end
        end,
        get_signal = LPH_JIT_MAX(function(signal)
            local type = typeof(signal)

            if type ~= "string" then
                error("Visions hook: get_signal arg #1 expected string got "..type)
                return
            end

            if signal == "on_ragebot_target_changed" or signal == "on_legitbot_target_changed" or signal == "on_target_changed" then
                local fake = {
                    ["Connect"] = function(self, callback)
                        return signals[signal]:Connect(function(player, ...)
                            return callback(player and player[2])
                        end)
                    end
                }

                return fake
            end

            return signals[signal]
        end),
        get_signals = LPH_NO_VIRTUALIZE(function()
            local all = {}
            for signal, _ in signals do
                all[#all+1] = signal
            end
            return all
        end),
        set_flag = LPH_JIT_MAX(function(flag, value)
            if flag == nil or flag == "author" or flag == "date" or flag == "loaded_addons" then
