            end

            local type = type(flag)

            if type ~= "string" then
                error("Visions hook: set_flag arg #1 expected string got "..type)
                return
            end

            flags[flag] = value
        end),
        get_flag = LPH_NO_VIRTUALIZE(function(flag)
            if flag == "author" or flag == "date" or flag == "loaded_addons" or flag == nil then
                return nil
            end 

            return flags[flag]
        end),
        get_flags = LPH_NO_VIRTUALIZE(function()
            local all = {}
            for flag, _ in flags do
                if flag == "author" or flag == "date" or flag == "loaded_addons" then
                    continue
                end 
                all[#all+1] = flag
            end
            return all
        end),
        add_ragebot_target = function(player)
            -- After an Anti Report shutdown nothing is picked for the ragebot, addons included.
            if getgenv()["neverlose_safety_shutdown"] then
                return
            end

            local type = typeof(player)

            if type ~= "Instance" then
                error("Visions hook: add_ragebot_target arg #1 expected Instance got "..type)
                return
            end

            local data = player_data[player]

            if not data then
                error("Visions hook: add_ragebot_target errored due to missing player data")
                return
            end

            ragebot_targets[data] = true
        end,
        remove_ragebot_target = function(player)
            local type = typeof(player)

            if type ~= "Instance" then
                error("Visions hook: remove_ragebot_target arg #1 expected Instance got "..type)
                return
            end

            local data = player_data[player]

            if not data then
                error("Visions hook: remove_ragebot_target errored due to missing player data")
                return
            end

            ragebot_targets[data] = nil
        end,
        -- Replaces the players picked in the menu's Target List. While anyone is picked the ragebot
        -- only goes for them (and picks one on its own, no need for the automatic option).
        set_target_list = function(players)
            local picked = {}
            local count = 0

            if type(players) == "table" then
                for _, player in players do
                    if typeof(player) == "Instance" and player["ClassName"] == "Player" and player ~= local_player and not picked[player] then
                        picked[player] = true
                        count += 1
                    end
                end
            end

            local previous_count = target_list["count"]

            target_list["players"] = picked
            target_list["count"] = count

            -- A target that is no longer picked is let go so the next one is chosen straight away,
            -- and clearing the list lets go of the player it was locked onto.
            if ragebot_target and ((count > 0 and not picked[ragebot_target[2]] and not ragebot_targets[ragebot_target]) or (count == 0 and previous_count > 0)) then
                set_ragebot_target(nil, nil)
            end

            target_list["refresh"] = true
        end,
        -- kills and deaths against a player since the script started: mine, theirs
        get_score = function(player)
            local entry = hide_manager["scores"][player]

            return entry and entry["mine"] or 0, entry and entry["theirs"] or 0
        end,
        get_target_list = function()
            local list = {}
            for player, _ in target_list["players"] do
                list[#list+1] = player
            end

            return list
        end,
        get_ragebot_targets = function()
            local targets = {}
            for data, _ in ragebot_targets do
                local player = data[2]
                if player then
                    targets[#targets+1] = player
                end
            end

            return targets
        end,
        load_config = newcclosure(function(string)
            local type = type(string)

            if type ~= "string" then
                error("Visions hook: load_config arg #1 expected string got "..type)
                return
            end

            if isfile("neverlose recode/configs/"..string..".cfg") then
                menu["load_config"](string)
            else
                error("Visions hook: load_config expected string got "..type)
            end
        end),
        set_tab_text = function(text)
            local identifier = getfenv(0).__IDENTIFIER or getfenv(1).__IDENTIFIER or getfenv(2).__IDENTIFIER or getfenv(3).__IDENTIFIER

            if identifier then
                local data = addon_data[identifier]

                if data then
                    local tab = data[2]

                    if tab and tab["text"] then
                        local type = type(text)

                        if type ~= "string" then
                            error("Visions hook: set_tab_text arg #1 expected string got "..type)
