            return get_state and get_state() or nil
        end),
        is_auto_stomping = LPH_NO_VIRTUALIZE(function()
            return stomping
        end),
        get_ping = LPH_NO_VIRTUALIZE(function()
            return local_ping
        end),
        purchase_item = LPH_JIT_MAX(function(item, ammo)
            -- After an Anti Report shutdown nothing buys on its own, addons included.
